// paid this realm no ticket money to get back: what they paid was the duel's rake, and the
// abandonment transition below turns that rake into THEIR claim on this same week
// (AUDIT-2026-09-28.md findings 31 and 34).
//
// THE TWO SENTENCES THAT FOLLOWED WERE BOTH FALSE AND ARE KEPT BECAUSE EACH WAS LOAD-BEARING
// FOR A DIFFERENT READER:
//
//	"A week whose entries are ALL earned therefore refunds nobody and MOVES ITS WHOLE POT TO
//	opsPot ON THE FIRST REFUND ATTEMPT — except that there can be no first refund attempt,
//	because no caller has a spend record, so such a week simply stays unrefundable and
//	RESOLVE REMAINS ITS ONLY EXIT."
//
// The first clause contradicted itself in its own sentence (a refund attempt that cannot
// happen cannot move anything) and named a destination that is deleted. The second was true
// when it was written and was FIXED BY finding 17 in the same audit: a pure-earned week has a
// SECOND exit, SweepDrawlessWeek's shape 2, gated on the same grace window this function uses,
// and that exit retires the sponsorship to the earned holders. Leaving "Resolve remains its
// only exit" standing is how a reader concludes that the stranding finding 17 closed is still
// open — or, worse, re-derives finding 17 as a new idea and implements it a second time.
//
// WHAT IS TRUE: such a week refunds nobody through this function, its draw is Resolve, and if
// no draw happens for the whole grace window then SweepDrawlessWeek marks it abandoned and its
// sponsorship becomes its earned holders' claim. It strands nothing by either route.
//
// EACH BUYER RECLAIMS EXACTLY THEIR OWN RECORDED SPEND, ONCE. The record is
// zeroed before the transfer, so a second call finds nothing and panics; and
// because Pot == sum(spends) + Sponsored for an unresolved week — with the
// sponsorship term taken out of the pot the moment the week is abandoned, see
// below — the refunds can never total more than the pot holds.
//
// SPONSORSHIP IS NOT REFUNDABLE AND IS NOT LEFT BEHIND. House money added by
// FundPot (the duel's rake, for one) belongs to no buyer, so nobody can claim it
// here; the first refund that pays out ROLLS IT FORWARD INTO THE LIVE WEEK'S POT —
// exactly as SweepDrawlessWeek does for a week nobody entered — instead of leaving
// it stranded in a pot whose every claim has been zeroed. It went to opsPot until
// 2026-09-29, and the two paths disagreeing about the same money was
// AUDIT-2026-09-28.md finding 16. The code and the reasoning are at the transition
// below.
//
// THE HOUSE FEE *IS* REFUNDED, SINCE 2026-09-29, AND THE PARAGRAPH THAT USED TO BE
// HERE SAID THE OPPOSITE. It read: "What a buyer gets back is their post-cut
// contribution — the part that was ever in the prize pot — not the gross ticket price.
// The 5% was taken at sale time and is already in the ops pot; clawing it back would
// mean the ops pot could go negative, or that this realm had to hold every cut in
// escrow for a week against the small chance of a pruned round." IT IS KEPT VERBATIM
// BECAUSE IT NAMES THE COST OF THE FIX AND THE FIX PAID IT: the realm now DOES hold
// every fee in escrow per week (Draw.Cut), which is the second option that sentence
// dismissed, and the ops pot cannot go negative because nothing credits it until a
// draw succeeds.
//
// WHAT A BUYER GETS BACK IS THEREFORE THE WHOLE TICKET PRICE. The owner's rule is that
// WE EARN WHEN THE GAME RUNS, NOT WHEN IT FAILS, and a refunded week is a week that did
// not run: the fee was a charge for a draw that never happened. This is a REDUCTION IN
// HOUSE REVENUE in the failure case, which needs no permission and is the safe
// direction — the same shape as finding 16 sending an abandoned week's sponsorship back
// to players rather than to the house.
//
// THE SPLIT IS IN THE BODY, and it is where the only rounding risk in the change lives;
// read it there. AUDIT-2026-09-28.md finding 25.
//
// A WEEK THAT WAS NEVER COMMITTED IS NOT REFUNDABLE HERE, and needs no separate
// path — but only because Commit TAKES THE WEEK AS AN ARGUMENT and any week
// that is over can be committed by anyone at any time. So a buyer holding a
// stranded week's tickets names that week to Commit themselves, and then either
// Resolves it (the normal outcome) or refunds it here if its round was lost.
// Before Commit took that argument this paragraph was simply false: a caller
// could not name the week, Commit could only act on the live one, and a week
// the clock had passed was unreachable by every path in this file — committed
// never, resolved never, refunded never, and counted in heldPots forever.
func Refund(cur realm, week int64) {
	rejectAttachedCoin(cur, "Refund")
	sweepDonations()

	d := getDraw(week)
	if d == nil {
		panic("raffle: no draw for that week")
	}
	if d.Resolved {
		panic("raffle: this week's draw is already resolved")
	}
	if !d.Committed {
		panic("raffle: this week is not committed yet — commit it first; refunds only open on a week nobody settled")
	}
	// TWO TERMS, NOT THREE, SINCE THE DRAND MIGRATION. This gate read
	//
	//	if !d.Abandoned && resolvable(d) && !refundGraceElapsed(d) {
	//
	// where resolvable(d) was the beacon-derived opener: "the round's signature is
	// gone, so this draw is dead". THAT OPENER IS DELETED, not rescaled, because the
	// state it detected cannot occur against drand — see resolvable()'s removal
	// above for why, and for why keeping a reduced version of it would have opened
	// refunds on every live draw immediately.
	//
	// THE Abandoned CHECK STILL COMES FIRST, and its reason is unchanged and is now
	// load-bearing for longer: once this week is in refund it stays in refund,
	// whatever the beacon says later. A pinned round can be relayed by anybody at any
	// time, for ever, so without this a week with some buyers already refunded could
	// be resolved over the original frozen range.
	//
	// THE HEIGHT GATE IS NOW THE ONLY OPENER. Refusing needs both terms — not
	// abandoned, and still inside the grace window. Read refundGraceBlocks for the
	// derivation and for why a beacon-state gate cannot do this job: it cannot
	// distinguish "nobody has relayed the round yet" from "nobody ever will".
	//
	// THE MESSAGE TELLS THE CALLER WHICH OF THE TWO THINGS TO DO, because both are
	// available to them: wait for the window, or relay the round themselves and
	// resolve. The height the window opens at is in Render, in DrawOf and in the
	// Commit event.
	if !d.Abandoned && !refundGraceElapsed(d) {
		panic("raffle: this week's draw is still live — refunds only open once the grace window has elapsed")
	}

	caller := cur.Previous().Address()
	k := string(caller)
	amount := treeInt64(d.spendOf, k)
	if amount <= 0 {
		panic("raffle: nothing to reclaim for that week")
	}

	// THE POINT OF NO RETURN, set on the first refund that actually pays out —
	// never by a refusal above, which must leave the week exactly as it was.
	//
	// AND THE ONE MOMENT SPONSORSHIP IS RETIRED FROM THE DRAW. A sponsored ugnot is
	// attributable to no buyer (see Draw.Sponsored and FundPot), so no Refund can
	// ever return it: if it just sat in d.Pot while every spendOf was zeroed AND NO
	// PATH COULD REACH IT, this week would end with Pot > 0, no claimant and no exit —
	// permanently unreachable money the invariant would go on counting, which is
	// precisely the defect the 2026-09-28 audit's first finding was about.
	//
	// THE FIRST HALF OF THAT SENTENCE IS NO LONGER WHAT HAPPENS AND THE SECOND HALF IS
	// STILL WHY. The money stays in d.Pot and STOPS BEING SPONSORSHIP: retireSponsorship
	// turns it into a per-unit claim held by the addresses that hold units in THIS week —
	// the duel players whose rake it is and the buyers who bought in. So there is a path to
	// it (ClaimDeadWeek), the claim is on named addresses rather than named in a register,
	// and the "unreachable money" objection is answered by the money already being where its
	// owners are. The call is INSIDE the `!d.Abandoned` branch, so it happens exactly once:
	// on the transition, not on every later refund.
	//
	// IT IS ALWAYS THE CLAIMANT CASE HERE, AND THAT IS STRUCTURAL RATHER THAN CHECKED. To
	// reach this line a caller must have a positive spendOf for this week, which only Buy
	// writes, and Buy appends unit weight in the same statement group — so d.tickets.Total()
	// is positive whenever this runs and retireSponsorship's no-holders branch is
	// unreachable from Refund. The no-holders branch belongs to SweepDrawlessWeek's shape 1.
	//
	// AND IT DOES NOT DISTURB THIS CALLER'S OWN REFUND. `amount` was read from spendOf
	// above and retireSponsorship does not touch spendOf, Pot's buyer-facing part, or Cut —
	// so the split below is over exactly the gross this buyer paid. Their share of the dead
	// week's sponsorship is a SEPARATE, later ClaimDeadWeek call. That separation is
	// deliberate: folding the share into spendOf instead would have made Refund re-derive a
	// house cut over money that never paid one, which drives d.Cut negative and turns a
	// buyer's own reclaim into a panic. The arithmetic is in AUDIT-2026-09-28.md finding 31.
	//
	// WHERE IT GOES CHANGED ON 2026-09-29, AND THE OLD DESTINATION WAS A FINDING
	// RATHER THAN UNTIDINESS. This branch used to do `opsPot += s` — the players'
	// side of the duel rake to the house — while SweepDrawlessWeek, twenty lines
	// further down this file, rolled THE SAME MONEY forward into the live week's pot
	// and said in as many words that "a week nobody entered should not hand the
	// players' share back to the house". Two functions moved identical money to
	// opposite destinations and nothing reconciled them. AUDIT-2026-09-28.md finding
	// 16 records the general lesson: THAT ASYMMETRY IS A FINDING, NOT A TIDINESS
	// PROBLEM — it will be exploited in whichever direction pays.
	//
	// AND SINCE EARNED ENTRIES EXIST IT WAS EXPLOITABLE, CHEAPLY. A week can now
	// accumulate a whole week of duel rake as ticket weight with no spendOf backing
	// (FundPotWithEntries). A griefer bought ONE ticket into such a week, waited for
	// it to end, committed it (permissionless), let refundGraceBlocks pass with
	// nobody relaying the round, and then called Refund: the branch fired, the ENTIRE
	// week of rake moved to opsPot, Resolve was shut for ever, every earned-entry
	// holder got nothing, and WithdrawOps — permissionless, fixed destination — sent
	// the lot to the ops vault. Net cost 5,000 ugnot of house cut; net beneficiary
	// the house. THE PARTY BEST PLACED TO TRIGGER IT WAS THE PARTY THAT RECEIVED THE
	// PROCEEDS, which is what makes it unacceptable regardless of how long the window
	// is.
	//
	// SO IT DOES NOT GO TO THE HOUSE, AND THE TWO PATHS AGREE: an abandoned week's
	// sponsorship is the players' money and it stays the players' money. It reduces house
	// revenue in an edge case, which is the safe direction.
	//
	// IT NO LONGER GOES FORWARD TO A FUTURE WEEK EITHER, AND THE PARAGRAPH THAT SAID IT DID
	// IS KEPT BECAUSE IT IS THE ONE A READER WILL HAVE IN THEIR HEAD. It said: "SO IT NOW
	// GOES FORWARD TO A FUTURE WEEK'S POT RATHER THAN TO THE HOUSE, EXACTLY AS
	// SweepDrawlessWeek DOES... it becomes part of a prize somebody can still win." Which
	// week that prize belonged to was the whole of findings 28 and 31, and forward motion is
	// what both of them had in common. It now goes NOWHERE: the week's own unit holders take
	// it, in the week it is already in.
	//
	// AND WHICH FUTURE WEEK IS NOT THIS CALLER'S TO DECIDE — FINDING 28, AND THE
	// PARAGRAPH THAT USED TO BE HERE IS WHY. It said: "THE ONE CASE SweepDrawlessWeek
	// ALREADY DOCUMENTS IS THE ONE CASE THAT FALLS BACK: if no live week can be opened
	// there is nowhere to roll it to. See rolloverTarget, which is the shared decision...
	// So when there is no live week the money goes to opsPot as it always did, which is
	// finding 12's residual and nothing wider." BOTH SENTENCES WERE TRUE AND TOGETHER
	// THEY WERE A DEFECT:
	//
	//   - THE DESTINATION WAS currentWeek(), evaluated in this call, so a caller chose
	//     it by choosing when to call. Buy into a week at its very end, refund the dead
	//     week in the same block, and a week of duel rake joins a pot whose competing
	//     ticket set is already known and closed. The loss fell on the dead week's
	//     earned-entry holders — duel players who paid the rake — and the beneficiary
	//     was whoever dominated the week the caller picked.
	//   - AND THE "no live week" FALLBACK WAS NOT AN EDGE CASE AT ALL. Refunds open 21
	//     days after a commit; the beacon's estimate goes unusable after ONE day without
	//     a relay. In the scenario a refund exists for, the beacon is stale by
	//     definition, so on a quiet realm the fallback was the NORMAL path and the rake
	//     went to the house — finding 16 undone by its own escape hatch.
	//
	// WHAT HAPPENS INSTEAD, IN ONE LINE: the sponsorship becomes a per-unit claim on THIS
	// week, payable to THIS week's unit holders, and nothing in this call names a week,
	// reads a clock or reads the beacon. Read retireSponsorship for the arithmetic and the
	// dust, and ClaimDeadWeek for the exit.
	//
	// THE INTERMEDIATE DESIGN, RECORDED BECAUSE IT WAS WRONG IN A WAY THAT LOOKED RIGHT.
	// For one day this branch called markCarryPending: the week was REGISTERED and the next
	// week record to be created pulled the money in at its own birth, which was meant to
	// make the destination unchoosable. It did not. The caller who creates that week is the
	// caller who calls Buy, so buying one ticket in the final block of a quiet week both
	// opened the record and absorbed every pending carry into a week whose entire ticket set
	// was theirs — certainty, for the price of the house cut. AUDIT-2026-09-28.md finding 31.
	//
	// THIS FUNCTION THEREFORE NO LONGER HAS A DESTINATION TO FAIL TO FIND, which is a
	// strictly stronger form of the promise it always had to keep: Refund must never
	// panic for a reason in another realm, because a payout path a stale beacon could
	// hold shut would be a fresh "money in, no way out" defect. It now reads no beacon at
	// all on this path. THE SWEEP MAY STILL REFUSE AND THIS FUNCTION STILL MAY NOT — see
	// SweepDrawlessWeek's clock — but the asymmetry is now about a clock, not about
	// whether a destination exists.
	//
	// AND IT CANNOT BE MADE EXPENSIVE ENOUGH TO FAIL EITHER, WHICH IS THE OTHER HALF OF THAT
	// PROMISE AND IS WHY retireSponsorship IS O(1). The obvious way to return money pro rata
	// is to walk the holders and credit each one, and a week's holder set is unbounded — two
	// more holders for every duel played. A loop here would have put a gas ceiling on the
	// FIRST REFUND OF A BUSY WEEK, which is a "money in, no way out" path created by the fix
	// for one. One rate is written instead, in constant time, and each holder derives their
	// own share when they claim.
	//
	// NO WUGNOT LEAVES THE REALM FOR THE TRANSITION, and the week's identity
	// Pot + Cut == sum(spendOf) + Sponsored + Claims holds across it: Sponsored falls by
	// exactly what Claims rises by, except for the sub-unit dust, which leaves Pot and
	// enters opsPot in the same statement. It holds across every refund below too, each of
	// which removes one buyer's gross from both sides. After the last refund this week is
	// Pot == Claims, and every ugnot of that has a named holder who can take it.
	if !d.Abandoned {
		d.Abandoned = true
		if d.Sponsored > 0 {
			retireSponsorship(d)
		}
	}

	// THE REFUNDED BUYER KEEPS THEIR TICKETS ON PURPOSE. d.tickets, d.ownerOf and
	// d.ticketsOf are deliberately NOT touched here: fenwick rejects negative
	// deltas by design and FrozenTotal must never move, so a ticket cannot be
	// retired once sold. That used to mean a refunded buyer kept their full
	// winning probability while holding their money back — harmless now, and only
	// because the line above makes this week unresolvable forever, so no draw over
	// this ticket set will ever happen. DO NOT "FIX" THE UN-RETIRED TICKETS by
	// reopening Resolve on an abandoned week: the tickets are dead weight, the
	// week's exit being one-way is what makes them safe.
	// THE GROSS IS SPLIT BACK INTO THE TWO TERMS IT ARRIVED IN — AUDIT-2026-09-28.md
	// finding 25, and this is the part of that change where the rounding lives.
	//
	// `amount` is the buyer's GROSS payment. At sale time Buy put
	// floor(cost * HouseCutBps / bpsDenom) of each purchase into d.Cut and the rest into
	// d.Pot. To take the money back out without leaving dust in either term, the split
	// is DERIVED THE SAME WAY BUY DERIVED IT — the same mulDiv, the same constants, over
	// this buyer's accumulated gross.
	//
	// WHY THAT IS EXACT AND NOT MERELY CLOSE, which is the whole question:
	//
	//   - THE TWO PARTS ALWAYS SUM TO THE GROSS, unconditionally, because cutPart is
	//     computed and potPart is the REMAINDER. So the per-week identity
	//     Pot + Cut == sum(spendOf) + Sponsored survives ANY rounding whatever: this
	//     call removes `amount` from the right and `amount` from the left. That is what
	//     makes Refund unable to overdraw, and it holds after a partial refund, after
	//     every ordering, and for every value of HouseCutBps.
	//   - THE SPLIT ALSO LANDS ON THE SAME SIDE AS BUY'S, because cutPerTicket's build
	//     guard forbids a TicketPrice/HouseCutBps pair for which the flooring discards
	//     anything. Every cost is a whole number of tickets, so every cut is
	//     tickets * cutPerTicket exactly, and so is every partial sum of them —
	//     therefore floor over the accumulated gross returns precisely the sum of the
	//     cuts that gross contributed. WITHOUT THAT GUARD the two could differ by one
	//     ugnot per buyer, d.Cut could be driven negative by a refund, and
	//     checkInvariant would abort a buyer's reclaim of their own money. The guard is
	//     load-bearing, not hygiene.
	//
	// THE SPONSORSHIP TERM IS ALREADY OUT OF THE POT by the time this runs (the
	// transition above), so the only claims left on this week are gross spends.
	cutPart := int64(mulDiv(uint64(amount), uint64(HouseCutBps), uint64(bpsDenom)))
	potPart := amount - cutPart

	d.spendOf.Set(k, int64(0))
	d.Pot -= potPart
	d.Cut -= cutPart
	heldPots -= potPart
	heldCuts -= cutPart
	if d.Pot < 0 {
		// Unreachable while Pot + Cut == sum(spends) + Sponsored. Loud rather than
		// paying out money that belongs to another week.
		panic("raffle: refund would overdraw the week's pot")
	}
	if d.Cut < 0 {
		// Unreachable for the reason spelled out above: the build guard makes the
		// per-buyer cut derivation exact, so the cut parts of a week's buyers sum to
		// exactly the Cut those buys booked. Loud rather than releasing a fee twice or
		// paying one buyer out of another week's escrow.
		panic("raffle: refund would overdraw the week's escrowed fee")
	}

	// THE FULL TICKET PRICE GOES BACK, NOT 95% OF IT. This is the behaviour change
	// finding 25 is about: the fee was never earned, because the draw never ran.
	wugnot.Transfer(cross(cur), caller, amount)

	chain.Emit("Refund",
		"week", strconv.FormatInt(week, 10),
		"buyer", string(caller),
		"amount", strconv.FormatInt(amount, 10),
		"prizePart", strconv.FormatInt(potPart, 10),
		"feeReturned", strconv.FormatInt(cutPart, 10),
		"pot", strconv.FormatInt(d.Pot, 10),
		"escrowedCut", strconv.FormatInt(d.Cut, 10))
	checkInvariant()
}

// --- ClaimDeadWeek -------------------------------------------------------

// ClaimDeadWeek pays the caller their pro-rata share of the sponsorship that a DEAD week's
// draw never got to pay out, and returns the amount. PERMISSIONLESS, self-service only —
// a caller can only ever claim their own share — and it is the EXIT for the claim term
// retireSponsorship creates. AUDIT-2026-09-28.md finding 31.
//
// WHY IT IS A NEW ENTRY POINT AT ALL, WHICH IS THE ONE QUESTION WORTH ANSWERING HERE. The
// cheaper design is to fold each holder's share into their spendOf and let the existing,
// already-audited Refund be the exit — no new function, no new term, no new tree. THAT DOES
// NOT WORK, AND THE ARITHMETIC IS WHY RATHER THAN A JUDGEMENT CALL:
//
//	Refund re-derives the house fee it must give back as
//	    cutPart = floor(gross * HouseCutBps / bpsDenom)
//	and decrements d.Cut by it. That derivation is EXACT — see cutPerTicket's build guard —
//	only because a spendOf is always a whole number of ticket prices, so its floor is
//	precisely the sum of the cuts those purchases booked.
//
//	A sponsorship share booked NO CUT. Add a share s to a buyer whose gross was
//	g = n * TicketPrice and Refund derives floor((g+s)/20) = n*500_000 + floor(s/20), while
//	d.Cut only ever received n*500_000. d.Cut goes NEGATIVE by floor(s/20) and Refund's own
//	"refund would overdraw the week's escrowed fee" panic fires — so the buyer cannot
//	reclaim their own ticket money at all. Worse in the pure-earned case: a holder with no
//	purchase gets gross s against a week whose Cut is 0, and floor(s/20) is stolen from
//	nothing. THE FIX FOR A FUND-STRANDING DEFECT WOULD HAVE CREATED ONE.
//
//	The identity itself survives — Refund removes `amount` from both sides whatever the
//	rounding — which is exactly what makes this dangerous: checkInvariant and AuditFailure
//	stay green right up to the panic. It is the Cut term, not the identity, that breaks.
//
// SO THE CLAIM IS A SEPARATE TERM WITH ITS OWN EXIT, AND IT CARRIES NO FEE BY CONSTRUCTION:
// sponsorship never paid a house cut on the way in and this pays none on the way out. The
// term appears in checkInvariant (heldClaims) and in AuditFailure (per week, and in the
// aggregate, and re-derived against claimedOf by deadWeekClaimFailure), which is the price
// of not reusing Refund and is paid in full.
//
// IT HAS NO CLOCK, NO BEACON READ AND NO REFUSABLE DEPENDENCY, deliberately. By the time a
// claim exists the week is already abandoned — every gate that had to be waited out
// (Refund's grace window, or SweepDrawlessWeek's) was waited out before retireSponsorship
// ran — so a second wait would only be a second thing that could go wrong on a payout path.
// Compare ReclaimStrandedCarry, which this replaces: that needed a beacon test AND a
// three-week long stop because it was trying to find a destination. There is nothing to
// find.
//
// IT IS O(log N) AND ALL-OR-NOTHING PER HOLDER. The share is derived from the rate and the
// holder's unit weight at call time rather than stored per holder at abandonment, which is
// what keeps the abandonment transition constant-time (read retireSponsorship). The weight
// cannot have changed since: an abandoned week is always a past week, and Buy and
// FundPotWithEntries only ever touch currentWeek(). One claimedOf entry therefore settles a
// holder for ever, and a second call finds it and refuses.
//
// A REFUNDED BUYER MAY STILL CLAIM, AND THAT IS CORRECT, NOT A LOOPHOLE. Refund returns the
// gross they paid for their tickets; this returns their share of money that was never
// theirs to pay and never anybody's to win. The two are different money with different
// owners, and the week's identity keeps them apart — spendOf on one side, Claims on the
// other. A holder with earned entries and no purchase has a claim here and nothing to
// refund, which is the whole point of finding 15's players being paid.
//
// BOOKS FIRST, TRANSFER SECOND, as in Resolve, Refund and WithdrawOps.
//
// Panics if there is no record for the week, if that week never distributed anything, if
// the caller holds no units in it, or if the caller has already claimed.
// ClaimSponsorRefund returns a sponsor's payment from a week that died without
// drawing. It pays the GROSS — the house's 5% included — because the fee was only
// ever earned by a draw actually running, and this draw never ran.
//
// THE OWNER'S RULING, 2026-09-30: a sponsor's money is "either returned to
// sponsor or rolls over until a draw happens". Rolling forward is what
// AUDIT-2026-09-28.md findings 28 and 31 removed — the caller chose which week it
// landed in by choosing when to call, and could aim it at a draw they already
// dominated. So it is returned, and it is PULLED rather than pushed: paying up to
// maxSponsorsPerWeek addresses inside retireSponsorship would put those transfers
// on the critical path of a buyer's own Refund, where one failing recipient could
// block the week.
//
// IT DOES NOT COMPETE WITH ClaimDeadWeek. That pays earned-entry holders out of
// the duel's OWNERLESS rake; this pays named sponsors out of money that never
// entered that pool, because retireSponsorship carves it out first. The two draw
// on different halves of the same pot and neither can reach the other's.
func ClaimSponsorRefund(cur realm, week int64) int64 {
	rejectAttachedCoin(cur, "ClaimSponsorRefund")
	sweepDonations()

	d := getDraw(week)
	if d == nil {
		panic("raffle: no draw for that week")
	}
	if d.Resolved {
		panic("raffle: that week's draw was resolved — the sponsorship did its job and there is nothing to refund")
	}
	if !d.Abandoned {
		panic("raffle: that week is not dead — a sponsorship is only refundable once the week has been abandoned")
	}
	// THE ALREADY-CLAIMED CHECK COMES FIRST, and the order is the whole point. The
	// last sponsor to claim takes SponsorRefundable to zero, so a caller checking
	// their own second attempt would otherwise be told the week owes nobody anything
	// — true, and useless to them. They want to know THEY have already had it.
	caller := cur.Previous().Address()
	k := string(caller)
	if d.sponsorRefundedOf != nil && d.sponsorRefundedOf.Has(k) {
		panic("raffle: you have already reclaimed this week's sponsorship")
	}
	if d.SponsorRefundable <= 0 {
		panic("raffle: that week owes its sponsors nothing")
	}

	// THE SUM OF THIS CALLER'S OWN ENTRIES, and nobody else's. Walking the list is
	// bounded by maxSponsorsPerWeek, which is why that bound exists.
	owed := int64(0)
	for _, sp := range d.Sponsors {
		if sp.By == caller {
			owed += sp.Amount
		}
	}
	if owed <= 0 {
		panic("raffle: you did not sponsor that week")
	}
	if owed > d.SponsorRefundable {
		// Unreachable while the carve-out is exact, and asserted rather than assumed:
		// this is the line between paying a sponsor and overdrawing the pool that
		// holds every other sponsor's money.
		panic("raffle: that refund would overdraw what the week owes its sponsors")
	}

	if d.sponsorRefundedOf == nil {
		d.sponsorRefundedOf = avl.NewTree()
	}
	d.sponsorRefundedOf.Set(k, true)
	d.SponsorRefundable -= owed
	heldSponsorRefunds -= owed
	d.Pot -= owed
	heldPots -= owed
	if d.Pot < 0 {
		panic("raffle: that refund would overdraw the week's pot")
	}

	wugnot.Transfer(cross(cur), caller, owed)

	chain.Emit("ClaimSponsorRefund",
		"week", strconv.FormatInt(week, 10),
		"sponsor", string(caller),
		"amount", strconv.FormatInt(owed, 10),
		"stillOwed", strconv.FormatInt(d.SponsorRefundable, 10),
		"pot", strconv.FormatInt(d.Pot, 10))
	checkInvariant()
	return owed
}

// SponsorRefundableFor is what a dead week owes ONE sponsor, and zero once they
// have pulled it. Without it a sponsor has to fetch SponsorsOf, sum their own
// rows by hand, and still cannot tell whether they already claimed — the tree
// that records that is unexported. 2026-09-30 audit, Y3.
func SponsorRefundableFor(week int64, addr address) int64 {
	d := getDraw(week)
	if d == nil || d.SponsorRefundable <= 0 {
		return 0
	}
	if d.sponsorRefundedOf != nil && d.sponsorRefundedOf.Has(string(addr)) {
		return 0
	}
	owed := int64(0)
	for _, sp := range d.Sponsors {
		if sp.By == addr {
			owed += sp.Amount
		}
	}
	return owed
}

// SponsorRefundableOf is what a dead week still owes its sponsors.
func SponsorRefundableOf(week int64) int64 {
	d := getDraw(week)
	if d == nil {
		return 0
	}
	return d.SponsorRefundable
}

func ClaimDeadWeek(cur realm, week int64) int64 {
	rejectAttachedCoin(cur, "ClaimDeadWeek")
	sweepDonations()

	d := getDraw(week)
	if d == nil {
		panic("raffle: no draw for that week")
	}
	if d.ClaimPerUnit <= 0 {
		// COVERS THREE STATES AND THE MESSAGE NAMES THE USEFUL ONE: the week is still live,
		// or it is dead but held no sponsorship, or its sponsorship was smaller than its
		// unit count and was therefore all sub-unit dust (read retireSponsorship). None of
		// them owes the caller anything.
		panic("raffle: that week has no dead-week share to claim")
	}
	if d.Resolved {
		// Unreachable: a claim rate is only ever written on an abandoned week and an
		// abandoned week can never be resolved. Loud rather than paying a claim out of a
		// pot that has already gone to a winner.
		panic("raffle: that week's draw was resolved — its pot went to the winner")
	}

	caller := cur.Previous().Address()
	k := string(caller)
	// EARNED UNITS ONLY — AUDIT-2026-09-28.md finding 34. This read was
	// treeInt64(d.ticketsOf, k), which counted the caller's BOUGHT units too and so paid a
	// refunded buyer a share of the duel players' rake, against a refund that had already
	// returned their whole gross. The two bases must agree with the divisor
	// retireSponsorship used, and that divisor is earnedTotal.
	units := treeInt64(d.earnedOf, k)
	if units <= 0 {
		// THE MESSAGE NAMES THE BASIS, because "I hold 400 units of that week" is exactly what
		// a refused buyer will be looking at. Bought units are not a claim on this money: they
		// contributed nothing to it and Refund returns what they did contribute, in full.
		panic("raffle: you hold no earned entries in that week")
	}
	if d.claimedOf.Has(k) {
		panic("raffle: you have already claimed that week's share")
	}

	// NO OVERFLOW GUARD IS NEEDED AND THE BOUND IS WORTH STATING. units <= earnedTotal
	// always (earnedOf and earnedTotal have one writer and it increments both by the same
	// amount), and ClaimPerUnit was floor(Sponsored / earnedTotal), so
	// units * ClaimPerUnit <= earnedTotal * ClaimPerUnit <= Sponsored, which was a real wugnot
	// balance. The Claims comparison below is the belt to that: it is the same statement
	// made against a number the audit re-derives independently.
	amount := units * d.ClaimPerUnit
	if amount <= 0 || amount > d.Claims {
		// Unreachable while deadWeekClaimFailure's re-derivation holds. Loud rather than
		// paying one holder out of another's share.
		panic("raffle: that week's dead-week share does not cover this holder's claim")
	}

	d.claimedOf.Set(k, amount)
	d.Claims -= amount
	d.Pot -= amount
	heldPots -= amount
	heldClaims -= amount
	if d.Pot < 0 {
		// Unreachable while Pot + Cut == sum(spendOf) + Sponsored + Claims. Loud rather
		// than paying out money that belongs to another week.
		panic("raffle: claim would overdraw the week's pot")
	}

	wugnot.Transfer(cross(cur), caller, amount)

	chain.Emit("ClaimDeadWeek",
		"week", strconv.FormatInt(week, 10),
		"holder", string(caller),
		"units", strconv.FormatInt(units, 10),
		"perUnit", strconv.FormatInt(d.ClaimPerUnit, 10),
		"amount", strconv.FormatInt(amount, 10),
		"unclaimed", strconv.FormatInt(d.Claims, 10),
		"pot", strconv.FormatInt(d.Pot, 10))

	// AND WHEN THE LAST HOLDER IS PAID, SAY SO — AUDIT-2026-09-28.md finding 37, which is the
	// 2026-09-29 audit's open question about heldClaims. THE AGGREGATE CANNOT DISTINGUISH
	// "AWAITING HOLDERS WHO WILL COME" FROM "FROZEN FOR EVER": both are a positive number. This
	// event is the moment one week stops being either, it fires exactly ONCE per week — on the
	// claim that empties it, and Claims can never rise again — so an operator can subtract
	// settled weeks from heldClaims by reading the log alone, with no iteration over the realm.
	// UnclaimedHoldersOf answers the complementary question for a week that has NOT emptied:
	// how many named addresses are still owed.
	//
	// EMITTED AFTER THE PAYMENT'S OWN EVENT AND AFTER THE TRANSFER, so a reader of the log sees
	// the claim and then the week closing, in that order, and a reverted transaction emits
	// neither.
	if d.Claims == 0 {
		chain.Emit("DeadWeekFullyClaimed",
			"week", strconv.FormatInt(week, 10),
			"perUnit", strconv.FormatInt(d.ClaimPerUnit, 10),
			"earnedUnits", strconv.FormatInt(d.earnedTotal, 10),
			"heldClaims", strconv.FormatInt(heldClaims, 10),
			"height", strconv.FormatInt(runtime.ChainHeight(), 10))
	}
	checkInvariant()
	return amount
}

// --- SweepDrawlessWeek ---------------------------------------------------

// SweepDrawlessWeek rolls a FINISHED week's sponsorship forward into the live week's
// pot, when nobody ever bought a ticket in it. PERMISSIONLESS, like Commit.
//
// THERE ARE TWO SWEEPABLE SHAPES SINCE 2026-09-29 AND THE SECOND HAS A CLOCK ON IT:
// a week with NO TICKETS AT ALL (the original drawless week, sweepable as soon as it is
// over) and a week with TICKETS BUT NO SPEND — every entry earned by duel play — which
// is sweepable only once it is committed and refundGraceElapsed has gone true, and
// which is marked Abandoned when it is. The full reasoning, including why "zero spend"
// alone would have been a fund-destroying gate, is in the body above the shape test.
// AUDIT-2026-09-28.md finding 17.
//
// FINDING 15 MADE THIS FUNCTION MUCH HARDER TO REACH AND IT IS DELIBERATELY KEPT.
// A week of duel rake used to end with sponsorship and a zero ticket total, which is
// exactly the state this function exists for. Now the duel's deliveries bring
// ENTRIES with them (FundPotWithEntries), so such a week normally has tickets, is a
// real draw, and this function correctly refuses it — its sponsorship is a prize
// somebody can win rather than money nobody can reach. The states that still land
// here are real and small: a rake too small to buy one whole entry
// (rake < EntryUnitPrice), a duel both of whose parties played from realm code and so
// earned nothing, and any plain FundPot sponsorship from a caller that is not the
// duel. DO NOT DELETE IT ON THE GROUNDS THAT THE COMMON CASE IS GONE: every one of
// those states still strands money without it, and that was the sixth of this
// product's "money in, no way out" findings.
//
// THE DEFECT IT CLOSES. FundPot credits the live week and creates that week's
// record if it does not exist yet, so a week in which duels were collected but
// nobody ever bought a raffle ticket ends the week holding sponsorship in a Draw
// with a zero ticket total. Commit rightly refuses that week (no tickets, no unit
// to draw, no owner to pay), Resolve and Refund both require Committed, and
// FundPot only ever funds the live week — so before this function that
// sponsorship was unreachable by EVERY path in this realm, permanently, while
// heldPots went on counting it and checkInvariant and AuditFailure stayed green
// over money that was gone. That is the same class of defect as the 2026-09-28
// audit's first and most serious finding, and it is not an exotic state: a quiet
// raffle week with an active coin flip is an ordinary Tuesday.
//
// WHERE THE MONEY GOES, AND WHY NOT opsPot, AND WHY IT DOES NOT GO ANYWHERE AT ALL. It
// goes BACK TO THE PEOPLE WHO HOLD UNITS IN THIS WEEK, pro rata — and for shape 1, which
// has no unit holders whatsoever, it goes to opsPot because there is provably nobody else.
// Read retireSponsorship; the branch this function takes is exactly `pureEarned` and is
// stated again at the call site. This money is the PLAYERS' side of the duel rake (see
// r/splash/arcade/duel's Collect: the ops share went to r/splash/ops already, and what
// arrives here is deliberately the rest), so on shape 2 it lands back on the duel players
// who generated it.
//
// TWO SENTENCES THIS REPLACES, IN ORDER, BECAUSE THE SEQUENCE IS THE LESSON. First: "So it
// rolls forward to the live week's pot" — the live week being whichever week the caller
// chose to fire in (finding 28). Then: "It marks the week and registers it
// (markCarryPending); the next week record to be created absorbs it at its own birth...
// to a week nobody in this transaction can name" — except that the caller who opens that
// week is the caller who calls Buy, so they could name it after all, and be its only
// entrant (finding 31). Both sentences described a destination. There is none now.
//
// AND REFUND NOW AGREES, WHICH IT DID NOT UNTIL 2026-09-29. This paragraph used to
// end "Contrast Refund, which moves an abandoned week's sponsorship to opsPot: there
// the week HAD entrants and they are being paid back individually, so there is no
// prize left for the sponsorship to enlarge." THE CONTRAST WAS THE DEFECT. Two
// functions in one file moved the same field's money to opposite destinations, and
// since earned entries exist an abandoned week's "entrants" are mostly duel players
// with no spendOf to be paid back at all — so the rationale did not hold either. One
// ticket plus the grace window turned the whole argument into a cheap transfer of a
// week of rake to the house. AUDIT-2026-09-28.md finding 16. Refund's transition now
// retires the sponsorship exactly as this function does, and retireSponsorship is the
// shared step — a step with no destination in it.
//
// THIS FUNCTION STILL DIFFERS FROM REFUND IN ONE WAY, AND MUST, BUT THE DIFFERENCE IS NOW
// A CLOCK RATHER THAN A DESTINATION. It may REFUSE — the live-week rule, the shape tests,
// and the grace window each shape must wait out — because a dead week's sponsorship has no
// claimant and no deadline, so a refusal costs nobody anything and any caller may retry
// for ever. Refund may not refuse, because a buyer is waiting; and since neither function
// looks for a destination any more, there is no longer any state in which Refund COULD be
// refused for want of one. That is strictly stronger than both fallbacks it replaced — the
// immediate opsPot bank of finding 16 and ReclaimStrandedCarry's three-week long stop of
// finding 28 — and both of them are now deleted rather than relocated, because a claim on
// the week the money is already in cannot fail to find anything.
//
// THE DESIGN TENSION, RESOLVED EXPLICITLY SO IT IS NOT "FIXED" BACK. This realm's
// stated principle is that THERE IS NO ROLLOVER, so a drawless week must not
// exist — and Commit still enforces exactly that, unchanged. That principle is
// about TICKET HOLDERS' pots: it stops a week's prize being deferred away from the
// people who entered that week and paid for it. Rolling SPONSORSHIP forward from a
// week that had no entrants whatsoever does not violate it, because there was
// nobody to defer anything away from — no ticket was sold, so no buyer's
// expectation of this week's prize exists to be broken. Do not "restore
// consistency" by deleting this function or by letting Commit accept a zero total;
// the second would reopen the drawless-draw hole, and the first would reopen the
// stranded-money hole.
//
// NO WUGNOT MOVES HERE, and a reader looking for the missing Transfer should stop
// looking. The tokens are already inside this realm — FundPot pulled them in when
// the dead week was sponsored — so this is PURE BOOKKEEPING between two weeks of
// the same realm. The realm's wugnot balance is identical before and after;
// heldPots and heldSponsored each lose and regain exactly the same amount, which
// is why checkInvariant's equality still holds at the end.
//
// Panics if the week is not over yet (a live week may still sell a ticket, which
// would make it a real draw), if there is no record for it, if anybody BOUGHT a
// ticket in it, if it holds no sponsorship, if it is resolved or already abandoned,
// if its entries are all earned and its draw can still happen (uncommitted, or
// inside the grace window), or — defensively — if a ticketless week is somehow
// committed.
func SweepDrawlessWeek(cur realm, week int64) {
	rejectAttachedCoin(cur, "SweepDrawlessWeek")
	sweepDonations()

	if week >= currentWeek() {
		// THE SAME "ONLY ONCE IT IS OVER" RULE AS Commit, and for a reason of its
		// own: the live week can still sell its first ticket, at which point it is
		// a real draw whose buyers are entitled to the sponsorship sitting in it.
		// Sweeping it would take the prize out from under a buyer mid-week.
		panic("raffle: a week can only be swept once it is over")
	}

	d := getDraw(week)
	if d == nil {
		panic("raffle: no draw for that week")
	}
	// RESOLVED AND ABANDONED ARE ASKED FIRST, and for the PURE-EARNED shape below they
	// are not defensive at all: a swept pure-earned week IS abandoned afterwards, so
	// this is what makes a second sweep of one impossible.
	if d.Resolved {
		panic("raffle: that week's draw is already resolved")
	}
	if d.Abandoned {
		panic("raffle: that week was abandoned and refunded; its sponsorship has already left the pot")
	}

	// THERE ARE TWO SWEEPABLE SHAPES AND THE SECOND IS GATED ON A CLOCK. Both are
	// "money arrived and no ticket was ever BOUGHT", which is what weekHasNoSpend
	// tests; they differ in whether any ticket WEIGHT exists.
	//
	//  1. NO TICKETS AT ALL — the original drawless week. Never committable, so never
	//     resolvable or refundable: sweepable the moment it is over.
	//  2. TICKETS BUT NO SPEND — a PURE-EARNED week (finding 15). Every unit credited
	//     to a duel player through FundPotWithEntries, not one ticket bought. It IS a
	//     real draw and Resolve is its proper exit, so it is sweepable ONLY once its
	//     draw can no longer happen: committed, and refundGraceElapsed.
	//
	// WHY SHAPE 2 EXISTS AT ALL — AUDIT-2026-09-28.md finding 17. Such a week is
	// committable, is not shape 1, and CANNOT BE REFUNDED BY ANYBODY: Refund pays
	// spendOf and no caller has a record, so it panics "nothing to reclaim for that
	// week" before it can even set Abandoned. Resolve was therefore its ONLY exit, with
	// no clock-based fallback — and that contradicts this realm's own doctrine at
	// refundGraceBlocks, which says in as many words that a beacon-state gate cannot
	// detect "nobody bothered to relay one" and a clock can. Finding 15 named the state
	// and argued it strands nothing because "the round can always be relayed"; that is
	// an argument about possibility, not about anybody's incentive to spend ~17.0M gas.
	//
	// AND THE GATE IS THE GRACE WINDOW, NOT MERELY "ZERO SPEND", BECAUSE THE NAIVE
	// VERSION IS THE TRAP. Letting this function act on any week with sum(spendOf) == 0
	// would let ANYONE sweep a LIVE, RESOLVABLE pure-earned week forward the instant it
	// ended — destroying a legitimate draw and taking the prize away from the very
	// earned-entry holders the whole of finding 15 exists to pay. That would be worse
	// than the problem. Gating on refundGraceElapsed(d) — the same clock, the same
	// constant and the same derivation that opens Refund for a week with buyers — means
	// the sweep can only fire once the draw has demonstrably NOT happened for the full
	// window. Before that, Resolve is the only exit and that is correct.
	//
	// IT MARKS THE WEEK WITH THE EXISTING ONE-WAY Abandoned FLAG rather than inventing a
	// second one, so Resolve and Capture refuse it for ever by exactly the checks they
	// already apply to a refunded week. See the transition further down.
	noSpend := weekHasNoSpend(d)
	if !noSpend {
		// A WEEK SOMEBODY BOUGHT A TICKET IN IS A REAL DRAW and belongs to
		// Commit/Resolve/Refund. Sweeping one would take a pot away from the buyers who
		// paid into it, which is the very thing the no-rollover principle forbids.
		panic("raffle: that week sold tickets — it is a real draw, so Commit and Resolve it (or Refund it), never sweep it")
	}
	pureEarned := d.tickets.Total() != 0
	if pureEarned {
		if !d.Committed {
			// THE DRAW CAN STILL HAPPEN AND IS THE RIGHT EXIT. Commit is permissionless
			// and takes the week as an argument, so anyone who wants this week settled —
			// every earned-entry holder, for a start — can commit it right now.
			panic("raffle: that week's entries were all earned and its draw can still happen — commit it and resolve it, and only sweep it if the grace window passes with no draw")
		}
		if !refundGraceElapsed(d) {
			// THE SAME CLOCK REFUND USES, FOR THE SAME REASON. Read the block above: a
			// sweep before this point would destroy a live draw.
			panic("raffle: that week's draw is still live — a week whose entries were all earned may only be swept once the grace window has elapsed")
		}
	} else {
		// DEFENSIVE AND UNREACHABLE. With a zero ticket total the week can never have
		// been committed (Commit refuses a zero total). Stated anyway, loudly, because
		// this function retires money from a week and a silent sweep of a week that had
		// somehow reached that state would be far worse than a failed transaction. (The
		// Resolved and Abandoned halves of the old trio moved above, where they are
		// load-bearing for shape 2.)
		if d.Committed {
			panic("raffle: that week is committed — it is a real draw, not a drawless one")
		}

		// AND SHAPE 1 HAS A CLOCK TOO, SINCE 2026-09-29 — AUDIT-2026-09-28.md finding 28.
		// It is the SAME WINDOW shape 2 waits out (refundGraceBlocks), counted from the
		// height the week ENDED rather than from a commit, because a ticketless week can
		// never be committed and therefore has no CommittedAt to count from.
		//
		// WHY A TICKETLESS WEEK NEEDS A CLOCK AT ALL, GIVEN THAT ITS MONEY HAS NO
		// CLAIMANT AND NO DEADLINE. Because without one, the sweep was FREE AND INSTANT
		// THE MOMENT A WEEK ENDED, and that is what made finding 28's chain possible: a
		// week that receives carried sponsorship is created EMPTY, so if nobody buys into
		// it, it is a ticketless, spend-free week holding sponsorship the instant it ends
		// — this exact shape. One transaction per hop, no wait, and the money could be
		// walked week by week until it stood where the caller wanted it.
		//
		// THAT CHAIN CANNOT BE BUILT ANY MORE AND THE CLOCK IS KEPT ANYWAY, DELIBERATELY.
		// Finding 31 removed the hop itself: no week ever receives another week's
		// sponsorship, so there is no such thing as a week "created empty holding carried
		// money", and the shape this clock was the belt for no longer exists. The gate is
		// retained because it costs nobody anything — the money has no claimant and no
		// deadline, and any caller may sweep the moment the window passes or a year later —
		// and because removing a gate is a change with its own risk, made on its own day.
		// THIS COMMENT IS THE RECORD THAT ITS ORIGINAL JUSTIFICATION IS RETIRED, so that
		// nobody later cites the chain as a live reason.
		//
		// IT STRANDS NOTHING. The money stays in the week, visible in SponsoredOf and in
		// Render, and the sweep has no expiry: any caller may sweep it the moment the
		// window passes, or a year later. The only thing the clock removes is the ability
		// to do it IMMEDIATELY AND REPEATEDLY.
		if runtime.ChainHeight() < weekEndHeight(week)+refundGraceBlocks {
			panic("raffle: that week has no tickets, but its sweep window has not opened yet — a ticketless week may only be swept once the grace window has elapsed since it ended")
		}
	}

	// BEFORE THE ASSERTIONS BELOW, WHICH IS THE WHOLE POINT. d.Cut != 0 asserts that
	// a swept week holds no escrowed fee, on the reasoning that a fee can only arrive
	// with a ticket SALE — true until Sponsor gave a fee a second way in. Folding
	// first restores the assertion's original meaning exactly: whatever Cut remains
	// after the sponsors' share has gone home must still be a ticket-sale fee, and
	// must still be impossible here.
	foldSponsorCut(d)

	amount := d.Sponsored
	if amount <= 0 {
		panic("raffle: that week holds no sponsorship — there is nothing to sweep")
	}
	if d.Pot != amount {
		// Unreachable: BOTH sweepable shapes have no spend record — that is what
		// weekHasNoSpend established above — so the pot identity
		// Pot + Cut == sum(spendOf) + Sponsored reduces to Pot == Sponsored for either
		// of them, given the zero Cut asserted just below. Loud rather than moving a
		// number that does not describe the week it came from.
		panic("raffle: drawless week's pot does not equal its sponsorship")
	}
	if d.Cut != 0 {
		// Unreachable, and asserted rather than assumed — AUDIT-2026-09-28.md finding
		// 25. An escrowed fee can only arrive with a ticket SALE, and both sweepable
		// shapes require sum(spendOf) == 0, so a swept week has no fee to release.
		// Stating it here is what stops this function silently moving a week's
		// sponsorship forward while leaving an unearned fee behind in a week it has
		// just marked Abandoned — which, having no spendOf record to refund it
		// through, nobody could ever reclaim. That would be a new "money in, no way
		// out" path, so it is a loud refusal and not a rollover.
		panic("raffle: a week with no spend is holding an escrowed fee")
	}

	// THE DESTINATION USED TO BE CHOSEN HERE AND IT IS NOT CHOSEN ANYWHERE ANY MORE —
	// AUDIT-2026-09-28.md finding 28. These lines stood here:
	//
	//	dest := currentWeek()
	//	if dd := getDraw(dest); dd != nil {
	//		if dd.Committed { panic(...) }
	//		if dd.Abandoned { panic(...) }
	//	}
	//
	// with a `dd := getOrCreateDraw(dest)` and a two-sided transfer below. Every one of
	// those lines was correct about the week it named; what was wrong is that it named
	// the week that was live AT THE MOMENT A PERMISSIONLESS CALLER CHOSE TO FIRE, so the
	// caller selected where other people's money went by selecting when to call. The
	// defensive refusals are gone with it because there is nothing left to refuse: this
	// function no longer touches a second week, creates no record, reads no beacon, and
	// takes no destination. It retires the money where it stands (retireSponsorship).
	//
	// THE SENTENCE THAT STOOD HERE FOR ONE DAY — "It registers, and the destination pulls at
	// its own birth" — WAS FINDING 31. The destination that pulls is a week the caller
	// creates, so the caller still chose it, and could be its only entrant.

	// A SWEPT PURE-EARNED WEEK IS ABANDONED, PERMANENTLY, AND THAT IS THE OTHER HALF
	// OF FINDING 17. Its ticket weight is real and its prize has just left, so
	// without this flag Resolve would still name a winner over the frozen range and
	// pay them a pot of zero — or, worse, a pot the NEXT sweep or sponsorship had
	// refilled. The existing one-way flag is reused rather than a second one invented:
	// Resolve and Capture already refuse an abandoned week with the exact words they
	// use for a refunded one, Refund's own gate then finds nothing to reclaim, and
	// this function refuses it too (the Abandoned check at the top). There is no path
	// that un-sets it.
	//
	// A SHAPE-1 WEEK IS NOW MARKED TOO, AND IT USED NOT TO BE. The retired reasoning:
	// "A SHAPE-1 WEEK IS NOT MARKED, deliberately: it has no tickets, so Commit refuses
	// it for ever anyway and Resolve and Capture cannot be reached at all. Marking it
	// would be a state change with no meaning." THE FLAG HAS A MEANING NOW, which is what
	// changed: Abandoned is the flag retireSponsorship demands before it will convert a
	// week's sponsorship into a claim, the flag that stops this function sweeping the same
	// week twice (the Abandoned check at the top, which for shape 1 was previously
	// unreachable and is now what makes a second sweep impossible), the flag Refund's gate
	// reads, and the flag AuditFailure's "an abandoned week holds no sponsorship" statement
	// is written in. So both shapes are marked, by one line, and "abandoned" now means
	// exactly "this week's draw will never happen and its money has stopped being a prize".
	d.Abandoned = true
	if pureEarned {
		chain.Emit("SweepAbandonedPureEarnedWeek",
			"week", strconv.FormatInt(week, 10),
			"frozenTotal", strconv.FormatInt(d.FrozenTotal, 10),
			"tickets", strconv.FormatInt(d.tickets.Total(), 10),
			"committedAt", strconv.FormatInt(d.CommittedAt, 10),
			"height", strconv.FormatInt(runtime.ChainHeight(), 10))
	}

	// AND THE MONEY IS RETIRED WHERE IT STANDS. The two-sided transfer that used to be here
	// — d.Sponsored to zero, d.Pot down, heldPots and heldSponsored down and back up
	// against a destination week — is gone with the destination, and so is the register
	// (markCarryPending) that replaced it for one day. Read retireSponsorship.
	//
	// WHICH OF ITS TWO BRANCHES RUNS IS STILL EXACTLY `pureEarned`, AND THAT IS THE WHOLE OF
	// THE "SAY WHICH CASE YOU ARE IN" REQUIREMENT AT THIS SITE — but since
	// AUDIT-2026-09-28.md finding 34 the branch retireSponsorship actually tests is
	// d.earnedTotal, so the equality of the two is asserted below rather than assumed:
	//
	//   - SHAPE 2, pureEarned == true: THE CLAIMANT CASE runs. Every unit of this week was
	//     credited to a duel player through FundPotWithEntries — that is what "no spend and a
	//     non-zero ticket total" means — so earnedTotal == tickets.Total() != 0, and the people
	//     who get this money back are exactly the players whose rake it was. This is the case
	//     finding 16 was about, answered without a destination.
	//   - SHAPE 1, pureEarned == false: d.tickets.Total() == 0, so earnedTotal is 0 too (it can
	//     never exceed the ticket total) and THE NO-CLAIMANT CASE runs: the money goes to
	//     opsPot. No address earned a unit of this week — this is a plain FundPot into a week
	//     nobody entered, a duel rake below one entry unit, or a duel both of whose parties
	//     played from realm code. Nobody is wronged because there is nobody to wrong. A week
	//     that HAS earned holders cannot reach this branch: earnedTotal never decreases.
	//
	// THE SHAPE-2 EQUALITY IS ASSERTED, NOT ASSUMED — finding 34's one new obligation at this
	// site. "No spend implies every unit was earned" is true only because appendTickets has
	// exactly two callers and Buy writes a spendOf record in the same transaction as its
	// append; Refund ZEROES a spend record rather than removing it, but an abandoned week is
	// refused at the top of this function, so a refunded week can never arrive here looking
	// spend-free. That is a four-step argument about three other functions, and it decides
	// whether a week's whole sponsorship goes to its players or to the house. So it is
	// checked, loudly, in the one place that depends on it. UNLIKE THE GUARDS INSIDE
	// retireSponsorship, A PANIC HERE COSTS NOBODY THEIR OWN MONEY: this is the sweep, which
	// may refuse (a dead week's sponsorship has no claimant and no deadline, so any caller may
	// retry for ever) — it is emphatically not Refund.
	if pureEarned && d.earnedTotal != d.tickets.Total() {
		panic("raffle: that week has no spend but its earned units do not account for all its ticket units")
	}
	retireSponsorship(d)

	chain.Emit("SweepDrawlessWeek",
		"week", strconv.FormatInt(week, 10),
		"amount", strconv.FormatInt(amount, 10),
		"pureEarned", strconv.FormatBool(pureEarned),
		"pot", strconv.FormatInt(d.Pot, 10),
		"height", strconv.FormatInt(runtime.ChainHeight(), 10))
	checkInvariant()
}

// --- WithdrawOps ---------------------------------------------------------

// WithdrawOps pushes the whole ops pot to opsVaultAddr and returns the amount
// moved. PERMISSIONLESS.
//
// THE DEFECT IT CLOSES, found 2026-09-28 by the engineer implementing that day's
// fifth fix rather than by the audit: opsPot only ever increased. It was written
// in three places — Buy's house cut (now Resolve's released escrow, finding 25),
// sweepDonations' absorbed arrivals, and
// Refund's move of an abandoned week's sponsorship — and read by nothing but the
// invariant and the reads. There was no outflow anywhere in this file, so three
// separate streams of money became permanently unreachable by every path in the
// realm, THE PRODUCT'S ENTIRE REVENUE AMONG THEM. checkInvariant and AuditFailure
// both stayed green over it, because both count opsPot as money the realm holds
// and neither has an opinion about whether anybody can ever reach it. That is the
// same class of defect as the unreachable week (the audit's first finding) and the
// stranded drawless-week sponsorship (SweepDrawlessWeek).
//
// PERMISSIONLESS, AND THAT IS SAFE PRECISELY BECAUSE THE DESTINATION IS FIXED AT
// COMPILE TIME. A reader will look for a caller check here and there is none, on
// purpose: opsVaultAddr is a const, so the caller does not choose where the money
// goes, cannot name themselves, and cannot name a week's pot. All they can do is
// push the house's money to the house — and paying the gas to do somebody else's
// bookkeeping is a favour, not an attack. Gating it on an operator key would buy
// nothing and would put a liveness dependency for the realm's revenue onto one
// key, exactly as it would for Commit, Capture and Resolve. This is
// r/splash/exchange's SettleOps shape, and the property that makes it sound is the
// one tools/raffle_addr_test.go exists to keep true.
//
// IT NEVER REACHES A PLAYER'S MONEY. No Draw is touched: not Pot, not Sponsored,
// not spendOf, not a ticket. The only book that moves is opsPot, which by
// construction holds nothing any buyer can claim — the fee in it was EARNED BY A DRAW
// THAT ACTUALLY RAN (Resolve releases the week's escrow; a week that fails refunds it
// with the gross, finding 25), a donation belongs to whoever chose to give it away, and
// a dead week's sponsorship was never attributable to a buyer at all.
//
// THE CITATION THAT USED TO STAND HERE IS RETIRED: this paragraph said "the cut was
// taken at sale time (see Refund's 'THE HOUSE CUT IS NOT REFUNDED')", and there is no
// such section in Refund any more — finding 25 deleted the behaviour and Refund records
// the retired paragraph verbatim in its place. A citation that outlives the thing it
// cites is how a reader ends up trusting a rule the code stopped following.
// AUDIT-2026-09-28.md finding 29. NOTE THAT THE THIRD STREAM IS NOW ALMOST CLOSED:
// since 2026-09-29 a dead week's sponsorship goes forward to a future week's prize
// and reaches this counter only when no week can be opened at all (Refund's
// transition, and AUDIT-2026-09-28.md finding 16). That is a deliberate reduction in
// house revenue and it is the safe direction.
//
// AND SINCE 2026-09-29 IT CANNOT REACH AN UNEARNED FEE EITHER, which is the point of
// finding 25 from this function's side. The house cut used to arrive in opsPot the
// instant a ticket was sold, so this call could push out money for draws that had not
// happened yet — and the buyers of a week that then failed got 95% back while the
// missing 5% had already left the realm. The fee now sits in Draw.Cut until Resolve
// releases it, heldCuts is a separate term in checkInvariant, and this function does not
// mention either. A caller who withdraws every block still cannot touch a live week's
// escrow.
//
// sweepDonations RUNS FIRST, as in every other mutator, so a donation that
// arrived since the last state change is included in this withdrawal rather than
// left behind for the next one.
//
// BOOKS FIRST, TRANSFER SECOND, exactly as Resolve and Refund do it: opsPot is
// zeroed BEFORE the wugnot leaves, so a re-entrant call — which wugnot's Transfer
// cannot cause today, having no hook or callback, but a future GRC20 might — finds
// an empty pot and panics rather than a balance it can take twice.
//
// THE INVARIANT IS EXACT ACROSS IT, not merely preserved one-sidedly:
// checkInvariant asserts heldPots + opsPot == balance, and this call reduces both
// sides by the same amount. heldPots and heldSponsored are deliberately untouched.
//
// Panics if there is nothing to withdraw.
func WithdrawOps(cur realm) int64 {
	rejectAttachedCoin(cur, "WithdrawOps")
	sweepDonations()

	amount := opsPot
	if amount <= 0 {
		panic("raffle: the ops pot is empty — there is nothing to withdraw")
	}

	opsPot = 0
	wugnot.Transfer(cross(cur), opsVaultAddr, amount)

	chain.Emit("WithdrawOps",
		"amount", strconv.FormatInt(amount, 10),
		"destination", string(opsVaultAddr))
	checkInvariant()
	return amount
}

// --- reads ---------------------------------------------------------------
//
// All plain and non-crossing: a read needs no authority check.

// PotSize is the CURRENT week's prize pot in ugnot: ticket sales after the house
// cut, PLUS whatever FundPot has sponsored into it (Sponsored, below). It is the
// whole amount the winner takes.
func PotSize() int64 {
	d := getDraw(currentWeek())
	if d == nil {
		return 0
	}
	return d.Pot
}

// TicketTotal is the CURRENT week's ticket units sold.
func TicketTotal() int64 {
	return TicketTotalOfWeek(currentWeek())
}

// TicketTotalOfWeek is a given week's ticket units sold: the LIVE total, not
// FrozenTotal, so it is readable before a commit and is zero for a week that
// never sold a ticket.
//
// IT IS THE READ THAT MAKES A DRAWLESS WEEK VISIBLE. DrawOf reports FrozenTotal,
// which is zero on any uncommitted week, so a caller cannot use it to tell "sold
// nothing" from "sold plenty and was never committed". Sweepability turns on
// exactly that distinction: a past week is sweepable when this is zero and
// SponsoredOf is positive. See SweepDrawlessWeek.
func TicketTotalOfWeek(week int64) int64 {
	d := getDraw(week)
	if d == nil {
		return 0
	}
	return d.tickets.Total()
}

// TicketsOf is addr's ticket units in the CURRENT week.
func TicketsOf(addr address) int64 {
	return TicketsOfWeek(currentWeek(), addr)
}

// SpendOf is addr's refundable contribution to the CURRENT week in ugnot: THE GROSS
// TICKET PRICE THEY PAID, house fee included, which is exactly what Refund returns.
//
// THIS COMMENT SAID THE OPPOSITE UNTIL NOW AND THE VALUE NEVER CHANGED. It read: "what
// they paid MINUS the house cut, which is what Refund would return. It is not the gross
// ticket price they paid." That was true until 2026-09-29, when the house fee stopped
// being banked at sale time and started being escrowed per week in Draw.Cut
// (AUDIT-2026-09-28.md finding 25): spendOf became the GROSS in the same change, and
// Refund returns the whole ticket price. The function was correct and its documentation
// was not — THE WORST SHAPE OF ALL FOR AN EXPORTED, FRONT-END-FACING READ, because a
// caller who believed it would display a refund quote 5% short and nothing would ever
// fail. Corrected rather than deleted, because the old sentence is the one a reader may
// have in their head. AUDIT-2026-09-28.md finding 29.
func SpendOf(addr address) int64 {
	return SpendOfWeek(currentWeek(), addr)
}

// TicketsOfWeek is addr's ticket units in a given week, so a front end can
// still show a buyer their past weeks once the clock has moved on.
func TicketsOfWeek(week int64, addr address) int64 {
	d := getDraw(week)
	if d == nil {
		return 0
	}
	return treeInt64(d.ticketsOf, string(addr))
}

// SpendOfWeek is addr's remaining refundable contribution to a given week: their GROSS
// ticket spend, fee included, which is what Refund pays them. Zero once they have been
// refunded. Read SpendOf for the claim this pair used to make and why it is retired.
func SpendOfWeek(week int64, addr address) int64 {
	d := getDraw(week)
	if d == nil {
		return 0
	}
	return treeInt64(d.spendOf, string(addr))
}

// CurrentWeek is the week tickets are being sold into right now.
func CurrentWeek() int64 {
	return currentWeek()
}

// WeekEndHeight is weekEndHeight, EXPORTED: the chain height at which a given week
// stops being the live one. A week is live for heights [WeekEndHeight(week-1),
// WeekEndHeight(week)) — the returned height is the FIRST height of week+1, NOT the
// last height of week, so at exactly this height CurrentWeek already reads week+1.
// A countdown that showed "1 block left" here would be off by one.
//
// IT IS A BLOCK HEIGHT AND DELIBERATELY NOT A TIME. This realm's week is
// raffleWeekDays*blocksPerDay blocks, and blocksPerDay = 26182 encodes an ASSUMED
// 86400/26182 = 3.29998 s per block (read blocksPerDay for how much that assumption is
// allowed to be wrong). The chain does not actually run at that rate: 3.306 s measured
// on gno.land mainnet and 3.376 s on onyx-1. So a caller wanting a wall-clock countdown
// must multiply by a block time IT chooses and own the error; this realm will not
// return seconds or "time remaining", because that would bake one clock's rounding into
// every front end that reads it and make the contract the source of a number it cannot
// know. Nothing on chain converts blocks to seconds and neither does this.
//
// WHY THIS AND NOT AN EXPORTED launchHeight: it is the stronger primitive, not the
// weaker one. raffleWeekDays and blocksPerDay are both unexported, so a LaunchHeight()
// alone could not be turned into a boundary without a caller hardcoding 7*26182 and
// re-implementing the +1 above. This read goes the other way: launchHeight is
// WeekEndHeight(0) - (WeekEndHeight(1) - WeekEndHeight(0)) and the week's length is
// WeekEndHeight(1) - WeekEndHeight(0), so one function answers every question the
// constant would have, with the off-by-one computed once, here, on chain.
//
// NEGATIVE OR FAR-FUTURE week IS NOT REFUSED and returns the arithmetic for it, exactly
// as weekEndHeight does — this is a pure function of week and launchHeight with no
// record lookup, so there is no "no such week" state to report. WeekEndHeight(-1) is
// launchHeight, the height this realm's week 0 began at, which is a useful answer rather
// than an error.
func WeekEndHeight(week int64) int64 {
	return weekEndHeight(week)
}

// CurrentWeekEndHeight is the chain height at which the LIVE week ends: the one number
// a countdown wants. WeekEndHeight(CurrentWeek()), read in a single call.
//
// IT IS ONE CALL ON PURPOSE. Composing the two exported reads off chain means two
// queries at two different chain heights, and a week that turns over between them yields
// a boundary for a week that has already ended — a countdown that jumps backwards by a
// whole week exactly at the moment it matters most. Read here, both halves see one
// height.
//
// A BLOCK HEIGHT, NOT A TIME, for the reasons on WeekEndHeight.
func CurrentWeekEndHeight() int64 {
	return weekEndHeight(currentWeek())
}

// DrawOf reports a week's record: committed, frozen ticket total, beacon round,
// pot, resolved, winner, abandoned, sponsored. All zero for a week that never
// sold a ticket.
//
// ABANDONED IS PART OF THIS TUPLE rather than a separate read because it is not
// a detail: it is the difference between a week that is waiting for its
// randomness and a week that is paying its buyers back and will never have a
// winner. A front end that showed "unresolved" for both would be lying to a
// buyer about whether to expect a draw or to go and claim a refund.
//
// SPONSORED IS PART OF IT for a related reason: pot minus sponsored is what the
// week's buyers put in and could reclaim, and sponsored is what the arcade added
// on top. A buyer looking at a pot deserves to know which part of it is a claim
// of theirs and which is house money that will never be refunded.
//
// COMMITTED-AT IS THE LAST ELEMENT, and it is here so a front end can compute the
// one number a buyer of a stuck week actually wants: CommittedAt +
// refundGraceBlocks, the height at which their money becomes reclaimable whatever
// the beacon does. RefundOpensAt does that arithmetic; this returns the raw
// height so a caller can also show how long the week has been waiting. Zero on an
// uncommitted week, which is exactly the "no refund clock is running yet" case.
func DrawOf(week int64) (bool, int64, int64, int64, bool, address, bool, int64, int64) {
	d := getDraw(week)
	if d == nil {
		return false, 0, 0, 0, false, address(""), false, 0, 0
	}
	return d.Committed, d.FrozenTotal, d.Round, d.Pot, d.Resolved, d.Winner, d.Abandoned, d.Sponsored, d.CommittedAt
}

// RefundGraceBlocks is refundGraceBlocks, EXPORTED so a front end can state the
// window without hardcoding it — the same reason TicketPrice is exported. Read
// refundGraceBlocks for what it means and how it was derived.
func RefundGraceBlocks() int64 { return refundGraceBlocks }

// RefundOpensAt is the chain height from which Refund will pay this week's buyers
// REGARDLESS OF THE BEACON: CommittedAt + refundGraceBlocks.
//
// ZERO MEANS "THERE IS NO FUTURE HEIGHT TO WAIT FOR", which covers three unrelated
// states and a caller must not read any of them as "refundable now": no record for
// the week, not committed yet (nothing is locked up), already resolved (the pot has
// gone to its winner), or already abandoned (refunds are open this instant and the
// height is behind us). Render draws the same distinction, as "n/a".
//
// IT IS NOW AN EXACT HEIGHT, NOT A CEILING, and the change is worth noting because the
// comment used to hedge. It said refunds "may open much earlier through the
// beacon-derived half of Refund's gate — the moment the committed round falls outside
// beacon.PruneWindow unresolved". THAT HALF OF THE GATE NO LONGER EXISTS (see
// resolvable()'s removal), so this height is the only one at which a refund opens, and
// a front end can show it as a fact rather than as a worst case.
func RefundOpensAt(week int64) int64 {
	d := getDraw(week)
	if d == nil || !d.Committed || d.Resolved || d.Abandoned || d.CommittedAt <= 0 {
		return 0
	}
	return d.CommittedAt + refundGraceBlocks
}

// SponsoredOf is the house money in a given week's pot: what FundPot added, and
// therefore the part of the pot no buyer can ever reclaim. Zero for a week that
// was never sponsored.
//
// THE SECOND HALF OF THIS COMMENT WAS FALSE, WAS CORRECTED, AND IS NOW TRUE AGAIN FOR A
// DIFFERENT REASON. It originally said "and zero again once an abandoned week's
// sponsorship has been moved to the ops pot"; that became wrong when the money started
// going forward to a future week (finding 16) and wrong twice over when it stopped moving
// at the moment of abandonment at all (finding 28).
//
// SINCE FINDING 31 THIS IS ZERO ON EVERY ABANDONED WEEK, and that is a guarantee rather
// than an accident: retireSponsorship zeroes the field in the same statement group that
// sets Abandoned, and AuditFailure reports any week where the two disagree. What the money
// became is a per-unit claim on the SAME week — read ClaimPerUnitOf, UnclaimedOf and
// ClaimableOf, and ClaimDeadWeek for the exit. A front end showing an abandoned week should
// show those three, not this one.
// SponsorsOf is the credit lines a week carries, in the order they were bought.
//
// A COPY, NOT THE SLICE. Returning d.Sponsors itself would hand a caller a
// reference into this realm's own storage; the copy is the same discipline as
// every other read here returning values rather than pointers.
func SponsorsOf(week int64) []Sponsorship {
	d := getDraw(week)
	if d == nil {
		return nil
	}
	out := make([]Sponsorship, len(d.Sponsors))
	copy(out, d.Sponsors)
	return out
}

// SponsorCutOf is how much of a week's escrowed fee came from sponsorships
// rather than ticket sales. Zero on a week that has retired its sponsorship,
// which is what makes "the fee found its way out" checkable from outside.
func SponsorCutOf(week int64) int64 {
	d := getDraw(week)
	if d == nil {
		return 0
	}
	return d.SponsorCut
}

func SponsoredOf(week int64) int64 {
	d := getDraw(week)
	if d == nil {
		return 0
	}
	return d.Sponsored
}

// CarryPendingSince AND CarryPendingTotal ARE GONE — AUDIT-2026-09-28.md finding 31. They
// read the carry register, which no longer exists, and there is deliberately no successor
// with the same shape: "how much money is waiting to be moved somewhere" is not a question
// this realm can be asked any more, because no money is waiting and there is nowhere to
// move it to. The three reads below answer the questions that replace it.

// ClaimPerUnitOf is the ugnot each ticket UNIT of a week may reclaim from the sponsorship
// that week's draw never paid out, or 0 for any week that is not abandoned. Read
// Draw.ClaimPerUnit and retireSponsorship.
//
// ZERO ON AN ABANDONED WEEK IS MEANINGFUL AND IS NOT AN ERROR: it means either that the
// week held no sponsorship at all, or that the sponsorship was smaller than the week's unit
// count, so no unit could be given a whole ugnot and the whole amount was sub-unit dust. The
// DeadWeekSponsorshipDistributed and DeadWeekSponsorshipToOps events distinguish the cases.
func ClaimPerUnitOf(week int64) int64 {
	d := getDraw(week)
	if d == nil {
		return 0
	}
	return d.ClaimPerUnit
}

// UnclaimedOf is how much of a dead week's distributed sponsorship its holders have not
// taken yet — Draw.Claims. It is PART OF THAT WEEK'S POT, so PotSizeOf-style reads already
// include it; this read exists so an operator can see how much of a dead week's money is
// still sitting there, and so AuditFailure's heldClaims re-derivation can be read alongside
// it.
func UnclaimedOf(week int64) int64 {
	d := getDraw(week)
	if d == nil {
		return 0
	}
	return d.Claims
}

// ClaimableOf is what `addr` may take out of a dead week right now: their EARNED unit weight
// times the week's claim rate, or 0 once they have taken it. IT IS EXACTLY WHAT ClaimDeadWeek
// WILL PAY, derived the same way and off the same tree, so a front end never has to guess.
//
// IT READS earnedOf AND NOT ticketsOf — AUDIT-2026-09-28.md finding 34, and this read had to
// move in the same commit as ClaimDeadWeek's. A read that disagrees with the entry point it
// mirrors is worse than no read at all: a front end would have shown a refunded buyer a
// positive claimable figure and then watched their transaction abort, which is how a caller
// learns to distrust the whole realm. THE TWO DERIVATIONS ARE NOW ONE EXPRESSION, DUPLICATED
// — earnedOf times ClaimPerUnit — and every test that asserts ClaimDeadWeek's return value
// against this read is what keeps them equal.
//
// A BUYER WHO HOLDS ONLY BOUGHT UNITS READS ZERO HERE, AND THAT IS THE ANSWER, NOT A GAP.
// Their money comes back through Refund, in full, fee included. Read EarnedOfWeek alongside
// TicketsOfWeek to see the two kinds of weight separately.
func ClaimableOf(week int64, addr address) int64 {
	d := getDraw(week)
	if d == nil || d.ClaimPerUnit <= 0 {
		return 0
	}
	k := string(addr)
	if d.claimedOf.Has(k) {
		return 0
	}
	return treeInt64(d.earnedOf, k) * d.ClaimPerUnit
}

// EarnedOfWeek is how many of `addr`'s units in a week were EARNED through duel play rather
// than bought — the basis a dead week's sponsorship is divided on. AUDIT-2026-09-28.md
// finding 34.
//
// IT EXISTS SO THE TWO KINDS OF WEIGHT ARE VISIBLE SEPARATELY. TicketsOfWeek returns the
// draw's basis (both kinds, indistinguishable, which is finding 15's design) and this returns
// the claim's. A front end showing a dead week needs both, because "you hold 412 units and
// your claim is on 12 of them" is the only explanation of a zero ClaimableOf that a buyer
// will accept.
func EarnedOfWeek(week int64, addr address) int64 {
	d := getDraw(week)
	if d == nil {
		return 0
	}
	return treeInt64(d.earnedOf, string(addr))
}

// EarnedTotalOfWeek is a week's whole earned unit count — the divisor retireSponsorship used,
// or will use. Zero on a week whose every unit was bought, which is the state that routes a
// dead week's sponsorship to opsPot rather than to holders.
func EarnedTotalOfWeek(week int64) int64 {
	d := getDraw(week)
	if d == nil {
		return 0
	}
	return d.earnedTotal
}

// UnclaimedHoldersOf is how many named addresses a dead week still owes a share to, and it is
// the other half of AUDIT-2026-09-28.md finding 37 — the audit's open question, "let an
// operator distinguish heldClaims AWAITING LIVE HOLDERS from heldClaims FROZEN FOR EVER".
//
// heldClaims ON ITS OWN CANNOT ANSWER THAT and neither can UnclaimedOf: a positive number
// means the same thing in both cases. This read turns the amount into a COUNT OF PEOPLE, so
// "3,600,000 ugnot owed to 24 addresses" reads differently from "3,600,000 ugnot owed to 24
// addresses that have not moved in a year", and an operator can at least see which weeks are
// settled and which are not. The DeadWeekFullyClaimed event in ClaimDeadWeek is the push
// version of the same fact, for a week that reaches zero.
//
// IT IS O(EARNED HOLDERS) AND THEREFORE A READ-ONLY FUNCTION AND NOTHING ELSE. It is never
// called from a state-changing path — that is the whole reason retireSponsorship writes a
// rate instead of a tree — and a caller who pays the gas to ask is paying for their own
// answer. COLLECT-THEN-LOOP, NEVER A NESTED avl.Iterate: the earnedOf keys are gathered in
// one pass and every claimedOf lookup happens after it, because nesting a second traversal
// inside the first's callback crashes this toolchain's VM outright (see AuditFailure).
//
// ZERO MEANS "NOTHING LEFT TO PAY" and is the answer on a live week, a resolved week, a week
// that never distributed anything, and a week every holder has claimed out.
func UnclaimedHoldersOf(week int64) int64 {
	d := getDraw(week)
	if d == nil || d.ClaimPerUnit <= 0 {
		return 0
	}
	keys := []string{}
	d.earnedOf.Iterate("", "", func(k string, _ any) bool {
		keys = append(keys, k)
		return false
	})
	n := int64(0)
	for _, k := range keys {
		if !d.claimedOf.Has(k) {
			n++
		}
	}
	return n
}

// Unclaimed is the sum of every week's unclaimed dead-week shares — the aggregate
// heldClaims, exposed so it can be read without iterating. It is already inside the pots, so
// it is not a fourth balance.
func Unclaimed() int64 {
	return heldClaims
}

// Sponsored is the house money in the CURRENT week's pot.
func Sponsored() int64 {
	return SponsoredOf(currentWeek())
}

// CapturedRandomness returns what Capture stored for a week, or the empty
// string if nothing was captured. Kept out of DrawOf so DrawOf's shape stays
// stable for callers.
func CapturedRandomness(week int64) string {
	d := getDraw(week)
	if d == nil {
		return ""
	}
	return d.Randomness
}

// OpsPot is the house's EARNED revenue this realm holds, in ugnot: the fees of weeks
// that actually drew, plus absorbed donations, plus any abandoned week's sponsorship
// that had no live week to roll into.
//
// IT IS NOT "THE ACCUMULATED HOUSE CUT" ANY MORE, which is what this comment said until
// 2026-09-29. A live week's fee is NOT in here — it is escrowed in that week and is
// still refundable. Read EscrowedCut and HeldCuts for the unearned half, and finding 25
// for why the two are separate numbers.
func OpsPot() int64 {
	return opsPot
}

// EscrowedCut is the house fee held against one week and NOT YET EARNED, in ugnot: it
// becomes ops revenue if that week resolves and goes back to the buyers if it does not.
// Zero for a week that has resolved, been fully refunded, or never sold a ticket.
func EscrowedCut(week int64) int64 {
	d := getDraw(week)
	if d == nil {
		return 0
	}
	return d.Cut
}

// HeldCuts is the total unearned house fee this realm holds across every week, in ugnot
// — the aggregate of EscrowedCut and the third term in the solvency equality.
func HeldCuts() int64 {
	return heldCuts
}

// --- enumerating the weeks -----------------------------------------------
//
// WHY A LISTER EXISTS AT ALL. Every other read here needs a week number the
// caller already has, and Render is prose. A front end looking for weeks to
// sweep (see SweepDrawlessWeek) had no way to find them except by parsing the
// rendered table, which is a human-readable format with no stability promise.
// Same shape as r/splash/arcade/duel's OfferIDs / DuelIDs, down to the clamp:
// an offset and a limit in, at most `limit` week numbers out, `limit` clamped to
// PageLimit rather than refused. Week numbers only — DrawOf, SponsoredOf and
// TicketTotalOfWeek are the per-week readers, and a batched row reader would mean
// inventing a second serialisation of the same page for callers to parse.

// PageLimit is the most week numbers one Weeks call returns. A larger limit is
// clamped to it, not refused.
const PageLimit int64 = 100

// WeekCount is the number of weeks that have a record: weeks that sold a ticket
// or were sponsored. O(1); avl keeps its size.
func WeekCount() int64 {
	return int64(draws.Size())
}

// Weeks is a window over the recorded week numbers in ASCENDING ORDER: it skips
// `offset` weeks and holds at most min(limit, PageLimit). Empty past the end.
// Negative arguments are a caller error and panic.
//
// Ascending order is week order, not merely key order, because weekKey is
// fixed-width and zero-padded (see keyWidth) — the same property Render relies on.
//
// A CALLER FINDS THE SWEEPABLE WEEKS by walking this and keeping those where
// week < CurrentWeek(), TicketTotalOfWeek(week) == 0 and SponsoredOf(week) > 0.
func Weeks(offset, limit int64) []int64 {
	if offset < 0 {
		panic("raffle: negative offset")
	}
	if limit < 0 {
		panic("raffle: negative limit")
	}
	if limit > PageLimit {
		limit = PageLimit
	}
	remaining := int64(draws.Size()) - offset
	if remaining < limit {
		limit = remaining
	}
	if limit <= 0 {
		return []int64{}
	}
	weeks := make([]int64, 0, limit)
	// IterateByOffset is avl's own offset-and-count traversal, O(log n + limit);
	// it is not a full scan followed by a slice.
	draws.IterateByOffset(int(offset), int(limit), func(key string, _ any) bool {
		weeks = append(weeks, weekOfKey(key))
		return false
	})
	return weeks
}

// weekOfKey inverts weekKey. ParseInt reads the zero padding fine; a key that
// does not parse cannot have come from weekKey, so it is a corrupt tree and not
// a case to paper over.
func weekOfKey(key string) int64 {
	week, err := strconv.ParseInt(key, 10, 64)
	if err != nil {
		panic("raffle: malformed week key " + key)
	}
	return week
}

// Render is the human-readable view. It ITERATES THE avl.Tree in key order,
// which is week order because weekKey is fixed-width and zero-padded, so the
// output is byte-identical across runs. A Go map here would randomise the order
// and make the rendered state unreproducible.
// sponsorText makes a stranger's credit line safe to put in this realm's markdown.
//
// TWO ESCAPES, NOT ONE. sanitize.InlineText handles the markdown and HTML
// metacharacters; the pipe is escaped separately because Render's per-week table
// is pipe-delimited and a label is allowed to contain '|' — 64 bytes is ample to
// forge a cell and fake a column. The list below is not a table today, and the
// pipe escape is here anyway so that moving this text into one later cannot
// reintroduce the hole. Same two-step, and the same reasoning, as the duel's.
//
// THE ESCAPING IS HERE AND NOT IN Sponsor DELIBERATELY: the stored value stays
// exactly what the sponsor typed, so every reader holds one thing rather than
// having to know whether their copy was pre-escaped.
func sponsorText(s string) string {
	return strings.ReplaceAll(sanitize.InlineText(s), "|", "\\|")
}

// renderSponsors lists a week's credit lines — the thing a sponsorship actually
// buys. Empty string when there are none, so the section simply does not appear.
func renderSponsors(week int64) string {
	d := getDraw(week)
	if d == nil || len(d.Sponsors) == 0 {
		return ""
	}
	out := "\n### Sponsored by\n\n"
	for _, sp := range d.Sponsors {
		out += "- **" + sponsorText(sp.Label) + "** — " + strconv.FormatInt(sp.Amount, 10) + " ugnot\n"
	}
	out += "\nA sponsorship raises the prize and buys no entries: a sponsor cannot win this draw.\n"
	return out
}

func Render(path string) string {
	i64 := strconv.FormatInt

	out := "# SPLASH weekly raffle\n\n"
	out += "Tickets are " + i64(TicketPrice, 10) + " ugnot each (wrapped GNOT, 6 decimals: 1 GNOT = 1000000 ugnot).\n"
	out += "One ticket is " + i64(unitsPerTicket, 10) + " units of draw weight, at " + i64(EntryUnitPrice, 10) + " ugnot a unit.\n"
	out += "The house takes " + i64(HouseCutBps, 10) + " bps of each sale; the rest is the prize, and the whole prize is paid to the winner's wallet.\n"
	out += "THE HOUSE FEE IS HELD IN ESCROW PER WEEK AND IS EARNED ONLY BY A DRAW: a week that is refunded returns the FULL ticket price.\n\n"
	out += "The arcade's rake is sponsored straight into this week's pot, so every duel makes the prize bigger.\n\n"
	out += "- current week: " + i64(currentWeek(), 10) + "\n"
	out += "- this week's pot: " + i64(PotSize(), 10) + " ugnot\n"
	out += "- of which sponsored: " + i64(Sponsored(), 10) + " ugnot\n"
	out += "- this week's tickets: " + i64(TicketTotal(), 10) + "\n"
	out += "- held across all unresolved weeks: " + i64(heldPots, 10) + " ugnot\n"
	out += "- house fees held in escrow, NOT yet earned and still refundable: " + i64(heldCuts, 10) + " ugnot\n"
	out += "- ops pot (earned): " + i64(opsPot, 10) + " ugnot\n"
	// THE UNCLAIMED DEAD-WEEK SHARES, SHOWN BECAUSE THEY ARE MONEY IN A DEAD WEEK'S POT AND A
	// READER WOULD OTHERWISE HAVE TO SUBTRACT THEM OUT BY HAND. Already inside "held across
	// all unresolved weeks" above, so this line is a breakdown and not a fourth term.
	//
	// THE LINE IT REPLACES WAS "sponsorship awaiting the next week to open" (finding 28's
	// register). Nothing awaits a week any more — finding 31 — so the question the old line
	// answered has no answer and the new one names the holders' claim instead.
	out += "- dead weeks' sponsorship owed back to their sponsors, not yet claimed: " +
		i64(heldSponsorRefunds, 10) + " ugnot\n"
	out += "- dead weeks' sponsorship returned to their own holders, not yet claimed: " +
		i64(heldClaims, 10) + " ugnot\n"
	out += "- weeks recorded: " + strconv.Itoa(draws.Size()) + "\n"
	out += renderSponsors(currentWeek())
	// THE TWO NUMBERS A BUYER OF A STUCK WEEK NEEDS. The grace window is stated
	// once here and the per-week table below gives the height it lands on, so a
	// front end can tell a buyer when their money becomes reclaimable even if the
	// beacon never publishes their round again. See refundGraceBlocks.
	out += "- current chain height: " + i64(runtime.ChainHeight(), 10) + "\n"
	out += "- refunds open unconditionally " + i64(refundGraceBlocks, 10) +
		" blocks after a week is committed (about " + i64(refundGraceDays, 10) +
		" days), whatever the beacon does\n"

	if draws.Size() == 0 {
		out += "\nNo tickets have been sold yet.\n"
		return out
	}

	// THE DEAD-WEEK COLUMNS ARE NEW SINCE FINDING 31 AND ARE NOT DECORATION. On an abandoned
	// week `sponsored` is now always 0 — retireSponsorship zeroes it — so without these two a
	// front end reading this table would see a week with a POT, no sponsorship and no buyer
	// claims and have no way to learn that the money is claimable, or by whom. "unclaimed" is
	// what the week still owes its holders and "per unit" is the rate to multiply their weight
	// by; ClaimableOf answers it per address. A pot nobody can see a claim on is how money
	// goes missing quietly, which is the same sentence Draw.Cut carries.
	out += "\n| week | tickets | pot | sponsored | unclaimed | per unit | escrowed fee | committed | round | captured | winner | abandoned | refund opens at |\n"
	out += "|---|---|---|---|---|---|---|---|---|---|---|---|---|\n"
	draws.Iterate("", "", func(_ string, value any) bool {
		d := value.(*Draw)
		committed := "no"
		total := d.tickets.Total()
		if d.Committed {
			committed = "yes"
			total = d.FrozenTotal
		}
		captured := "no"
		if d.Randomness != "" {
			captured = "yes"
		}
		winner := "unresolved"
		if d.Resolved {
			winner = string(d.Winner)
		}
		// ABANDONED IS SHOWN, and shown separately from the winner column: a
		// reader must be able to tell a week still waiting for its randomness
		// from one that is refunding and will never be drawn.
		abandoned := "no"
		if d.Abandoned {
			abandoned = "yes"
			if !d.Resolved {
				winner = "refunding"
			}
		}
		// THE HEIGHT A BUYER CAN STOP WAITING AT, per week. "n/a" on a week with
		// no refund clock running: uncommitted (nothing is locked yet), already
		// resolved (the pot has gone to its winner), or already abandoned (refunds
		// are open now and this number is behind us). A bare height rather than a
		// countdown, because Render must be byte-identical for the same state and
		// a countdown would also have to be recomputed by every reader anyway.
		refundOpens := "n/a"
		if d.Committed && !d.Resolved && !d.Abandoned && d.CommittedAt > 0 {
			refundOpens = i64(d.CommittedAt+refundGraceBlocks, 10)
		}
		out += "| " + i64(d.Week, 10) +
			" | " + i64(total, 10) +
			" | " + i64(d.Pot, 10) +
			" | " + i64(d.Sponsored, 10) +
			" | " + i64(d.Claims, 10) +
			" | " + i64(d.ClaimPerUnit, 10) +
			" | " + i64(d.Cut, 10) +
			" | " + committed +
			" | " + i64(d.Round, 10) +
			" | " + captured +
			" | " + winner +
			" | " + abandoned +
			" | " + refundOpens + " |\n"
		return false
	})
	return out
}

// Package duel implements the first slice of Splash Play I, the Duel,
// settled from r/splash/beacon instead of a two-party commit-reveal
// (SPEC-09-duel-beacon.md v1.0, ../../../../SPEC-09-duel-beacon.md).
//
// TEMPORARY NAME. "duel" is scratch space, built beside the LIVE
// r/splash/arcade/duel so that realm keeps working while this one is proven.
// The two are swapped in one commit once this one is ready, and the deploy
// path is decided then (SPEC-09 is silent on it on purpose). Nothing here
// should be linked to, or depended on, from outside this directory.
//
// THIS SLICE IS Post, Cancel, Accept AND THE ROUND PIN. No Resolve — that is
// slice 2 (SPEC-09 §3 describes the whole lifecycle; the part after Accept is
// not built yet). A duel created here therefore has no payout path: it
// exists so the pin itself, SPEC-09's "only subtle part" (§3.1), can be built
// and proved on its own before anything is wired to money leaving the realm.
//
// WHY COMMIT-REVEAL IS GONE RATHER THAN CARRIED OVER (SPEC-09 §1). The old
// duel moved OFF the beacon on 2026-09-30 because Accept needed an UPPER
// bound on drand's head ("round R is not signed yet"), and no arithmetic over
// a RELAYED round could ever establish one: a signature proves a round
// EXISTS (a lower bound), and the absence of one is not provable on chain,
// because withholding a relay is free and invisible. beacon.CurrentRound(),
// added 2026-10-08, derives drand's round from the BLOCK'S OWN CLOCK instead
// — no relayer in the path — so that upper bound now exists, and the whole
// reason commit-reveal's complexity existed is gone with it. What carries
// over is not the lifecycle but four audit findings about THIS REALM'S OWN
// escrow and money handling that were never specific to commit-reveal
// (SPEC-09 §8): rejectAttachedCoin and requireUserCall below, no transfer
// destination ever being a caller-supplied argument, and (for later slices)
// one clock/one derived value and no sentinel field standing in for a height.
//
// THE STAKE IS WRAPPED GNOT, exactly as in r/splash/arcade/duel: this realm
// escrows gno.land/r/gnoland/wugnot and touches no other token.
//
// NO Resolved, NO Winner, NO Secret, NO Nonce, NO NonceRevealedAt, NO
// TakerCommit, AND NO DEADLINE OF ANY KIND IN THIS SLICE'S STATE (SPEC-09 §4,
// §8). Resolve (slice 2) pays and deletes a duel in one call, so a resolved
// duel will never exist to be recorded; there is nothing here for a sentinel
// "never happened yet" value to be confused with a real height.
package duel

import (
	"crypto/sha256"
	"math/bits"
	"strconv"
	"unicode/utf8"

	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"

	"gno.land/r/g1r4aw43kagaaquhegxw6xr346h9f2qu2ezf0jar/arcade/raffle/v4"
	"gno.land/r/g1r4aw43kagaaquhegxw6xr346h9f2qu2ezf0jar/beacon/v2"
	"gno.land/r/gnoland/wugnot"
)

// --- the economics (SPEC-09 §5: "unchanged, deliberately") ---------------
//
// rakeBps, bpsDenom, rakePotShareBps and rakeOpsShareBps, and the rungs
// ladder below, are copied VERBATIM from r/splash/arcade/duel/duel.gno,
// which in turn cites BIBLE.md "Arcade rake" §2.6/§2.7 and SPEC-03 §5/§9.
// SPEC-09 §5 is explicit that nothing about the economics changes in this
// rewrite — only how the coin is flipped — so these numbers are re-stated,
// not re-derived. This slice stops at having them present and the stake
// escrowed: rakeOf/splitRake and the raffle entries they feed belong to
// Resolve, slice 2, and are not needed until a payout exists to apply them
// to.

const (
	// rakeBps is the arcade rake: 300 bps of the pool, i.e. of 2 x stake.
	rakeBps  = 300
	bpsDenom = 10000

	// The rake splits 60% to the current raffle pot / 40% to ops, ops
	// floored, dust to the pot (SPEC-09 §5).
	//
	// rakePotShareBps IS A THIRD COPY OF THE SAME NUMBER, NOT JUST A SECOND
	// ONE — r/splash/arcade/duel/duel.gno's identical constant is the first
	// copy, and r/splash/arcade/raffle/raffle.gno's arcadeRakePotShareBps
	// (raffle.gno:3218) is the second, restated there because "the import
	// only goes one way" (raffle.gno, same comment block): the raffle cannot
	// import either duel to read their constant, so it keeps its own. This
	// file is in the same position relative to the raffle, for the same
	// reason, so it keeps a third.
	//
	// THE RAFFLE SAYS, IN ITS OWN SOURCE, WHY A COPY LIKE THIS ONE IS
	// DANGEROUS ON ITS OWN: raffle.gno:3214 requires
	// "raffle.ArcadeEntryUnitsBound(potShare) to equal it, to the entry",
	// and raffle.gno:3276-3277 exports that function "so the duel's suite
	// can pin the two realms' arithmetic to each other" — an invitation,
	// not a decoration. maxEntryUnitsFor below is this realm's restatement
	// of that same bound (raffle.gno:3286-3291), and if this constant ever
	// drifts from the raffle's WITHOUT raffle.ArcadeEntryUnitsBound moving
	// with it — in particular if it is ever LOWERED, which loosens this
	// file's gross-up — checkInvariant below keeps passing (it only checks
	// pendingEntryUnits against THIS FILE'S OWN maxEntryUnitsFor), but every
	// raffle.FundPotWithEntries call FlushPot makes then finds its units (or
	// their total) over the RAFFLE'S bound and panics, unconditionally
	// (raffle.gno:3449-3455). FlushPot is therefore refused for that batch
	// forever, and the only door left is SweepStuckRake, which — after
	// pendingGraceBlocks — donates the WHOLE booked pot share (the players'
	// 60%) into the raffle's ops pot and drops every entry riding with it.
	// Money enters, the correct exit (FlushPot) closes permanently, and the
	// wrong one (SweepStuckRake) pays the house — and nothing in this file
	// would report it, because nothing here checks this number against the
	// raffle's own. TestMaxEntryUnitsForMatchesRafflesArcadeEntryUnitsBound
	// in duel_test.gno is the pin against that drift, ported from the old
	// duel's TestFix15_TheRafflesEntryBoundIsExactlyThisRealmsRakeEquivalent
	// (duel_test.gno:3338,3341) and TestFix26 (duel_test.gno:3742,3747); the
	// compile-time floor two lines below is the second half of that pin —
	// read ITS comment for what it stops that the test, being a test, can
	// only catch after the fact.
	rakePotShareBps = 6000
	rakeOpsShareBps = 4000
)

// A negative array length is a compile error, so this line fails the BUILD
// if a future edit pushes the two shares past the denominator — copied from
// r/splash/arcade/duel/duel.gno's identical guard.
var _ [bpsDenom - rakePotShareBps - rakeOpsShareBps]struct{}

// THE PLAYERS' SHARE MUST BE AT LEAST HALF THE RAKE — same idiom, same
// value and the same reasoning as r/splash/arcade/raffle/raffle.gno's
// identical guard on its own copy of this number (raffle.gno:3238, "a
// negative array length is a compile error"). rakePotShareBps's own comment
// above explains WHY a drift here is dangerous (it silently closes
// FlushPot and opens SweepStuckRake as the real exit); this line is HALF of
// what stops that drift happening in the first place — the other half is
// TestMaxEntryUnitsForMatchesRafflesArcadeEntryUnitsBound in
// duel_test.gno. The test alone is not enough: a test only runs when
// somebody runs it, but a build fails every time, for every editor,
// including one who never thinks to run this package's suite before
// touching this constant. Note what this guard does NOT do: the
// bpsDenom-sum guard just above already stops the two shares overflowing
// the denominator, but says nothing about EITHER share's own floor — a drop
// to e.g. rakePotShareBps=1000/rakeOpsShareBps=9000 still sums to bpsDenom
// and would sail past that guard while being exactly the dangerous drift
// this one exists to catch.
var _ [rakePotShareBps - 5_000]struct{}

// rungs is the stake ladder, in ugnot (GNOT has 6 decimals): 10 / 50 / 200 /
// 1,000 GNOT. FIXED, never mutable. Copied verbatim from
// r/splash/arcade/duel/duel.gno; SPEC-03 §9 records these as a free dial and
// SPEC-09 §5 carries them forward unchanged.
const (
	rung0 = 10_000_000    // 10 GNOT
	rung1 = 50_000_000    // 50 GNOT
	rung2 = 200_000_000   // 200 GNOT
	rung3 = 1_000_000_000 // 1,000 GNOT
)

var rungs = [...]int64{rung0, rung1, rung2, rung3}

// maxStake is the largest stake the ladder can ever name — rung3 — used to
// bound poolOf's and rakeOf's inputs before any arithmetic touches them.
// Copied verbatim from r/splash/arcade/duel/duel.gno.
const maxStake = rung3

func init() {
	for i := 1; i < len(rungs); i++ {
		if rungs[i] <= rungs[i-1] {
			panic("duel: the stake ladder must ascend")
		}
	}
}

// opsVaultAddr is gno.land/r/g1r4aw43kagaaquhegxw6xr346h9f2qu2ezf0jar/ops, the
// operations share of the rake's destination. SAME CONSTANT, SAME DERIVATION,
// SAME REASONING as r/splash/arcade/duel/duel.gno's identical constant: the
// realm at that path need not exist yet for the address to be right, and it
// is a plain wugnot.Transfer destination, not a function call gated by any
// package-path check.
const opsVaultAddr address = "g1dqnxfp5zj89ggfcfzvampmhmrkjq36d2zvdyk7"

// raffleRealmAddr is the address of the raffle this file IMPORTS, and the two
// must move together or FlushPot silently approves the wrong account.
//
// THE COMMENT HERE USED TO SAY "no /v2 suffix exists yet in this repo" and
// promised the raffle would move "at its own redeploy". It has now moved
// twice, to /v3 and then /v4, and this constant did not follow it the first
// time anybody looked. That is the whole hazard of an address DERIVED FROM A
// PACKAGE PATH: the import above changes with a one-line edit and this literal
// does not, and nothing about the result looks wrong until a cross-realm call
// fails on an allowance that was granted to a realm nobody is using.
//
// Caught on 2026-10-08 by the duel's own FlushPot test failing with
// "insufficient allowance" the moment the import went to /v4 — which is the
// test doing exactly its job. tools/raffle_addr_test.go derives this from the
// raffle's gnomod.toml and fails if the two disagree; believe that guard over
// this comment.
//
// Used as a wugnot.Transfer destination (SweepStuckRake) and as the Approve
// target in FlushPot. Never as a gate: the raffle's entry doors gate on
// PACKAGE PATH, not on an address.
const raffleRealmAddr address = "g1lmd9dxwefss54vtf80jscnds6a7k4ec86873c3"

// mulDiv, poolOf, rakeOf and splitRake are copied verbatim (arithmetic and
// bounds) from r/splash/arcade/duel/duel.gno — SPEC-09 §5: "nothing about the
// economics changes". Comments are condensed to a pointer at the old file
// rather than reproduced in full; read poolOf/rakeOf/splitRake there for the
// complete reasoning (mulDiv's 128-bit product, the floor-to-ops/dust-to-pot
// rule, and the two real (non-tautological) guards on splitRake).

// mulDiv returns floor(a*b/d) via a 128-bit intermediate product: raw a*b/d
// on token-scale int64s wraps silently on the GnoVM (tools/muldiv_probe.gno).
func mulDiv(a, b, d uint64) uint64 {
	hi, lo := bits.Mul64(a, b)
	if d == 0 {
		panic("duel: mulDiv: division by zero")
	}
	if hi >= d {
		panic("duel: mulDiv: overflow")
	}
	q, _ := bits.Div64(hi, lo, d)
	return q
}

// poolOf is 2 x stake, the whole pot of a duel, with the input bounded first.
func poolOf(stake int64) int64 {
	if stake <= 0 || stake > maxStake {
		panic("duel: stake out of bounds")
	}
	return 2 * stake
}

// rakeOf is the rake on a pool: floor(pool x rakeBps / bpsDenom).
func rakeOf(pool int64) int64 {
	if pool <= 0 || pool > 2*maxStake {
		panic("duel: pool out of bounds")
	}
	return int64(mulDiv(uint64(pool), rakeBps, bpsDenom))
}

// splitRake divides a rake 60/40 into the raffle pot share and the ops
// share. Ops is floored; the pot takes the remainder and all the dust, so
// potShare + opsShare == rake exactly, always.
func splitRake(rake int64) (potShare, opsShare int64) {
	if rake < 0 {
		panic("duel: negative rake")
	}
	opsShare = int64(mulDiv(uint64(rake), rakeOpsShareBps, bpsDenom))
	potShare = rake - opsShare
	if potShare < 0 {
		panic("duel: rake split does not sum to the rake: pot share is negative")
	}
	if potShare < int64(mulDiv(uint64(rake), rakePotShareBps, bpsDenom)) {
		panic("duel: rake split shorts the pot share")
	}
	return potShare, opsShare
}

// rakeEntryUnits and splitEntries are copied verbatim (arithmetic, bounds and
// the three asserted invariants) from r/splash/arcade/duel/duel.gno. Read
// that file's identical functions for the full history (AUDIT-2026-09-28.md
// findings 15, 22 and 26) — condensed here to what each check enforces.

// rakeEntryUnits is how many raffle entry units a rake of `rake` ugnot earns:
// exactly what that money would have bought at raffle.EntryUnitPrice.
// raffle.EntryUnitPrice is read as a compile-time constant of another realm,
// never a call, so this adds no runtime dependency on the raffle.
func rakeEntryUnits(rake int64) int64 {
	if rake < 0 {
		panic("duel: negative rake")
	}
	return rake / raffle.EntryUnitPrice
}

// splitEntries divides a duel's earned entries between its winner and its
// loser: each player is guaranteed one entry whenever the total can pay for
// two (total >= 2), and the remainder is weighted two thirds to the loser.
func splitEntries(total int64) (winnerUnits, loserUnits int64) {
	if total < 0 {
		panic("duel: negative entry total")
	}
	switch {
	case total == 0:
		winnerUnits, loserUnits = 0, 0
	case total == 1:
		winnerUnits, loserUnits = 0, 1
	default:
		winnerUnits = total / 3
		if winnerUnits < 1 {
			winnerUnits = 1
		}
		loserUnits = total - winnerUnits
	}
	if winnerUnits+loserUnits != total {
		panic("duel: entry split does not sum to the total")
	}
	if loserUnits < winnerUnits {
		panic("duel: entry split shorts the loser")
	}
	if total >= 2 && (winnerUnits < 1 || loserUnits < 1) {
		panic("duel: entry split leaves a player with no entry out of a total that can pay both")
	}
	return winnerUnits, loserUnits
}

// maxEntryUnitsFor is the most booked entry units a booked pot share of
// `potShare` ugnot may ever carry — the same ceiling r/splash/arcade/raffle
// applies at its door (raffle.ArcadeEntryUnitsBound, raffle.gno:3286-3291),
// computed here from this realm's own constants so checkInvariant can assert
// it without calling another realm. Copied verbatim from
// r/splash/arcade/duel/duel.gno. A THIRD COPY, same situation as
// rakePotShareBps above — read THAT constant's comment for what happens if
// this one ever disagrees with the raffle's own
// (raffle.gno:3449-3455/FlushPot/SweepStuckRake) — and PINNED the same way:
// TestMaxEntryUnitsForMatchesRafflesArcadeEntryUnitsBound in
// duel_test.gno asserts this function equals raffle.ArcadeEntryUnitsBound,
// to the entry, exactly as the old duel's
// TestFix15_TheRafflesEntryBoundIsExactlyThisRealmsRakeEquivalent
// (duel_test.gno:3338,3341,3742,3747) pins the old duel's identical copy.
func maxEntryUnitsFor(potShare int64) int64 {
	if potShare <= 0 {
		return 0
	}
	gross := int64(mulDiv(uint64(potShare), bpsDenom, rakePotShareBps))
	return gross / raffle.EntryUnitPrice
}

// --- the pin (SPEC-09 §3.1 — "the only subtle part") -----------------------

const (
	// pinOffsetRounds IS A SECURITY BUDGET, IN SECONDS, NOT ONLY A UX DIAL
	// FOR HOW LONG A PLAYER WAITS — stated plainly because only the wait
	// half has ever been documented here. The attack this margin prevents:
	// beacon.CurrentRound() derives drand's round from the BLOCK'S OWN
	// CLOCK (this file's package doc comment), so if that clock ever lags
	// drand's REAL head by more than this margin, the round Accept pins is
	// already signed in the real world, its randomness is fetchable from
	// drand's public API right now, and a taker who checks it before
	// calling Accept can simply decline to send that call when the outcome
	// is unfavourable — turning a 50/50 game into a free option. Given
	// bucketRounds's round-up, the reachable pin for any Accept is
	// [current+pinOffsetRounds+1, current+pinOffsetRounds+bucketRounds]
	// rounds ahead (pinRound's own doc comment derives this), so at
	// pinOffsetRounds=100, bucketRounds=100, drand's 3-second period, the
	// MINIMUM margin this design has against that lag is
	// (pinOffsetRounds+1) x 3s = 303s — not the 100 rounds / 5 minutes
	// framing below, which is the TYPICAL case, not the floor. HALVING
	// THIS CONSTANT FOR SNAPPIER SETTLEMENT HALVES THAT MARGIN TOO: it is
	// the ONLY security margin this design has against a clock-lag
	// foreknowledge attack, there being no other check anywhere in this
	// file that stands in for it (see Resolve's own doc comment on why a
	// beacon.Published(round) check at Accept would not help — an attacker
	// with foreknowledge simply would not publish early). So this constant
	// is tuned for BOTH properties — far enough past
	// beacon.CurrentRound() that it is unknowable at the moment of the pin
	// (drand's period is 3 seconds, so 100 rounds is 5 minutes, SPEC-09
	// §3.1, §9), AND the clock-skew budget above — and a future change to
	// it must weigh both, not just the first.
	pinOffsetRounds = 100

	// bucketRounds rounds the pin UP to a shared boundary, and that single
	// choice does two jobs at once (SPEC-09 §3.1):
	//
	//   - EVERY DUEL ACCEPTED IN THE SAME BUCKET SHARES A ROUND, which is
	//     the communal settling moment the owner asked for; and
	//   - ONE beacon.Publish SERVES ALL OF THEM, which is what makes the gas
	//     affordable: a publish was measured at ~0.277 GNOT on 2026-10-07,
	//     and one publish per duel would cost more than the rake on even the
	//     smallest (10 GNOT) stake, let alone recoup it.
	//
	// 100 again, so a bucket spans the same 5 minutes as the offset
	// (SPEC-09 §9's proposed starting point for both).
	bucketRounds = 100

	// minPinOffsetRounds is the compile-time floor pinOffsetRounds may never
	// be shrunk below, in this file's existing idiom (see bpsDenom's
	// identical negative-array-length guard above). THIS is what actually
	// stops pinOffsetRounds being shrunk — not the runtime assertion in
	// pinRound below, which cannot check a compile-time constant against a
	// value derived from that same constant (see pinRound's own doc comment).
	//
	// IT WAS 1, AND 1 WAS THE WRONG NUMBER. Corrected 2026-10-08 after the
	// re-audit: 1 is the bare MATHEMATICAL minimum for "ahead" to mean
	// anything, and this guard's whole purpose is to protect the SECURITY
	// minimum, which is a different and much larger number. At
	// pinOffsetRounds = 1 the margin is (1+1)*3 = 6 SECONDS against a
	// clock-lag foreknowledge attack, where the budget stated on
	// pinOffsetRounds above is 303. Every value from 1 to 99 collapses that
	// margin and every one of them COMPILED CLEAN — verified by setting it
	// to 1 and watching the build succeed.
	//
	// So the floor is now derived from the budget rather than from the
	// arithmetic: it IS pinOffsetRounds' current value, because that value
	// is the budget. Raising pinOffsetRounds is always safe and needs no
	// change here; lowering it below the documented margin now fails the
	// BUILD, which is the only guard an editor cannot skip.
	//
	// A GUARD CALIBRATED TO THE WRONG QUANTITY READS EXACTLY LIKE A GUARD.
	// That is the fourth time this project has met that shape in one day.
	minPinOffsetRounds = 100
)

// A negative array length is a compile error, so this line fails the BUILD
// if a future edit shrinks pinOffsetRounds below minPinOffsetRounds — the
// same guard idiom as bpsDenom's above, applied to this file's other
// security-bearing constant.
var _ [pinOffsetRounds - minPinOffsetRounds]struct{}

// pinRound computes the round Accept binds a duel to. It is the ONLY place
// this arithmetic exists (SPEC-09 §8: "one expression used twice, never two
// copies" — the old duel's R1/N1/T1 findings were all one deadline written
// as several expressions that drifted apart).
//
//	raw   = beacon.CurrentRound() + pinOffsetRounds
//	Round = ((raw / bucketRounds) + 1) * bucketRounds
//
// current IS READ EXACTLY ONCE, into a local, and reused for both the
// derivation above and the assertion below — never a second call to
// beacon.CurrentRound() — so the invariant is checked against the very value
// the pin was derived from, not a possibly-different later read.
//
// ASSERTS SPEC-09 INVARIANT 2 IN THE CONTRACT, NOT JUST IN A TEST — and this
// time correctly: the panic below checks the MARGIN (round must be at least
// current + pinOffsetRounds), not merely the SIGN (round > current). The
// sign alone is NOT a useful guard: bucketRounds's own round-up already
// makes round > current by at least 1, for ANY pinOffsetRounds including 0
// — so a sign-only check (this file's previous version) passes even when
// pinOffsetRounds has collapsed to 0 and the pin has collapsed with it to
// 1-100 rounds, well inside ordinary clock skew. The margin check here is
// STILL NOT what defends pinOffsetRounds from being set too low, though:
// raw embeds pinOffsetRounds directly, so round's own derivation already
// guarantees round >= current + pinOffsetRounds + 1 for WHATEVER
// pinOffsetRounds compiles in — the check below is therefore a defence
// against a future bug in the ROUNDING step (e.g. bucketRounds's arithmetic
// silently losing the "+1" that makes the round-up strict), not a defence
// against pinOffsetRounds itself being shrunk. THAT defence is the
// minPinOffsetRounds floor above, a BUILD-TIME failure — because
// pinOffsetRounds is a compile-time constant, and nothing checked at
// runtime against a value derived from that same constant can ever catch
// the constant itself being wrong.
func pinRound() int64 {
	current := beacon.CurrentRound()
	round := pinnedRoundFor(current)
	if round < current+pinOffsetRounds {
		panic("duel: pinned round is not at least pinOffsetRounds ahead of beacon.CurrentRound() — refusing to pin")
	}
	return round
}

// pinnedRoundFor is the pin arithmetic, and the ONLY copy of it.
//
// It was inlined in pinRound until RoundForAcceptAt needed the same answer for
// the front end. Two copies of this expression would be the same defect as a
// JavaScript copy, just closer together and harder to spot: a front end
// promising "you have 4 minutes to join this flip" against arithmetic that no
// longer matches what Accept does would be lying to a player about money. One
// function, both callers.
func pinnedRoundFor(current int64) int64 {
	raw := current + pinOffsetRounds
	return ((raw / bucketRounds) + 1) * bucketRounds
}

// --- state (SPEC-09 §4) ----------------------------------------------------

// maxLabelLen bounds an offer's label, in bytes. Copied from
// r/splash/arcade/duel/duel.gno.
const maxLabelLen = 64

// Offer is a standing stake in the lobby (SPEC-09 §4).
type Offer struct {
	Poster   address
	Rung     int64 // index into rungs, not a raw amount
	PostedAt int64 // block height, for a future Render

	// Opponent, when non-zero, is the only address that may Accept this
	// offer. Zero means open to anyone.
	Opponent address

	// Label is free text from the poster, purely descriptive (checkLabel):
	// it never touches settlement.
	Label string

	// PosterIsUser records whether the Post that created this offer was a
	// DIRECT user call, carried forward to Duel.PosterIsUser at Accept. See
	// Duel.PosterIsUser for why the flag is kept even though requireUserCall
	// already makes it unconditionally true today (SPEC-09 §8, the entries
	// half of finding 8; copied from r/splash/arcade/duel/duel.gno's
	// identical field).
	PosterIsUser bool
}

// Duel is a matched pair with a round pinned to settle it (SPEC-09 §4).
type Duel struct {
	Poster, Taker address
	Rung          int64
	Label         string

	// Round is pinned by pinRound() at Accept and NEVER rebound by
	// anything after — not by Resolve (slice 2), not by anything
	// (SPEC-09 invariant 1).
	Round int64

	AcceptedAt int64 // block height

	// PosterIsUser and TakerIsUser record whether each party's OWN call —
	// the Post that created the offer, the Accept that matched it — was a
	// DIRECT user call rather than a realm's. SPEC-09 §8 is explicit that
	// finding 8's ENTRIES half still needs this flag even though this
	// slice's requireUserCall already refuses any non-user Post or Accept
	// outright, which makes both fields unconditionally true today: the
	// same reasoning r/splash/arcade/duel/duel.gno's identical fields give
	// (see that file's bookEntries) — the flag is the ONE place finding 8's
	// property is enforced for entries specifically, so a future
	// relaxation of requireUserCall must fail here as a declined entry and
	// an event, not as a raffle entry credited to an address that cannot
	// spend it. Slice 1 did not add these fields; this slice does, because
	// Resolve is the first thing in this realm that books an entry.
	PosterIsUser bool
	TakerIsUser  bool
}

var (
	// offers is offerID -> *Offer and duels is duelID -> *Duel. avl.Trees,
	// never maps: a future Render must iterate them in a deterministic
	// order, which a map's iteration order does not guarantee.
	offers = avl.NewTree()
	duels  = avl.NewTree()

	// IDs start at 1 so that 0 never names a record. Separate sequences, as
	// in r/splash/arcade/duel.
	nextOfferID int64 = 1
	nextDuelID  int64 = 1

	// escrowed is the wugnot this realm holds on behalf of players: one
	// stake per open offer, two per live duel. Maintained incrementally,
	// never by iteration; the realm's balance must never fall below it
	// (checkInvariant).
	escrowed int64

	// pendingPot and pendingEntries are the players' side of every
	// resolved duel's rake, BOOKED AND NOT YET SENT to the raffle — the
	// exact pattern r/splash/arcade/duel/duel.gno's settle/FlushPot split
	// uses, and ported here deliberately rather than a direct call inside
	// Resolve. See Resolve's own doc comment for why: raffle.gno's
	// FundPot/FundPotWithEntries both gate on cur.Previous().PkgPath() ==
	// the OLD duel's literal package path, which this realm's package path
	// is not and can never be while the two coexist, so a call from this
	// file into either door panics every time, unconditionally — SPEC-09
	// §8a, found during slice 2, confirmed it is a certainty and not a risk.
	// Booking here keeps a winner's payout safe from that (and from any
	// other raffle-side refusal) exactly as it already protects the old
	// realm's Collect — "nothing about a duel depends on the raffle any
	// more". DELIVERING THIS BOOKED AMOUNT IS THIS SLICE'S OWN JOB: FlushPot,
	// below, is the permissionless delivery call slice 2 deferred (SPEC-09
	// §8a.4). It CANNOT be proven to succeed end-to-end by this suite —
	// today's deployed raffle will refuse every call this realm's package
	// path can produce, unconditionally, until the raffle is redeployed
	// naming this realm's path (SPEC-09 §8b) — so FlushPot is built and
	// tested for everything that does NOT require the raffle to accept, and
	// end-to-end delivery is unproven until that redeploy. See FlushPot's own
	// doc comment and the task report for the full finding.
	pendingPot        int64
	pendingEntries    = avl.NewTree()
	pendingEntryUnits int64

	// pendingSince is the clock SweepStuckRake's last-resort grace window is
	// counted from: the chain height at which pendingPot last went from zero
	// to non-zero (Resolve), ADVANCED AGAIN EVERY TIME A NEW HOLDER IS
	// ADMITTED to the entry batch (bookEntries) — so the window always
	// measures the age of the YOUNGEST CLAIM in the batch, not the batch's
	// age. Zero when pendingPot is zero, and reset by every successful
	// FlushPot and by SweepStuckRake. Copied verbatim, reasoning included,
	// from r/splash/arcade/duel/duel.gno's identical field (that file's own
	// comment records why this is NOT, and cannot be, a measure of delivery
	// having been attempted and refused — AUDIT-duel-2026-09-27.md addendum
	// 2, finding D-4).
	pendingSince int64
)

// maxPendingEntryHolders bounds the undelivered entry batch, exactly as
// r/splash/arcade/duel/duel.gno's identical constant: an unbounded batch
// could grow past what a block can iterate. Copied verbatim.
const maxPendingEntryHolders = 128

// blocksPerDay and pendingGraceBlocks: SAME VALUES, SAME REASONING as
// r/splash/arcade/duel/duel.gno's identical constants. 21 days of blocks is
// the same window r/splash/arcade/raffle gives a committed week before its
// refunds open; pendingGraceBlocks must stay several raffle weeks long, and
// the raffle's week is blocks, so the two move together whatever the block
// time turns out to be. Copied verbatim.
const blocksPerDay = 26182

const pendingGraceBlocks = blocksPerDay * 21

// realmSelf is this realm's own address, resolved once so every escrow call
// names a constant rather than re-deriving it.
var realmSelf = unsafe.CurrentRealm().Address()

func selfAddr() address {
	return realmSelf
}

// idKeyWidth/idZeroPad/idKey: enough decimal digits for any non-negative
// int64, so avl's lexicographic key order is numeric ID order. Copied from
// r/splash/arcade/duel/duel.gno.
const idKeyWidth = 19

const idZeroPad = "0000000000000000000"

func idKey(id int64) string {
	s := strconv.FormatInt(id, 10)
	if len(s) < idKeyWidth {
		s = idZeroPad[:idKeyWidth-len(s)] + s
	}
	return s
}

// getOffer returns the offer, or nil. avl's Get returns a single value, so
// existence is a separate Has.
func getOffer(id int64) *Offer {
	key := idKey(id)
	if !offers.Has(key) {
		return nil
	}
	return offers.Get(key).(*Offer)
}

func getDuel(id int64) *Duel {
	key := idKey(id)
	if !duels.Has(key) {
		return nil
	}
	return duels.Get(key).(*Duel)
}

// stakeOf is the only place the ladder is read. Panics on any index outside
// it, including negative ones.
func stakeOf(rung int64) int64 {
	if rung < 0 || rung >= int64(len(rungs)) {
		panic("duel: invalid rung")
	}
	return rungs[rung]
}

func checkLabel(label string) {
	if len(label) > maxLabelLen {
		panic("duel: label too long")
	}
	if !utf8.ValidString(label) {
		panic("duel: label is not valid UTF-8")
	}
	for i := 0; i < len(label); i++ {
		if label[i] < 0x20 || label[i] == 0x7f {
			panic("duel: label contains a control character")
		}
	}
}

// checkInvariant is the O(1) solvency check run at the end of every
// state-changing function: the realm must hold at least what it owes in
// escrow. ">=" and not "==", deliberately — wugnot.Transfer is
// permissionless, so anyone can push wugnot at this address, and an exact
// check would let a one-ugnot donation brick every open offer and live duel.
func checkInvariant() {
	if escrowed < 0 {
		panic("duel: escrowed went negative")
	}
	if pendingPot < 0 {
		panic("duel: pending rake went negative")
	}
	if pendingEntryUnits < 0 {
		panic("duel: booked raffle entries went negative")
	}
	if pendingSince < 0 {
		panic("duel: pending-since booking height went negative")
	}
	if pendingPot > 0 && pendingSince <= 0 {
		// Copied check from r/splash/arcade/duel/duel.gno: a booked rake
		// with no booking height is a clock SweepStuckRake cannot read.
		panic("duel: a rake is booked with no booking height")
	}
	if pendingPot == 0 && pendingSince != 0 {
		panic("duel: no rake is booked but a booking height is still set")
	}
	if pendingEntryUnits > 0 && pendingPot <= 0 {
		// Entries with no rake behind them could never be delivered: the
		// raffle prices its ceiling off the money delivered in the same
		// call. Copied reasoning from r/splash/arcade/duel/duel.gno.
		panic("duel: raffle entries are booked with no rake behind them")
	}
	if pendingEntryUnits > maxEntryUnitsFor(pendingPot) {
		panic("duel: booked raffle entries exceed what the booked rake would buy at the ticket price")
	}
	if pendingEntries.Size() > maxPendingEntryHolders {
		panic("duel: the pending entry batch is over its bound")
	}
	// ">=" against escrowed+pendingPot, not "==": wugnot.Transfer is
	// permissionless, so anyone can push wugnot at this address, and an
	// exact check would let a one-ugnot donation brick every open offer,
	// live duel and booked rake.
	if wugnot.BalanceOf(selfAddr()) < escrowed+pendingPot {
		panic("duel: realm holds less wugnot than it owes in escrow and booked rake")
	}
}

// entryUnitsOf reads the booked entry units for a tree key (a holder
// address string), zero if absent. Copied from r/splash/arcade/duel/duel.gno.
func entryUnitsOf(k string) int64 {
	if !pendingEntries.Has(k) {
		return 0
	}
	return pendingEntries.Get(k).(int64)
}

// bookEntries credits `holder` with `units` raffle entry units, booked in
// this realm for a future delivery, and returns what it actually booked —
// zero when the holder is not eligible or the batch is full. IT NEVER
// PANICS AND NEVER REFUSES ITS CALLER: a winner's Resolve must not be able
// to fail over a raffle entry, so every reason not to credit somebody is a
// zero and an event, not an abort. Copied verbatim (including both
// eligibility reasons and their reasoning) from
// r/splash/arcade/duel/duel.gno's identical function.
func bookEntries(holder address, units int64, isUser bool) int64 {
	if units <= 0 {
		return 0
	}
	if holder == "" {
		return 0
	}
	if !isUser {
		// SPEC-09 §8, finding 8's entries half: a realm's address is
		// package-derived and cannot spend an entry it won, so a party
		// that did not play from a direct user call earns none. See
		// Duel.PosterIsUser for why this is unreachable today and kept
		// anyway.
		chain.Emit("DuelEntriesDeclined",
			"holder", string(holder),
			"units", strconv.FormatInt(units, 10),
			"reason", "the party did not play from a direct user call")
		return 0
	}
	k := string(holder)
	if !pendingEntries.Has(k) && pendingEntries.Size() >= maxPendingEntryHolders {
		chain.Emit("DuelEntriesDropped",
			"holder", string(holder),
			"units", strconv.FormatInt(units, 10),
			"holders", strconv.Itoa(pendingEntries.Size()),
			"reason", "the undelivered entry batch is full")
		return 0
	}
	if !pendingEntries.Has(k) {
		// A NEW HOLDER ADVANCES SweepStuckRake'S CLOCK, so the grace window
		// tracks the YOUNGEST CLAIM in the batch rather than the batch's own
		// age — copied from r/splash/arcade/duel/duel.gno's identical check
		// (finding D-4). An EXISTING holder's further units inherit the
		// batch's clock rather than re-advancing it: admissions are bounded
		// by maxPendingEntryHolders, so the clock can advance at most that
		// many times and the window always closes; advancing on every
		// booking instead could let one repeat player defer the last
		// resort forever.
		pendingSince = runtime.ChainHeight()
	}
	pendingEntries.Set(k, entryUnitsOf(k)+units)
	pendingEntryUnits += units
	return units
}

// --- guards carried over from r/splash/arcade/duel (SPEC-09 §8) ----------

// requireUserCall refuses a Post or Accept that did not come directly from a
// user. A realm party that wins a duel would have no way to call a
// winner-only exit, which strands the pool (SPEC-09 §8, finding D-1). Here
// Resolve (slice 2) is permissionless and pays directly, which removes the
// settlement hazard at its root — but §8 keeps the flag on Post and Accept
// anyway, for the entries half of finding 8 that a later slice still needs.
func requireUserCall(cur realm, what string) {
	if !cur.Previous().IsUserCall() {
		panic("duel: " + what + " must be called directly by a user — a realm cannot be a party to a duel")
	}
}

// rejectAttachedCoin panics if the caller attached native coin to a call
// that has no use for it. Every money-in path in this realm is the wugnot
// GRC20 allowance (Post, Accept), never the transaction's send envelope, so
// any attached ugnot would simply sit at this address forever with no code
// path that ever looks at it (SPEC-09 §8, ../speed/AUDIT-2026-10-07.md Y1).
// Call this as the FIRST STATEMENT of every crossing entrypoint.
//
// unsafe.OriginSend() reads the envelope attached at the chain root, shared
// by every realm in the call chain, so reading it is only sound when the
// immediate caller is an EOA — cur.Previous().IsUserCall() is that check.
// When the call did not come directly from a user, this is silently a
// no-op: requireUserCall is what refuses that case on Post and Accept, and
// Cancel has no reason to refuse a realm caller that is the offer's own
// poster.
func rejectAttachedCoin(cur realm, what string) {
	if !cur.Previous().IsUserCall() {
		return
	}
	if sent := unsafe.OriginSend(); len(sent) != 0 {
		panic("duel: " + what + " does not take native coin — pay through the wugnot allowance instead")
	}
}

// --- the lifecycle, this slice: Post / Cancel / Accept (SPEC-09 §3) -------

// Post pulls rungs[rung] from the caller through the wugnot allowance and
// leaves it standing in the lobby. Returns the new offer's ID.
//
// opponent, when non-zero, addresses the offer to one player: only that
// address may later Accept it. Zero ("") leaves it open to anyone.
//
// label is free text for a future render, at most maxLabelLen bytes (""
// is no label). Neither argument touches settlement: the pinned round and
// the beacon's randomness decide that, not this call.
func Post(cur realm, rung int64, opponent address, label string) int64 {
	rejectAttachedCoin(cur, "Post")
	// A PARTY TO A DUEL MUST BE AN ADDRESS THAT CAN CALL A WINNER-ONLY EXIT
	// once one exists (requireUserCall; SPEC-09 §8, finding D-1).
	requireUserCall(cur, "Post")

	stake := stakeOf(rung)
	if opponent != "" && !opponent.IsValid() {
		panic("duel: invalid opponent address")
	}
	checkLabel(label)
	caller := cur.Previous().Address()
	if wugnot.Allowance(caller, selfAddr()) < stake {
		panic("duel: insufficient allowance — approve this realm for the rung's stake first")
	}

	wugnot.TransferFrom(cross(cur), caller, selfAddr(), stake)

	id := nextOfferID
	nextOfferID++
	offers.Set(idKey(id), &Offer{
		Poster:   caller,
		Rung:     rung,
		PostedAt: runtime.ChainHeight(),
		Opponent: opponent,
		Label:    label,
		// requireUserCall above already refused this call otherwise, so
		// this is unconditionally true today — recorded rather than
		// assumed. See Offer.PosterIsUser for why it is kept.
		PosterIsUser: cur.Previous().IsUserCall(),
	})
	escrowed += stake

	chain.Emit("DuelPost",
		"offer", strconv.FormatInt(id, 10),
		"poster", string(caller),
		"rung", strconv.FormatInt(rung, 10),
		"stake", strconv.FormatInt(stake, 10),
		"opponent", string(opponent),
		"label", label)
	checkInvariant()
	return id
}

// Cancel returns an unaccepted offer's stake to its poster, exactly and with
// no fee, and deletes the record. Poster only.
//
// An accepted offer no longer exists — Accept deletes it in the same
// transaction that creates the duel — so "Cancel of an accepted offer" and
// "Cancel of an unknown offer" are the same refusal: whichever of Cancel or
// Accept lands first in block order removes the offer, and the other finds
// nothing. THE DESTINATION IS READ FROM THE RECORD, never a caller-supplied
// argument (SPEC-09 §8): a canceller can only ever recover the poster's own
// stake to the poster's own address.
func Cancel(cur realm, offerID int64) {
	rejectAttachedCoin(cur, "Cancel")
	o := getOffer(offerID)
	if o == nil {
		panic("duel: no such offer")
	}
	caller := cur.Previous().Address()
	if caller != o.Poster {
		panic("duel: only the poster may cancel")
	}
	stake := stakeOf(o.Rung)

	// Delete before paying, so no path exists on which the offer is both
	// refunded and still standing.
	offers.Remove(idKey(offerID))
	escrowed -= stake

	wugnot.Transfer(cross(cur), o.Poster, stake)

	chain.Emit("DuelCancel",
		"offer", strconv.FormatInt(offerID, 10),
		"poster", string(o.Poster),
		"stake", strconv.FormatInt(stake, 10))
	checkInvariant()
}

// Accept takes a standing offer: pulls a stake equal to THE OFFER'S rung —
// the caller chooses nothing about the money — deletes the offer, pins the
// settlement round and creates the duel. Returns the new duel's ID.
//
// THE TAKER CHOOSES THE MOMENT OF Accept AND THEREFORE THE BUCKET, AND THAT
// IS SAFE — STATED RATHER THAN ASSUMED (SPEC-09 §3.1, invariant 3): every
// bucket reachable from "now" lies in the future, so no choice among them
// reveals anything about the randomness it will eventually be settled with.
// The poster has no influence over the round at all: it is pinned HERE, at
// Accept, and the poster's own call happened earlier, before this duel or
// its bucket existed to choose.
func Accept(cur realm, offerID int64) int64 {
	rejectAttachedCoin(cur, "Accept")
	// A PARTY TO A DUEL MUST BE AN ADDRESS THAT CAN CALL A WINNER-ONLY EXIT
	// once one exists (requireUserCall; SPEC-09 §8, finding D-1).
	requireUserCall(cur, "Accept")

	o := getOffer(offerID)
	if o == nil {
		panic("duel: no such offer")
	}
	caller := cur.Previous().Address()
	if o.Opponent != "" && caller != o.Opponent {
		// Addressed to someone else. Checked before the allowance so the
		// refusal never depends on what the wrong player has approved.
		panic("duel: this offer is addressed to another player")
	}
	stake := stakeOf(o.Rung)
	if wugnot.Allowance(caller, selfAddr()) < stake {
		panic("duel: insufficient allowance — approve this realm for the rung's stake first")
	}

	// The offer is deleted before the pull, the same ordering as Cancel:
	// the record goes first, the money moves second, so a re-entrant Accept
	// on this offer finds nothing whatever the token does.
	offers.Remove(idKey(offerID))

	wugnot.TransferFrom(cross(cur), caller, selfAddr(), stake)

	round := pinRound()

	id := nextDuelID
	nextDuelID++
	duels.Set(idKey(id), &Duel{
		Poster:     o.Poster,
		Taker:      caller,
		Rung:       o.Rung,
		Label:      o.Label,
		Round:      round,
		AcceptedAt: runtime.ChainHeight(),
		// Carried from the offer, not re-derived: PosterIsUser describes
		// the POSTER'S OWN Post call, which happened earlier and is not
		// this call's business to recompute. TakerIsUser is this call's
		// own IsUserCall(), unconditionally true today because
		// requireUserCall above already gates it — see Duel.PosterIsUser.
		PosterIsUser: o.PosterIsUser,
		TakerIsUser:  cur.Previous().IsUserCall(),
	})
	escrowed += stake

	chain.Emit("DuelAccept",
		"offer", strconv.FormatInt(offerID, 10),
		"duel", strconv.FormatInt(id, 10),
		"poster", string(o.Poster),
		"taker", string(caller),
		"rung", strconv.FormatInt(o.Rung, 10),
		"round", strconv.FormatInt(round, 10))
	checkInvariant()
	return id
}

// --- the outcome (SPEC-09 §3.2) -------------------------------------------

// outcomeTag is copied BYTE FOR BYTE from r/splash/arcade/duel/duel.gno's
// identical constant. THE OLD REALM'S commitTag AND takerCommitTag ARE GONE
// WITH THE COMMIT-REVEAL DESIGN THEY EXISTED TO SEAL (SPEC-09 §1, §4: no
// Secret, no Nonce, no TakerCommit here at all) — there is only ONE domain
// tag in this file, so the prefix-freeness machinery the old file needed to
// keep three tags from colliding (checkTagsPrefixFree and its init, guarding
// commitTag/outcomeTag/takerCommitTag pairwise) has nothing left to guard.
// Its absence here is deliberate, not an oversight: domain separation across
// a single tag is not a thing that needs checking.
const outcomeTag = "splash/duel/v1/result:"

// outcome computes a published duel's winner (SPEC-09 §3.2):
//
//	sum        = sha256(outcomeTag ‖ randomness ‖ duelID)
//	posterWins = sum[len(sum)-1] % 2 == 0
//
// duelID, AS ITS DECIMAL STRING (strconv.FormatInt, exactly as the old
// realm's posterWins suffixed its own duelID), IS MIXED IN, AND THAT IS
// LOAD-BEARING. bucketRounds (SPEC-09 §3.1) means MANY DUELS SHARE ONE
// Round and therefore one randomness — pinRound's whole point is that one
// beacon.Publish serves a whole bucket. Without duelID in this preimage,
// every duel in a bucket would hash to the identical sum and therefore
// resolve IDENTICALLY: exploitable (the first duel to resolve leaks every
// other duel in its bucket's outcome before they are even looked at) and
// absurd to watch (a communal settling moment where everyone flips the same
// side of the same coin). Mixing in duelID gives each duel its own
// independent coin despite sharing randomness with its whole bucket.
func outcome(duelID int64, randomness string) (posterWins bool) {
	sum := sha256.Sum256([]byte(outcomeTag + randomness + strconv.FormatInt(duelID, 10)))
	return sum[len(sum)-1]%2 == 0
}

// --- Resolve, this slice (SPEC-09 §3) -------------------------------------

// Resolve computes a duel's winner from the published beacon round, pays and
// deletes the record — ALL IN ONE CALL. PERMISSIONLESS: there is no Collect
// in this design (SPEC-09 §3), so a winner never has to come back, and
// anybody — a party, a bystander, a keeper — may call this once the pinned
// round is on chain. The caller supplies nothing but duelID: the winner, the
// payout and the entries are all non-discretionary functions of stored
// state and the beacon's own randomness (invariant 4).
//
// ORDER OF OPERATIONS, SPEC-09'S OWN: reject attached coin first, as every
// entrypoint; look up the duel, refusing an unknown one; refuse if the
// pinned round is not yet published; THEN compute the outcome, pay, book
// entries, delete, emit.
//
// THE PAYOUT IS PORTED FROM r/splash/arcade/duel/duel.gno's settle, NOT
// REDESIGNED (SPEC-09 §8, this task's own instruction): same pool/rake
// arithmetic, same 60/40 split with ops floored and dust to the pot, same
// splitEntries/rakeEntryUnits weighting, same conservation assertion. THE
// ONE DEPARTURE, AND IT IS DELIBERATE RATHER THAN AN OMISSION, IS WHERE THE
// POT SHARE AND ITS ENTRIES LAND. The old settle's own comment says it
// plainly — "BOOKED, NOT SENT, AND NOT ONE LINE OF RAFFLE CODE RUNS IN THIS
// TRANSACTION" — and books into pendingPot/pendingEntries for a SEPARATE,
// later FlushPot to deliver, specifically so a raffle-side refusal can never
// take a winner's payout down with it. This file ports exactly that half of
// settle (see pendingPot's own doc comment above) rather than a direct,
// same-transaction call to raffle.FundPotWithEntries, because such a call
// would not merely risk the winner's payout here — IT WOULD PANIC EVERY
// SINGLE TIME, UNCONDITIONALLY: raffle.gno's FundPot and FundPotWithEntries
// both gate on cur.Previous().PkgPath() == the literal string
// "gno.land/r/g1r4aw43kagaaquhegxw6xr346h9f2qu2ezf0jar/arcade/duel/v3" — the
// OLD realm's own package path — and this realm's module is
// ".../arcade/duel/v2" (SPEC-09 §8b, set in slice 3's gnomod.toml), a
// different string, so that check fails on every call for as long as the
// raffle's compile-time constant names the old path. A direct call here
// would make Resolve permanently unable to pay any duel whose rake is
// positive (every rung's is), which is every duel — the opposite of SPEC-09
// invariant 7 ("a duel can never be stuck by inaction"). ACTUALLY DELIVERING
// THE BOOKED POT IS FlushPot, BELOW (THIS SLICE, SPEC-09 §8a.4) — permissionless,
// separate from this call, and provably safe for a winner's payout even
// while the raffle refuses it. Nothing is lost in the meantime: the booked
// wugnot sits in this realm's own balance, accounted for by pendingPot in
// checkInvariant, exactly as it would between settle and FlushPot in the
// old realm today.
func Resolve(cur realm, duelID int64) {
	rejectAttachedCoin(cur, "Resolve")

	d := getDuel(duelID)
	if d == nil {
		panic("duel: no such duel")
	}

	// THE STATE AN HONEST PLAYER ACTUALLY HITS WHILE WAITING OUT THE ~5
	// MINUTES until drand signs the pinned round — so this reads as a
	// status with an instruction, not a dead end. ANYBODY may publish it;
	// it is not this realm's job to, and naming the round lets the caller
	// (or the front end on their behalf) go do exactly that and come back.
	if !beacon.Published(d.Round) {
		panic("duel: round " + strconv.FormatInt(d.Round, 10) +
			" is not published yet — anybody may call beacon.Publish for it once drand has signed it, then call Resolve again")
	}

	randomness := beacon.Randomness(d.Round)
	posterWins := outcome(duelID, randomness)

	winner, loser := d.Taker, d.Poster
	winnerIsUser, loserIsUser := d.TakerIsUser, d.PosterIsUser
	if posterWins {
		winner, loser = d.Poster, d.Taker
		winnerIsUser, loserIsUser = d.PosterIsUser, d.TakerIsUser
	}

	stake := stakeOf(d.Rung)
	pool := poolOf(stake)
	rake := rakeOf(pool)
	payout := pool - rake
	potShare, opsShare := splitRake(rake)
	if payout+potShare+opsShare != pool {
		// A real check, not a tautology: payout and the two shares are
		// each computed from the pool by their own path above, and this
		// is the first place all three meet (SPEC-09 invariant 5).
		panic("duel: conservation violated — payout plus rake is not the pool")
	}
	winnerUnits, loserUnits := splitEntries(rakeEntryUnits(rake))

	// Delete before paying, the same ordering Cancel and Accept already
	// use: no path exists on which this duel is both paid and still
	// resolvable. THE DESTINATION IS NEVER A CALLER-SUPPLIED ARGUMENT
	// (SPEC-09 §8) — winner is read from the record via outcome(), not
	// from anything the caller of Resolve passed in.
	duels.Remove(idKey(duelID))
	escrowed -= pool

	wugnot.Transfer(cross(cur), winner, payout)
	if potShare > 0 {
		// Booked, not sent — see this function's own doc comment above for
		// why. The entries that rake bought are booked in the same breath,
		// inside this branch deliberately: an entry must never exist
		// without the money that pays for it (checkInvariant asserts this
		// too).
		if pendingPot == 0 {
			// pendingSince starts the grace clock the instant a batch goes
			// from nothing owed to something owed — copied from
			// r/splash/arcade/duel/duel.gno's identical check in settle.
			pendingSince = runtime.ChainHeight()
		}
		pendingPot += potShare
		winnerUnits = bookEntries(winner, winnerUnits, winnerIsUser)
		loserUnits = bookEntries(loser, loserUnits, loserIsUser)
	} else {
		// No rake to pay for entries, so there are none. Unreachable on
		// today's ladder (every rung's rake is positive).
		winnerUnits, loserUnits = 0, 0
	}
	if opsShare > 0 {
		wugnot.Transfer(cross(cur), opsVaultAddr, opsShare)
	}

	recordResult(duelID, d.Round, winner, loser, d.Rung)

	chain.Emit("DuelResolve",
		"duel", strconv.FormatInt(duelID, 10),
		"round", strconv.FormatInt(d.Round, 10),
		"winner", string(winner),
		"loser", string(loser),
		"payout", strconv.FormatInt(payout, 10),
		"rake", strconv.FormatInt(rake, 10),
		"rafflePotBooked", strconv.FormatInt(potShare, 10),
		"ops", strconv.FormatInt(opsShare, 10),
		"pendingPot", strconv.FormatInt(pendingPot, 10),
		"winnerEntries", strconv.FormatInt(winnerUnits, 10),
		"loserEntries", strconv.FormatInt(loserUnits, 10),
		"pendingEntries", strconv.FormatInt(pendingEntryUnits, 10))
	checkInvariant()
}

// --- FlushPot and SweepStuckRake, this slice (SPEC-09 §8a.4) --------------

// FlushPot delivers the whole booked rake — pendingPot and the entries
// earned alongside it — to r/splash/arcade/raffle's CURRENT week, through
// raffle.FundPotWithEntries (or raffle.FundPot when nobody earned an
// entry), and returns the amount actually delivered. PERMISSIONLESS: anyone
// may pay the gas to do it, and the destination is not theirs to choose.
// Ported from r/splash/arcade/duel/duel.gno's FlushPot, same shape and same
// reasoning: a resolved duel's payout must never depend on another realm's
// bookkeeping (see pendingPot's own doc comment above), so delivery is a
// SEPARATE, later, permissionless call whose only failure mode costs the
// CALLER OF THIS FUNCTION a reverted transaction — never a duel's winner,
// who has already been paid and whose record is already gone.
//
// A NO-OP, NOT A PANIC, WHEN NOTHING IS BOOKED — the FIRST of two deliberate
// departures from the old realm's identical function, which panics in this
// case. A permissionless call anybody (in practice: a keeper, on a
// schedule) may make at any time is better served by a harmless zero than
// by forcing every caller to read PendingPot first just to avoid an abort.
//
// THE SECOND DEPARTURE: pendingPot AND THE REST OF THE BOOKING ARE ZEROED
// ONLY AFTER raffle.FundPot/FundPotWithEntries HAS RETURNED WITHOUT
// PANICKING — not before, the old realm's own ordering. ON A REAL CHAIN
// THIS ORDERING CHOICE DOES NOT MATTER: a panic reverts the WHOLE
// transaction, so whether the zeroing happened before or after the
// cross-realm call, it is discarded along with everything else the call
// did, and the old realm's "before" ordering is exactly as revert-safe as
// this file's "after" ordering. RE-ENTRANCY THROUGH THE CROSS-REALM CALL
// ITSELF IS SEPARATELY UNREACHABLE, ARCHITECTURALLY, NOT BY CONVENTION:
// this file imports raffle, so raffle cannot import this file back without
// a compile-time import cycle, and nothing else in raffle's own code calls
// into this realm — there is no path by which raffle.FundPot/
// FundPotWithEntries could call back into FlushPot mid-execution regardless
// of ordering. A mutation check (reorder this file to zero
// first, the old realm's way) DOES make
// TestFlushPotRefusedDeliveryLeavesBookingIntactAndRetryable fail — but
// that result is a property of gno test's HARNESS, not of the chain:
// uassert.AbortsContains recovers the panic inside the same test process
// without re-running the whole message atomically, so a package-level
// write made before the panic (the zeroing) survives the recover when a
// real chain's revert would have discarded it. The harness's recover is
// not a state rollback, and the old realm's comment overstated what the
// mutation test proves by citing it as if it were one. The ordering below
// is kept anyway — zeroing after costs nothing and makes the retry property
// visible in THIS function's own control flow rather than resting on a
// chain-level guarantee this suite cannot exercise — but the reason to keep
// it is suite-observability, not a chain safety property the old ordering
// lacked.
//
// THE RULE THIS FILE ACTUALLY FOLLOWS, SO THE TWO ORDERINGS IN THIS SECTION
// DO NOT READ AS A CONTRADICTION: every OTHER state change in this file
// (Cancel's escrowed -=, Accept's offers.Remove, Resolve's duels.Remove)
// mutates bookkeeping BEFORE the paying wugnot.Transfer, on the general
// principle that a retry or a re-entrant call should find nothing rather
// than something stale. SweepStuckRake, below, follows that same general
// rule: its wugnot.Transfer is a plain, ungated call that this function's
// own prior checks (and checkInvariant's balance assertion) already make
// as close to unconditional as this realm can establish, so there is
// nothing to protect by delaying the zeroing. FlushPot is the ONE
// deliberate exception to the general rule, and the reason is specific to
// it: its cross-realm call is, TODAY, KNOWN to panic unconditionally (the
// raffle's package-path gate, documented below), so zeroing after is what
// keeps the retry property visible inside this function's own control flow
// for the one call in this file whose failure is not hypothetical.
//
// END-TO-END DELIVERY IS UNPROVEN BY THIS SUITE, AND THAT IS STATED HERE
// RATHER THAN DISCOVERED LATER (SPEC-09 §8a — found during slice 2 and a
// certainty, not a risk). raffle.gno's FundPot and FundPotWithEntries both
// gate on cur.Previous().PkgPath() being EXACTLY
// "gno.land/r/g1r4aw43kagaaquhegxw6xr346h9f2qu2ezf0jar/arcade/duel/v3" — the
// OLD realm's own path, never this realm's ".../arcade/duel/v2" — so EVERY
// CALL THIS FUNCTION MAKES TO THE RAFFLE TODAY PANICS, UNCONDITIONALLY, and
// that panic reverts this whole call with pendingPot intact (the retry
// property above, independently of the zero-after ordering, since nothing
// here has executed the zeroing yet when the panic happens). This is §8a's
// forced deploy order working as designed, not a defect to chase here: the
// raffle must be redeployed FIRST, naming this realm's path, before this
// function's happy path can be exercised for real — and it will be, for
// the first time, at that deploy, not in this suite. What this suite proves
// instead, and all it honestly can: the booking is correct, a refused
// delivery loses nothing and remains retryable, the books balance, this
// function is permissionless, and it refuses attached coin.
func FlushPot(cur realm) int64 {
	rejectAttachedCoin(cur, "FlushPot")
	amount := pendingPot
	if amount <= 0 {
		return 0
	}

	// THE BATCH IS COLLECTED BEFORE ANY CROSS-REALM CALL, AND NEVER NEST ONE
	// avl.Iterate INSIDE ANOTHER — copied warning from
	// r/splash/arcade/duel/duel.gno's FlushPot: the raffle's own FundPot
	// iterates its own trees, and a second traversal starting inside the
	// first's callback crashes this toolchain's VM with a Go-level nil
	// dereference that no gno panic recovers from. So the walk finishes
	// here, fully, before the raffle runs at all.
	holders := make([]address, 0, pendingEntries.Size())
	units := make([]int64, 0, pendingEntries.Size())
	pendingEntries.Iterate("", "", func(key string, value any) bool {
		holders = append(holders, address(key))
		units = append(units, value.(int64))
		return false
	})
	entryUnits := pendingEntryUnits

	wugnot.Approve(cross(cur), raffleRealmAddr, amount)
	if len(holders) > 0 {
		raffle.FundPotWithEntries(cross(cur), amount, holders, units)
	} else {
		// NO ELIGIBLE HOLDERS, A REAL STATE AND NOT A DEGENERATE ONE: every
		// party of every settled duel played from realm code, or the rakes
		// were too small to buy one whole entry. The money must still go,
		// and the raffle's entry door refuses an empty batch on purpose, so
		// this is the plain door.
		raffle.FundPot(cross(cur), amount)
	}

	// ONLY NOW, WITH THE CROSS-REALM CALL HAVING RETURNED WITHOUT PANICKING
	// (see this function's own doc comment for why this ordering, not the
	// old realm's), IS THE BOOKING CLEARED.
	pendingPot = 0
	pendingSince = 0
	pendingEntries = avl.NewTree()
	pendingEntryUnits = 0

	chain.Emit("DuelFlushPot",
		"amount", strconv.FormatInt(amount, 10),
		"destination", string(raffleRealmAddr),
		"entryHolders", strconv.Itoa(len(holders)),
		"entryUnits", strconv.FormatInt(entryUnits, 10))
	checkInvariant()
	return amount
}

// SweepStuckRake is the LAST RESORT for a booked rake the raffle will not
// take, so that pendingPot is never a place money can enter and never
// leave. It transfers the WHOLE booked amount to the raffle's address by a
// PLAIN wugnot.Transfer — no raffle code runs, so nothing in the raffle can
// refuse it — and returns the amount moved. PERMISSIONLESS, and only once
// the batch's YOUNGEST CLAIM (pendingSince) has stood for
// pendingGraceBlocks. Ported from r/splash/arcade/duel/duel.gno's
// SweepStuckRake — same mechanism, same grace window, same dropped-entries
// cost, same reasoning; read that function's own doc comment for the full
// argument, including the gas figures for a full 128-holder batch. This
// comment restates only what is specific to deciding to port it here at
// all.
//
// WHY PORT A GRACE-WINDOW LAST RESORT WHEN §8a's REFUSAL IS A CERTAINTY,
// NOT THE OCCASIONAL TROUBLE THE OLD REALM'S VERSION IS A LAST RESORT FOR —
// this is the one judgment call this slice makes and states plainly rather
// than assuming. The invariant SweepStuckRake protects ("a place money can
// enter and never leave") does not care WHY FlushPot's door is shut, only
// THAT it might stay shut indefinitely. Today it is shut by construction —
// the raffle's duelRealmPkgPath names the old realm, not this one — and it
// reopens only when the raffle is redeployed naming this realm's path
// (SPEC-09 §8b). Resolve keeps booking pendingPot regardless of whether
// that redeploy ever happens, is delayed, or the swap this directory is
// scaffolding for is abandoned; Resolve must not, and does not, know or
// care. Without this function that booking would have exactly one exit
// (FlushPot), and that exit is the one this entire slice's own doc comment
// says is unproven. A grace-windowed, gate-bypassing last resort is cheap
// insurance against that exit never opening, and the mechanism — a plain
// transfer that runs no raffle code — does not depend on knowing why the
// gate is shut, only on giving the booking a second way out that the gate
// cannot touch.
//
// THE BOOKED ENTRIES ARE DROPPED ON THIS PATH, exactly as in the old
// realm's SweepStuckRake and for the identical reason: the money lands in
// the raffle's ops pot via sweepDonations, not a prize pot, so there is no
// draw left for an entry to be an entry IN — and an entry with no rake
// behind it is exactly what checkInvariant refuses. The 60/40 split is
// NOT preserved on this path (it all becomes the house's ops pot); that is
// the honest cost of a window existing at all, and it is preventable by
// anyone, at any time, by simply calling FlushPot instead.
//
// Panics if there is nothing booked, or if the window has not elapsed.
func SweepStuckRake(cur realm) int64 {
	rejectAttachedCoin(cur, "SweepStuckRake")
	amount := pendingPot
	if amount <= 0 {
		panic("duel: no rake is waiting to be delivered to the raffle")
	}
	if pendingSince <= 0 {
		// Unreachable: pendingSince is set in the same statement group that
		// makes pendingPot non-zero (Resolve, bookEntries). Loud rather than
		// treating an unset clock as elapsed.
		panic("duel: the pending rake has no booking height")
	}
	if runtime.ChainHeight()-pendingSince < pendingGraceBlocks {
		panic("duel: nothing in this batch is old enough for the last resort — call FlushPot instead")
	}

	// THE BOOKED ENTRIES DIE HERE, discarded in O(1) by replacing the tree
	// rather than walking and removing — this function is the LAST RESORT
	// for a booked rake nobody could deliver, so its own cost must not scale
	// with the batch that could not be delivered.
	sweptEntryUnits := pendingEntryUnits
	sweptEntryHolders := pendingEntries.Size()

	pendingPot = 0
	pendingSince = 0
	pendingEntries = avl.NewTree()
	pendingEntryUnits = 0

	wugnot.Transfer(cross(cur), raffleRealmAddr, amount)

	chain.Emit("DuelSweepStuckRake",
		"amount", strconv.FormatInt(amount, 10),
		"destination", string(raffleRealmAddr),
		"droppedEntryHolders", strconv.Itoa(sweptEntryHolders),
		"droppedEntryUnits", strconv.FormatInt(sweptEntryUnits, 10))
	checkInvariant()
	return amount
}

// --- the read surface ------------------------------------------------------
//
// ADDED 2026-10-08, AFTER THE REALM WAS ALREADY DEPLOYED WITHOUT IT. The first
// v2 deployment exported exactly six functions -- Post, Cancel, Accept,
// Resolve, FlushPot, SweepStuckRake -- every one an action and not one a
// question. The realm was playable and completely unreadable: no board, no
// standing offers, no live duels, and above all no way to show the countdown
// that is the whole point of settling from a future beacon round. The audit
// raised it as an open question and it was not acted on before deploy.
//
// NONE OF THESE TAKE `cur realm`, SO NONE NEEDS rejectAttachedCoin. That guard
// exists because a crossing entrypoint can have native coin attached to it and
// this realm has no way to spend ugnot; a plain function is not a transaction
// and cannot carry an envelope. Every function below is a pure read: no writes,
// no lazy initialisation, no caching into state.

// pageLimit caps every list this realm returns. UNBOUNDED READS ARE A DENIAL
// SURFACE, not merely untidy: offers and duels grow without limit, and a caller
// asking for all of them on a busy arcade gets a response no node wants to
// build. Callers page.
const pageLimit = 100

// PinOffsetRounds and BucketRounds expose the pin arithmetic, so a front end
// can work out WHICH FLIP a new acceptance would land in -- "4 minutes left to
// get into this one" -- without keeping a second copy of either number.
//
// THAT SECOND COPY IS THE WHOLE REASON THESE EXIST. The constants are a
// security budget (read pinOffsetRounds' comment), and a JavaScript duplicate
// of a security budget is one that drifts silently the moment anyone retunes
// it. The front end asks the realm instead. Same reasoning and same shape as
// arcade/speed's PinOffsetRounds.
//
// They are reads of compile-time constants: no state, no caller, nothing to
// guard.
func PinOffsetRounds() int64 { return pinOffsetRounds }
func BucketRounds() int64    { return bucketRounds }

// RoundForAcceptAt is THE question a front end actually has, answered by the
// realm that owns the answer: if a duel were accepted while the beacon reads
// `currentRound`, which round would it be pinned to?
//
// It is the exact expression Accept uses, factored out so there is ONE copy of
// it and both callers share it -- see pinnedRoundFor below. A front end can
// therefore show a truthful join deadline: the answer changes at a bucket
// boundary, and the moment it changes is the moment the current flip closes to
// newcomers.
func RoundForAcceptAt(currentRound int64) int64 { return pinnedRoundFor(currentRound) }

// RungCount and StakeOfRung expose the ladder so a front end need not hardcode
// it. Same names and shapes as the superseded realm, deliberately, so the
// existing front end's reads.js keeps working.
func RungCount() int64 { return int64(len(rungs)) }

func StakeOfRung(rung int64) int64 { return stakeOf(rung) }

// Escrowed is the players' money this realm is holding: every standing offer's
// stake plus both stakes of every live duel. It does NOT include pendingPot,
// which is the raffle's share already earned and awaiting delivery -- read
// PendingPot for that. Two separate numbers because they are two separate
// claims, and summing them would hide which is which.
func Escrowed() int64 { return escrowed }

func OfferCount() int64 { return int64(offers.Size()) }

func DuelCount() int64 { return int64(duels.Size()) }

// OfferIDs and DuelIDs page through the boards in key order. offset and limit
// are CLAMPED rather than validated: a caller asking for a million gets
// pageLimit, and one asking past the end gets an empty slice. A reader that
// panics on a bad page is a reader a front end has to guard against.
func OfferIDs(offset, limit int64) []int64 { return idsOf(offers, offset, limit) }

func DuelIDs(offset, limit int64) []int64 { return idsOf(duels, offset, limit) }

func idsOf(t *avl.Tree, offset, limit int64) []int64 {
	if offset < 0 {
		offset = 0
	}
	if limit <= 0 || limit > pageLimit {
		limit = pageLimit
	}
	out := []int64{}
	var seen int64
	t.Iterate("", "", func(k string, v any) bool {
		if seen < offset {
			seen++
			return false
		}
		if int64(len(out)) >= limit {
			return true
		}
		id, err := strconv.ParseInt(k, 10, 64)
		if err == nil {
			out = append(out, id)
		}
		seen++
		return false
	})
	return out
}

// OfferOf reports a standing offer: poster, rung, posted-at height. All zero
// for an id that is not on the table -- the same "zero means absent" shape the
// superseded realm used, so a front end can tell absent from present without a
// second call.
func OfferOf(id int64) (address, int64, int64) {
	o := getOffer(id)
	if o == nil {
		return "", 0, 0
	}
	return o.Poster, o.Rung, o.PostedAt
}

// OfferChallenge reports who an offer is aimed at and what its poster said.
// A zero opponent means open to anyone.
func OfferChallenge(id int64) (address, string) {
	o := getOffer(id)
	if o == nil {
		return "", ""
	}
	return o.Opponent, o.Label
}

// DuelOf reports a live duel: poster, taker, rung, THE PINNED ROUND, and the
// height it was accepted at.
//
// THE ROUND IS THE IMPORTANT ONE AND IS WHY THIS SHAPE DIFFERS FROM THE
// SUPERSEDED REALM'S. That realm returned a reveal deadline, a resolved flag
// and a winner, because its duels sat in state until somebody opened them.
// Here Resolve pays and DELETES in the same call, so a duel in this tree is by
// definition unsettled and there is no winner to report. What a caller wants
// instead is the round -- pair it with beacon.TimeOfRound(round) and you have
// the countdown.
func DuelOf(id int64) (address, address, int64, int64, int64) {
	d := getDuel(id)
	if d == nil {
		return "", "", 0, 0, 0
	}
	return d.Poster, d.Taker, d.Rung, d.Round, d.AcceptedAt
}

func DuelLabel(id int64) string {
	d := getDuel(id)
	if d == nil {
		return ""
	}
	return d.Label
}

// DuelRound is DuelOf's fourth value on its own, because it is the one a
// countdown polls and a caller should not have to decode a five-tuple to get
// it. 0 for an unknown or already-settled duel.
func DuelRound(id int64) int64 {
	d := getDuel(id)
	if d == nil {
		return 0
	}
	return d.Round
}

// PendingPot is the raffle's share of settled duels' rake, earned and booked
// but not yet delivered. FlushPot's own doc comment told callers to read this
// and IT DID NOT EXIST -- a comment pointing at a function nobody wrote, which
// is the shape this project has met repeatedly today.
func PendingPot() int64 { return pendingPot }

// PendingEntryUnits and PendingEntryHolders are what FlushPot will deliver
// alongside the pot. A keeper reads all three to decide whether calling is
// worth the gas.
func PendingEntryUnits() int64 { return pendingEntryUnits }

func PendingEntryHolders() int64 { return int64(pendingEntries.Size()) }

// PendingSince is the height the current booking started accruing, or 0 when
// nothing is booked. It is SweepStuckRake's grace clock, exposed so the wait
// is visible rather than inferred.
func PendingSince() int64 { return pendingSince }

// --- recent results, a bounded ring ----------------------------------------
//
// WHY THIS EXISTS. Resolve pays and DELETES the duel in the same call, so a
// settled duel leaves no state whatsoever. That is right for storage and wrong
// for the product: this design's whole point is that MANY DUELS SHARE A ROUND
// AND SETTLE TOGETHER, and a front end that showed nothing a second later would
// throw away the one moment the design was built to create.
//
// WHY IT IS BOUNDED, AND WHAT THAT COSTS. A realm cannot be pruned and nothing
// here can delete on a caller's behalf, so an unbounded history is a storage
// leak that grows for ever with no exit -- the exact shape this project forbids
// for money and forbids here for the same reason. So the ring keeps the last
// resultRingSize settlements and overwrites the oldest.
//
// WHAT IS LOST: everything older falls off and is recoverable ONLY from the
// chain's event log, which DuelResolve writes in full. That is a real loss and
// is stated rather than buried -- a reader must not mistake this for the
// complete history.
const resultRingSize = 32

type Result struct {
	DuelID int64
	Round  int64
	Winner address
	Loser  address
	Rung   int64
	Height int64
}

var (
	results    []Result // len is capped at resultRingSize
	resultNext int      // write cursor; wraps
	resultSeen int64    // total ever recorded, including those overwritten
)

// recordResult is called by Resolve immediately before it emits, with the
// values it has already computed. It never panics and never allocates beyond
// the ring: once full it overwrites in place.
func recordResult(duelID, round int64, winner, loser address, rung int64) {
	r := Result{
		DuelID: duelID,
		Round:  round,
		Winner: winner,
		Loser:  loser,
		Rung:   rung,
		Height: runtime.ChainHeight(),
	}
	resultSeen++
	if len(results) < resultRingSize {
		results = append(results, r)
		resultNext = len(results) % resultRingSize
		return
	}
	results[resultNext] = r
	resultNext = (resultNext + 1) % resultRingSize
}

// ResultCount is how many settlements the ring currently holds, which is at
// most resultRingSize. Read ResultsSeen for how many there have ever been.
func ResultCount() int64 { return int64(len(results)) }

// ResultsSeen is every settlement this realm has ever made, including those the
// ring has overwritten. The gap between this and ResultCount is exactly what a
// caller must go to the event log for.
func ResultsSeen() int64 { return resultSeen }

// ResultRingSize is the bound, exported so a front end can say "last 32"
// without hardcoding a number that might change.
func ResultRingSize() int64 { return resultRingSize }

// RecentResults returns up to `limit` settlements, MOST RECENT FIRST. limit is
// clamped to the ring's size.
func RecentResults(limit int64) []Result {
	n := int64(len(results))
	if n == 0 {
		return []Result{}
	}
	if limit <= 0 || limit > n {
		limit = n
	}
	out := make([]Result, 0, limit)
	// resultNext points at the oldest slot once full, so walk backwards from
	// the most recently written one.
	i := resultNext - 1
	if i < 0 {
		i = len(results) - 1
	}
	for c := int64(0); c < limit; c++ {
		out = append(out, results[i])
		i--
		if i < 0 {
			i = len(results) - 1
		}
	}
	return out
}

// --- Render ----------------------------------------------------------------
//
// THE PAGE gnoweb SHOWS. The first v2 deployment had none, so anybody who went
// looking at this realm directly saw nothing at all.
//
// IT MUST NEVER PANIC, WHATEVER path IS. A panicking Render does not fail
// quietly on one request -- it takes the realm's whole gnoweb page down, for
// everyone, permanently, with no way to fix it because a realm cannot be
// upgraded. So this function ignores `path` entirely, reads only, and every
// loop below is over a bounded collection.
//
// EVERY PIECE OF CALLER TEXT GOES THROUGH cell(). A Label is free text from a
// poster, and this is a markdown document: an unescaped label can forge table
// rows, inject links, or impersonate the house. sanitize.InlineText handles the
// markdown; the pipe escaping is ours, because a bare | ends a table cell.
func cell(s string) string {
	out := sanitize.InlineText(s)
	esc := ""
	for _, r := range out {
		if r == '|' {
			esc += "\\|"
			continue
		}
		esc += string(r)
	}
	return esc
}

func short(a address) string {
	s := string(a)
	if len(s) <= 12 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

func Render(path string) string {
	out := "# SPLASH — the Duel\n\n"
	out += "Two stakes, one coin, settled from a public randomness round that does not exist yet " +
		"when you commit. Neither player can steer it and neither has to come back.\n\n"

	out += "## The ladder\n\n| rung | stake |\n|---|---|\n"
	for i := range rungs {
		out += "| " + strconv.Itoa(i) + " | " + strconv.FormatInt(rungs[i], 10) + " |\n"
	}

	out += "\n## On the table\n\n"
	if offers.Size() == 0 {
		out += "_Nothing standing._\n"
	} else {
		out += "| # | poster | stake | called out | said |\n|---|---|---|---|---|\n"
		offers.Iterate("", "", func(k string, v any) bool {
			o, ok := v.(*Offer)
			if !ok {
				return false
			}
			target := "anyone"
			if o.Opponent != "" {
				target = short(o.Opponent)
			}
			out += "| " + cell(k) + " | " + short(o.Poster) + " | " +
				strconv.FormatInt(stakeOf(o.Rung), 10) + " | " + target + " | " + cell(o.Label) + " |\n"
			return false
		})
	}

	out += "\n## In the air\n\n"
	if duels.Size() == 0 {
		out += "_No duel is waiting on a round._\n"
	} else {
		out += "Each of these is already locked. The round named below decides it, and nobody " +
			"knows that round's value yet.\n\n"
		out += "| # | poster | taker | stake | decided by round |\n|---|---|---|---|---|\n"
		duels.Iterate("", "", func(k string, v any) bool {
			d, ok := v.(*Duel)
			if !ok {
				return false
			}
			out += "| " + cell(k) + " | " + short(d.Poster) + " | " + short(d.Taker) + " | " +
				strconv.FormatInt(stakeOf(d.Rung), 10) + " | " +
				strconv.FormatInt(d.Round, 10) + " |\n"
			return false
		})
	}

	out += "\n## Settled lately\n\n"
	if len(results) == 0 {
		out += "_Nothing yet._\n"
	} else {
		out += "The last " + strconv.FormatInt(int64(len(results)), 10) + " of " +
			strconv.FormatInt(resultSeen, 10) + " ever settled. Older ones are in the chain's " +
			"event log, not here — this list is deliberately bounded.\n\n"
		out += "| # | won | lost | stake | round |\n|---|---|---|---|---|\n"
		for _, r := range RecentResults(int64(len(results))) {
			out += "| " + strconv.FormatInt(r.DuelID, 10) + " | " + short(r.Winner) + " | " +
				short(r.Loser) + " | " + strconv.FormatInt(stakeOf(r.Rung), 10) + " | " +
				strconv.FormatInt(r.Round, 10) + " |\n"
		}
	}

	out += "\n## The books\n\n"
	out += "- players' money held: " + strconv.FormatInt(escrowed, 10) + "\n"
	out += "- raffle's share booked, awaiting delivery: " + strconv.FormatInt(pendingPot, 10) + "\n"
	return out
}

package catalog

import (
	"strings"

	"gno.land/p/nym-alexiscolin000/gnoradio/role/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
)

// RegisterArtist creates or updates the caller's artist profile. Names use
// Latin letters so look-alike names in other scripts cannot impersonate.
func RegisterArtist(cur realm, name, bio string) int {
	caller := userCaller(cur)
	noPayment()
	name, bio = strings.TrimSpace(name), strings.TrimSpace(bio)
	mustText("bio", bio, 0, maxBio)
	t := rd()
	id := artistOf(t, caller)
	if id != 0 {
		a := getArtist(t, id)
		if name != a.Name { // a kept name stays valid when the reserved list grows
			mustName(name)
		}
		rename(t, a, name)
		a.Bio = bio
		t.setRec(cArtists, id, fits(artistRecord(a)))
		save(cur, t)
		emitEvent("ArtistUpdated", "id", text.Itoa(id), "name", name)
		return id
	}
	mustName(name)
	a := newArtist(t, OriginArtist, name, bio, "", caller)
	t.set(cOwners, caller.String(), text.Itoa(a.ID))
	save(cur, t)
	emitEvent("ArtistRegistered", "id", text.Itoa(a.ID), "owner", caller.String(), "name", name)
	return a.ID
}

// CreateArtist adds an unclaimed artist. Admin only. A curated artist has a
// name and its page at the source (https), shown for attribution. An Audius
// or Jamendo artist is a pointer: no name or bio, and source is its platform
// id ("audius-user:<id>", "jamendo-artist:<id>"), which also keeps it unique;
// the app reads its name live from the platform.
func CreateArtist(cur realm, kind, name, bio, source string) int {
	onlyAdmin(cur)
	name, bio, source = strings.TrimSpace(name), strings.TrimSpace(bio), strings.TrimSpace(source)
	switch {
	case kind == OriginCurated:
		mustName(name)
		mustText("bio", bio, 0, maxBio)
		if source != "" && !text.HTTPS(source, 300) {
			panic("catalog: source must be an https link")
		}
	case isRef(kind):
		if name != "" || bio != "" || !validRef(kind, source) {
			panic("catalog: an Audius or Jamendo artist has no name or bio, and source " + refUser(kind) + "<id>")
		}
	default:
		panic("catalog: kind must be curated, audius or jamendo")
	}
	t := rd()
	a := newArtist(t, kind, name, bio, source, "")
	save(cur, t)
	emitEvent("ArtistCreated", "id", text.Itoa(a.ID), "kind", kind, "name", name)
	return a.ID
}

// AssignArtist hands an unclaimed artist to the wallet that proved it owns
// the profile (claim checked off-chain). Their tracks then receive tips.
func AssignArtist(cur realm, artistID int, owner address) {
	onlyAdmin(cur)
	t := rd()
	a := mustArtist(t, artistID)
	if a.Owner != "" {
		panic("catalog: artist already claimed")
	}
	if !role.Canonical(owner) || data.IsGnoRadio(owner) || artistOf(t, owner) != 0 {
		panic("catalog: this wallet is invalid or already has an artist profile")
	}
	a.Owner, a.Verified = owner, true
	putArtist(t, a)
	t.del(cClaims, store.Pad(a.ID))
	t.set(cOwners, owner.String(), text.Itoa(a.ID))
	t.activity("claim", owner, "0", text.Itoa(a.ID), "0")
	save(cur, t)
	emitEvent("ArtistClaimed", "id", text.Itoa(a.ID), "owner", owner.String())
}

// Follow and Unfollow an artist.
func Follow(cur realm, artistID int) {
	caller := userCaller(cur)
	noPayment()
	t := rd()
	a := mustArtist(t, artistID)
	if a.Owner == caller {
		panic("catalog: you cannot follow yourself")
	}
	u := user(t, caller)
	follows, ok := store.Add(u.Follows, artistID)
	if !ok {
		panic("catalog: already following")
	}
	if store.Count(u.Follows) >= maxFollows {
		panic("catalog: follows limit reached")
	}
	u.Follows = follows
	putUser(t, caller, u)
	a.Followers++
	putArtist(t, a)
	t.activityOnce("follow", caller, "0", text.Itoa(artistID))
	save(cur, t)
	emitEvent("Followed", "artist", text.Itoa(artistID), "by", caller.String())
}

func Unfollow(cur realm, artistID int) {
	caller := userCaller(cur)
	noPayment()
	t := rd()
	u := user(t, caller)
	follows, ok := store.Remove(u.Follows, artistID)
	if !ok {
		panic("catalog: not following")
	}
	u.Follows = follows
	putUser(t, caller, u)
	if a := getArtist(t, artistID); a != nil && a.Followers > 0 {
		a.Followers--
		putArtist(t, a)
	}
	save(cur, t)
	emitEvent("Unfollowed", "artist", text.Itoa(artistID), "by", caller.String())
}

func newArtist(t *tx, kind, name, bio, source string, owner address) *Artist {
	k := skeleton(name)
	if isRef(kind) {
		k = source // a pointer is reserved under its platform id ("audius-user:12")
	}
	if _, taken := t.get(cNames, k); taken {
		panic("catalog: this artist name is already taken")
	}
	a := &Artist{ID: int(t.bump(mArtists, 1)), Owner: owner, Kind: kind, Name: name, Bio: bio, Source: source, Joined: now()}
	t.addRec(cArtists, a.ID, fits(artistRecord(a)))
	t.set(cNames, k, text.Itoa(a.ID))
	return a
}

// rename moves the artist to a new name and frees the old one (the caller
// saves a). A hidden artist keeps its name so it cannot dodge moderation.
func rename(t *tx, a *Artist, name string) {
	k, old := skeleton(name), skeleton(a.Name)
	if k == old {
		a.Name = name
		return
	}
	if a.Hidden {
		panic("catalog: a hidden artist cannot change its name")
	}
	if id, ok := t.get(cNames, k); ok && text.Atoi(id) != a.ID {
		panic("catalog: this artist name is already taken")
	}
	t.set(cNames, k, text.Itoa(a.ID))
	if id, ok := t.get(cNames, old); old != "" && ok && text.Atoi(id) == a.ID { // a pointer had no name
		t.del(cNames, old)
	}
	a.Name = name
	if a.Verified {
		emitEvent("Verified", "artist", text.Itoa(a.ID), "verified", "false")
	}
	a.Verified = false
	// A pending claim was checked for the old name: a rename must not inherit
	// it, nor the old proof (a later Verify by the admin shows no host).
	t.del(cClaims, store.Pad(a.ID))
	t.del(cProofs, store.Pad(a.ID))
}

// ReleaseName frees a reserved name no visible artist is using. Admin only.
func ReleaseName(cur realm, name string) {
	onlyAdmin(cur)
	t := rd()
	k := strings.TrimSpace(name)
	if strings.HasPrefix(k, refKey) { // a pointer track's key: free once the track is hidden
		v, ok := t.get(cNames, k)
		if !ok {
			panic("catalog: this name is not reserved")
		}
		if tr := getTrack(t, text.Atoi(v)); tr != nil && !tr.Hidden {
			panic("catalog: this pointer track is visible")
		}
		t.del(cNames, k)
		save(cur, t)
		emitEvent("NameReleased", "name", k)
		return
	}
	ref := strings.HasPrefix(k, refUser(OriginAudius)) || strings.HasPrefix(k, refUser(OriginJamendo)) // a pointer's raw platform key
	if !ref {
		k = skeleton(k)
	}
	v, ok := t.get(cNames, k)
	if !ok {
		panic("catalog: this name is not reserved")
	}
	if a := getArtist(t, text.Atoi(v)); a != nil && !a.Hidden && (ref && a.Source == k || !ref && skeleton(a.Name) == k) {
		panic("catalog: this name belongs to a visible artist")
	}
	t.del(cNames, k)
	save(cur, t)
	emitEvent("NameReleased", "name", k)
}

// refUser is the source prefix of a pointer artist's platform id.
func refUser(kind string) string {
	if kind == OriginJamendo {
		return "jamendo-artist:"
	}
	return "audius-user:"
}

func validRef(kind, source string) bool {
	return strings.HasPrefix(source, refUser(kind)) && alnum(strings.TrimPrefix(source, refUser(kind)), 1, 32)
}

// Package catalog is GnoRadio's catalog rules, release 1: artists, tracks,
// albums, playlists, likes, follows, tips, support, moderation and
// verification. Other GnoRadio realms (radio, tickets, home) read it through
// the value getters in read.gno; it imports none of them.
//
// It keeps no state but its admin role. Every record lives in the data realm
// (gno.land/r/nym-alexiscolin000/gnoradio/data), in the "catalog/…" collections only the current
// catalog writer may change (db.gno). Promo budgets sit in data's vault, so a
// later release takes over the data and the coins without copying anything.
//
// Four track origins share one catalog:
//   - "artist":  published by the artist's own wallet, tips enabled;
//   - "curated": imported by the admin from CC0 / CC BY / CC BY-SA / CC BY-NC / CC BY-NC-SA sources;
//   - "audius", "jamendo": pointers the admin imports. The record keeps only
//     what the radio needs (platform id, genre, duration, licence); the app
//     reads title, artist and cover live, since both platforms' API terms
//     allow session caching only (attribution required).
//
// Imported artists start unclaimed; once the admin assigns them to
// a wallet (AssignArtist) or the robot verifies a claim, their tracks receive
// tips.
//
// Tips and support are forwarded in the same transaction: this realm ends
// every transaction holding no coins.
package catalog

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strings"
	"time"

	"gno.land/p/nym-alexiscolin000/gnoradio/role/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
)

const (
	version = "1.0.0"
	denom   = "ugnot"
	ugnot   = 1_000_000

	OriginArtist  = "artist"
	OriginCurated = "curated"
	OriginAudius  = "audius"
	OriginJamendo = "jamendo"

	minTip         = 100_000           // 0.1 GNOT
	maxTip         = 1_000_000 * ugnot // keeps share math far from overflow
	maxSplits      = 4
	maxSplitPct    = 90 // the artist always keeps at least 10%
	earlyBadges    = 10
	minDuration    = 10
	maxDuration    = 1200
	maxPerArtist   = 500 // tracks per artist
	maxAlbumTracks = 40
	maxListTracks  = 200
	maxUserLists   = 50
	maxFollows     = 1000
	maxUserReports = 5   // open reports per reporter
	maxTitle       = 64  // track, album and playlist titles, in characters
	maxBio         = 280 // artist bio
	maxCredits     = 160 // a track's credits and a curated import's attribution
	maxReason      = 200 // report and moderation reasons
	topSize        = 10
	maxSupportPct  = 50
)

// NumGenres is the size of the fixed genre list; genre ids are 1..NumGenres.
const NumGenres = 20

var genres = [NumGenres + 1]string{"",
	"Electronica", "Synthwave", "Ambient", "Techno", "House", "Drum & Bass", "Dubstep & Trap",
	"Lo-fi Beats", "Hip-hop & Rap", "R&B & Soul", "Rock & Indie", "Metal & Punk", "Pop",
	"Jazz & Blues", "Folk & Acoustic", "Cinematic & Classical", "World", "Latin", "Reggae & Dub", "Funk & Disco"}

// licenses an artist may pick; curated imports are limited to CC0, BY, BY-SA, BY-NC and BY-NC-SA
// (no ND, no reserved rights).
var licenses = []string{
	"CC0-1.0", "CC-BY-4.0", "CC-BY-SA-4.0", "CC-BY-ND-4.0",
	"CC-BY-NC-4.0", "CC-BY-NC-SA-4.0", "CC-BY-NC-ND-4.0", "ALL-RIGHTS-RESERVED",
}

// AudiusLicense is the license id of tracks streamed from Audius.
const AudiusLicense = "Audius-OML"

const rightsTerms = "I own or control the rights to this recording and its composition, or hold a licence that allows this, and I grant the operator of GnoRadio and its users a worldwide, non-exclusive, royalty-free licence to store, stream, broadcast and display it through GnoRadio and gno.land for as long as it is published."

var (
	self  string     // this realm's path
	admin *role.Role // the moderator; nil when a release before renounced it
)

// init takes the admin over from the previous release (catalog/config
// "admin"), or names the deployer. While this realm is the catalog writer
// (release 1 at deploy) it also makes the catalog's collections.
func init(cur realm) {
	self = cur.PkgPath()
	holder, mirrored := data.Get(cConfig, "admin")
	if !mirrored {
		deployer := unsafe.OriginCaller()
		if deployer == "" && runtime.ChainID() == "dev" {
			deployer = chain.PackageAddress(self + "/dev") // gno test: a key nobody holds
		}
		holder = deployer.String()
	}
	if holder != "" {
		admin = role.New("admin", address(holder))
	}
	if data.Writer("catalog") == self {
		setup(cur, address(holder))
	}
}

// ---- helpers shared by every file ----

func now() int64 { return time.Now().Unix() }

func userCaller(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("catalog: call this directly from your wallet")
	}
	return cur.Previous().Address()
}

// adminAddr is the admin: the data realm's mirror is the authority, so a
// change the previous release made after this one was deployed counts.
func adminAddr() address {
	h, ok := data.Get(cConfig, "admin")
	return role.Mirror(admin, h, ok)
}

// syncAdmin adopts the mirror when the previous release changed it after
// this one's init (during the release's delay).
func syncAdmin() {
	h, ok := data.Get(cConfig, "admin")
	admin = role.Adopt(admin, "admin", h, ok)
}

func onlyAdmin(cur realm) {
	syncAdmin()
	if admin == nil || !admin.Is(0, cur) {
		panic("catalog: admin only")
	}
	noPayment()
}

func noPayment() {
	if len(unsafe.OriginSend()) != 0 {
		panic("catalog: this action does not take coins")
	}
}

// paid returns the ugnot attached to the call; anything else is refused.
func paid() int64 {
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != denom || sent[0].Amount <= 0 {
		panic("catalog: attach an amount in ugnot")
	}
	return sent[0].Amount
}

func emitEvent(name string, kv ...string) { chain.Emit(name, kv...) }

// ---- release and admin ----

// Ready tells the data realm that this release is on chain (see
// data.Propose). Anyone may call it.
func Ready(cur realm) {
	noPayment()
	data.Ready(cross(cur))
}

// OfferAdmin offers the admin role to an address (offering it to the admin
// cancels the offer); AcceptAdmin takes it. Each change is mirrored to the
// data realm, so the next release keeps the admin.
func OfferAdmin(cur realm, to address) {
	onlyAdmin(cur)
	admin.Offer(0, cur, to)
}

func AcceptAdmin(cur realm) {
	noPayment()
	syncAdmin()
	if admin == nil {
		panic("catalog: nothing offered to you")
	}
	admin.Accept(0, cur)
	data.Set(cross(cur), cConfig, "admin", admin.Holder().String())
}

// RenounceAdmin gives the admin role up for good, for this release and the
// next ones.
func RenounceAdmin(cur realm) {
	onlyAdmin(cur)
	admin.Renounce(0, cur)
	data.Set(cross(cur), cConfig, "admin", "")
}

// Render points gnoweb visitors to the GnoRadio site; a retired release says
// which realm took over.
func Render(_ string) string {
	home := strings.TrimPrefix(data.Writer("home"), "gno.land") // the home of the release in force
	d := strings.TrimPrefix(dataPath, "gno.land")
	out := "# GnoRadio · catalog\n\nThis contract holds GnoRadio's catalog rules; its data lives in [" + d + "](" + d +
		"). The site lives at [" + home + "](" + home + ").\n"
	if w := data.Writer("catalog"); w != self {
		out += "\nThis release is retired: the catalog is now `" + w + "`.\n"
	}
	return out
}

// Info is the catalog's summary for the app: counts, the admin and the
// realm that writes the catalog now ("current", this one unless retired).
func Info() string {
	t := rd()
	return `{"version":` + text.Str(version) + `,"artists":` + text.Itoa64(t.count(mArtists)) + `,"tracks":` + text.Itoa64(t.count(mTracks)) +
		`,"albums":` + text.Itoa64(t.count(mAlbums)) + `,"playlists":` + text.Itoa64(t.count(mPlaylists)) + `,"listeners":` + text.Itoa(data.Size(cUsers)) +
		`,"genres":` + text.Itoa(NumGenres) + `,"now":` + text.Itoa64(now()) + `,"current":` + text.Str(data.Writer("catalog")) +
		`,"admin":` + text.Str(adminAddr().String()) + `}`
}

package catalog

import (
	"strings"

	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
)

// The catalog's collections in the data realm (docs/ARCHITECTURE-v1.md,
// section 3). P(n) is store.Pad. Records are store.Rec values; id lists are
// store's packed lists.
const (
	cArtists    = "catalog/artists"    // P((id-1)/chunkSize) -> artist heads (chunk)
	cAlists     = "catalog/alists"     // P(artist) -> Rec(track ids, album ids)
	cOwners     = "catalog/owners"     // owner address -> artist id
	cNames      = "catalog/names"      // name skeleton -> artist id
	cTracks     = "catalog/tracks"     // P((id-1)/chunkSize) -> track records (chunk)
	cGenres     = "catalog/genres"     // P(genre)/P(id>>9) -> packed track ids
	cAlbums     = "catalog/albums"     // P((id-1)/chunkSize) -> album records (chunk)
	cPlaylists  = "catalog/playlists"  // P(id) -> playlist record
	cUsers      = "catalog/users"      // address -> Rec(follows, tipped, playlists, reports)
	cLikes      = "catalog/likes"      // address/P(id>>9) -> packed liked track ids
	cTipped     = "catalog/tipped"     // address/P(id>>9) -> packed tipped track ids
	cReports    = "catalog/reports"    // P(id) -> report record (open reports only)
	cRemoved    = "catalog/removed"    // kind:id -> moderator's reason, "" when its artist hid it
	cHosts      = "catalog/hosts"      // allowed https host -> "1"
	cMeta       = "catalog/meta"       // "n" -> counts
	cTops       = "catalog/tops"       // liked|artists|fans|support -> ranks
	cActivity   = "catalog/activity"   // P(0..63) -> activity record (ring, head in meta)
	cConfig     = "catalog/config"     // admin, treasury, goal, bot, gen
	cSupporters = "catalog/supporters" // address -> lifetime support
	cMonthly    = "catalog/monthly"    // YYYY-MM -> support that month
	cPromo      = "catalog/promo"      // P(artist) -> promo percent
	cBudgets    = "catalog/budgets"    // P(artist) -> sponsored-pick settings and stats
	cWalletDay  = "catalog/walletday"  // address -> day|artist ids sponsored that day
	cClaims     = "catalog/claims"     // P(artist) -> pending claim
	cProofs     = "catalog/proofs"     // P(artist) -> proof URL of the last finalized claim
)

var collections = []string{cArtists, cAlists, cOwners, cNames, cTracks, cGenres, cAlbums, cPlaylists, cUsers,
	cLikes, cTipped, cReports, cRemoved, cHosts, cMeta, cTops, cActivity, cConfig, cSupporters, cMonthly,
	cPromo, cBudgets, cWalletDay, cClaims, cProofs}

const (
	chunkSize    = 8    // records per key of the chunked collections; tickets/nft reads artists with it: frozen
	maxRec       = 1500 // longest artist, track or album record when written by its author
	idRange      = 9    // likes, tips and genres are kept per range of 1<<idRange track ids
	activitySize = 64
)

// setup makes the catalog's collections and its first settings, once: a
// later release finds them made (it is not the writer in its init).
func setup(cur realm, holder address) {
	for _, c := range collections {
		data.Make(cross(cur), c)
	}
	if data.Has(cMeta, "n") {
		return
	}
	ops := store.Ops{}.Set(cMeta, "n", newCounts()).Set(cConfig, "admin", holder.String()).
		Set(cHosts, "archive.org", "1").Set(cHosts, "upload.wikimedia.org", "1")
	data.Batch(cross(cur), ops)
}

// tx reads each key from the data realm once and writes every key it
// changed once, in one call (data.Set or data.Batch). Every entrypoint loads
// what it needs, changes it in its tx, then saves; readers use one too, so a
// chunk is decoded once per call. A tx is never stored.
type tx struct {
	es  []entry
	idx map[string]int // entry key -> position in es
}

type entry struct {
	c, k  string // collection and key
	val   string
	ok    bool // the key exists
	dirty bool
}

func rd() *tx { return &tx{idx: map[string]int{}} }

// at finds a key's entry, reading it from data the first time unless blind
// (a key about to be overwritten).
func (t *tx) at(c, k string, blind bool) *entry {
	key := c + " " + k
	if i, ok := t.idx[key]; ok {
		return &t.es[i]
	}
	e := entry{c: c, k: k}
	if !blind {
		e.val, e.ok = data.Get(c, k)
	}
	t.idx[key] = len(t.es)
	t.es = append(t.es, e)
	return &t.es[len(t.es)-1]
}

func (t *tx) get(c, k string) (string, bool) {
	e := t.at(c, k, false)
	return e.val, e.ok
}

func (t *tx) val(c, k string) string { return t.at(c, k, false).val }

func (t *tx) set(c, k, v string) {
	e := t.at(c, k, false)
	e.val, e.ok, e.dirty = v, true, true
}

// put writes a key without reading it first.
func (t *tx) put(c, k, v string) {
	e := t.at(c, k, true)
	e.val, e.ok, e.dirty = v, true, true
}

func (t *tx) del(c, k string) {
	if e := t.at(c, k, false); e.ok {
		e.val, e.ok, e.dirty = "", false, true
	}
}

// save writes what t changed: one data.Set or data.Remove, or Batches of
// 64 ops (a bulk ResolveReports may change more keys than one Batch takes;
// the transaction keeps them atomic, as in radio).
func save(cur realm, t *tx) {
	var ops store.Ops
	for _, e := range t.es {
		if !e.dirty {
			continue
		}
		if e.ok {
			ops = ops.Set(e.c, e.k, e.val)
		} else {
			ops = ops.Del(e.c, e.k)
		}
	}
	for len(ops) > 4*64 {
		data.Batch(cross(cur), ops[:4*64])
		ops = ops[4*64:]
	}
	switch {
	case len(ops) == 0:
	case len(ops) > 4:
		data.Batch(cross(cur), ops)
	case ops[0] == store.OpSet:
		data.Set(cross(cur), ops[1], ops[2], ops[3])
	default:
		data.Remove(cross(cur), ops[1], ops[2])
	}
}

// ---- chunked records: artists, tracks and albums, chunkSize per key ----

// rec returns record id of a chunked collection ("" when absent).
func (t *tx) rec(c string, id int) string {
	if id < 1 {
		return ""
	}
	k, i := store.Slot(id, chunkSize)
	ch := t.val(c, k)
	if ch == "" {
		return ""
	}
	return store.Field(ch, i)
}

// point is tx.rec without a tx, for the getters that read one or two
// records: no tx to build for a call the radio makes in loops.
func point(c string, id int) string {
	if id < 1 {
		return ""
	}
	k, i := store.Slot(id, chunkSize)
	if ch, _ := data.Get(c, k); ch != "" {
		return store.Field(ch, i)
	}
	return ""
}

// artistAt is field f of an artist's record, "" when unknown (point).
func artistAt(id, f int) string {
	if rec := point(cArtists, id); rec != "" {
		return store.Field(rec, f)
	}
	return ""
}

// setRec replaces record id.
func (t *tx) setRec(c string, id int, rec string) {
	k, i := store.Slot(id, chunkSize)
	t.set(c, k, store.With(t.val(c, k), i, rec))
}

// addRec appends record id, the collection's next one.
func (t *tx) addRec(c string, id int, rec string) {
	k, i := store.Slot(id, chunkSize)
	if i == 0 {
		t.put(c, k, store.Rec(rec))
		return
	}
	t.set(c, k, store.Append(t.val(c, k), rec))
}

// fits refuses a record too long for its chunk: chunkSize records, each
// with room left for its counters and early badges, stay under data's
// 16 KiB value limit, so one author can never fill a chunk others share.
func fits(rec string) string {
	if len(rec) > maxRec {
		panic("catalog: these details are too long, shorten the links or texts")
	}
	return rec
}

// ---- counts: catalog/meta "n", one field each ----

// Count fields. A count is read and changed in place (store.Field and
// store.With): converting numbers costs gas, so nothing decodes the record.
// Reaching field i walks the i before it: what a publish changes comes first.
const (
	mTracks = 0
	mGenre  = 0 // + genre id (1..NumGenres): tracks filed under it
)

const (
	mArtists = NumGenres + 1 + iota
	mAlbums
	mPlaylists
	mReports // filed
	mOpen    // reports not yet resolved
	mSupporters
	mSupport // ugnot
	mFields
)

func newCounts() string {
	fs := make([]string, mFields)
	for i := range fs {
		fs[i] = "0"
	}
	return store.Rec(fs...)
}

func (t *tx) count(i int) int64 {
	if m := t.val(cMeta, "n"); m != "" {
		return text.Atoi64(store.Field(m, i))
	}
	return 0
}

// bump adds d to count i and returns the new value; save writes it.
func (t *tx) bump(i int, d int64) int64 {
	n := t.count(i) + d
	t.set(cMeta, "n", store.With(t.val(cMeta, "n"), i, text.Itoa64(n)))
	return n
}

// ---- id ranges: a sorted packed list per 512 ids ----

func rangeKey(prefix string, id int) string { return prefix + "/" + store.Pad(id>>idRange) }

// addID and removeID change a ranged id set; false when nothing changed.
func (t *tx) addID(c, prefix string, id int) bool {
	k := rangeKey(prefix, id)
	list := t.val(c, k)
	if n := store.Count(list); n == 0 || store.At(list, n-1) < id {
		t.set(c, k, list+store.Enc(id)) // a new highest id, as every new track's
		return true
	}
	list, ok := store.Add(list, id)
	if ok {
		t.set(c, k, list)
	}
	return ok
}

func (t *tx) removeID(c, prefix string, id int) bool {
	k := rangeKey(prefix, id)
	list, ok := store.Remove(t.val(c, k), id)
	switch {
	case !ok:
	case list == "":
		t.del(c, k)
	default:
		t.set(c, k, list)
	}
	return ok
}

// rangePage reads up to limit ids of a ranged set from offset, highest
// first, and the set's size, one data.Page per 100 ranges.
func rangePage(c, prefix string, offset, limit int) (ids []int, total int) {
	end := prefix + "0"
	// ponytail: at most 10 pages of 100 ranges (512,000 track ids); keep a
	// counter per set if the catalog ever gets near that.
	for p := 0; p < 10; p++ {
		keys, lists := store.Rows(data.Page(c, prefix+"/", end, 100, true))
		for _, l := range lists {
			n := store.Count(l)
			total += n
			if offset >= n {
				offset -= n
				continue
			}
			if len(ids) < limit {
				ids = append(ids, store.Page(l, offset, limit-len(ids), true)...)
			}
			offset = 0
		}
		if len(keys) < 100 {
			break
		}
		end = keys[len(keys)-1]
	}
	return ids, total
}

// ---- activity ring and leaderboards ----

// Activity is one entry of the public activity feed.
type Activity struct {
	Kind   string // publish | like | follow | tip | support | playlist | album | claim
	By     address
	Track  int // track, playlist or album id depending on Kind
	Artist int
	Amount int64
	At     int64
}

// activity writes the next slot of the fixed-size ring (storage never
// grows), numbers given as decimal strings. The ring's head is a key of its
// own in catalog/meta: rewriting the counts would cost a like more.
func (t *tx) activity(kind string, by address, track, artist, amount string) {
	h := text.Atoi(t.val(cMeta, "head"))
	t.put(cActivity, store.Pad(h), store.Rec(kind, by.String(), track, artist, amount, text.Itoa64(now())))
	t.set(cMeta, "head", text.Itoa((h+1)%activitySize))
}

// activityOnce is activity for likes and follows, skipped when the newest
// entry is already this wallet's of the same kind: like and unlike cycles,
// or a run of likes, take one slot of the feed, not the whole ring.
func (t *tx) activityOnce(kind string, by address, track, artist string) {
	h := text.Atoi(t.val(cMeta, "head"))
	last := t.val(cActivity, store.Pad((h+activitySize-1)%activitySize))
	if store.Field(last, 0) == kind && store.Field(last, 1) == by.String() {
		return
	}
	t.activity(kind, by, track, artist, "0")
}

type Rank struct {
	Key   string
	Value int64
}

// Leaderboard names in cTops.
const (
	topLiked   = "liked"   // track ids by likes
	topArtists = "artists" // artist ids by tips
	topFans    = "fans"    // addresses by tipped
	topSupport = "support" // addresses by support
)

func ranks(rec string) []Rank {
	if rec == "" {
		return nil
	}
	f := store.Fields(rec)
	out := make([]Rank, 0, len(f)/2)
	for i := 0; i+1 < len(f); i += 2 {
		out = append(out, Rank{f[i], text.Atoi64(f[i+1])})
	}
	return out
}

func (t *tx) top(name string) []Rank { return ranks(t.val(cTops, name)) }

// rank moves k to v in a leaderboard, written only when the ranking
// changed. Most changes leave it alone: when v grew (up) and is no higher
// than the tenth value, k was not ranked either, so nothing is decoded. A
// value that went down is looked for in the list (a substring match only
// means "maybe ranked").
func (t *tx) rank(name, k string, v int64, up bool) {
	old := t.val(cTops, name)
	if old != "" {
		if last := store.Field(old, 2*topSize-1); last != "" && v <= text.Atoi64(last) && (up || !strings.Contains(old, k)) {
			return
		}
	}
	list := updateTop(ranks(old), k, v)
	fs := make([]string, 0, 2*len(list))
	for _, r := range list {
		fs = append(fs, r.Key, text.Itoa64(r.Value))
	}
	if rec := store.Rec(fs...); rec != old {
		t.set(cTops, name, rec)
	}
}

// updateTop keeps a short leaderboard sorted by value, highest first.
func updateTop(list []Rank, k string, v int64) []Rank {
	if len(list) == topSize && v <= list[topSize-1].Value {
		ranked := false
		for _, r := range list {
			ranked = ranked || r.Key == k
		}
		if !ranked {
			return list
		}
	}
	out := make([]Rank, 0, topSize+1)
	for _, r := range list {
		if r.Key != k {
			out = append(out, r)
		}
	}
	i := len(out)
	for i > 0 && out[i-1].Value < v {
		i--
	}
	if i >= topSize {
		return out
	}
	out = append(out, Rank{})
	copy(out[i+1:], out[i:])
	out[i] = Rank{k, v}
	if len(out) > topSize {
		out = out[:topSize]
	}
	return out
}

package catalog

import (
	"strconv"
	"strings"

	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
)

// JSON exports for the GnoRadio app and indexers (vm/qeval). Their shapes
// are the app's contract (app/src/lib): change them together.

func ints(xs []int) string {
	var b strings.Builder
	b.WriteString("[")
	for i, x := range xs {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(text.Itoa(x))
	}
	b.WriteString("]")
	return b.String()
}

// The JSON is written from the records' fields as stored: numbers are
// already decimal strings, and converting them costs gas.

// trackJSON writes track id from its record and its artist's head.
func trackJSON(id int, rec, arec string) string {
	f := store.Fields(rec)
	out := `{"id":` + text.Itoa(id) + `,"artist":` + f[fArtist] + `,"artistName":"` + store.Field(arec, aName) +
		`","claimed":` + strconv.FormatBool(store.Field(arec, aOwner) != "") + `,"origin":"` + f[fOrigin] + `","title":"` + f[fTitle] +
		`","genre":` + f[fGenre] + `,"duration":` + f[fDuration] + `,"license":"` + f[fLicense] +
		`","cmo":"` + f[fCMO] + `","credits":"` + f[fCredits] + `","audio":"` + f[fAudio] + `","audioSha256":"` + f[fAudioSHA] +
		`","cover":"` + f[fCover] + `","coverSha256":"` + f[fCoverSHA] + `","source":"` + f[fSource] +
		`","attribution":"` + f[fAttribution] + `","album":` + f[fAlbum] + `,"created":` + f[fCreated] +
		`,"likes":` + f[fLikes] + `,"tips":` + f[fTips] + `,"supporters":` + f[fSupporters] + `,"splits":[`
	if f[fSplits] != "" {
		for i, p := range strings.Split(f[fSplits], ",") {
			to, pct, _ := strings.Cut(p, ":")
			if i > 0 {
				out += ","
			}
			out += `{"to":"` + to + `","pct":` + pct + `}`
		}
	}
	return out + `]}`
}

// playableRec returns a track's record and its artist's head when both are
// visible ("" otherwise).
func playableRec(t *tx, id int) (rec, arec string) {
	rec = t.rec(cTracks, id)
	if rec == "" || store.Field(rec, fHidden) != "" {
		return "", ""
	}
	arec = t.rec(cArtists, text.Atoi(store.Field(rec, fArtist)))
	if arec == "" || store.Field(arec, aHidden) != "" {
		return "", ""
	}
	return rec, arec
}

// TrackJSON returns one playable track.
func TrackJSON(id int) string {
	rec, arec := playableRec(rd(), id)
	if rec == "" {
		panic("catalog: unknown track")
	}
	return trackJSON(id, rec, arec)
}

// TracksJSON pages through playable tracks (newest first), at most 100.
// Chunks and artist heads are read once per page.
func TracksJSON(offset, limit int) string {
	limit = store.Limit(limit, maxBatch)
	t := rd()
	total := int(t.count(mTracks))
	var b strings.Builder
	b.WriteString(`{"total":` + text.Itoa(total) + `,"tracks":[`)
	n := 0
	for _, id := range seqPage(total, offset, limit, true) {
		if rec, arec := playableRec(t, id); rec != "" {
			if n > 0 {
				b.WriteString(",")
			}
			b.WriteString(trackJSON(id, rec, arec))
			n++
		}
	}
	b.WriteString(`]}`)
	return b.String()
}

func ArtistJSON(id int) string {
	t := rd()
	arec := t.rec(cArtists, id)
	if arec == "" || store.Field(arec, aHidden) != "" {
		panic("catalog: unknown artist")
	}
	return artistJSON(t, id, arec)
}

func artistJSON(t *tx, id int, arec string) string {
	f := store.Fields(arec)
	trackIDs, albumIDs := lists(t, id)
	promo, ok := t.get(cPromo, store.Pad(id))
	if !ok {
		promo = text.Itoa(defaultPromoPct)
	}
	a := &Artist{ID: id, Hidden: f[aHidden] != "", Owner: address(f[aOwner]), Verified: f[aVerified] != ""}
	return `{"id":` + text.Itoa(id) + `,"name":` + text.Str(f[aName]) + `,"kind":` + text.Str(f[aKind]) + `,"owner":` + text.Str(f[aOwner]) +
		`,"bio":` + text.Str(f[aBio]) + `,"source":` + text.Str(f[aSource]) + `,"joined":` + f[aJoined] + `,"tips":` + f[aTips] +
		`,"followers":` + f[aFollowers] + `,"verified":` + strconv.FormatBool(a.Verified) +
		`,"proofHost":` + text.Str(proofHost(t, id, f[aVerified])) + `,"promo":` + promo +
		`,"sponsor":` + text.Itoa64(offer(t, a)) + `,"tracks":` + store.JSON(trackIDs) + `,"albums":` + store.JSON(albumIDs) + `}`
}

// albumJSON writes a visible album ("" when it or its artist is hidden).
func albumJSON(t *tx, id int) string {
	rec := t.rec(cAlbums, id)
	if rec == "" {
		return ""
	}
	f := store.Fields(rec)
	if f[6] != "" || !artistVisible(t, text.Atoi(f[0])) {
		return ""
	}
	return `{"id":` + text.Itoa(id) + `,"artist":` + f[0] + `,"title":` + text.Str(f[1]) + `,"cover":` + text.Str(f[2]) +
		`,"coverSha256":` + text.Str(f[3]) + `,"year":` + f[4] + `,"tracks":` + store.JSON(f[7]) + `}`
}

func AlbumJSON(id int) string {
	s := albumJSON(rd(), id)
	if s == "" {
		panic("catalog: unknown album")
	}
	return s
}

// playlistJSON writes a visible playlist ("" when hidden or unknown).
func playlistJSON(t *tx, id int) string {
	rec := ""
	if id > 0 {
		rec = t.val(cPlaylists, store.Pad(id))
	}
	if rec == "" || store.Field(rec, 3) != "" {
		return ""
	}
	f := store.Fields(rec)
	return `{"id":` + text.Itoa(id) + `,"owner":` + text.Str(f[0]) + `,"title":` + text.Str(f[1]) +
		`,"updated":` + f[2] + `,"tracks":` + store.JSON(f[4]) + `}`
}

func PlaylistJSON(id int) string {
	s := playlistJSON(rd(), id)
	if s == "" {
		panic("catalog: unknown playlist")
	}
	return s
}

// UserJSON returns a listener's public counters (likes are paged with LikesJSON).
func UserJSON(addr address) string {
	likes, follows, tipped, lists := UserStats(addr)
	return `{"address":` + text.Str(addr.String()) + `,"likes":` + text.Itoa(likes) + `,"follows":` + text.Itoa(follows) +
		`,"tipped":` + text.Itoa64(tipped) + `,"playlists":` + ints(lists) + `,"artist":` + text.Itoa(ArtistOf(addr)) + `}`
}

func LikesJSON(addr address, offset, limit int) string { return ints(LikedPage(addr, offset, limit)) }

func GenresJSON() string {
	var b strings.Builder
	b.WriteString("[")
	for g := 1; g <= NumGenres; g++ {
		if g > 1 {
			b.WriteString(",")
		}
		b.WriteString(`{"id":` + text.Itoa(g) + `,"name":` + text.Str(genres[g]) + `}`)
	}
	b.WriteString("]")
	return b.String()
}

// maxBatch caps the batched readers, so one query stays far below the qeval budget.
const maxBatch = 100

// batch writes {"total":n,"<key>":[...]} for ids offset+1..offset+limit, skipping
// hidden items; one query replaces up to 100 single reads.
func batch(key string, total, offset, limit int, one func(id int) string) string {
	limit = store.Limit(limit, maxBatch)
	offset = max0(offset)
	var b strings.Builder
	b.WriteString(`{"total":` + text.Itoa(total) + `,"` + key + `":[`)
	n := 0
	for id := offset + 1; id <= total && id <= offset+limit; id++ {
		if s := one(id); s != "" {
			if n > 0 {
				b.WriteString(",")
			}
			b.WriteString(s)
			n++
		}
	}
	b.WriteString(`]}`)
	return b.String()
}

// ArtistsJSON returns visible artists with ids offset+1..offset+limit (at most 100).
func ArtistsJSON(offset, limit int) string {
	t := rd()
	return batch("artists", int(t.count(mArtists)), offset, limit, func(id int) string {
		if arec := t.rec(cArtists, id); arec != "" && store.Field(arec, aHidden) == "" {
			return artistJSON(t, id, arec)
		}
		return ""
	})
}

// AlbumsJSON returns visible albums with ids offset+1..offset+limit (at most 100).
func AlbumsJSON(offset, limit int) string {
	t := rd()
	return batch("albums", int(t.count(mAlbums)), offset, limit, func(id int) string { return albumJSON(t, id) })
}

// PlaylistsJSON returns visible playlists with ids offset+1..offset+limit (at most 100).
func PlaylistsJSON(offset, limit int) string {
	t := rd()
	return batch("playlists", int(t.count(mPlaylists)), offset, limit, func(id int) string { return playlistJSON(t, id) })
}

package catalog

import (
	"strconv"
	"strings"

	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
)

// Report flags a track, album, artist or playlist for the moderators
// (e.g. "broken link", "not the real artist", "copyright").
func Report(cur realm, kind string, target int, reason string) {
	caller := userCaller(cur)
	noPayment()
	reason = strings.TrimSpace(reason)
	mustText("reason", reason, 4, maxReason)
	t := rd()
	switch kind {
	case "track":
		mustTrack(t, target)
	case "album":
		if al := getAlbum(t, target); al == nil || al.Hidden {
			panic("catalog: unknown album")
		}
	case "artist":
		mustArtist(t, target)
	case "playlist":
		if p := getPlaylist(t, target); p == nil || p.Hidden {
			panic("catalog: unknown playlist")
		}
	default:
		panic("catalog: kind must be track, album, artist or playlist")
	}
	u := user(t, caller)
	if u.Reports >= maxUserReports {
		panic("catalog: you have " + text.Itoa(maxUserReports) + " open reports, wait for the moderators")
	}
	u.Reports++
	putUser(t, caller, u)
	t.bump(mOpen, 1)
	t.put(cReports, store.Pad(int(t.bump(mReports, 1))), store.Rec(kind, text.Itoa(target), reason, caller.String(), text.Itoa64(now())))
	save(cur, t)
	emitEvent("Reported", "kind", kind, "target", text.Itoa(target), "by", caller.String())
}

func getReport(t *tx, id int) (ReportInfo, bool) {
	rec, ok := t.get(cReports, store.Pad(id))
	if !ok || id < 1 {
		return ReportInfo{}, false
	}
	f := store.Fields(rec)
	return ReportInfo{ID: id, Kind: f[0], Target: f[1], Reason: f[2], By: address(f[3]), At: text.Atoi64(f[4])}, true
}

// ResolveReport closes a report once handled. Admin only.
func ResolveReport(cur realm, id int) {
	onlyAdmin(cur)
	t := rd()
	if !resolve(t, id) {
		panic("catalog: unknown report")
	}
	save(cur, t)
}

// ResolveReports closes the open reports with ids from..from+count-1 (count
// 1-50) in one transaction, e.g. a run of spam reports; ids already closed
// are skipped. There is no global cap on open reports, so spam never blocks
// an honest reporter: each wallet keeps at most 5 open. Admin only.
func ResolveReports(cur realm, from, count int) {
	onlyAdmin(cur)
	if count < 1 || count > 50 {
		panic("catalog: resolve 1 to 50 reports at a time")
	}
	t := rd()
	for id := from; id < from+count; id++ {
		resolve(t, id)
	}
	save(cur, t)
}

// resolve closes one report, false when there is no such open report.
func resolve(t *tx, id int) bool {
	r, ok := getReport(t, id)
	if !ok {
		return false
	}
	t.del(cReports, store.Pad(id))
	if t.count(mOpen) > 0 {
		t.bump(mOpen, -1)
	}
	if u := user(t, r.By); u.Reports > 0 {
		u.Reports--
		putUser(t, r.By, u)
	}
	emitEvent("ReportResolved", "id", text.Itoa(id))
	return true
}

// Hide or restore content. Admin only; hiding takes a public reason (4-200
// characters) and restoring works on anything, whoever hid it. Hidden content
// stays on-chain (and on IPFS); it is no longer listed, played or tippable.
// Radio stations drop a hidden track on their next Refresh
// (radio.RefreshArtist for a whole artist).
func HideTrack(cur realm, trackID int, hidden bool, reason string) {
	onlyAdmin(cur)
	t := rd()
	tr := getTrack(t, trackID)
	if tr == nil {
		panic("catalog: unknown track")
	}
	tr.Hidden = hidden
	putTrack(t, tr)
	moderate(cur, t, "track", trackID, hidden, reason)
}

func HideAlbum(cur realm, albumID int, hidden bool, reason string) {
	onlyAdmin(cur)
	t := rd()
	al := getAlbum(t, albumID)
	if al == nil {
		panic("catalog: unknown album")
	}
	al.Hidden = hidden
	putAlbum(t, al)
	moderate(cur, t, "album", albumID, hidden, reason)
}

func HideArtist(cur realm, artistID int, hidden bool, reason string) {
	onlyAdmin(cur)
	t := rd()
	a := getArtist(t, artistID)
	if a == nil {
		panic("catalog: unknown artist")
	}
	a.Hidden = hidden
	putArtist(t, a)
	moderate(cur, t, "artist", artistID, hidden, reason)
}

func HidePlaylist(cur realm, playlistID int, hidden bool, reason string) {
	onlyAdmin(cur)
	t := rd()
	p := getPlaylist(t, playlistID)
	if p == nil {
		panic("catalog: unknown playlist")
	}
	p.Hidden = hidden
	putPlaylist(t, p)
	moderate(cur, t, "playlist", playlistID, hidden, reason)
}

// moderate records the moderator's public reason and saves t.
func moderate(cur realm, t *tx, kind string, id int, hidden bool, reason string) {
	mark(t, kind, id, hidden, reason)
	save(cur, t)
}

// mark records the moderator's public reason for one item (the caller saves).
func mark(t *tx, kind string, id int, hidden bool, reason string) {
	reason = strings.TrimSpace(reason)
	k := kind + ":" + text.Itoa(id)
	if hidden {
		mustText("reason", reason, 4, maxReason)
		t.set(cRemoved, k, reason)
	} else {
		t.del(cRemoved, k)
	}
	emitEvent("Moderated", "kind", kind, "target", text.Itoa(id), "hidden", strconv.FormatBool(hidden), "reason", reason, "by", "moderator")
}

// maxHideBatch bounds HideSource: 2 writes per artist.
const maxHideBatch = 50

// HideSource hides every artist read from a platform ("audius" or
// "jamendo"), and so all their tracks, for a platform that ends GnoRadio's
// API access. It walks artist ids from `from`, count (1-50) at a time, and
// returns where to go on (0 once past the last artist). One artist opting out
// is a HideArtist. Admin only.
func HideSource(cur realm, kind string, from, count int, reason string) int {
	onlyAdmin(cur)
	if !isRef(kind) || from < 1 || count < 1 || count > maxHideBatch {
		panic("catalog: HideSource(audius|jamendo, from >= 1, count 1-" + text.Itoa(maxHideBatch) + ", reason)")
	}
	mustText("reason", strings.TrimSpace(reason), 4, maxReason)
	t := rd()
	last := int(t.count(mArtists))
	for id := from; id < from+count && id <= last; id++ {
		if a := getArtist(t, id); a != nil && a.Kind == kind {
			// An artist that hid itself gets the reason too, so HideOwn cannot show it again;
			// one a moderator hid keeps its own reason.
			if r, ok := t.get(cRemoved, "artist:"+text.Itoa(id)); a.Hidden && ok && r != "" {
				continue
			}
			if !a.Hidden {
				a.Hidden = true
				putArtist(t, a)
			}
			mark(t, "artist", id, true, reason)
		}
	}
	save(cur, t)
	if from+count > last {
		return 0
	}
	return from + count
}

// HideOwn hides or shows again the caller's own track, album or artist
// profile ("artist", with the profile's id). The artist can show again only
// what they hid themselves: what the moderator hid stays hidden.
func HideOwn(cur realm, kind string, id int, hidden bool) {
	caller := userCaller(cur)
	noPayment()
	t := rd()
	a := getArtist(t, artistOf(t, caller))
	if a == nil {
		panic("catalog: create your artist profile first")
	}
	k := kind + ":" + text.Itoa(id)
	if reason, ok := t.get(cRemoved, k); ok && reason != "" {
		panic("catalog: hidden by the moderator; contact them to restore it")
	}
	switch kind {
	case "track":
		tr := getTrack(t, id)
		if tr == nil || tr.Artist != a.ID {
			panic("catalog: not your track")
		}
		mustToggle(tr.Hidden, hidden)
		tr.Hidden = hidden
		putTrack(t, tr)
	case "album":
		al := getAlbum(t, id)
		if al == nil || al.Artist != a.ID {
			panic("catalog: not your album")
		}
		mustToggle(al.Hidden, hidden)
		al.Hidden = hidden
		putAlbum(t, al)
	case "artist":
		if id != a.ID {
			panic("catalog: not your profile")
		}
		mustToggle(a.Hidden, hidden)
		a.Hidden = hidden
		putArtist(t, a)
	default:
		panic("catalog: kind must be track, album or artist")
	}
	if hidden {
		t.set(cRemoved, k, "")
	} else {
		t.del(cRemoved, k)
	}
	save(cur, t)
	emitEvent("Moderated", "kind", kind, "target", text.Itoa(id), "hidden", strconv.FormatBool(hidden), "reason", "", "by", "artist")
}

func mustToggle(was, hidden bool) {
	if was == hidden {
		if hidden {
			panic("catalog: already hidden")
		}
		panic("catalog: already shown")
	}
}

// HiddenNote says why a track, album, artist or playlist is hidden, for its
// page: "Removed by moderation: <reason>", "Hidden by the artist.", or "".
func HiddenNote(kind string, id int) string {
	reason, ok := rd().get(cRemoved, kind+":"+text.Itoa(id))
	switch {
	case !ok:
		return ""
	case reason == "":
		return "Hidden by the artist."
	}
	return "Removed by moderation: " + reason
}

// Verify marks an artist whose identity was checked off-chain.
func Verify(cur realm, artistID int, verified bool) {
	onlyAdmin(cur)
	t := rd()
	a := mustArtist(t, artistID)
	a.Verified = verified
	putArtist(t, a)
	t.del(cClaims, store.Pad(artistID)) // settled by the admin either way
	if !verified {
		t.del(cProofs, store.Pad(artistID))
	}
	save(cur, t)
	emitEvent("Verified", "artist", text.Itoa(artistID), "verified", strconv.FormatBool(verified))
}

// AllowHost adds or removes an https host that audio and covers may use.
func AllowHost(cur realm, host string, allowed bool) {
	onlyAdmin(cur)
	host = strings.ToLower(strings.TrimSpace(host))
	if !validHost(host) {
		panic("catalog: invalid host")
	}
	t := rd()
	if allowed {
		t.set(cHosts, host, "1")
	} else {
		t.del(cHosts, host)
	}
	save(cur, t)
	emitEvent("HostAllowed", "host", host, "allowed", strconv.FormatBool(allowed))
}

package catalog

import (
	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
)

// Promo share: an artist lets a part of each tip go to the listeners who
// brought the tipper, the one who picked the track on the radio and the one
// whose link they followed. It is opt-in: 0% until the artist sets it
// (0..20%), and the tipper sees it before signing. A tipper never pays it to
// themselves: not as the picker, not as the referrer, and not to a
// referrer they name for a track they picked (social.gno, tip). The radio realm alone knows who picked what
// is on air, so the shared tips arrive through RadioTip, which only the
// current radio writer of the data realm may call; it never takes a picker
// from the client.

const (
	defaultPromoPct = 0
	maxPromoPct     = 20
)

// SetPromoShare sets the percent of each tip on the caller's tracks that goes
// to the picker and the referrer (0..20).
func SetPromoShare(cur realm, pct int) {
	caller := userCaller(cur)
	noPayment()
	if pct < 0 || pct > maxPromoPct {
		panic("catalog: the promo share is between 0 and 20%")
	}
	t := rd()
	id, _ := ownArtist(t, caller)
	t.set(cPromo, store.Pad(id), text.Itoa(pct))
	save(cur, t)
	emitEvent("PromoShare", "artist", text.Itoa(id), "pct", text.Itoa(pct))
}

// PromoShare returns an artist's promo percent.
func PromoShare(artistID int) int { return promoShare(rd(), artistID) }

func promoShare(t *tx, artistID int) int {
	if v, ok := t.get(cPromo, store.Pad(artistID)); ok {
		return text.Atoi(v)
	}
	return defaultPromoPct
}

// RadioTip pays a tip the radio realm received for the listener tipper
// (radio.TipOnAir): the radio has already forwarded total ugnot to this realm
// and names the picker of the slot on air. Only the radio writer may call it.
// It returns what the picker and the referrer received.
func RadioTip(cur realm, trackID, supportPct int, tipper, picker, ref address, total int64) (toPicker, toRef int64) {
	onlyRadio(cur)
	return tip(cur, tipper, total, trackID, supportPct, picker, ref)
}

// onlyRadio admits the radio realm the data realm names as radio writer
// now, unless the radio role is paused: a paused radio moves no coins
// through the catalog either.
func onlyRadio(cur realm) {
	if cur.Previous().PkgPath() != data.Writer("radio") {
		panic("catalog: only the GnoRadio radio realm can call this")
	}
	if data.Paused("radio") {
		panic("catalog: the radio is paused")
	}
}

// promoShares splits an artist-side amount's promo share between the picker
// and the referrer still eligible ("" when not): half each, the odd ugnot to
// the picker, all of it to one alone.
func promoShares(amt int64, pct int, picker, ref address) (toPicker, toRef int64) {
	share := amt * int64(pct) / 100
	switch {
	case picker != "" && ref != "":
		toRef = share / 2
		return share - toRef, toRef
	case picker != "":
		return share, 0
	case ref != "":
		return 0, share
	}
	return 0, 0
}

package catalog

import (
	"strings"

	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
)

// ---- Read API for the other GnoRadio realms (values only) ----

func GenreName(g int) string {
	if g < 1 || g > NumGenres {
		return ""
	}
	return genres[g]
}

func TrackCount() int    { return int(rd().count(mTracks)) }
func ArtistCount() int   { return int(rd().count(mArtists)) }
func AlbumCount() int    { return int(rd().count(mAlbums)) }
func PlaylistCount() int { return int(rd().count(mPlaylists)) }

// TrackBrief is what the radio needs; playable is false for an unknown or
// hidden track, or one whose artist is hidden.
func TrackBrief(id int) (artistID, genre int, duration int64, playable_ bool) {
	rec := point(cTracks, id)
	if rec == "" {
		return 0, 0, 0, false
	}
	a := text.Atoi(store.Field(rec, fArtist))
	arec := point(cArtists, a)
	return a, text.Atoi(store.Field(rec, fGenre)), text.Atoi64(store.Field(rec, fDuration)),
		store.Field(rec, fHidden) == "" && arec != "" && store.Field(arec, aHidden) == ""
}

// TrackBriefFor is TrackBrief and whether addr ("" for nobody) is the
// track's artist or one of its collaborators, from the same reads.
func TrackBriefFor(id int, addr address) (artistID, genre int, duration int64, playable_, own bool) {
	rec := point(cTracks, id)
	if rec == "" {
		return 0, 0, 0, false, false
	}
	a := text.Atoi(store.Field(rec, fArtist))
	arec := point(cArtists, a)
	playable_ = store.Field(rec, fHidden) == "" && arec != "" && store.Field(arec, aHidden) == ""
	if addr != "" && arec != "" {
		// splits are "addr:pct,…" and an address holds no ',' or ':'
		sp := store.Field(rec, fSplits)
		own = store.Field(arec, aOwner) == addr.String() || sp != "" && strings.Contains(","+sp, ","+addr.String()+":")
	}
	return a, text.Atoi(store.Field(rec, fGenre)), text.Atoi64(store.Field(rec, fDuration)), playable_, own
}

// PlayableTitle is a track's title, "" unless it is playable (TrackBrief). An
// Audius or Jamendo pointer stores no title: it is "Audius track" here, the
// app names it from the platform.
func PlayableTitle(id int) string {
	rec := point(cTracks, id)
	if rec == "" || store.Field(rec, fHidden) != "" {
		return ""
	}
	if arec := point(cArtists, text.Atoi(store.Field(rec, fArtist))); arec == "" || store.Field(arec, aHidden) != "" {
		return ""
	}
	return refLabel(store.Field(rec, fOrigin), store.Field(rec, fTitle), "track")
}

func TrackTitle(id int) string {
	if rec := point(cTracks, id); rec != "" {
		return refLabel(store.Field(rec, fOrigin), store.Field(rec, fTitle), "track")
	}
	return ""
}

func ArtistName(artistID int) string {
	if rec := point(cArtists, artistID); rec != "" {
		return refLabel(store.Field(rec, aKind), store.Field(rec, aName), "artist")
	}
	return ""
}

func ArtistOwner(artistID int) address { return address(artistAt(artistID, aOwner)) }
func ArtistOf(owner address) int       { return artistOf(rd(), owner) }

// ArtistPayee is what a payment to an artist checks, from one read: who
// is paid, whether verified, and whether the profile is visible.
func ArtistPayee(id int) (owner address, verified, visible bool) {
	rec := point(cArtists, id)
	if rec == "" {
		return "", false, false
	}
	return address(store.Field(rec, aOwner)), store.Field(rec, aVerified) == "1", store.Field(rec, aHidden) == ""
}
func ArtistVisible(artistID int) bool {
	rec := point(cArtists, artistID)
	return rec != "" && store.Field(rec, aHidden) == ""
}

// ---- Value getters for the home realm and tools ----

// GetTrack returns a copy of a track; ok is false if unknown. A pointer's
// empty title reads as its platform ("Audius track").
func GetTrack(id int) (Track, bool) {
	if tr := getTrack(rd(), id); tr != nil {
		tr.Title = refLabel(tr.Origin, tr.Title, "track")
		return *tr, true
	}
	return Track{}, false
}

func GetArtist(id int) (Artist, bool) {
	t := rd()
	if a := getArtist(t, id); a != nil {
		a.Name = refLabel(a.Kind, a.Name, "artist")
		return *withLists(t, a), true
	}
	return Artist{}, false
}

// ArtistByRef looks a pointer artist up by its platform id ("audius-user:12").
func ArtistByRef(ref string) int {
	v, _ := data.Get(cNames, strings.TrimSpace(ref))
	return text.Atoi(v)
}

// ArtistByName looks a profile up by its (case-insensitive) name.
func ArtistByName(name string) int {
	v, _ := data.Get(cNames, skeleton(strings.TrimSpace(name)))
	return text.Atoi(v)
}

func GetAlbum(id int) (Album, bool) {
	if a := getAlbum(rd(), id); a != nil {
		return *a, true
	}
	return Album{}, false
}

func GetPlaylist(id int) (Playlist, bool) {
	if p := getPlaylist(rd(), id); p != nil {
		return *p, true
	}
	return Playlist{}, false
}

// ReportCount is the number of open (unresolved) reports.
func ReportCount() int { return int(rd().count(mOpen)) }

func GetReport(id int) (ReportInfo, bool) { return getReport(rd(), id) }

// UserStats returns a listener's public counters and playlists. The like
// count reads the listener's own like ranges, one page.
func UserStats(addr address) (likes, follows int, tipped int64, lists []int) {
	_, likes = rangePage(cLikes, addr.String(), 0, 0)
	u := user(rd(), addr)
	return likes, store.Count(u.Follows), u.Tipped, u.Playlists
}

// LikedPage lists a listener's liked track ids, newest tracks first,
// paginated. Likes are keyed by track id, so this is the newest music the
// listener liked, not the order of their likes (that needs an index per like,
// which would add to every like's storage deposit).
func LikedPage(addr address, offset, limit int) []int {
	ids, _ := rangePage(cLikes, addr.String(), max0(offset), store.Limit(limit, 100))
	return ids
}

// ---- Narrow getters: one field without copying a whole struct ----

// ArtistTrackCount is the number of tracks an artist published.
func ArtistTrackCount(artistID int) int {
	tl, _ := lists(rd(), artistID)
	return store.Count(tl)
}

// ArtistTrackPage lists an artist's track ids in publishing order, paginated.
func ArtistTrackPage(artistID, offset, limit int) []int {
	if offset < 0 {
		return nil
	}
	tl, _ := lists(rd(), artistID)
	return store.Page(tl, offset, store.Limit(limit, 100), false)
}

// ArtistBrief returns what a link to an artist needs, without the bio or the
// id lists; ok is false for an unknown artist.
func ArtistBrief(artistID int) (name string, verified, hidden, ok bool) {
	rec := point(cArtists, artistID)
	if rec == "" {
		return "", false, false, false
	}
	return refLabel(store.Field(rec, aKind), store.Field(rec, aName), "artist"), store.Field(rec, aVerified) != "", store.Field(rec, aHidden) != "", true
}

// PlaylistBrief returns a playlist's header without its track ids.
func PlaylistBrief(id int) (owner address, title string, tracks int, hidden, ok bool) {
	rec := rd().val(cPlaylists, store.Pad(id)) // counts the ids without decoding them
	if id < 1 || rec == "" {
		return "", "", 0, false, false
	}
	f := store.Fields(rec)
	return address(f[0]), f[1], store.Count(f[4]), f[3] != "", true
}

// FollowsPage lists the artist ids a listener follows, paginated.
func FollowsPage(addr address, offset, limit int) []int {
	return store.Page(user(rd(), addr).Follows, max0(offset), store.Limit(limit, 100), false)
}

// GenrePage lists the track ids of a genre (hidden ones included), newest first.
func GenrePage(genre, offset, limit int) []int {
	if genre < 1 || genre > NumGenres {
		return nil
	}
	ids, _ := rangePage(cGenres, store.Pad(genre), max0(offset), store.Limit(limit, 100))
	return ids
}

// GenreCount is the number of tracks filed under a genre.
func GenreCount(genre int) int {
	if genre < 1 || genre > NumGenres {
		return 0
	}
	return int(rd().count(mGenre + genre))
}

// TrackPage lists track ids, newest first when newest is true.
// Ids are dense (1..count), so these pages are arithmetic.
func TrackPage(offset, limit int, newest bool) []int {
	return seqPage(TrackCount(), offset, limit, newest)
}
func ArtistPage(offset, limit int) []int   { return seqPage(ArtistCount(), offset, limit, false) }
func AlbumPage(offset, limit int) []int    { return seqPage(AlbumCount(), offset, limit, true) }
func PlaylistPage(offset, limit int) []int { return seqPage(PlaylistCount(), offset, limit, true) }

// ReportPage lists open report ids, newest first.
func ReportPage(offset, limit int) []int {
	keys, _ := store.Rows(data.PageAt(cReports, max0(offset), store.Limit(limit, 100), true))
	out := make([]int, 0, len(keys))
	for _, k := range keys {
		out = append(out, text.Atoi(k))
	}
	return out
}

func seqPage(n, offset, limit int, newest bool) []int {
	var out []int
	for k := max0(offset); k < n && len(out) < store.Limit(limit, 100); k++ {
		if newest {
			out = append(out, n-k)
		} else {
			out = append(out, k+1)
		}
	}
	return out
}

func max0(n int) int {
	if n < 0 {
		return 0
	}
	return n
}

func TopLiked() []Rank   { return rd().top(topLiked) }
func TopArtists() []Rank { return rd().top(topArtists) }
func TopFans() []Rank    { return rd().top(topFans) }

func Admin() address            { return adminAddr() }
func PendingAdmin() address     { return admin.Pending() } // the address the admin role is offered to, "" if none
func Version() string           { return version }
func RightsTerms() string       { return rightsTerms }
func HostAllowed(h string) bool { return data.Has(cHosts, strings.ToLower(h)) }

package catalog

import (
	"strings"

	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
)

// Records are store.Rec values: fields behind a length header, so reading a
// field never scans the record. Hot fields come first. Id lists use store's
// JSON-ready width and go straight into the JSON exports. The fields are
// catalog v0's, ordered so the frequent writes touch the first ones.

type Split struct {
	To  address
	Pct int64 // percent of each tip
}

type Artist struct {
	ID        int
	Owner     address // "" while unclaimed (curated / Audius / Jamendo)
	Kind      string  // artist | curated | audius | jamendo
	Name      string
	Bio       string
	Source    string // curated: source page; audius / jamendo: platform id (audius-user:<id>, jamendo-artist:<id>)
	Joined    int64
	Tips      int64
	Followers int
	Tracks    []int
	Albums    []int
	Verified  bool
	Hidden    bool
}

type Track struct {
	ID          int
	Artist      int
	Origin      string
	Title       string
	Genre       int
	Duration    int64 // seconds
	License     string
	CMO         string // none | sacem-nc
	Credits     string
	Audio       string // ipfs://… ar://… audius:… jamendo:… https://…
	AudioSHA    string // sha256 hex, required for https
	Cover       string
	CoverSHA    string
	SourceURL   string
	Attribution string
	Splits      []Split
	Album       int
	Created     int64
	Likes       int
	Tips        int64
	Supporters  int
	Hidden      bool
	Early       []address // first listeners to like it
}

type Album struct {
	ID       int
	Artist   int
	Title    string
	Cover    string
	CoverSHA string
	Year     int
	Tracks   []int
	Created  int64
	Hidden   bool
}

type Playlist struct {
	ID      int
	Owner   address
	Title   string
	Tracks  []int
	Updated int64
	Hidden  bool
}

// User is what a listener writes, so a follow only touches that listener's
// own record. Follows are a sorted packed list (9 bytes each); likes and the
// tipped tracks live apart, per range of 512 track ids.
type User struct {
	Follows   string // sorted packed artist ids
	Tipped    int64
	Playlists []int
	Reports   int // open reports filed by this user
}

type ReportInfo struct {
	ID     int
	Kind   string // track | album | artist | playlist
	Target string
	Reason string
	By     address
	At     int64
}

// ---- tracks: what the radio reads first, then what likes and tips change ----

// Track record fields. Reading or replacing field i walks the i fields
// before it, so the fields the frequent actions read and change come first.
const (
	fArtist = iota
	fGenre
	fDuration
	fHidden
	fLikes
	fEarly // first listeners to like it, comma-joined
	fTips
	fSupporters
	fAlbum
	fCreated
	fOrigin
	fTitle
	fLicense
	fCMO
	fCredits
	fAudio
	fAudioSHA
	fCover
	fCoverSHA
	fSource
	fAttribution
	fSplits // "addr:pct,…"
)

func getTrack(t *tx, id int) *Track {
	rec := t.rec(cTracks, id)
	if rec == "" {
		return nil
	}
	f := store.Fields(rec)
	tr := &Track{
		ID: id, Artist: text.Atoi(f[fArtist]), Genre: text.Atoi(f[fGenre]), Duration: text.Atoi64(f[fDuration]), Hidden: f[fHidden] != "",
		Likes: text.Atoi(f[fLikes]), Tips: text.Atoi64(f[fTips]), Supporters: text.Atoi(f[fSupporters]), Album: text.Atoi(f[fAlbum]),
		Created: text.Atoi64(f[fCreated]), Origin: f[fOrigin], Title: f[fTitle], License: f[fLicense], CMO: f[fCMO],
		Credits: f[fCredits], Audio: f[fAudio], AudioSHA: f[fAudioSHA], Cover: f[fCover], CoverSHA: f[fCoverSHA],
		SourceURL: f[fSource], Attribution: f[fAttribution],
	}
	if f[fSplits] != "" {
		for _, p := range strings.Split(f[fSplits], ",") {
			to, pct, _ := strings.Cut(p, ":")
			tr.Splits = append(tr.Splits, Split{To: address(to), Pct: text.Atoi64(pct)})
		}
	}
	if f[fEarly] != "" {
		for _, a := range strings.Split(f[fEarly], ",") {
			tr.Early = append(tr.Early, address(a))
		}
	}
	return tr
}

func trackRecord(tr *Track) string {
	var splits, early []string
	for _, s := range tr.Splits {
		splits = append(splits, s.To.String()+":"+text.Itoa64(s.Pct))
	}
	for _, a := range tr.Early {
		early = append(early, a.String())
	}
	return store.Rec(text.Itoa(tr.Artist), text.Itoa(tr.Genre), text.Itoa64(tr.Duration), text.Flag(tr.Hidden), text.Itoa(tr.Likes),
		strings.Join(early, ","), text.Itoa64(tr.Tips), text.Itoa(tr.Supporters), text.Itoa(tr.Album), text.Itoa64(tr.Created), tr.Origin,
		tr.Title, tr.License, tr.CMO, tr.Credits, tr.Audio, tr.AudioSHA, tr.Cover, tr.CoverSHA, tr.SourceURL,
		tr.Attribution, strings.Join(splits, ","))
}

func putTrack(t *tx, tr *Track) { t.setRec(cTracks, tr.ID, trackRecord(tr)) }

// brief reads only what playback needs, without decoding the whole track.
func brief(t *tx, id int) (artist, genre int, dur int64, hidden, ok bool) {
	rec := t.rec(cTracks, id)
	if rec == "" {
		return 0, 0, 0, false, false
	}
	return text.Atoi(store.Field(rec, fArtist)), text.Atoi(store.Field(rec, fGenre)), text.Atoi64(store.Field(rec, fDuration)), store.Field(rec, fHidden) != "", true
}

// ---- artists: a small head record, the id lists apart ----

// Artist head fields, in the same spirit: what tips and follows read and
// change first. The permanent tickets/nft realm reads aHidden and aName (and
// chunkSize) straight from the data realm: no release may move them.
const (
	aHidden = iota
	aOwner
	aVerified
	aTips
	aFollowers
	aKind
	aName
	aBio
	aSource
	aJoined
)

// getArtist returns an artist's head; Tracks and Albums stay empty (see withLists).
func getArtist(t *tx, id int) *Artist {
	rec := t.rec(cArtists, id)
	if rec == "" {
		return nil
	}
	f := store.Fields(rec)
	return &Artist{
		ID: id, Hidden: f[aHidden] != "", Owner: address(f[aOwner]), Verified: f[aVerified] != "", Tips: text.Atoi64(f[aTips]),
		Followers: text.Atoi(f[aFollowers]), Kind: f[aKind], Name: f[aName], Bio: f[aBio], Source: f[aSource], Joined: text.Atoi64(f[aJoined]),
	}
}

func artistRecord(a *Artist) string {
	return store.Rec(text.Flag(a.Hidden), a.Owner.String(), text.Flag(a.Verified), text.Itoa64(a.Tips), text.Itoa(a.Followers), a.Kind,
		a.Name, a.Bio, a.Source, text.Itoa64(a.Joined))
}

func putArtist(t *tx, a *Artist) { t.setRec(cArtists, a.ID, artistRecord(a)) }

// artistField reads one field of the head ("" for an unknown artist).
func artistField(t *tx, id, i int) string {
	if rec := t.rec(cArtists, id); rec != "" {
		return store.Field(rec, i)
	}
	return ""
}

func artistVisible(t *tx, id int) bool {
	rec := t.rec(cArtists, id)
	return rec != "" && store.Field(rec, aHidden) == ""
}

// lists returns an artist's track and album id lists (made at its first publish).
func lists(t *tx, artistID int) (trackIDs, albumIDs string) {
	rec := t.val(cAlists, store.Pad(artistID))
	if rec == "" {
		return "", ""
	}
	f := store.Fields(rec)
	return f[0], f[1]
}

func setLists(t *tx, artistID int, trackIDs, albumIDs string) {
	t.set(cAlists, store.Pad(artistID), store.Rec(trackIDs, albumIDs))
}

// withLists fills an artist head's Tracks and Albums.
func withLists(t *tx, a *Artist) *Artist {
	tl, al := lists(t, a.ID)
	a.Tracks, a.Albums = store.Ints(tl), store.Ints(al)
	return a
}

func artistOf(t *tx, owner address) int { return text.Atoi(t.val(cOwners, owner.String())) }

// ---- albums and playlists ----

func getAlbum(t *tx, id int) *Album {
	rec := t.rec(cAlbums, id)
	if rec == "" {
		return nil
	}
	f := store.Fields(rec)
	return &Album{ID: id, Artist: text.Atoi(f[0]), Title: f[1], Cover: f[2], CoverSHA: f[3], Year: text.Atoi(f[4]),
		Created: text.Atoi64(f[5]), Hidden: f[6] != "", Tracks: store.Ints(f[7])}
}

func albumRecord(al *Album) string {
	return store.Rec(text.Itoa(al.Artist), al.Title, al.Cover, al.CoverSHA, text.Itoa(al.Year), text.Itoa64(al.Created),
		text.Flag(al.Hidden), store.Pack(al.Tracks))
}

func putAlbum(t *tx, al *Album) { t.setRec(cAlbums, al.ID, albumRecord(al)) }

func getPlaylist(t *tx, id int) *Playlist {
	if id < 1 {
		return nil
	}
	rec := t.val(cPlaylists, store.Pad(id))
	if rec == "" {
		return nil
	}
	f := store.Fields(rec)
	return &Playlist{ID: id, Owner: address(f[0]), Title: f[1], Updated: text.Atoi64(f[2]), Hidden: f[3] != "",
		Tracks: store.Ints(f[4])}
}

func putPlaylist(t *tx, p *Playlist) {
	t.set(cPlaylists, store.Pad(p.ID), store.Rec(p.Owner.String(), p.Title, text.Itoa64(p.Updated), text.Flag(p.Hidden), store.Pack(p.Tracks)))
}

// ---- listeners ----

// user returns a listener's record (an empty one if none); save it with putUser.
func user(t *tx, addr address) *User {
	rec := t.val(cUsers, addr.String())
	if rec == "" {
		return &User{}
	}
	f := store.Fields(rec)
	return &User{Follows: f[0], Tipped: text.Atoi64(f[1]), Playlists: store.Ints(f[2]), Reports: text.Atoi(f[3])}
}

func putUser(t *tx, addr address, u *User) {
	t.set(cUsers, addr.String(), store.Rec(u.Follows, text.Itoa64(u.Tipped), store.Pack(u.Playlists), text.Itoa(u.Reports)))
}

// ---- lookups shared by every file ----

func visibleArtist(a *Artist) bool { return a != nil && !a.Hidden }

func playable(t *tx, tr *Track) bool {
	return tr != nil && !tr.Hidden && artistVisible(t, tr.Artist)
}

func mustArtist(t *tx, id int) *Artist {
	a := getArtist(t, id)
	if !visibleArtist(a) {
		panic("catalog: unknown artist")
	}
	return a
}

func mustTrack(t *tx, id int) *Track {
	tr := getTrack(t, id)
	if !playable(t, tr) {
		panic("catalog: unknown track")
	}
	return tr
}

// ownArtist returns the caller's visible artist profile: its id and head.
func ownArtist(t *tx, caller address) (int, string) {
	id := artistOf(t, caller)
	arec := t.rec(cArtists, id)
	if arec == "" || store.Field(arec, aHidden) != "" {
		panic("catalog: create your artist profile first")
	}
	return id, arec
}

// mayEdit reports whether caller manages artist a: its owner, or the admin
// while the artist is unclaimed.
func mayEdit(caller address, a *Artist) bool {
	if a.Owner != "" {
		return caller == a.Owner
	}
	return caller != "" && caller == adminAddr()
}

package catalog

import (
	"chain"
	"chain/banker"
	"strings"

	"gno.land/p/nym-alexiscolin000/gnoradio/role/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
)

// Like records a public like. The first listeners to like a track earn its
// early-listener badge. (Saving a track privately is done in the app, free.)
func Like(cur realm, trackID int) {
	caller := userCaller(cur)
	noPayment()
	// Likes and the early badges are updated in place: the most frequent write
	// never decodes the whole track.
	t := rd()
	rec, arec := playableRec(t, trackID)
	if rec == "" {
		panic("catalog: unknown track")
	}
	if address(store.Field(arec, aOwner)) == caller {
		panic("catalog: you cannot like your own track")
	}
	if !t.addID(cLikes, caller.String(), trackID) {
		panic("catalog: already liked")
	}
	n := text.Atoi(store.Field(rec, fLikes)) + 1
	rec = store.With(rec, fLikes, text.Itoa(n))
	if early := store.Field(rec, fEarly); !hasEarly(early, caller) && (len(early)+1)/(len(caller)+1) < earlyBadges {
		if early != "" {
			early += ","
		}
		rec = store.With(rec, fEarly, early+caller.String())
	}
	t.setRec(cTracks, trackID, rec)
	id := text.Itoa(trackID)
	t.rank(topLiked, id, int64(n), true)
	t.activityOnce("like", caller, id, store.Field(rec, fArtist))
	save(cur, t)
	emitEvent("Liked", "track", id, "by", caller.String())
}

// hasEarly reports whether a comma-joined address list holds a (addresses
// share one length, so this compares slices instead of scanning bytes).
func hasEarly(list string, a address) bool {
	w := len(a) + 1
	for p := 0; p+len(a) <= len(list); p += w {
		if list[p:p+len(a)] == a.String() {
			return true
		}
	}
	return false
}

// dropEarly takes a out of a comma-joined address list.
func dropEarly(list string, a address) string {
	var kept []string
	for _, x := range strings.Split(list, ",") {
		if x != a.String() {
			kept = append(kept, x)
		}
	}
	return strings.Join(kept, ",")
}

// Unlike takes a like back, and its early-listener badge with it.
func Unlike(cur realm, trackID int) {
	caller := userCaller(cur)
	noPayment()
	t := rd()
	if !t.removeID(cLikes, caller.String(), trackID) {
		panic("catalog: not liked")
	}
	if rec := t.rec(cTracks, trackID); rec != "" {
		if n := text.Atoi(store.Field(rec, fLikes)); n > 0 {
			rec = store.With(rec, fLikes, text.Itoa(n-1))
			t.rank(topLiked, text.Itoa(trackID), int64(n-1), false)
		}
		// The early-listener badge goes with the like: like and unlike
		// cycles keep no badge, and free the slot for a real listener.
		if early := store.Field(rec, fEarly); hasEarly(early, caller) {
			rec = store.With(rec, fEarly, dropEarly(early, caller))
		}
		t.setRec(cTracks, trackID, rec)
	}
	save(cur, t)
	emitEvent("Unliked", "track", text.Itoa(trackID), "by", caller.String())
}

// Tip forwards the attached ugnot to the track's artist and collaborators,
// split as declared at publish time, in this same transaction. Only verified
// artists receive tips (verify.gno). Verification proves control of a web
// host or an Audius account, not who the artist is: the proof host is public
// next to every ✓ (ProofHost), and the 72 h claim window (PendingClaims) is
// there to catch an impersonator before tips open.
func Tip(cur realm, trackID int) {
	tip(cur, userCaller(cur), paid(), trackID, 0, "", "")
}

// TipWithSupport is Tip plus an optional contribution to GnoRadio: of the
// attached total T, the artist side receives T*100/(100+supportPct) (split as
// in Tip) and the rest goes to the GnoRadio treasury. supportPct is 0..50.
func TipWithSupport(cur realm, trackID int, supportPct int) {
	tip(cur, userCaller(cur), paid(), trackID, supportPct, "", "")
}

// tip pays total from this realm's balance for caller. The artist's promo
// share (promo.gno) of the artist side goes to picker and ref, when given and
// neither the tipper nor the artist, and only when the tipper did not pick
// the track themselves; collaborators split what is left.
func tip(cur realm, caller address, total int64, trackID, supportPct int, picker, ref address) (toPicker, toRef int64) {
	if supportPct < 0 || supportPct > maxSupportPct {
		panic("catalog: supportPct must be between 0 and 50")
	}
	// The track and artist records are changed in place, as Like does.
	t := rd()
	if supportPct > 0 && treasury(t) == "" {
		panic("catalog: no treasury is set, a tip carries no support share")
	}
	rec, arec := playableRec(t, trackID)
	if rec == "" {
		panic("catalog: unknown track")
	}
	owner := address(store.Field(arec, aOwner))
	if owner == "" || store.Field(arec, aVerified) == "" {
		panic("catalog: this artist has not verified their profile yet")
	}
	if owner == caller {
		panic("catalog: you cannot tip your own track")
	}
	if total > maxTip+maxTip/2 {
		panic("catalog: a tip is between 0.1 and 1000000 GNOT")
	}
	amt := total * 100 / int64(100+supportPct)
	platform := total - amt
	if amt < minTip || amt > maxTip {
		panic("catalog: a tip is between 0.1 and 1000000 GNOT")
	}
	// A tipper who picked the track themselves brings no listener: no promo
	// share goes out, neither to the pick nor to a link they name.
	selfPicked := picker == caller
	if selfPicked || picker == owner || !role.Canonical(picker) || data.IsGnoRadio(picker) {
		picker = ""
	}
	self := cur.Address()
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	// This realm holds nothing between transactions: the tip is all it has.
	if bk.GetCoins(self).AmountOf(denom) < total {
		panic("catalog: the tip did not arrive")
	}
	if selfPicked || ref == caller || ref == owner || ref == picker || !role.Canonical(ref) || data.IsGnoRadio(ref) {
		ref = ""
	}
	artistID := text.Atoi(store.Field(rec, fArtist))
	toPicker, toRef = promoShares(amt, promoShare(t, artistID), picker, ref)
	artistSide := amt - toPicker - toRef

	rest := artistSide
	var paidTo strings.Builder
	if splits := store.Field(rec, fSplits); splits != "" {
		for _, p := range strings.Split(splits, ",") {
			to, pct, _ := strings.Cut(p, ":")
			share := artistSide * text.Atoi64(pct) / 100
			if share > 0 && !data.IsGnoRadio(address(to)) { // a realm of a later release: the owner keeps it
				bk.SendCoins(self, address(to), chain.Coins{{Denom: denom, Amount: share}})
				rest -= share
				paidTo.WriteString(to + ":" + text.Itoa64(share) + ",")
			}
		}
	}
	bk.SendCoins(self, owner, chain.Coins{{Denom: denom, Amount: rest}})
	paidTo.WriteString(owner.String() + ":" + text.Itoa64(rest))
	if toPicker > 0 {
		bk.SendCoins(self, picker, chain.Coins{{Denom: denom, Amount: toPicker}})
	}
	if toRef > 0 {
		bk.SendCoins(self, ref, chain.Coins{{Denom: denom, Amount: toRef}})
	}
	if platform > 0 {
		bk.SendCoins(self, treasury(t), chain.Coins{{Denom: denom, Amount: platform}})
		recordSupport(t, caller, platform)
	}

	rec = store.With(rec, fTips, text.Itoa64(text.Atoi64(store.Field(rec, fTips))+artistSide))
	if t.addID(cTipped, caller.String(), trackID) {
		rec = store.With(rec, fSupporters, text.Itoa(text.Atoi(store.Field(rec, fSupporters))+1))
	}
	t.setRec(cTracks, trackID, rec)
	artistTips := text.Atoi64(store.Field(arec, aTips)) + artistSide
	t.setRec(cArtists, artistID, store.With(arec, aTips, text.Itoa64(artistTips)))
	// The tipper's rank and feed line count what reached the artist side: a
	// promo share may go back to a second wallet of the tipper's.
	u := user(t, caller)
	u.Tipped += artistSide
	putUser(t, caller, u)
	aid, id := store.Field(rec, fArtist), text.Itoa(trackID)
	t.rank(topArtists, aid, artistTips, true)
	t.rank(topFans, caller.String(), u.Tipped, true)
	t.activity("tip", caller, id, aid, text.Itoa64(artistSide))
	save(cur, t)
	emitEvent("Tipped", "track", id, "by", caller.String(), "amount", text.Itoa64(amt), "paid", paidTo.String(), "support", text.Itoa64(platform),
		"picker", picker.String(), "toPicker", text.Itoa64(toPicker), "ref", ref.String(), "toRef", text.Itoa64(toRef))
	return toPicker, toRef
}

// ---- Albums ----

// CreateAlbum groups tracks of one artist. The artist (or the admin for an
// unclaimed artist) creates it; trackIDs is "12,13,14" in play order.
func CreateAlbum(cur realm, artistID int, title, cover, coverSHA string, year int, trackIDs string) int {
	caller := userCaller(cur)
	noPayment()
	t := rd()
	a := mustArtist(t, artistID)
	if !mayEdit(caller, a) {
		panic("catalog: only the artist can create its albums")
	}
	title, cover, coverSHA = strings.TrimSpace(title), strings.TrimSpace(cover), strings.ToLower(strings.TrimSpace(coverSHA))
	mustText("title", title, 1, maxTitle)
	if cover != "" {
		mustMedia("cover", cover, coverSHA, false)
	}
	if year < 1900 || year > 2100 {
		panic("catalog: year must be between 1900 and 2100")
	}
	ids := parseIDs(trackIDs, maxAlbumTracks)
	artistTracks, albumIDs := lists(t, a.ID)
	if store.Count(albumIDs) >= maxPerArtist {
		panic("catalog: albums per artist limit reached")
	}
	albumID := int(t.bump(mAlbums, 1))
	for _, id := range ids {
		tr := mustTrack(t, id)
		if tr.Artist != a.ID || tr.Album != 0 {
			panic("catalog: track " + text.Itoa(id) + " is not this artist's or already in an album")
		}
		tr.Album = albumID
		putTrack(t, tr)
	}
	al := &Album{ID: albumID, Artist: a.ID, Title: title, Cover: cover, CoverSHA: coverSHA, Year: year, Tracks: ids, Created: now()}
	t.addRec(cAlbums, al.ID, fits(albumRecord(al)))
	setLists(t, a.ID, artistTracks, albumIDs+store.Enc(al.ID))
	t.activity("album", caller, text.Itoa(al.ID), text.Itoa(a.ID), "0")
	save(cur, t)
	emitEvent("AlbumCreated", "id", text.Itoa(al.ID), "artist", text.Itoa(a.ID), "title", title)
	return al.ID
}

// ---- Playlists ----

// PublishPlaylist makes a public playlist in one signature; trackIDs is
// "12,40,7". Private playlists live in the app and cost nothing.
func PublishPlaylist(cur realm, title, trackIDs string) int {
	caller := userCaller(cur)
	noPayment()
	title = strings.TrimSpace(title)
	mustText("title", title, 1, maxTitle)
	t := rd()
	ids := checkedIDs(t, trackIDs)
	u := user(t, caller)
	if len(u.Playlists) >= maxUserLists {
		panic("catalog: playlists per listener limit reached")
	}
	p := &Playlist{ID: int(t.bump(mPlaylists, 1)), Owner: caller, Title: title, Tracks: ids, Updated: now()}
	u.Playlists = append(u.Playlists, p.ID)
	putUser(t, caller, u)
	putPlaylist(t, p)
	t.activity("playlist", caller, text.Itoa(p.ID), "0", "0")
	save(cur, t)
	emitEvent("PlaylistPublished", "id", text.Itoa(p.ID), "owner", caller.String(), "tracks", text.Itoa(len(ids)))
	return p.ID
}

// UpdatePlaylist replaces a playlist's title and tracks. Owner only.
func UpdatePlaylist(cur realm, playlistID int, title, trackIDs string) {
	caller := userCaller(cur)
	noPayment()
	t := rd()
	p := getPlaylist(t, playlistID)
	if p == nil || p.Hidden || p.Owner != caller {
		panic("catalog: not your playlist")
	}
	title = strings.TrimSpace(title)
	mustText("title", title, 1, maxTitle)
	p.Title, p.Tracks, p.Updated = title, checkedIDs(t, trackIDs), now()
	putPlaylist(t, p)
	save(cur, t)
	emitEvent("PlaylistUpdated", "id", text.Itoa(p.ID), "tracks", text.Itoa(len(p.Tracks)))
}

// checkedIDs parses a playlist's track ids. Only the id range and duplicates
// are checked: loading every track would cost a read per id, and hidden or
// removed tracks are skipped when the playlist is read.
func checkedIDs(t *tx, s string) []int {
	ids := parseIDs(s, maxListTracks)
	for _, id := range ids {
		if int64(id) > t.count(mTracks) {
			panic("catalog: unknown track " + text.Itoa(id))
		}
	}
	return ids
}

package catalog

import (
	"chain"
	"chain/banker"
	"strings"

	"gno.land/p/nym-alexiscolin000/gnoradio/role/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
)

// Sponsored picks: a verified artist funds a budget that refunds the cost of
// a listener's pick of their track once it has aired in full: the pick's fee
// at the app's 80M gas limit (0.08 GNOT) and its ~1,200-byte deposit (0.12
// GNOT), plus the collect's fee at 40M (0.04 GNOT), less the ~500 bytes of
// deposit the collect frees (0.05 GNOT): about 0.19 GNOT (radio/v1 gas
// filetests). It is a refund, not paid listening: the payout stays near the
// pick cost so throwaway wallets gain nothing by farming it, and the radio
// adds airtime and reputation rules (radio/sponsor.gno). Residual,
// accepted: a script that sets tight gas limits pays less than the 0.2 GNOT
// refund and keeps about 0.05 to 0.1 GNOT a pick, within the quotas (three
// sponsored picks a wallet a day, one per artist, and the budget's daily
// limit, defaultPerDay unless the artist sets one), so a budget drains no
// faster than its daily limit.
//
// The coins sit in the data realm's vault, account "catalog/<P(artist)>",
// never in this realm. The radio reserves the payout when the pick is queued
// (a vault hold); the hold is paid when the pick has aired, released if the
// slot is dropped, and lapses by itself claimDays after the slot ends. The
// funder withdraws the rest at any time with data.VaultWithdraw, whatever
// this realm does: paused, replaced or retired. This realm only keeps the
// artist's settings and stats (catalog/budgets).
//
// A budget has a funding generation, bumped when another wallet funds it
// (the previous funder is refunded, holds included). A reservation carries
// the generation it was made in, and pays or releases only in that one: the
// vault pools an artist's holds per day, so a reservation of an earlier
// funding is never paid from (nor released into) a later listener's hold,
// even when the budget went back to the same funder.

const (
	defaultPickPay = 200_000 // ugnot per aired sponsored pick, 0.2 GNOT: the pick and its collect (above)
	minPickPay     = 10_000
	maxPickPay     = 500_000 // room for dearer gas, still a refund, never a wage
	maxPickPerDay  = 100     // the artist's own daily limit
	defaultPerDay  = 10      // the daily limit unless the artist sets one (0 = this default): a farming script drains a budget slowly
	walletPicksDay = 3       // sponsored picks per listener per UTC day, one per artist
	claimDays      = 7       // a reservation lapses this long after the slot ends
	daySecs        = 24 * 3600
)

// dataPath is the data realm: its address holds the vault's coins.
const dataPath = "gno.land/r/nym-alexiscolin000/gnoradio/data"

type budget struct {
	Pay    int64 // per aired sponsored pick, 0 = paused
	PerDay int   // sponsored picks a day (stored 0 reads as defaultPerDay)
	Day    int64 // UTC day of Today
	Today  int
	Funded int64
	Paid   int64
	Picks  int
	Gen    int // funding generation (see above)
}

// acct is an artist's vault account.
func acct(artistID int) string { return "catalog/" + store.Pad(artistID) }

func getBudget(t *tx, artistID int) (budget, bool) {
	rec, ok := t.get(cBudgets, store.Pad(artistID))
	if !ok {
		return budget{}, false
	}
	f := store.Fields(rec)
	b := budget{Pay: text.MustAtoi64(f[0]), PerDay: text.MustAtoi(f[1]), Day: text.MustAtoi64(f[2]), Today: text.MustAtoi(f[3]), Funded: text.MustAtoi64(f[4]),
		Paid: text.MustAtoi64(f[5]), Picks: text.MustAtoi(f[6]), Gen: text.MustAtoi(store.Field(rec, 7))}
	if b.PerDay == 0 {
		b.PerDay = defaultPerDay
	}
	return b, true
}

func putBudget(t *tx, artistID int, b budget) {
	t.set(cBudgets, store.Pad(artistID), store.Rec(text.Itoa64(b.Pay), text.Itoa(b.PerDay), text.Itoa64(b.Day), text.Itoa(b.Today),
		text.Itoa64(b.Funded), text.Itoa64(b.Paid), text.Itoa(b.Picks), text.Itoa(b.Gen)))
}

func today() int64 { return now() / daySecs }

// lapseDay is the last UTC day a pick ending at end can be paid.
func lapseDay(end int64) int64 { return (end + claimDays*daySecs) / daySecs }

// FundPromo adds the attached ugnot to the caller's sponsored-pick budget in
// the vault. A new budget pays defaultPickPay per aired pick (SetPromoPay
// changes it). If the profile changed hands since the last funding, the
// previous funder gets their whole balance back first, reservations included,
// and the budget starts a new funding generation. The caller's budget must
// then hold at least one refund, or no pick could ever use it.
func FundPromo(cur realm) {
	caller := userCaller(cur)
	amt := paid()
	if amt < minTip || amt > maxTip {
		panic("catalog: a promo budget takes 0.1 to 1000000 GNOT")
	}
	t := rd()
	id, arec := ownArtist(t, caller)
	if store.Field(arec, aVerified) == "" {
		panic("catalog: verify your profile first")
	}
	b, ok := getBudget(t, id)
	if !ok {
		b.Pay = defaultPickPay
	}
	b.Funded += amt
	ac := acct(id)
	funder, bal, _ := data.VaultInfo(ac)
	own := amt // what the caller will have in the budget
	if funder == caller {
		own += bal
	}
	if b.Pay > 0 && own < b.Pay {
		panic("catalog: fund at least one pick's refund (" + text.Itoa64(b.Pay) + " ugnot)")
	}
	if funder != caller && funder != "" {
		b.Gen++ // every reservation of the previous funding is void
		if bal > 0 {
			data.VaultRefund(cross(cur), ac)
			emitEvent("PromoWithdrawn", "artist", text.Itoa(id), "to", funder.String(), "amount", text.Itoa64(bal))
		}
	}
	putBudget(t, id, b)
	// The coins go to the vault before data counts them (data checks it).
	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(cur.Address(), chain.PackageAddress(dataPath), chain.Coins{{Denom: denom, Amount: amt}})
	data.VaultCredit(cross(cur), ac, caller, amt)
	save(cur, t)
	_, bal, _ = data.VaultInfo(ac)
	emitEvent("PromoFunded", "artist", text.Itoa(id), "by", caller.String(), "amount", text.Itoa64(amt), "balance", text.Itoa64(bal))
}

// SetPromoPay sets what each aired sponsored pick of the caller's tracks
// refunds (10 000..500 000 ugnot, 0 pauses) and the daily limit (1 to 100,
// 0 = the default, 10).
func SetPromoPay(cur realm, ugnotPerPick int64, perDay int) {
	caller := userCaller(cur)
	noPayment()
	if ugnotPerPick != 0 && (ugnotPerPick < minPickPay || ugnotPerPick > maxPickPay) {
		panic("catalog: a sponsored pick refunds 0.01 to 0.5 GNOT (0 pauses)")
	}
	if perDay < 0 || perDay > maxPickPerDay {
		panic("catalog: the daily limit is 1 to 100 picks (0: the default, 10)")
	}
	t := rd()
	id, _ := ownArtist(t, caller)
	b, _ := getBudget(t, id)
	b.Pay, b.PerDay = ugnotPerPick, perDay
	putBudget(t, id, b)
	save(cur, t)
	emitEvent("PromoPay", "artist", text.Itoa(id), "pay", text.Itoa64(ugnotPerPick), "perDay", text.Itoa(perDay))
}

// PromoReserve reserves the refund of a sponsored pick of trackID by picker
// whose slot ends at end. Only the radio realm may call it (radio.QueueSponsored);
// it panics with the reason when the pick cannot be sponsored. It returns
// the amount reserved and the budget's funding generation, which the radio
// passes back to PromoClaim, PromoClaimable and PromoRelease.
func PromoReserve(cur realm, trackID int, picker address, end int64) (int64, int) {
	onlyRadio(cur)
	t := rd()
	tr := mustTrack(t, trackID)
	a := getArtist(t, tr.Artist)
	b, _ := getBudget(t, a.ID)
	funder, _, free := data.VaultInfo(acct(a.ID))
	if a.Hidden || !a.Verified || a.Owner == "" || funder != a.Owner || b.Pay == 0 {
		panic("catalog: this artist does not sponsor picks right now")
	}
	own := picker == a.Owner || !role.Canonical(picker) || data.IsGnoRadio(picker)
	for _, s := range tr.Splits {
		own = own || s.To == picker
	}
	if own {
		panic("catalog: the artist and collaborators cannot take a sponsored pick")
	}
	day := today()
	if b.Day != day {
		b.Day, b.Today = day, 0
	}
	if b.PerDay > 0 && b.Today >= b.PerDay {
		panic("catalog: this artist's sponsored picks for today are taken, pick it normally")
	}
	if free < b.Pay {
		panic("catalog: this artist's promo budget is empty, pick it normally")
	}
	wd := t.val(cWalletDay, picker.String())
	d, list, _ := strings.Cut(wd, "|")
	if text.Atoi64(d) != day {
		list = ""
	}
	if strings.Contains(","+list, ","+text.Itoa(a.ID)+",") {
		panic("catalog: one sponsored pick per artist a day, pick it normally")
	}
	if strings.Count(list, ",") >= walletPicksDay {
		panic("catalog: three sponsored picks a day, pick normally")
	}
	t.set(cWalletDay, picker.String(), text.Itoa64(day)+"|"+list+text.Itoa(a.ID)+",")
	b.Today++
	putBudget(t, a.ID, b)
	data.VaultHold(cross(cur), acct(a.ID), b.Pay, lapseDay(end))
	save(cur, t)
	emitEvent("PromoReserved", "artist", text.Itoa(a.ID), "track", text.Itoa(trackID), "picker", picker.String(), "amount", text.Itoa64(b.Pay))
	return b.Pay, b.Gen
}

// PromoClaim pays picker a reservation of funding generation gen once their
// sponsored pick ending at end has aired; the radio realm checks the slot. A
// lapsed or cancelled reservation (the budget was refunded since) pays nothing.
func PromoClaim(cur realm, trackID int, picker address, end, amount int64, gen int) {
	onlyRadio(cur)
	t := rd()
	artistID, _, _, _, _ := brief(t, trackID)
	e := lapseDay(end)
	if data.VaultDay() > e { // the vault's clock: a pause never makes a refund lapse
		panic("catalog: this sponsored pick was not collected within 7 days")
	}
	b, _ := getBudget(t, artistID)
	if amount <= 0 || b.Gen != gen || data.VaultHeld(acct(artistID), e) < amount {
		panic("catalog: this sponsorship was cancelled")
	}
	b.Paid += amount
	b.Picks++
	putBudget(t, artistID, b)
	data.VaultPay(cross(cur), acct(artistID), picker, amount, e)
	save(cur, t)
	emitEvent("PromoPaid", "artist", text.Itoa(artistID), "track", text.Itoa(trackID), "to", picker.String(), "amount", text.Itoa64(amount))
}

// PromoClaimable reports whether PromoClaim would pay a sponsored pick's
// refund: reserved for end in generation gen, neither lapsed nor cancelled.
func PromoClaimable(trackID int, end, amount int64, gen int) bool {
	t := rd()
	artistID, _, _, _, _ := brief(t, trackID)
	e := lapseDay(end)
	b, _ := getBudget(t, artistID)
	return data.VaultDay() <= e && amount > 0 && b.Gen == gen && data.VaultHeld(acct(artistID), e) >= amount
}

// PromoRelease returns a reservation to its budget: the slot was dropped or
// cut before it aired in full. A reservation of an earlier funding
// generation than gen's budget was refunded with it: nothing to release. A
// pick that never aired, reserved at reserved (unix; 0 when it partly aired),
// also gives back the daily counts it took, the artist's and picker's, if
// that was today. Radio realm only.
func PromoRelease(cur realm, trackID int, picker address, end, amount, reserved int64, gen int) {
	onlyRadio(cur)
	t := rd()
	artistID, _, _, _, _ := brief(t, trackID)
	b, _ := getBudget(t, artistID)
	if amount > 0 && b.Gen == gen {
		// lapsed or cancelled already: less, or nothing
		if amount = data.VaultRelease(cross(cur), acct(artistID), amount, lapseDay(end)); amount > 0 {
			emitEvent("PromoReleased", "artist", text.Itoa(artistID), "track", text.Itoa(trackID), "amount", text.Itoa64(amount))
		}
	}
	day := today()
	if reserved <= 0 || reserved/daySecs != day {
		return
	}
	if b.Day == day && b.Today > 0 {
		b.Today--
		putBudget(t, artistID, b)
	}
	wd := t.val(cWalletDay, picker.String())
	if d, list, _ := strings.Cut(wd, "|"); text.Atoi64(d) == day {
		t.set(cWalletDay, picker.String(), d+"|"+strings.Replace(","+list, ","+text.Itoa(artistID)+",", ",", 1)[1:])
	}
	save(cur, t)
}

// PromoOffer is what a sponsored pick of the artist's tracks refunds right
// now (0: none). Picker-specific limits are checked when picking.
func PromoOffer(artistID int) int64 {
	t := rd()
	return offer(t, getArtist(t, artistID))
}

func offer(t *tx, a *Artist) int64 {
	if a == nil {
		return 0
	}
	if a.Hidden || !a.Verified || a.Owner == "" {
		return 0
	}
	b, ok := getBudget(t, a.ID)
	if !ok || b.Pay == 0 || b.PerDay > 0 && b.Day == today() && b.Today >= b.PerDay {
		return 0
	}
	if funder, _, free := data.VaultInfo(acct(a.ID)); funder != a.Owner || free < b.Pay {
		return 0
	}
	return b.Pay
}

// PromoJSON is an artist's sponsored-pick budget:
// {"artist","funder","balance","reserved","free","pay","perDay","today","funded","paid","picks","offer"}.
// The funder withdraws "free" with data.VaultWithdraw(acct) where acct is
// "catalog/" and the artist id on 8 digits.
func PromoJSON(artistID int) string {
	t := rd()
	b, _ := getBudget(t, artistID)
	funder, bal, free := data.VaultInfo(acct(artistID))
	if b.Day != today() {
		b.Today = 0
	}
	return `{"artist":` + text.Itoa(artistID) + `,"funder":` + text.Str(funder.String()) + `,"balance":` + text.Itoa64(bal) +
		`,"reserved":` + text.Itoa64(bal-free) + `,"free":` + text.Itoa64(free) + `,"pay":` + text.Itoa64(b.Pay) + `,"perDay":` + text.Itoa(b.PerDay) +
		`,"today":` + text.Itoa(b.Today) + `,"funded":` + text.Itoa64(b.Funded) + `,"paid":` + text.Itoa64(b.Paid) + `,"picks":` + text.Itoa(b.Picks) +
		`,"offer":` + text.Itoa64(offer(t, getArtist(t, artistID))) + `}`
}

package catalog

import (
	"chain"
	"chain/banker"
	"strings"
	"time"

	"gno.land/p/nym-alexiscolin000/gnoradio/role/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
)

// GnoRadio's own funding, always on top of what artists receive and always
// visible on-chain: direct support and the optional share added to a tip.
// Every coin is forwarded to the treasury in the same transaction.

// SupportGnoRadio sends the attached ugnot to the GnoRadio treasury.
func SupportGnoRadio(cur realm) {
	caller := userCaller(cur)
	amt := paid()
	if amt < minTip || amt > maxTip {
		panic("catalog: support is between 0.1 and 1000000 GNOT")
	}
	t := rd()
	if treasury(t) == "" {
		panic("catalog: no treasury is set, GnoRadio takes no support")
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), treasury(t), chain.Coins{{Denom: denom, Amount: amt}})
	recordSupport(t, caller, amt)
	save(cur, t)
	emitEvent("Supported", "by", caller.String(), "amount", text.Itoa64(amt))
}

// SetTreasury changes where GnoRadio's support goes; "" (the default) takes none. Admin only.
func SetTreasury(cur realm, to address) {
	onlyAdmin(cur)
	if to != "" && !role.Canonical(to) { // "" switches support off
		panic("catalog: invalid address")
	}
	if data.IsGnoRadio(to) {
		panic("catalog: the treasury cannot be a GnoRadio realm")
	}
	t := rd()
	emitEvent("TreasuryChanged", "from", treasury(t).String(), "to", to.String())
	t.set(cConfig, "treasury", to.String())
	save(cur, t)
}

// SetMonthlyGoal sets the monthly support goal shown in the app (ugnot). Admin only.
func SetMonthlyGoal(cur realm, ugnot int64) {
	onlyAdmin(cur)
	if ugnot < 0 || ugnot > maxTip {
		panic("catalog: goal out of range")
	}
	t := rd()
	t.set(cConfig, "goal", text.Itoa64(ugnot))
	save(cur, t)
	emitEvent("MonthlyGoal", "ugnot", text.Itoa64(ugnot))
}

func treasury(t *tx) address { return address(t.val(cConfig, "treasury")) }

func Treasury() address { return treasury(rd()) }

// SupportInfo returns GnoRadio's public funding state for this month.
func SupportInfo() (to address, total int64, supporters int, monthTotal, goal int64) {
	t := rd()
	return treasury(t), t.count(mSupport), int(t.count(mSupporters)), text.Atoi64(t.val(cMonthly, month(now()))), text.Atoi64(t.val(cConfig, "goal"))
}

func recordSupport(t *tx, by address, amt int64) {
	t.bump(mSupport, amt)
	s, had := t.get(cSupporters, by.String())
	if !had {
		t.bump(mSupporters, 1)
	}
	total := text.Atoi64(s) + amt
	t.set(cSupporters, by.String(), text.Itoa64(total))
	t.rank(topSupport, by.String(), total, true)
	mo := month(now())
	t.set(cMonthly, mo, text.Itoa64(text.Atoi64(t.val(cMonthly, mo))+amt))
	t.activity("support", by, "0", "0", text.Itoa64(amt))
}

func month(unix int64) string { return time.Unix(unix, 0).UTC().Format("2006-01") }

// Activities returns up to limit entries, newest first.
func Activities(limit int) []Activity {
	limit = store.Limit(limit, activitySize)
	t := rd()
	head := text.Atoi(t.val(cMeta, "head"))
	out := make([]Activity, 0, limit)
	for i := 1; i <= limit; i++ {
		v := t.val(cActivity, store.Pad((head-i+activitySize)%activitySize))
		if v == "" {
			break // the ring is not full yet
		}
		f := store.Fields(v)
		out = append(out, Activity{Kind: f[0], By: address(f[1]), Track: text.Atoi(f[2]), Artist: text.Atoi(f[3]), Amount: text.Atoi64(f[4]), At: text.Atoi64(f[5])})
	}
	return out
}

// ActivityJSON returns the activity feed, newest first (limit <= 64).
func ActivityJSON(limit int) string {
	var b strings.Builder
	b.WriteString("[")
	for i, a := range Activities(limit) {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(`{"kind":` + text.Str(a.Kind) + `,"by":` + text.Str(a.By.String()) + `,"track":` + text.Itoa(a.Track) +
			`,"artist":` + text.Itoa(a.Artist) + `,"amount":` + text.Itoa64(a.Amount) + `,"at":` + text.Itoa64(a.At) + `}`)
	}
	b.WriteString("]")
	return b.String()
}

// SupportJSON returns GnoRadio's public funding state.
func SupportJSON() string {
	to, total, supporters, mt, goal := SupportInfo()
	var b strings.Builder
	b.WriteString(`{"treasury":` + text.Str(to.String()) + `,"total":` + text.Itoa64(total) + `,"supporters":` + text.Itoa(supporters) +
		`,"month":` + text.Str(month(now())) + `,"monthTotal":` + text.Itoa64(mt) + `,"goal":` + text.Itoa64(goal) + `,"top":[`)
	for i, r := range rd().top(topSupport) {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(`{"address":` + text.Str(r.Key) + `,"amount":` + text.Itoa64(r.Value) + `}`)
	}
	b.WriteString(`]}`)
	return b.String()
}

package catalog

import (
	"strconv"
	"strings"

	"gno.land/p/nym-alexiscolin000/gnoradio/role/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
)

// Tracks are added and edited through the radio realm only (radio.PublishTrack,
// radio.ImportTrack, radio.EditTrack): it puts a new track in the station
// rotations, and moves an edited one, in the same transaction. The radio
// names the wallet that signed (caller, by); only the radio writer the data
// realm names may call these.

// PublishFor adds a track by caller's own artist profile.
// duration is "m:ss"; cmo is "none" or "sacem-nc"; splits is optional,
// "g1...:30,g1...:15" in percent (the artist keeps at least 10%);
// rights must be "yes" (the caller accepts RightsTerms).
// audio and cover are ipfs://, ar:// or https:// links (an allowed host,
// with the file's sha256).
func PublishFor(cur realm, caller address, title string, genre int, duration, license, cmo, credits, audio, audioSHA, cover, coverSHA, splits, rights string) int {
	onlyRadio(cur)
	noPayment()
	t := rd()
	aid, _ := ownArtist(t, caller)
	if strings.ToLower(strings.TrimSpace(rights)) != "yes" {
		panic("catalog: accept the rights declaration (answer yes)")
	}
	tr := &Track{Origin: OriginArtist, CMO: "none"}
	setInfo(tr, title, genre, duration, credits, true)
	mustRefAudio(tr, audio)
	setLicense(tr, license, cmo)
	setMedia(tr, audio, audioSHA, cover, coverSHA)
	tr.Splits = parseSplits(splits, caller)
	id := addTrack(t, caller, aid, tr)
	save(cur, t)
	return id
}

// ImportFor adds a curated (CC0 / CC BY / CC BY-SA / CC BY-NC / CC BY-NC-SA)
// track, or a pointer to an Audius or Jamendo track, to an unclaimed artist.
// by must be the admin. A pointer keeps only what the radio needs (audio
// "audius:<id>" or "jamendo:<id>", genre, duration, licence): title, credits,
// cover, source and attribution stay empty and the app reads them live from
// the platform, whose API terms allow session caching only.
func ImportFor(cur realm, by address, artistID int, title string, genre int, duration, license, credits, audio, audioSHA, cover, coverSHA, sourceURL, attribution string) int {
	onlyRadio(cur)
	noPayment()
	if by == "" || by != adminAddr() {
		panic("catalog: admin only")
	}
	t := rd()
	a := mustArtist(t, artistID)
	if a.Kind == OriginArtist {
		panic("catalog: artists publish their own tracks")
	}
	tr := &Track{Origin: a.Kind, CMO: "none"}
	setInfo(tr, title, genre, duration, credits, false)
	mustRefAudio(tr, audio)
	if tr.Origin == OriginAudius {
		tr.License = AudiusLicense
	} else if tr.License = curatedLicense(license); tr.License == "" {
		panic("catalog: curated imports must be CC0, CC BY, BY-SA, BY-NC or BY-NC-SA")
	}
	setMedia(tr, audio, audioSHA, cover, coverSHA)
	sourceURL, attribution = strings.TrimSpace(sourceURL), strings.TrimSpace(attribution)
	if isRef(tr.Origin) {
		if cover != "" || sourceURL != "" || attribution != "" {
			panic("catalog: a pointer stores no cover, source or attribution")
		}
	} else {
		if !text.HTTPS(sourceURL, 300) {
			panic("catalog: sourceURL must be the track's https page at the source")
		}
		mustText("attribution", attribution, 2, maxCredits)
	}
	tr.SourceURL, tr.Attribution = sourceURL, attribution
	if isRef(tr.Origin) { // one record per platform track (the key has a '-', no name skeleton does)
		if _, dup := t.get(cNames, refKey+tr.Audio); dup {
			panic("catalog: this pointer track is already imported (hide it and ReleaseName \"" + refKey + tr.Audio + "\" to import it again)")
		}
	}
	id := addTrack(t, adminAddr(), a.ID, tr)
	if isRef(tr.Origin) { // pointers imported before this key existed have none: fine on a fresh chain
		t.set(cNames, refKey+tr.Audio, text.Itoa(id))
	}
	save(cur, t)
	return id
}

// EditFor fixes a track's details. Its artist only (the admin while the
// artist is unclaimed): caller is who signed.
func EditFor(cur realm, caller address, trackID int, title string, genre int, duration, credits, audio, audioSHA, cover, coverSHA string) {
	onlyRadio(cur)
	noPayment()
	t := rd()
	tr := mustTrack(t, trackID)
	a := getArtist(t, tr.Artist)
	if !mayEdit(caller, a) {
		panic("catalog: only the artist can edit this track")
	}
	mustRefAudio(tr, audio)
	// A pointer keeps its platform id and stores no cover: only its genre,
	// duration and (claimed owner) title change.
	if isRef(tr.Origin) && (strings.TrimSpace(audio) != tr.Audio || strings.TrimSpace(cover) != "" || strings.TrimSpace(coverSHA) != "") {
		panic("catalog: a pointer keeps its audio and stores no cover")
	}
	oldGenre := tr.Genre
	// The owner of a claimed Audius or Jamendo profile may name their own
	// tracks: the record then stores the title with the artist's consent.
	setInfo(tr, title, genre, duration, credits, a.Owner != "")
	if tr.Genre != oldGenre {
		t.removeID(cGenres, store.Pad(oldGenre), tr.ID)
		t.addID(cGenres, store.Pad(tr.Genre), tr.ID)
		t.bump(mGenre+oldGenre, -1)
		t.bump(mGenre+tr.Genre, 1)
	}
	setMedia(tr, audio, audioSHA, cover, coverSHA)
	t.setRec(cTracks, tr.ID, fits(trackRecord(tr)))
	save(cur, t)
	emitEvent("TrackEdited", "id", text.Itoa(tr.ID), "audio", tr.Audio, "duration", text.Itoa64(tr.Duration), "genre", text.Itoa(tr.Genre))
}

func addTrack(t *tx, publisher address, artistID int, tr *Track) int {
	trackIDs, albumIDs := lists(t, artistID)
	if store.Count(trackIDs) >= maxPerArtist {
		panic("catalog: tracks per artist limit reached")
	}
	t.bump(mGenre+tr.Genre, 1)
	tr.ID, tr.Artist, tr.Created = int(t.bump(mTracks, 1)), artistID, now()
	t.addRec(cTracks, tr.ID, fits(trackRecord(tr)))
	setLists(t, artistID, trackIDs+store.Enc(tr.ID), albumIDs)
	t.addID(cGenres, store.Pad(tr.Genre), tr.ID)
	t.activity("publish", publisher, text.Itoa(tr.ID), text.Itoa(artistID), "0")
	emitEvent("TrackPublished", "id", text.Itoa(tr.ID), "artist", text.Itoa(artistID), "origin", tr.Origin, "genre", text.Itoa(tr.Genre),
		"duration", text.Itoa64(tr.Duration), "title", tr.Title, "audio", tr.Audio, "license", tr.License)
	return tr.ID
}

// setInfo sets a track's text and timing. An Audius or Jamendo pointer stores
// no title or credits unless named: its claimed artist's owner fills them in.
// Without that, an edit may keep or clear the stored text (a legacy import), never set new text.
func setInfo(tr *Track, title string, genre int, duration, credits string, named bool) {
	title, credits = strings.TrimSpace(title), strings.TrimSpace(credits)
	switch {
	case isRef(tr.Origin) && (title == "" || title == tr.Title) && (credits == "" || credits == tr.Credits): // cleared or unchanged
	case isRef(tr.Origin) && !named:
		panic("catalog: a pointer stores no title or credits (the app reads them from the platform)")
	default:
		mustText("title", title, 1, maxTitle)
		mustText("credits", credits, 0, maxCredits)
	}
	if genre < 1 || genre > NumGenres {
		panic("catalog: genre must be 1.." + text.Itoa(NumGenres))
	}
	d, ok := parseClock(duration)
	if !ok || d < minDuration || d > maxDuration {
		panic("catalog: duration as m:ss, between 0:10 and 20:00")
	}
	tr.Title, tr.Genre, tr.Duration, tr.Credits = title, genre, d, credits
}

// refKey prefixes a pointer's audio in cNames (the '-' keeps it off every name skeleton).
const refKey = "track-"

// isRef reports whether tracks of this origin are pointers: read live from
// Audius or Jamendo, with no title or credits stored on chain.
func isRef(origin string) bool { return origin == OriginAudius || origin == OriginJamendo }

// mustRefAudio keeps a pointer's audio on its platform ("audius:<id>",
// "jamendo:<id>") and every other track off both.
func mustRefAudio(tr *Track, audio string) {
	prefix := strings.TrimSpace(audio)
	if i := strings.IndexByte(prefix, ':'); i >= 0 {
		prefix = prefix[:i]
	}
	if isRef(prefix) != isRef(tr.Origin) || isRef(tr.Origin) && prefix != tr.Origin {
		panic("catalog: Audius and Jamendo tracks use audio audius:<id> or jamendo:<id>, other tracks neither")
	}
}

// refLabel is what gnoweb shows for a pointer's empty title or name: the
// platform it is read from ("Audius track", "Jamendo artist").
func refLabel(origin, stored, what string) string {
	if stored != "" || !isRef(origin) {
		return stored
	}
	return strings.ToUpper(origin[:1]) + origin[1:] + " " + what
}

func setLicense(tr *Track, license, cmo string) {
	lic := normLicense(license)
	if lic == "" {
		panic("catalog: unknown license, use one of " + strings.Join(licenses, ", "))
	}
	cmo = strings.ToLower(strings.TrimSpace(cmo))
	switch cmo {
	case "", "none":
		cmo = "none"
	case "sacem-nc":
		if !strings.Contains(lic, "-NC") {
			panic("catalog: SACEM members may only publish works declared under a CC NC license")
		}
	default:
		panic("catalog: collective society must be none or sacem-nc")
	}
	tr.License, tr.CMO = lic, cmo
}

func setMedia(tr *Track, audio, audioSHA, cover, coverSHA string) {
	audio, audioSHA = strings.TrimSpace(audio), strings.ToLower(strings.TrimSpace(audioSHA))
	cover, coverSHA = strings.TrimSpace(cover), strings.ToLower(strings.TrimSpace(coverSHA))
	mustMedia("audio", audio, audioSHA, true)
	if coverSHA != "" && (cover == "" || !isSHA256(coverSHA)) { // coverSHA goes into the JSON as is
		panic("catalog: cover sha256 must be 64 hex characters, with a cover")
	}
	if cover != "" {
		mustMedia("cover", cover, coverSHA, false)
	}
	tr.Audio, tr.AudioSHA, tr.Cover, tr.CoverSHA = audio, audioSHA, cover, coverSHA
}

// parseSplits reads the collaborators: never the artist, never a GnoRadio realm.
func parseSplits(s string, artist address) []Split {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil
	}
	parts := strings.Split(s, ",")
	if len(parts) > maxSplits {
		panic("catalog: at most 4 collaborators")
	}
	var out []Split
	var sum int64
	seen := map[string]bool{}
	for _, p := range parts {
		addrStr, pctStr, ok := strings.Cut(strings.TrimSpace(p), ":")
		to := address(strings.TrimSpace(addrStr))
		pct, err := strconv.ParseInt(strings.TrimSuffix(strings.TrimSpace(pctStr), "%"), 10, 64)
		if !ok || err != nil || !role.Canonical(to) || to == artist || data.IsGnoRadio(to) || seen[to.String()] || pct < 1 || pct > maxSplitPct {
			panic("catalog: collaborators as g1...:30,g1...:15 (percent)")
		}
		seen[to.String()] = true
		sum += pct
		out = append(out, Split{To: to, Pct: pct})
	}
	if sum > maxSplitPct {
		panic("catalog: collaborators may receive at most 90%")
	}
	return out
}

package catalog

import (
	"strconv"
	"strings"
	"unicode"

	"gno.land/p/nym-alexiscolin000/gnoradio/safe/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
)

func mustText(field, s string, min, max int) {
	if !text.Valid(s, min, max) {
		panic("catalog: " + field + " must be " + text.Itoa(min) + "-" + text.Itoa(max) +
			" characters: letters, digits, spaces and . , ' - ! ? : / & only")
	}
	// A report reason may quote what it reports (/moderation masks it).
	if field != "reason" && safe.Slur(s) {
		panic("catalog: " + field + " holds a slur")
	}
}

// validName restricts artist names to ASCII letters and digits plus the
// Latin-1 accented letters, so look-alike names cannot impersonate an artist.
func validName(s string) bool {
	if strings.TrimSpace(s) != s || strings.Contains(s, "  ") {
		return false
	}
	n, alnum := 0, 0
	for _, r := range s {
		n++
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') ||
			(r >= 0xC0 && r <= 0xFF && r != 0xD7 && r != 0xF7) {
			alnum++
			continue
		}
		switch r {
		case ' ', '.', '\'', '-', '&':
			continue
		}
		return false
	}
	// At least one letter or digit, so the reserved skeleton is never empty.
	return n >= 2 && n <= 40 && alnum > 0
}

// latin1 folds the Latin-1 letters 0xC0-0xFF (lowercased) to ASCII.
var latin1 = [64]string{
	"a", "a", "a", "a", "a", "a", "ae", "c", "e", "e", "e", "e", "i", "i", "i", "i",
	"d", "n", "o", "o", "o", "o", "o", "", "o", "u", "u", "u", "u", "y", "th", "ss",
	"a", "a", "a", "a", "a", "a", "ae", "c", "e", "e", "e", "e", "i", "i", "i", "i",
	"d", "n", "o", "o", "o", "o", "o", "", "o", "u", "u", "u", "u", "y", "th", "y",
}

// skeleton is the key an artist name is reserved under: lowercase, common
// Latin accents stripped, fullwidth letters and digits mapped to ASCII,
// spaces and punctuation dropped and look-alikes folded (i/l/1 → l, 0 → o,
// 3 → e, 4 → a, 5 → s, 7 → t, 9 → g, u → v, rn → m, vv → w, cl → d), so
// "Beyonce", "BEYONCÉ", "Ｂｅｙｏｎｃｅ", "Daft  Punk", "DAFT PUNK", "Kanye
// Vvest", "Kanye Uuest", "Clrake" and "9orillaz" collide with the real names.
func skeleton(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case ' ', '.', '\'', '-', '&', 0x3000:
			continue
		}
		switch {
		case r >= 0xFF21 && r <= 0xFF3A:
			r = r - 0xFF21 + 'a'
		case r >= 0xFF41 && r <= 0xFF5A:
			r = r - 0xFF41 + 'a'
		case r >= 0xFF10 && r <= 0xFF19:
			r = r - 0xFF10 + '0'
		}
		r = unicode.ToLower(r)
		if r >= 0xC0 && r <= 0xFF && latin1[r-0xC0] != "" {
			b.WriteString(confusable(latin1[r-0xC0]))
			continue
		}
		b.WriteString(confusable(string(r)))
	}
	k := strings.ReplaceAll(b.String(), "rn", "m")
	k = strings.ReplaceAll(k, "vv", "w")
	return strings.ReplaceAll(k, "cl", "d")
}

// confusable folds characters that look alike in common fonts.
func confusable(s string) string {
	switch s {
	case "i", "1", "|":
		return "l"
	case "0":
		return "o"
	case "3":
		return "e"
	case "4":
		return "a"
	case "5":
		return "s"
	case "7":
		return "t"
	case "9":
		return "g"
	case "u":
		return "v" // before the vv → w fold: "uu" and "vu" pass for w too
	}
	return s
}

// Reserved names, as skeletons: a name holding a stem anywhere, or one of
// the words as a word, could pass for GnoRadio, its staff, the chain
// (gno.land folds to gnoland), the wallet (Adena) or the audio source
// (Audius). Adena and Audius are prefixes, not stems: refused at the start
// of the name or of any word in it ("AdenaWallet", "Ade-na", "Audius2"),
// while names that only end with them pass ("Pasadena", "La Cadena",
// "Claudius").
var (
	reservedStems = []string{skeleton("gnoradio"), skeleton("moderator"), skeleton("moderation"),
		skeleton("treasury"), skeleton("administrator"), skeleton("gnoland")}
	reservedWords    = []string{skeleton("admin"), skeleton("staff"), skeleton("official")}
	reservedPrefixes = []string{skeleton("adena"), skeleton("audius")}
)

func reserved(name string) bool {
	k := skeleton(name)
	for _, s := range reservedStems {
		if strings.Contains(k, s) {
			return true
		}
	}
	for _, s := range reservedWords {
		if strings.Contains(k, s) && anyWord(name, func(w string) bool { return w == s }) {
			return true
		}
	}
	for _, s := range reservedPrefixes {
		if strings.HasPrefix(k, s) || strings.Contains(k, s) && anyWord(name, func(w string) bool { return strings.HasPrefix(w, s) }) {
			return true
		}
	}
	return false
}

// anyWord reports whether the skeleton of a word of name passes ok.
func anyWord(name string, ok func(string) bool) bool {
	for _, w := range strings.FieldsFunc(name, func(r rune) bool { return strings.ContainsRune(" .'-&", r) }) {
		if ok(skeleton(w)) {
			return true
		}
	}
	return false
}

func mustName(s string) {
	if !validName(s) {
		panic("catalog: artist name must be 2-40 characters: Latin letters (a-z and Latin-1 accents), digits, spaces and . ' - &")
	}
	if safe.Slur(s) {
		panic("catalog: artist name holds a slur")
	}
	if reserved(s) {
		panic("catalog: this artist name is reserved for GnoRadio, gno.land, Adena or Audius")
	}
}

func alnum(s string, min, max int) bool {
	if len(s) < min || len(s) > max {
		return false
	}
	for _, c := range s {
		if (c < 'a' || c > 'z') && (c < 'A' || c > 'Z') && (c < '0' || c > '9') {
			return false
		}
	}
	return true
}

func validHost(h string) bool {
	if len(h) < 3 || len(h) > 100 || !strings.Contains(h, ".") {
		return false
	}
	for _, c := range h {
		if (c < 'a' || c > 'z') && (c < '0' || c > '9') && c != '.' && c != '-' {
			return false
		}
	}
	return true
}

// hostOf is the authority of an https link: up to the first / ? or #
// (lower case). It is a plain host only when validHost says so.
func hostOf(url string) string {
	rest := strings.TrimPrefix(url, "https://")
	if i := strings.IndexAny(rest, "/?#"); i >= 0 {
		rest = rest[:i]
	}
	return strings.ToLower(rest)
}

func isSHA256(s string) bool {
	if len(s) != 64 {
		return false
	}
	for _, c := range s {
		if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
			return false
		}
	}
	return true
}

// mustMedia checks an audio or cover reference:
//
//	ipfs://<cid>        content-addressed, sha256 optional
//	ar://<txid>         Arweave, sha256 optional
//	audius:<trackId>    audio only, streamed through the Audius API
//	jamendo:<trackId>   audio only, streamed from Jamendo
//	https://<host>/…    host must be allowed, sha256 required
func mustMedia(field, uri, sha string, audioField bool) {
	if sha != "" && !isSHA256(sha) {
		panic("catalog: " + field + " sha256 must be 64 hex characters")
	}
	switch {
	case strings.HasPrefix(uri, "ipfs://"):
		if !alnum(strings.TrimPrefix(uri, "ipfs://"), 46, 100) {
			panic("catalog: " + field + " ipfs:// needs a valid CID")
		}
	case strings.HasPrefix(uri, "ar://"):
		id := strings.TrimPrefix(uri, "ar://")
		if len(id) != 43 || !text.URLChars(id) {
			panic("catalog: " + field + " ar:// needs a 43-character transaction id")
		}
	case strings.HasPrefix(uri, "audius:"), strings.HasPrefix(uri, "jamendo:"):
		_, id, _ := strings.Cut(uri, ":")
		if !audioField || !alnum(id, 1, 32) {
			panic("catalog: " + field + " audius:<id> or jamendo:<id> is only valid for audio")
		}
	case strings.HasPrefix(uri, "https://"):
		if !text.HTTPS(uri, 300) || !data.Has(cHosts, hostOf(uri)) {
			panic("catalog: " + field + " host is not allowed (ask the admin to add it)")
		}
		if sha == "" {
			panic("catalog: " + field + " over https needs the file's sha256")
		}
	default:
		panic("catalog: " + field + " must be ipfs://, ar://, audius:, jamendo: or an allowed https:// link")
	}
}

// normLicense maps loose input ("cc by", "cc-by-4.0", "CC0") to an SPDX id.
func normLicense(s string) string {
	s = strings.ToUpper(strings.TrimSpace(s))
	s = strings.ReplaceAll(s, " ", "-")
	s = strings.ReplaceAll(s, "_", "-")
	if s == "CC0" {
		s = "CC0-1.0"
	}
	if strings.HasPrefix(s, "CC-") && !strings.HasSuffix(s, "-4.0") {
		s += "-4.0"
	}
	for _, l := range licenses {
		if s == l {
			return l
		}
	}
	return ""
}

// parseClock parses "m:ss" (or plain seconds) into seconds.
func parseClock(s string) (int64, bool) {
	s = strings.TrimSpace(s)
	m, sec, hasColon := strings.Cut(s, ":")
	if !hasColon {
		if !text.Digits(s) || len(s) > 5 {
			return 0, false
		}
		v, _ := strconv.ParseInt(s, 10, 64)
		return v, true
	}
	if len(m) > 3 || len(sec) != 2 || !text.Digits(m) || !text.Digits(sec) {
		return 0, false
	}
	mv, _ := strconv.ParseInt(m, 10, 64)
	sv, _ := strconv.ParseInt(sec, 10, 64)
	if sv > 59 {
		return 0, false
	}
	return mv*60 + sv, true
}

// parseIDs parses "12,40,7" into distinct ids, at most max of them.
func parseIDs(s string, max int) []int {
	s = strings.TrimSpace(s)
	if s == "" {
		panic("catalog: list at least one track id")
	}
	parts := strings.Split(s, ",")
	if len(parts) > max {
		panic("catalog: at most " + text.Itoa(max) + " tracks")
	}
	out := make([]int, 0, len(parts))
	seen := map[int]bool{}
	for _, p := range parts {
		p = strings.TrimSpace(p)
		n, err := strconv.Atoi(p)
		if err != nil || n < 1 || !text.Digits(p) {
			panic("catalog: track ids as 12,40,7")
		}
		if seen[n] {
			panic("catalog: duplicate track " + text.Itoa(n))
		}
		seen[n] = true
		out = append(out, n)
	}
	return out
}

// curatedLicense accepts the redistributable licenses curated imports may
// carry, in any version and national port: CC0-1.0, CC-BY-<v>[-XX],
// CC-BY-SA-<v>[-XX], CC-BY-NC-<v>[-XX], CC-BY-NC-SA-<v>[-XX] (v = 1.0, 2.0, 2.5, 3.0, 4.0). It returns the normalized
// id, or "" when the license is not allowed.
func curatedLicense(s string) string {
	s = strings.ToUpper(strings.ReplaceAll(strings.TrimSpace(s), " ", "-"))
	if s == "CC0" || s == "CC0-1.0" {
		return "CC0-1.0"
	}
	var rest string
	switch {
	case strings.HasPrefix(s, "CC-BY-NC-SA-"):
		rest = strings.TrimPrefix(s, "CC-BY-NC-SA-")
	case strings.HasPrefix(s, "CC-BY-NC-"):
		rest = strings.TrimPrefix(s, "CC-BY-NC-")
	case strings.HasPrefix(s, "CC-BY-SA-"):
		rest = strings.TrimPrefix(s, "CC-BY-SA-")
	case strings.HasPrefix(s, "CC-BY-"):
		rest = strings.TrimPrefix(s, "CC-BY-")
	default:
		return ""
	}
	ver, port, _ := strings.Cut(rest, "-")
	switch ver {
	case "1.0", "2.0", "2.5", "3.0", "4.0":
	default:
		return ""
	}
	if port != "" && (len(port) != 2 || !alnum(port, 2, 2)) {
		return ""
	}
	return s
}

package catalog

import (
	"chain/runtime"
	"crypto/ed25519"
	"encoding/hex"
	"strconv"

	"gno.land/p/nym-alexiscolin000/gnoradio/role/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
)

// Automatic verification, paid by the artist. The artist puts a proof line in
// a place only they control (their Audius bio, or /.well-known/gnoradio.txt on
// their own website); the GnoRadio robot reads it and, off-chain and for free,
// signs a certificate (Ed25519, ClaimMessage) valid for a short while. The
// artist submits it with Claim from their own wallet; after claimDelay anyone
// can finalize: the profile goes to that wallet and turns Verified, which
// opens tips and paid tickets. The robot key signs nothing else; the admin can
// revoke it, cancel a pending claim and undo a wrong one. Changing or revoking
// the key voids every claim it started that is still pending, so a stolen key
// is undone in one call; there is no daily cap that one person could use up
// for everyone.

const (
	claimDelay = 72 * 3600 // seconds a claim stays public before it counts
	certLife   = 2 * 3600  // longest validity of a robot certificate, seconds
)

type claim struct {
	To    address
	Proof string
	At    int64
	Gen   int // the robot key's generation when the claim was made
}

// ClaimMessage is what the robot signs: the chain, the GnoRadio deployment
// (its data realm, so a staging deployment on the same chain cannot reuse a
// certificate), the profile, the wallet, where the proof was found and until
// when the certificate holds.
func ClaimMessage(artistID int, to address, proof string, expires int64) string {
	return "gnoradio-claim|" + runtime.ChainID() + "|" + dataPath + "|" + text.Itoa(artistID) + "|" + to.String() + "|" + proof + "|" + text.Itoa64(expires)
}

// botKey is the robot's Ed25519 public key (empty: verification paused) and
// gen its generation, bumped by SetBot.
func botKey(t *tx) (key []byte, gen int) {
	key, _ = hex.DecodeString(t.val(cConfig, "bot"))
	return key, text.Atoi(t.val(cConfig, "gen"))
}

func getClaim(t *tx, artistID int) *claim {
	rec, ok := t.get(cClaims, store.Pad(artistID))
	if !ok {
		return nil
	}
	f := store.Fields(rec)
	return &claim{To: address(f[0]), Proof: f[1], At: text.Atoi64(f[2]), Gen: text.Atoi(f[3])}
}

// liveClaim is the pending claim made with the current robot key, if any.
func liveClaim(t *tx, artistID int) *claim {
	c := getClaim(t, artistID)
	if _, gen := botKey(t); c == nil || c.Gen != gen {
		return nil
	}
	return c
}

// SetBot sets the robot's Ed25519 public key, hex ("" disables it). Every
// pending claim started with the previous key is voided: its artist claims
// again with a fresh certificate. Admin only.
func SetBot(cur realm, pubKeyHex string) {
	onlyAdmin(cur)
	key, err := hex.DecodeString(pubKeyHex)
	if err != nil || (len(key) != 0 && len(key) != 32) {
		panic("catalog: the robot key is a 32-byte Ed25519 public key in hex")
	}
	t := rd()
	_, gen := botKey(t)
	t.set(cConfig, "bot", hex.EncodeToString(key))
	t.set(cConfig, "gen", text.Itoa(gen+1))
	save(cur, t)
	emitEvent("BotSet", "key", pubKeyHex)
}

// Claim starts the verification of artistID for the caller with the robot's
// certificate (ClaimMessage signed, hex). It replaces any pending claim for the
// artist and restarts the delay. The artist pays its gas.
func Claim(cur realm, artistID int, proof string, expires int64, sigHex string) {
	caller := userCaller(cur)
	noPayment()
	ts := now()
	t := rd()
	key, gen := botKey(t)
	if len(key) == 0 {
		panic("catalog: verification is paused")
	}
	if expires < ts || expires > ts+certLife {
		panic("catalog: this certificate has expired, check your page again")
	}
	// A plain host, so the host shown next to the ✓ is the one the proof
	// was read from (no user info, port, or "?@other.host" trick).
	if !text.HTTPS(proof, 300) || !validHost(hostOf(proof)) {
		panic("catalog: proof must be an https link on a plain host")
	}
	sig, err := hex.DecodeString(sigHex)
	if err != nil || len(sig) != 64 || !ed25519.Verify(key, []byte(ClaimMessage(artistID, caller, proof, expires)), sig) {
		panic("catalog: this certificate is not valid for your wallet")
	}
	a := mustArtist(t, artistID)
	mustClaimable(t, a, caller)
	mustRobotVerifiable(a)
	t.set(cClaims, store.Pad(artistID), store.Rec(caller.String(), proof, text.Itoa64(ts), text.Itoa(gen)))
	save(cur, t)
	emitEvent("ClaimProposed", "artist", text.Itoa(artistID), "to", caller.String(), "proof", proof)
}

// FinalizeClaim applies a pending claim once claimDelay has passed. Anyone
// can call it, usually the artist from the app.
func FinalizeClaim(cur realm, artistID int) {
	noPayment()
	t := rd()
	c := getClaim(t, artistID)
	if c == nil {
		panic("catalog: no pending verification for this artist")
	}
	if _, gen := botKey(t); c.Gen != gen {
		panic("catalog: this check was signed by a robot key since replaced, check your page again")
	}
	if now() < c.At+claimDelay {
		panic("catalog: verification completes 72 hours after the check")
	}
	a := mustArtist(t, artistID)
	mustClaimable(t, a, c.To)
	t.del(cClaims, store.Pad(artistID))
	if a.Owner == "" {
		a.Owner = c.To
		t.set(cOwners, c.To.String(), text.Itoa(a.ID))
		t.activity("claim", c.To, "0", text.Itoa(a.ID), "0")
	}
	a.Verified = true
	putArtist(t, a)
	t.set(cProofs, store.Pad(artistID), c.Proof)
	save(cur, t)
	emitEvent("ArtistClaimed", "id", text.Itoa(a.ID), "owner", c.To.String(), "proof", c.Proof)
}

// CancelClaim drops a pending claim (e.g. the proof page was hijacked). Admin only.
func CancelClaim(cur realm, artistID int) {
	onlyAdmin(cur)
	t := rd()
	if _, ok := t.get(cClaims, store.Pad(artistID)); !ok {
		panic("catalog: no pending verification for this artist")
	}
	t.del(cClaims, store.Pad(artistID))
	save(cur, t)
	emitEvent("ClaimCancelled", "artist", text.Itoa(artistID))
}

// ResetOwner undoes a wrong claim on an imported profile (e.g. a hijacked
// proof page found too late): the profile is unclaimed again. Self-registered
// profiles keep their owner. Admin only.
func ResetOwner(cur realm, artistID int) {
	onlyAdmin(cur)
	t := rd()
	a := mustArtist(t, artistID)
	if a.Kind == OriginArtist || a.Owner == "" {
		panic("catalog: only a claimed imported profile can be reset")
	}
	t.del(cOwners, a.Owner.String())
	a.Owner, a.Verified = "", false
	if isRef(a.Kind) && !a.Hidden { // a pointer has no name of its own: the claimant's name and bio go too
		if old := skeleton(a.Name); old != "" {
			if id, ok := t.get(cNames, old); ok && text.Atoi(id) == a.ID {
				t.del(cNames, old)
			}
		}
		a.Name, a.Bio = "", ""
	}
	putArtist(t, a)
	t.del(cProofs, store.Pad(artistID))
	t.del(cClaims, store.Pad(artistID))
	save(cur, t)
	emitEvent("OwnerReset", "artist", text.Itoa(artistID))
}

// mustRobotVerifiable refuses the robot's path for a curated profile: it
// carries a real artist's name and tracks that GnoRadio imported, and no
// domain proves who that artist is (neither the import site's operator nor
// any domain an impersonator buys). The moderator assigns it (AssignArtist).
func mustRobotVerifiable(a *Artist) {
	if a.Kind == OriginCurated || a.Kind == OriginJamendo { // Jamendo has no bio a robot could read
		panic("catalog: an imported profile is verified by the GnoRadio moderator, not with a proof page")
	}
}

// mustClaimable: an unowned profile goes to a wallet without a profile; an
// owned one can only be verified for its own wallet.
func mustClaimable(t *tx, a *Artist, to address) {
	if a.Hidden {
		panic("catalog: this artist is hidden")
	}
	if a.Verified {
		panic("catalog: this artist is already verified")
	}
	if a.Owner != "" {
		if a.Owner != to {
			panic("catalog: this profile belongs to another wallet")
		}
		return
	}
	if !role.Canonical(to) || artistOf(t, to) != 0 {
		panic("catalog: this wallet is invalid or already has an artist profile")
	}
}

// ArtistVerified reports whether an artist proved who they are (tips and
// paid tickets need it).
func ArtistVerified(artistID int) bool { return artistAt(artistID, aVerified) == "1" }

// ClaimState is an artist's pending verification: the wallet it goes to and
// when FinalizeClaim may apply it; pending is false when there is none.
func ClaimState(artistID int) (pending bool, to address, readyAt int64) {
	if c := liveClaim(rd(), artistID); c != nil {
		return true, c.To, c.At + claimDelay
	}
	return false, "", 0
}

// PendingClaim is a verification on its way: the artist, the wallet it goes
// to, the proof link and when FinalizeClaim may apply it.
type PendingClaim struct {
	Artist  int
	To      address
	Proof   string
	ReadyAt int64
}

// PendingClaims lists up to limit (1-100) verifications pending with the
// current robot key, by artist id from offset, and how many claims are
// stored (stale ones included, so offset+limit < total means more). A claim
// stays public for 72 hours before it counts: this is where anyone watches
// them.
func PendingClaims(offset, limit int) (out []PendingClaim, total int) {
	t := rd()
	_, gen := botKey(t)
	keys, recs := store.Rows(data.PageAt(cClaims, max0(offset), store.Limit(limit, 100), false))
	for i, k := range keys {
		if f := store.Fields(recs[i]); text.Atoi(f[3]) == gen {
			out = append(out, PendingClaim{Artist: text.Atoi(k), To: address(f[0]), Proof: f[1], ReadyAt: text.Atoi64(f[2]) + claimDelay})
		}
	}
	return out, data.Size(cClaims)
}

// ProofHost is where a verified artist's proof was found: a host they
// control, not proof of who they are, so show it next to the ✓. It is ""
// when the artist is not verified, or a moderator verified it (Verify,
// AssignArtist).
func ProofHost(artistID int) string {
	t := rd()
	return proofHost(t, artistID, artistField(t, artistID, aVerified))
}

func proofHost(t *tx, artistID int, verified string) string {
	if verified == "" {
		return ""
	}
	if h := hostOf(t.val(cProofs, store.Pad(artistID))); validHost(h) {
		return h
	}
	return "" // a record a later release wrote: show no host rather than a wrong one
}

// ClaimJSON is the verification state of an artist for the app:
// {"verified":b,"proof":"…","pending":b,"to":"…","pendingProof":"…","readyAt":n,"bot":"…"}.
func ClaimJSON(artistID int) string {
	t := rd()
	out := `{"verified":` + strconv.FormatBool(artistField(t, artistID, aVerified) == "1") + `,"proof":"` + t.val(cProofs, store.Pad(artistID)) + `"`
	if c := liveClaim(t, artistID); c != nil {
		out += `,"pending":true,"to":"` + c.To.String() + `","pendingProof":"` + c.Proof + `","readyAt":` + text.Itoa64(c.At+claimDelay)
	} else {
		out += `,"pending":false`
	}
	key, _ := botKey(t)
	return out + `,"bot":` + strconv.FormatBool(len(key) != 0) + `}`
}

package tickets

import (
	"strings"

	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	catalog "gno.land/r/nym-alexiscolin000/gnoradio/catalog/v2"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
	"gno.land/r/nym-alexiscolin000/gnoradio/tickets/nft"
)

// The tickets' collections in the data realm (docs/ARCHITECTURE-v1.md,
// section 3). P(n) is store.Pad, T(t) a 12-digit unix time. The event and
// ticket records are laid out as the permanent NFT realm reads them
// (nft.E*, nft.T*).
const (
	cEvents   = nft.CEvents        // P(id) -> event record
	cTickets  = nft.CTickets       // P((id-1)/16) -> 16 ticket records
	cByArtist = "tickets/byartist" // P(artist)/P(event) -> ""
	cUpcoming = "tickets/upcoming" // T(start)/P(event) -> "" (not cancelled, not hidden)
	cAhead    = "tickets/ahead"    // P(artist)/T(start)/P(event) -> "" (not cancelled)
	cOwned    = "tickets/owned"    // address -> packed ticket ids held
	cBuyers   = "tickets/buyers"   // P(event)/address -> tickets bought
	cAttended = "tickets/attended" // address -> concerts checked in at
	cMeta     = "tickets/meta"     // "n" -> Rec(events, tickets)
	cConfig   = "tickets/config"   // admin, fee
	cPresent  = "tickets/present"  // P(ticket) -> Rec(holder, unix time, door code) of its last Present
)

var collections = []string{cEvents, cTickets, cByArtist, cUpcoming, cAhead, cOwned, cBuyers, cAttended, cMeta, cConfig, cPresent}

// setup makes the collections and the first settings, once: a later
// release finds them made (it is not the writer in its init).
func setup(cur realm, holder address) {
	for _, c := range collections {
		data.Make(cross(cur), c)
	}
	if !data.Has(cMeta, "n") {
		save(cur, store.Ops{}.Set(cMeta, "n", store.Rec("0", "0")).Set(cConfig, "admin", holder.String()))
	}
}

// save writes ops in one call: data.Set or data.Remove for one op, else one
// data.Batch.
func save(cur realm, ops store.Ops) {
	switch {
	case len(ops) == 0:
	case len(ops) > 4:
		data.Batch(cross(cur), ops)
	case ops[0] == store.OpSet:
		data.Set(cross(cur), ops[1], ops[2], ops[3])
	default:
		data.Remove(cross(cur), ops[1], ops[2])
	}
}

func get(c, k string) string {
	v, _ := data.Get(c, k)
	return v
}

func upKey(e *Event) string { return store.TimeKey(e.Start) + "/" + store.Pad(e.ID) }

func aheadKey(e *Event) string { return store.Pad(e.ArtistID) + "/" + upKey(e) }

// idOf reads the event id at the end of an index key.
func idOf(k string) int { return text.Atoi(k[strings.LastIndex(k, "/")+1:]) }

// count is the number of keys of c with start <= key < end.
func count(c, start, end string) int { return data.Index(c, end) - data.Index(c, start) }

// ---- counts: tickets/meta "n" ----

const (
	mEvents = iota
	mTickets
)

func meta() string { return get(cMeta, "n") }

func metaCount(m string, i int) int {
	if m == "" {
		return 0
	}
	return text.Atoi(store.Field(m, i))
}

// ---- events ----

// decode reads an event record ("" gives nil).
func decode(id int, rec string) *Event {
	if rec == "" {
		return nil
	}
	f := store.Fields(rec)
	return &Event{ID: id, ArtistID: text.Atoi(f[nft.EArtist]), Title: f[nft.ETitle], Venue: f[nft.EVenue], Link: f[nft.ELink],
		Start: text.Atoi64(f[nft.EStart]), Price: text.Atoi64(f[nft.EPrice]), Capacity: text.Atoi(f[nft.ECapacity]), Sold: text.Atoi(f[nft.ESold]),
		Cancelled: f[nft.ECancelled] != "", Hidden: f[nft.EHidden] != "", Removed: f[nft.ERemoved]}
}

// record encodes an event in the order of nft.E*.
func record(e *Event) string {
	f := make([]string, nft.EFields)
	f[nft.ESold], f[nft.EArtist], f[nft.EStart], f[nft.EPrice], f[nft.ECapacity] =
		text.Itoa(e.Sold), text.Itoa(e.ArtistID), text.Itoa64(e.Start), text.Itoa64(e.Price), text.Itoa(e.Capacity)
	f[nft.ECancelled], f[nft.EHidden], f[nft.ERemoved] = text.Flag(e.Cancelled), text.Flag(e.Hidden), e.Removed
	f[nft.ETitle], f[nft.EVenue], f[nft.ELink] = e.Title, e.Venue, e.Link
	return store.Rec(f...)
}

func getEvent(id int) *Event {
	if id < 1 {
		return nil
	}
	return decode(id, get(cEvents, store.Pad(id)))
}

// visible: not hidden by moderation, and its artist profile is visible.
func visible(e *Event) bool { return e != nil && !e.Hidden && catalog.ArtistVisible(e.ArtistID) }

func mustEvent(id int) *Event {
	e := getEvent(id)
	if !visible(e) {
		panic("tickets: unknown concert")
	}
	return e
}

// ---- tickets: chunks of nft.Chunk records ----

// chunks reads ticket records, each chunk once per call.
type chunks map[string]string

func (cs chunks) ticket(id int) *Ticket {
	if id < 1 {
		return nil
	}
	k, i := store.Slot(id, nft.Chunk)
	ch, ok := cs[k]
	if !ok {
		ch = get(cTickets, k)
		cs[k] = ch
	}
	if ch == "" {
		return nil
	}
	rec := store.Field(ch, i)
	if rec == "" {
		return nil
	}
	return &Ticket{ID: id, Event: text.Atoi(store.Field(rec, nft.TEvent)), Serial: text.Atoi(store.Field(rec, nft.TSerial)),
		Attended: store.Field(rec, nft.TAttended) != ""}
}

func getTicket(id int) *Ticket { return chunks{}.ticket(id) }

func mustTicket(id int) *Ticket {
	tk := getTicket(id)
	if tk == nil {
		panic("tickets: unknown ticket")
	}
	return tk
}

func ticketRecord(tk *Ticket) string {
	return store.Rec(text.Itoa(tk.Event), text.Itoa(tk.Serial), text.Flag(tk.Attended))
}

// ---- holders' lists ----

// own adds id to addr's list (remove: takes it out) as an op.
func own(ops store.Ops, addr address, id int, add bool) store.Ops {
	list := get(cOwned, addr.String())
	if add {
		if store.Count(list) >= maxOwned {
			panic("tickets: this wallet holds " + text.Itoa(maxOwned) + " tickets, the most it can")
		}
		list, _ = store.Add(list, id)
	} else {
		list, _ = store.Remove(list, id)
	}
	if list == "" {
		return ops.Del(cOwned, addr.String())
	}
	return ops.Set(cOwned, addr.String(), list)
}

package tickets

import (
	"strconv"
	"strings"

	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	catalog "gno.land/r/nym-alexiscolin000/gnoradio/catalog/v2"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
	"gno.land/r/nym-alexiscolin000/gnoradio/tickets/nft"
)

// Read API for the home realm and the GnoRadio app (values only).

// TicketOwner returns the current holder of a ticket.
func TicketOwner(ticketID int) address {
	mustTicket(ticketID)
	return nft.OwnerOf(text.Itoa(ticketID))
}

// EventInfo returns a copy of a visible concert; ok is false otherwise.
func EventInfo(id int) (Event, bool) {
	if e := getEvent(id); visible(e) {
		return *e, true
	}
	return Event{}, false
}

// HiddenNote says why a concert is hidden: "Removed by moderation: <reason>", or "".
func HiddenNote(eventID int) string {
	if e := getEvent(eventID); e != nil && e.Hidden {
		return "Removed by moderation: " + e.Removed
	}
	return ""
}

// TicketInfo returns a copy of a ticket.
func TicketInfo(id int) (Ticket, bool) {
	if tk := getTicket(id); tk != nil {
		return *tk, true
	}
	return Ticket{}, false
}

func EventCount() int  { return metaCount(meta(), mEvents) }
func TicketCount() int { return metaCount(meta(), mTickets) }

// Attended returns how many concerts a holder checked in at.
func Attended(holder address) int { return text.Atoi(get(cAttended, holder.String())) }

// PresentedAt is when the ticket's current holder last presented it at the
// door (Present) with this door code, unix seconds; 0 when they did not, or
// it changed hands since, or it was checked in. CheckIn takes it for 10
// minutes.
func PresentedAt(ticketID int, code string) int64 {
	rec := get(cPresent, store.Pad(ticketID))
	if rec == "" || code == "" || address(store.Field(rec, 0)) != nft.Holder(ticketID) || store.Field(rec, 2) != code {
		return 0
	}
	return text.Atoi64(store.Field(rec, 1))
}

// ServiceFee returns the per-ticket service fee in ugnot (0 while no treasury is set).
func ServiceFee() int64 { return serviceFee() }

// Admin is the moderator ("" once renounced).
func Admin() address { return adminAddr() }

// PendingAdmin is the address the moderator role is offered to ("" if none).
func PendingAdmin() address { return admin.Pending() }

// TicketsOf returns up to limit ticket ids held by owner, newest first.
func TicketsOf(owner address, offset, limit int) []int {
	limit = store.Limit(limit, 50)
	if offset < 0 {
		offset = 0
	}
	return store.Page(get(cOwned, owner.String()), offset, limit, true)
}

// ArtistEvents returns up to limit visible concert ids of an artist, newest
// first.
func ArtistEvents(artistID, limit int) []int {
	limit = store.Limit(limit, 50)
	if !catalog.ArtistVisible(artistID) {
		return nil
	}
	var ids []int
	p := store.Pad(artistID)
	for end := p + "0"; ; {
		keys, _ := store.Rows(data.Page(cByArtist, p+"/", end, 100, true))
		for _, k := range keys {
			if e := getEvent(idOf(k)); !e.Hidden {
				if ids = append(ids, e.ID); len(ids) >= limit {
					return ids
				}
			}
		}
		if len(keys) < 100 {
			return ids
		}
		end = keys[len(keys)-1]
	}
}

// Upcoming returns up to n visible, not cancelled future concerts, soonest
// first.
func Upcoming(n int) []Event {
	n = store.Limit(n, 50)
	var out []Event
	eachUpcoming(n, func(e *Event) bool {
		out = append(out, *e)
		return len(out) >= n
	})
	return out
}

// PastEvents returns up to limit (1-100) ids of the concerts that have
// started, were not cancelled and are not hidden, latest first from offset,
// and how many there are. The start-time index pages them: cancelled or
// hidden concerts take no room, however many there are.
func PastEvents(offset, limit int) (ids []int, total int) {
	limit = store.Limit(limit, 100)
	total = data.Index(cUpcoming, store.TimeKey(now()+1))
	if offset < 0 || offset >= total {
		return nil, total
	}
	if offset+limit > total {
		limit = total - offset
	}
	keys, _ := store.Rows(data.PageAt(cUpcoming, data.Size(cUpcoming)-total+offset, limit, true))
	for _, k := range keys {
		ids = append(ids, idOf(k))
	}
	return ids, total
}

// eachUpcoming walks the visible future concerts, soonest first, until fn
// returns true or maxScan index entries were read; want sizes the first
// page. Past entries are skipped by starting the walk at now.
func eachUpcoming(want int, fn func(e *Event) bool) {
	start, scanned, size := store.TimeKey(now()+1), 0, want+5
	for {
		if size > 100 {
			size = 100
		}
		keys, _ := store.Rows(data.Page(cUpcoming, start, "", size, false))
		for _, k := range keys {
			scanned++
			if e := getEvent(idOf(k)); visible(e) && !e.Cancelled && fn(e) || scanned >= maxScan {
				return
			}
		}
		if len(keys) < size {
			return
		}
		start, size = keys[len(keys)-1]+"\x00", 100
	}
}

// ---- JSON and art ----

// EventSVG returns the specimen ticket of a visible concert as a markdown
// image, or "" when the concert is not visible.
func EventSVG(id int) string { return nft.EventSVG(id) }

// TicketSVG returns a ticket as a markdown image, or "" if unknown.
func TicketSVG(id int) string { return nft.TicketSVG(id) }

func eventJSON(e *Event, fee string) string {
	return `{"id":` + text.Itoa(e.ID) + `,"artist":` + text.Itoa(e.ArtistID) + `,"artistName":` + text.Str(nft.ArtistName(e.ArtistID)) +
		`,"title":` + text.Str(e.Title) + `,"venue":` + text.Str(e.Venue) + `,"link":` + text.Str(e.Link) +
		`,"start":` + text.Itoa64(e.Start) + `,"price":` + text.Itoa64(e.Price) + `,"capacity":` + text.Itoa(e.Capacity) +
		`,"sold":` + text.Itoa(e.Sold) + `,"cancelled":` + strconv.FormatBool(e.Cancelled) + `,"fee":` + fee + `}`
}

// EventsJSON pages through concerts, newest first (limit <= 50): offset and
// limit count stored concerts, hidden ones are left out of the page, and
// "next" gives the offset of the following page (0 at the end).
// upcoming=true lists future, not cancelled, visible concerts instead,
// soonest first, with offset and limit counting listed concerts ("next" is
// then a listed-concert offset, 0 when the scan ended).
func EventsJSON(offset, limit int, upcoming bool) string {
	limit = store.Limit(limit, 50)
	if offset < 0 {
		offset = 0
	}
	fee := text.Itoa64(serviceFee())
	var b strings.Builder
	b.WriteString(`{"total":` + text.Itoa(EventCount()) + `,"events":[`)
	n, next := 0, 0
	add := func(e *Event) {
		if n > 0 {
			b.WriteString(",")
		}
		b.WriteString(eventJSON(e, fee))
		n++
	}
	if upcoming {
		// One concert past a full page proves there is a next page.
		i := 0
		eachUpcoming(offset+limit+1, func(e *Event) bool {
			if n >= limit {
				next = i
				return true
			}
			if i >= offset {
				add(e)
			}
			i++
			return false
		})
	} else {
		// offset and limit count stored concerts, hidden ones included, so
		// the page is found in O(log n); hidden ones are left out.
		keys, recs := store.Rows(data.PageAt(cEvents, offset, limit, true))
		for i, k := range keys {
			if e := decode(text.Atoi(k), recs[i]); visible(e) {
				add(e)
			}
		}
		if offset+len(keys) < data.Size(cEvents) {
			next = offset + len(keys)
		}
	}
	b.WriteString(`],"next":` + text.Itoa(next) + `}`)
	return b.String()
}

// TicketsOfJSON lists the tickets held by owner, newest first (<= 50).
func TicketsOfJSON(owner address) string {
	var b strings.Builder
	b.WriteString(`[`)
	cs := chunks{}
	for i, id := range TicketsOf(owner, 0, 50) {
		tk := cs.ticket(id)
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(`{"id":` + text.Itoa(tk.ID) + `,"event":` + text.Itoa(tk.Event) + `,"serial":` + text.Itoa(tk.Serial) +
			`,"attended":` + strconv.FormatBool(tk.Attended) + `}`)
	}
	b.WriteString(`]`)
	return b.String()
}

// FeesJSON returns the ticket service fee and where it goes.
func FeesJSON() string {
	return `{"serviceFee":` + text.Itoa64(serviceFee()) + `,"treasury":` + text.Str(catalog.Treasury().String()) + `}`
}

// Package tickets is GnoRadio's concert tickets rules, release 1. Concerts
// belong to artist profiles of the catalog; a ticket is a GRC721 NFT of the
// permanent realm gno.land/r/nym-alexiscolin000/gnoradio/tickets/nft, drawn on-chain. Ticket
// money goes straight to the artist's owner address in the same transaction,
// the service fee to the GnoRadio treasury: this realm ends every
// transaction holding no coins.
//
// It keeps no state but its admin role. Every record lives in the data realm,
// in the "tickets/…" collections only the current tickets writer may change
// (db.gno), and the NFTs in the NFT realm, which only that writer drives: a
// later release takes over both without copying anything.
package tickets

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nym-alexiscolin000/gnoradio/role/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/safe/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	catalog "gno.land/r/nym-alexiscolin000/gnoradio/catalog/v2"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
	"gno.land/r/nym-alexiscolin000/gnoradio/tickets/nft"
)

const (
	denom          = "ugnot"
	ugnot          = 1_000_000
	minPrice       = 100_000 // 0.1 GNOT
	maxTicketPrice = 10_000 * ugnot
	maxCapacity    = 10000
	maxPerBuyer    = 4
	maxPerArtist   = 500       // concerts ever created
	maxOpenAhead   = 10        // future, not cancelled concerts per artist
	checkInWindow  = 12 * 3600 // check-in opens 12h before the concert
	checkInClose   = 12 * 3600 // and closes 12h after its start
	presentFor     = 10 * 60   // a Present admits its ticket for 10 minutes
	maxServiceFee  = 10 * ugnot
	maxOwned       = 1000 // tickets one wallet holds
	maxGifted      = 500  // a wallet takes gifts while it holds fewer: gifts never block buying
	maxScan        = 1000 // upcoming index entries one read walks
	nftPath        = "gno.land/r/nym-alexiscolin000/gnoradio/tickets/nft"
)

// Event is a concert.
type Event struct {
	ID        int
	ArtistID  int
	Title     string
	Venue     string
	Link      string // optional https link, public
	Start     int64
	Price     int64 // ugnot, 0 = free
	Capacity  int
	Sold      int
	Cancelled bool
	Hidden    bool
	Removed   string // the moderator's reason while hidden
}

// Ticket is one NFT ticket.
type Ticket struct {
	ID       int
	Event    int
	Serial   int
	Attended bool
}

var (
	self  string     // this realm's path
	admin *role.Role // the moderator; nil when a release before renounced it
)

// init takes the admin over from the previous release (tickets/config
// "admin"), or names the deployer. While this realm is the tickets writer
// (release 1 at deploy) it also makes the collections.
func init(cur realm) {
	self = cur.PkgPath()
	holder, mirrored := data.Get(cConfig, "admin")
	if !mirrored {
		deployer := unsafe.OriginCaller()
		if deployer == "" && runtime.ChainID() == "dev" {
			deployer = chain.PackageAddress(self + "/dev") // gno test: a key nobody holds
		}
		holder = deployer.String()
	}
	if holder != "" {
		admin = role.New("admin", address(holder))
	}
	if data.Writer("tickets") == self {
		setup(cur, address(holder))
	}
}

// ---- concerts ----

// CreateEvent announces a concert by the caller's artist profile.
// start is "YYYY-MM-DD HH:MM" in UTC; price is in GNOT ("0" for free, "2.5");
// link is an optional https URL (stream or venue page, public).
func CreateEvent(cur realm, title, venue, link, start, price string, capacity int) int {
	caller := userCaller(cur)
	noPayment()
	artistID := mustArtistOf(caller)
	p := store.Pad(artistID)
	if count(cByArtist, p+"/", p+"0") >= maxPerArtist {
		panic("tickets: concert limit reached for this artist")
	}
	if count(cAhead, p+"/"+store.TimeKey(now()+1), p+"0") >= maxOpenAhead {
		panic("tickets: an artist can announce " + text.Itoa(maxOpenAhead) + " upcoming concerts at a time")
	}
	title, venue, link = strings.TrimSpace(title), strings.TrimSpace(venue), strings.TrimSpace(link)
	mustText("title", title, 2, 48)
	mustText("venue", venue, 2, 48)
	if link != "" && !text.HTTPS(link, 200) {
		panic("tickets: link must start with https:// (max 200 chars, no spaces)")
	}
	when, err := time.Parse("2006-01-02 15:04", strings.TrimSpace(start))
	if err != nil {
		panic("tickets: start must look like 2026-11-20 21:00 (UTC)")
	}
	if when.Unix() <= now() {
		panic("tickets: the concert must be in the future")
	}
	pr, ok := parseGNOT(price)
	if !ok || pr > maxTicketPrice || (pr > 0 && pr < minPrice) {
		panic("tickets: price must be 0 (free) or between 0.1 and 10000 GNOT")
	}
	if capacity < 1 || capacity > maxCapacity {
		panic("tickets: capacity must be between 1 and 10000")
	}
	m := meta()
	e := &Event{ID: metaCount(m, mEvents) + 1, ArtistID: artistID, Title: title, Venue: venue, Link: link,
		Start: when.Unix(), Price: pr, Capacity: capacity}
	save(cur, store.Ops{}.Set(cEvents, store.Pad(e.ID), record(e)).Set(cByArtist, p+"/"+store.Pad(e.ID), "").
		Set(cUpcoming, upKey(e), "").Set(cAhead, aheadKey(e), "").Set(cMeta, "n", store.With(m, mEvents, text.Itoa(e.ID))))
	chain.Emit("EventCreated", "id", text.Itoa(e.ID), "artist", text.Itoa(artistID), "start", text.Itoa64(e.Start), "price", text.Itoa64(pr))
	return e.ID
}

// CancelEvent stops ticket sales. GnoRadio never held the payments: they
// went straight to the artist, who handles refunds directly. Artist owner
// only.
func CancelEvent(cur realm, eventID int) {
	caller := userCaller(cur)
	noPayment()
	e := mustEvent(eventID)
	if catalog.ArtistOwner(e.ArtistID) != caller {
		panic("tickets: only the artist can cancel this concert")
	}
	e.Cancelled = true
	save(cur, store.Ops{}.Set(cEvents, store.Pad(e.ID), record(e)).Del(cUpcoming, upKey(e)).Del(cAhead, aheadKey(e)))
	chain.Emit("EventCancelled", "id", text.Itoa(e.ID))
}

// BuyTicket mints a ticket to the caller. A paid ticket needs the exact
// price plus the service fee attached: the price goes straight to the
// artist, the fee to the GnoRadio treasury.
func BuyTicket(cur realm, eventID int) int {
	caller := userCaller(cur)
	e := getEvent(eventID)
	if e == nil || e.Hidden {
		panic("tickets: unknown concert")
	}
	owner, verified, shown := catalog.ArtistPayee(e.ArtistID) // mustEvent's check and the payee, one read
	if !shown {
		panic("tickets: unknown concert")
	}
	if e.Cancelled {
		panic("tickets: this concert is cancelled")
	}
	if now() >= e.Start {
		panic("tickets: ticket sales are closed")
	}
	if e.Sold >= e.Capacity {
		panic("tickets: sold out")
	}
	if e.Price > 0 && (owner == "" || !verified) {
		panic("tickets: this artist has not verified their profile yet")
	}
	buyKey := store.Pad(e.ID) + "/" + caller.String()
	bought := text.Atoi(get(cBuyers, buyKey))
	if bought >= maxPerBuyer || (e.Price == 0 && bought >= 1) {
		panic("tickets: ticket limit reached for this concert (1 free or 4 paid per wallet)")
	}
	fee, to := int64(0), address("")
	if e.Price == 0 {
		noPayment()
	} else {
		if fee = serviceFee(); fee > 0 {
			to = catalog.Treasury() // serviceFee is 0 while none is set
		}
		if paid() != e.Price+fee {
			panic("tickets: attach exactly " + text.GNOT(e.Price+fee))
		}
	}

	m := meta()
	tk := &Ticket{ID: metaCount(m, mTickets) + 1, Event: e.ID, Serial: e.Sold + 1}
	k, i := store.Slot(tk.ID, nft.Chunk)
	ch := store.Rec(ticketRecord(tk))
	if i > 0 {
		ch = store.Append(get(cTickets, k), ticketRecord(tk))
	}
	e.Sold = tk.Serial
	ops := store.Ops{}.Set(cEvents, store.Pad(e.ID), record(e)).
		Set(cBuyers, buyKey, text.Itoa(bought+1)).Set(cMeta, "n", store.With(m, mTickets, text.Itoa(tk.ID))).Set(cTickets, k, ch)
	save(cur, own(ops, caller, tk.ID, true))
	nft.Mint(cross(cur), caller, tk.ID)
	if e.Price > 0 {
		bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bk.SendCoins(cur.Address(), owner, chain.Coins{{Denom: denom, Amount: e.Price}})
		if fee > 0 {
			bk.SendCoins(cur.Address(), to, chain.Coins{{Denom: denom, Amount: fee}})
		}
	}
	chain.Emit("TicketBought", "event", text.Itoa(e.ID), "ticket", text.Itoa(tk.ID), "by", caller.String(), "price", text.Itoa64(e.Price), "fee", text.Itoa64(fee))
	return tk.ID
}

// TransferTicket gives one of the caller's tickets to someone else. There is
// no built-in resale market.
func TransferTicket(cur realm, to address, ticketID int) {
	caller := userCaller(cur)
	noPayment()
	tk := mustTicket(ticketID)
	if tk.Attended {
		panic("tickets: a checked-in ticket can no longer be gifted")
	}
	if !role.Canonical(to) || to == caller || data.IsGnoRadio(to) || to == cur.Address() {
		panic("tickets: invalid recipient")
	}
	if nft.Holder(ticketID) != caller {
		panic("tickets: you do not hold this ticket")
	}
	if store.Count(get(cOwned, to.String())) >= maxGifted {
		panic("tickets: this wallet holds " + text.Itoa(maxGifted) + " tickets and takes no more gifts")
	}
	save(cur, own(own(nil, caller, ticketID, false), to, ticketID, true))
	nft.Transfer(cross(cur), caller, to, ticketID)
	chain.Emit("TicketGifted", "ticket", text.Itoa(ticketID), "from", caller.String(), "to", to.String())
}

// Present shows a ticket at the door: its holder signs from their own
// wallet, with the door code the staff's screen shows after scanning the
// ticket's QR. A QR built from public data (the ticket id and its holder)
// cannot do that for them, and a stranger with a copied QR gets another
// code: the holder's Present does not admit them. CheckIn then admits the
// ticket with that code for 10 minutes. Only while the door is open: from
// 12h before the concert to 12h after its start.
func Present(cur realm, ticketID int, code string) {
	caller := userCaller(cur)
	noPayment()
	mustDoorCode(code)
	tk := mustTicket(ticketID)
	e := mustEvent(tk.Event)
	if nft.Holder(ticketID) != caller {
		panic("tickets: you do not hold this ticket")
	}
	mustDoorOpen(e, tk)
	data.Set(cross(cur), cPresent, store.Pad(ticketID), store.Rec(caller.String(), text.Itoa64(now()), code))
	chain.Emit("TicketPresented", "ticket", text.Itoa(ticketID), "holder", caller.String())
}

// CheckIn marks a ticket as used at the door; its holder earns the
// "I was there" stamp. The concert's artist owner only, while the door is
// open, and only for a ticket its current holder presented (Present) with
// this door code in the last 10 minutes.
func CheckIn(cur realm, ticketID int, code string) {
	caller := userCaller(cur)
	noPayment()
	mustDoorCode(code)
	tk := mustTicket(ticketID)
	e := mustEvent(tk.Event)
	if catalog.ArtistOwner(e.ArtistID) != caller {
		panic("tickets: only the concert's artist can check tickets in")
	}
	mustDoorOpen(e, tk)
	if at := PresentedAt(ticketID, code); at == 0 || now()-at > presentFor {
		panic("tickets: the holder must present this ticket from their wallet with this door code first (it counts for 10 minutes)")
	}
	tk.Attended = true
	k, i := store.Slot(tk.ID, nft.Chunk)
	holder := nft.Holder(ticketID)
	save(cur, store.Ops{}.Set(cTickets, k, store.With(get(cTickets, k), i, ticketRecord(tk))).
		Set(cAttended, holder.String(), text.Itoa(Attended(holder)+1)).Del(cPresent, store.Pad(ticketID)))
	chain.Emit("CheckedIn", "ticket", text.Itoa(ticketID), "holder", holder.String())
}

// mustDoorCode refuses a door code that is not 4 to 8 digits.
func mustDoorCode(code string) {
	if len(code) < 4 || len(code) > 8 {
		panic("tickets: the door code is 4 to 8 digits")
	}
	for i := 0; i < len(code); i++ {
		if code[i] < '0' || code[i] > '9' {
			panic("tickets: the door code is 4 to 8 digits")
		}
	}
}

// mustDoorOpen refuses a ticket the door cannot take now.
func mustDoorOpen(e *Event, tk *Ticket) {
	if e.Cancelled {
		panic("tickets: this concert is cancelled")
	}
	if tk.Attended {
		panic("tickets: ticket already checked in")
	}
	switch t := now(); {
	case t < e.Start-checkInWindow:
		panic("tickets: check-in opens 12h before the concert")
	case t > e.Start+checkInClose:
		panic("tickets: this concert is over, check-in is closed")
	}
}

// ---- moderation ----

// HideEvent hides or restores a concert. Admin only; hiding takes a public
// reason (4-200 characters). Tickets stay with their holders.
func HideEvent(cur realm, eventID int, hidden bool, reason string) {
	onlyAdmin(cur)
	e := getEvent(eventID)
	if e == nil {
		panic("tickets: unknown concert")
	}
	reason = strings.TrimSpace(reason)
	if hidden {
		mustText("reason", reason, 4, 200)
	} else {
		reason = ""
	}
	e.Hidden, e.Removed = hidden, reason
	ops := store.Ops{}.Set(cEvents, store.Pad(e.ID), record(e))
	if visible(e) && !e.Cancelled && e.Start > now() {
		ops = ops.Set(cUpcoming, upKey(e), "")
	} else {
		ops = ops.Del(cUpcoming, upKey(e))
	}
	save(cur, ops)
	chain.Emit("Moderated", "kind", "event", "target", text.Itoa(eventID), "hidden", strconv.FormatBool(hidden), "reason", reason, "by", "moderator")
}

// RefreshArtist re-reads an artist's visibility in the catalog and updates
// the Upcoming index for its future concerts (at most maxOpenAhead): once
// moderators hide a profile, its concerts stop taking places in the
// Upcoming scan; a restored artist's come back. Anyone may call it.
func RefreshArtist(cur realm, artistID int) {
	noPayment()
	p := store.Pad(artistID) + "/"
	keys, _ := store.Rows(data.Page(cAhead, p+store.TimeKey(now()+1), p+"~", maxOpenAhead, false))
	reindex(cur, artistID, keys)
}

// RefreshArtistPast does the same for up to 50 of an artist's past concerts
// from offset (oldest first; the 500 an artist may have take ten calls), so
// a hidden profile's past concerts leave the past-concerts index too.
// Anyone may call it.
func RefreshArtistPast(cur realm, artistID, offset int) {
	noPayment()
	p := store.Pad(artistID) + "/"
	lo, hi := data.Index(cAhead, p), data.Index(cAhead, p+store.TimeKey(now()+1))
	if offset < 0 || lo+offset >= hi {
		panic("tickets: no past concert of this artist there")
	}
	n := hi - lo - offset
	if n > 50 {
		n = 50
	}
	keys, _ := store.Rows(data.PageAt(cAhead, lo+offset, n, false))
	reindex(cur, artistID, keys)
}

// reindex re-files an artist's concerts (their cAhead keys) in the Upcoming
// index by visibility.
func reindex(cur realm, artistID int, keys []string) {
	var ops store.Ops
	for _, k := range keys {
		e := getEvent(idOf(k))
		if visible(e) && !e.Cancelled {
			ops = ops.Set(cUpcoming, upKey(e), "")
		} else {
			ops = ops.Del(cUpcoming, upKey(e))
		}
	}
	save(cur, ops)
	chain.Emit("ArtistRefreshed", "artist", text.Itoa(artistID), "concerts", text.Itoa(len(keys)))
}

// SetServiceFee sets the per-ticket service fee in ugnot (0..10 GNOT), paid
// by buyers of paid tickets on top of the price and forwarded to the GnoRadio
// treasury. Admin only.
func SetServiceFee(cur realm, ugnot int64) {
	onlyAdmin(cur)
	if ugnot < 0 || ugnot > maxServiceFee {
		panic("tickets: service fee must be between 0 and 10 GNOT")
	}
	data.Set(cross(cur), cConfig, "fee", text.Itoa64(ugnot))
	chain.Emit("ServiceFee", "ugnot", text.Itoa64(ugnot))
}

// ---- release and admin ----

// Ready tells the data realm that this release is on chain (see
// data.Propose). Anyone may call it.
func Ready(cur realm) {
	noPayment()
	data.Ready(cross(cur))
}

// OfferAdmin offers the admin role to an address (offering it to the admin
// cancels the offer); AcceptAdmin takes it. Each change is mirrored to the
// data realm, so the next release keeps the admin.
func OfferAdmin(cur realm, to address) {
	onlyAdmin(cur)
	admin.Offer(0, cur, to)
}

func AcceptAdmin(cur realm) {
	noPayment()
	syncAdmin()
	if admin == nil {
		panic("tickets: nothing offered to you")
	}
	admin.Accept(0, cur)
	data.Set(cross(cur), cConfig, "admin", admin.Holder().String())
}

// RenounceAdmin gives the admin role up for good, for this release and the
// next ones.
func RenounceAdmin(cur realm) {
	onlyAdmin(cur)
	admin.Renounce(0, cur)
	data.Set(cross(cur), cConfig, "admin", "")
}

// Render points gnoweb visitors to the GnoRadio site; a retired release says
// which realm took over.
func Render(_ string) string {
	home := strings.TrimPrefix(data.Writer("home"), "gno.land") // the home of the release in force
	out := "# GnoRadio · tickets\n\nThis contract holds GnoRadio's ticket rules; the tickets are NFTs of [" +
		strings.TrimPrefix(nftPath, "gno.land") + "](" + strings.TrimPrefix(nftPath, "gno.land") +
		"). The site lives at [" + home + "](" + home + ").\n"
	if w := data.Writer("tickets"); w != self {
		out += "\nThis release is retired: the tickets rules are now `" + w + "`.\n"
	}
	return out
}

// ---- helpers ----

func now() int64 { return time.Now().Unix() }

func userCaller(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("tickets: call this directly from your wallet")
	}
	return cur.Previous().Address()
}

// adminAddr is the admin: the data realm's mirror is the authority, so a
// change the previous release made after this one was deployed counts.
func adminAddr() address {
	h, ok := data.Get(cConfig, "admin")
	return role.Mirror(admin, h, ok)
}

// syncAdmin adopts the mirror when the previous release changed it after
// this one's init (during the release's delay).
func syncAdmin() {
	h, ok := data.Get(cConfig, "admin")
	admin = role.Adopt(admin, "admin", h, ok)
}

func onlyAdmin(cur realm) {
	syncAdmin()
	if admin == nil || !admin.Is(0, cur) {
		panic("tickets: admin only")
	}
	noPayment()
}

func noPayment() {
	if len(unsafe.OriginSend()) != 0 {
		panic("tickets: this action takes no coins")
	}
}

// paid returns the ugnot attached to the call; anything else is refused.
func paid() int64 {
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != denom || sent[0].Amount <= 0 {
		panic("tickets: attach a single ugnot amount")
	}
	return sent[0].Amount
}

// serviceFee is the stored fee, 0 while no treasury is set: the fee has nowhere to go, so buyers never pay it.
func serviceFee() int64 {
	if v := get(cConfig, "fee"); v != "" && catalog.Treasury().IsValid() {
		return text.MustAtoi64(v)
	}
	return 0
}

func mustArtistOf(addr address) int {
	id := catalog.ArtistOf(addr)
	if id == 0 || !catalog.ArtistVisible(id) {
		panic("tickets: create your artist profile first")
	}
	return id
}

func mustText(field, s string, min, max int) {
	if !text.Valid(s, min, max) {
		panic("tickets: " + field + " must be " + text.Itoa(min) + "-" + text.Itoa(max) +
			" characters (letters, digits, spaces and . , ' - ! ? : / &)")
	}
	if safe.Slur(s) {
		panic("tickets: " + field + " holds a slur")
	}
}

// parseGNOT parses a decimal GNOT amount ("10", "2.5") into ugnot.
func parseGNOT(s string) (int64, bool) {
	s = strings.TrimSpace(s)
	whole, frac, _ := strings.Cut(s, ".")
	if whole == "" || len(whole) > 9 || len(frac) > 6 || !text.Digits(whole) || (frac != "" && !text.Digits(frac)) {
		return 0, false
	}
	w, _ := strconv.ParseInt(whole, 10, 64)
	f, _ := strconv.ParseInt(frac+"000000"[len(frac):], 10, 64)
	return w*ugnot + f, true
}

package radio

import (
	"strings"

	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
)

const activitySize = 64

// Activity is one programming action on a station.
type Activity struct {
	Kind    string // queue | curator | sponsored
	By      address
	Track   int
	Station int
	Start   int64
	At      int64
}

// recordActivity writes the next slot of the fixed-size ring (storage
// never grows): Rec(kind, by, numbers), the numbers the track (4 digits),
// the station (1), the start (6) and the time (6). The head is in the flow
// record.
func recordActivity(t *tx, kind string, by address, track, station int, start int64) {
	h := t.flowAt(fHead, 1)
	n := store.AppendFixed(store.AppendFixed(store.AppendFixed(store.AppendFixed(make([]byte, 0, 17), int64(track), 4), int64(station), 1), start, 6), now(), 6)
	t.put(cActivity, store.Pad(h), store.Rec(kind, by.String(), string(n)))
	t.setFlowAt(fHead, 1, (h+1)%activitySize)
}

func activityOf(rec string) Activity {
	f := store.Fields(rec)
	n := f[2]
	return Activity{Kind: f[0], By: address(f[1]), Track: int(store.Num(n, 0, 4)), Station: int(store.Num(n, 4, 1)), Start: store.Num(n, 5, 6), At: store.Num(n, 11, 6)}
}

// activities returns up to limit records, newest first: the ring's slots
// before its head, read one by one (the ring fills from slot 0 and no slot
// is ever deleted, so the first empty one ends it).
func activities(limit int) []string {
	limit = store.Limit(limit, activitySize)
	t := rd()
	head := t.flowAt(fHead, 1)
	out := make([]string, 0, limit)
	for i := 1; i <= limit; i++ {
		rec := t.val(cActivity, store.Pad((head-i+activitySize)%activitySize))
		if rec == "" {
			break // the ring is not full yet
		}
		out = append(out, rec)
	}
	return out
}

// Activities returns up to limit entries, newest first.
func Activities(limit int) []Activity {
	var out []Activity
	for _, rec := range activities(limit) {
		out = append(out, activityOf(rec))
	}
	return out
}

// ActivityJSON returns the programming feed, newest first (limit <= 64).
func ActivityJSON(limit int) string {
	var b strings.Builder
	b.WriteString("[")
	for i, rec := range activities(limit) {
		a := activityOf(rec)
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(`{"kind":` + text.Str(a.Kind) + `,"by":` + text.Str(a.By.String()) + `,"track":` + text.Itoa(a.Track) +
			`,"station":` + text.Itoa(a.Station) + `,"start":` + text.Itoa64(a.Start) + `,"at":` + text.Itoa64(a.At) + `}`)
	}
	b.WriteString("]")
	return b.String()
}

package radio

import (
	"chain"
	"strings"

	"gno.land/p/nym-alexiscolin000/gnoradio/role/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
)

// The radio admin (curator and moderator) is a p/role held by this realm,
// passed in two steps. Each change is mirrored to radio/config "admin", so
// the next release keeps it, and the mirror is the authority: a change the
// previous release made after this one's init counts.

// adminAddr is the admin ("" once renounced).
func adminAddr() address {
	h, ok := data.Get(cConfig, "admin")
	return role.Mirror(admin, h, ok)
}

// syncAdmin adopts the mirror when the previous release changed it after
// this one's init (during the release's delay).
func syncAdmin() {
	h, ok := data.Get(cConfig, "admin")
	admin = role.Adopt(admin, "admin", h, ok)
}

func onlyAdmin(cur realm) {
	syncAdmin()
	if admin == nil || !admin.Is(0, cur) {
		panic("radio: admin only")
	}
	noPayment()
}

// Admin is the radio admin ("" once renounced).
func Admin() address { return adminAddr() }

// PendingAdmin is the address the admin role is offered to ("" if none).
func PendingAdmin() address { return admin.Pending() }

// Ready tells the data realm that this release is on chain (see
// data.Propose). Anyone may call it.
func Ready(cur realm) {
	noPayment()
	data.Ready(cross(cur))
}

// OfferAdmin offers the admin role to an address (offering it to the admin
// cancels the offer); AcceptAdmin takes it. Each change is mirrored to the
// data realm, so the next release keeps the admin.
func OfferAdmin(cur realm, to address) {
	onlyAdmin(cur)
	admin.Offer(0, cur, to)
}

func AcceptAdmin(cur realm) {
	noPayment()
	syncAdmin()
	if admin == nil {
		panic("radio: nothing offered to you")
	}
	admin.Accept(0, cur)
	data.Set(cross(cur), cConfig, "admin", admin.Holder().String())
}

// RenounceAdmin gives the admin role up for good, for this release and the
// next ones.
func RenounceAdmin(cur realm) {
	onlyAdmin(cur)
	admin.Renounce(0, cur)
	data.Set(cross(cur), cConfig, "admin", "")
}

// DropSlot silences a track in one station's rotation (moderation of last
// resort). It stays silent through Refresh until RestoreSlot. Radio admin only.
func DropSlot(cur realm, stationID, trackID int) {
	onlyAdmin(cur)
	t := rd()
	st := t.station(stationID)
	i, ok := st.slot(trackID)
	if st.id == MainStation {
		ok = trackID >= 1 && trackID <= t.synced() // Main simulcasts: the drop flag alone silences it there
	}
	if !ok {
		panic("radio: track not in this station's rotation")
	}
	ts := now()
	if !t.has(cDropped, dropKey(st.id, trackID)) {
		t.set(cDropped, dropKey(st.id, trackID), "1")
		t.setFlowAt(fDrops, 4, t.flowAt(fDrops, 4)+1)
	}
	if st.id != MainStation {
		st.setDuration(i, 0, ts)
	}
	release(cur, st.dropSlots(trackID, ts))
	save(cur, t)
	chain.Emit("SlotDropped", "station", text.Itoa(st.id), "track", text.Itoa(trackID))
}

// RestoreSlot undoes DropSlot: the track plays again on that station if the
// catalog still allows it. Radio admin only.
func RestoreSlot(cur realm, stationID, trackID int) {
	onlyAdmin(cur)
	mustStation(stationID)
	t := rd()
	if !t.del(cDropped, dropKey(stationID, trackID)) {
		panic("radio: this slot was not dropped")
	}
	t.setFlowAt(fDrops, 4, t.flowAt(fDrops, 4)-1)
	refresh(cur, t, trackID)
	save(cur, t)
	chain.Emit("SlotRestored", "station", text.Itoa(stationID), "track", text.Itoa(trackID))
}

// Unqueue removes a track's programmed slots from a station; one on air ends
// now. Radio admin (curator) only.
func Unqueue(cur realm, stationID, trackID int) {
	onlyAdmin(cur)
	t := rd()
	st := t.station(stationID)
	release(cur, st.dropSlots(trackID, now()))
	save(cur, t)
	chain.Emit("Unqueued", "station", text.Itoa(st.id), "track", text.Itoa(trackID))
}

// Render points gnoweb visitors to the GnoRadio site; a retired release says
// which realm took over.
func Render(_ string) string {
	home := strings.TrimPrefix(data.Writer("home"), "gno.land") // the home of the release in force
	d := strings.TrimPrefix(dataPath, "gno.land")
	out := "# GnoRadio · radio\n\nThis contract holds GnoRadio's radio rules; its data lives in [" + d + "](" + d +
		"). The site lives at [" + home + "](" + home + ").\n"
	if w := data.Writer("radio"); w != self {
		out += "\nThis release is retired: the radio is now `" + w + "`.\n"
	}
	return out
}

package radio

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strings"

	"gno.land/p/nym-alexiscolin000/gnoradio/role/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	"gno.land/r/nym-alexiscolin000/gnoradio/catalog/v2"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
)

// Curators are the listeners who pick tracks. While a pick is on air, a tip to
// its artist made with TipOnAir sends the artist's promo share to the picker
// (catalog/promo.gno). Every pick and every shared tip updates the picker's
// counters and the weekly top of the station and of all stations: one record
// and a 10-entry list, whatever the number of curators.

const (
	allStations = -1
	topCurators = 10
	topMax      = 5 + topCurators*46 // the longest station top: week, count, then score and key per curator
	week        = 7 * 24 * 3600
	tipGrace    = 120 // seconds after a pick ends during which a tip still credits its picker
)

// Curator is a picker's record, all time or for one week.
type Curator struct {
	Address address
	Picks   int
	Tips    int   // tips received while their picks were on air
	Earned  int64 // ugnot from those tips
	Promo   int64 // ugnot refunded by artists for sponsored picks (sponsor.gno)
}

// A curator is one record: all time, picks, tips, earned, promo, first
// pick, period, picks this period, picks the period before (sponsor.gno);
// this week across stations, week, picks, tips, earned; each a fixed-width
// number (cWidths). Then one entry per station picked on lately: the
// station (1 digit), week, picks, tips, earned and the last pick time
// (sWidths).
const (
	cWeek   = 8
	cFields = 12
	cLen    = 62 // the numbers
	sLen    = 27 // one station entry
)

var (
	cWidths = [cFields]int{4, 4, 8, 8, 6, 4, 4, 4, 4, 4, 4, 8}
	sWidths = [5]int{4, 4, 4, 8, 6}
)

// TipOnAir tips the artist of trackID: the attached ugnot go through the
// catalog, which pays the artist and collaborators exactly as
// catalog.TipWithSupport does. When trackID is a listener's pick on air on
// stationID (or ended less than two minutes ago), the artist's promo share
// goes to that listener; the radio reads the picker from its own schedule.
// ref is who shared the link the tipper came from ("" for none): picker and
// ref split the promo share, never more.
func TipOnAir(cur realm, stationID, trackID, supportPct int, ref address) {
	tipper := userCaller(cur)
	if ref != "" && !role.Canonical(ref) {
		panic("radio: ref is not an address (lower-case g1...)")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != "ugnot" || sent[0].Amount <= 0 {
		panic("radio: attach an amount in ugnot")
	}
	t := rd()
	st := t.station(stationID)
	picker, home := st.picker(trackID, now(), adminAddr())
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), chain.PackageAddress(data.Writer("catalog")), sent)
	toPicker, _ := catalog.RadioTip(cross(cur), trackID, supportPct, tipper, picker, ref, sent[0].Amount)
	if toPicker > 0 {
		credit(t, picker, home, 0, 1, toPicker) // ranked where the pick lives
		save(cur, t)
		chain.Emit("CuratorTipped", "station", text.Itoa(st.id), "track", text.Itoa(trackID), "picker", picker.String(), "amount", text.Itoa64(toPicker))
	}
}

// credit adds picks or a shared tip to a curator, all time and this week.
// The station's entry also keeps the time of the last pick there, which the
// queue cooldown reads (lastPickAt): no extra write per pick.
func credit(t *tx, by address, stationID, picks, tips int, earned int64) {
	k := by.String()
	ts := now()
	c, sts := curRec(t, k)
	c[0], c[1], c[2] = c[0]+int64(picks), c[1]+int64(tips), c[2]+earned
	if picks > 0 {
		// The reputation sponsored picks need (sponsor.gno): the first pick,
		// and picks counted per period, this one and the one before.
		if c[4] == 0 {
			c[4] = ts
		}
		switch p := ts / repPeriod; c[5] {
		case p:
			c[6]++
		case p - 1:
			c[5], c[6], c[7] = p, 1, c[6]
		default:
			c[5], c[6], c[7] = p, 1, 0
		}
	}
	wk := weekOf(ts)
	if c[cWeek] != wk {
		c[cWeek], c[cWeek+1], c[cWeek+2], c[cWeek+3] = wk, 0, 0, 0
	}
	c[cWeek+1], c[cWeek+2], c[cWeek+3] = c[cWeek+1]+int64(picks), c[cWeek+2]+int64(tips), c[cWeek+3]+earned
	w := stationOf(sts, stationID)
	if w[0] != wk {
		w = []int64{wk, 0, 0, 0, w[4]}
	}
	w[1], w[2], w[3] = w[1]+int64(picks), w[2]+int64(tips), w[3]+earned
	if picks > 0 {
		w[4] = ts
	}
	putCur(t, k, c, withStation(sts, stationID, w, ts))
	setTop(t, 0, wk, k, c[cWeek+1]+c[cWeek+2])
	setTop(t, stationID+1, wk, k, w[1]+w[2])
}

// curRec reads a curator record (zeros when absent) and its station entries.
func curRec(t *tx, k string) ([]int64, string) {
	c := make([]int64, cFields)
	rec := t.val(cCurators, k)
	if rec == "" {
		return c, ""
	}
	at := 0
	for i, w := range cWidths {
		c[i] = store.Num(rec, at, w)
		at += w
	}
	return c, rec[at:]
}

func putCur(t *tx, k string, c []int64, sts string) {
	b := make([]byte, 0, cLen+len(sts))
	for i, w := range cWidths {
		b = store.AppendFixed(b, c[i], w)
	}
	t.set(cCurators, k, string(append(b, sts...)))
}

// stationOf returns a curator's entry for a station: week, picks, tips,
// earned, last pick time (zeros when none).
func stationOf(sts string, stationID int) []int64 {
	w := make([]int64, 5)
	for i := 0; i+sLen <= len(sts); i += sLen {
		if int(dec[sts[i]]) == stationID {
			at := i + 1
			for j, n := range sWidths {
				w[j] = store.Num(sts, at, n)
				at += n
			}
			break
		}
	}
	return w
}

// withStation sets a station's entry and drops the entries that no longer
// count: an older week whose last pick is past the cooldown.
func withStation(sts string, stationID int, w []int64, ts int64) string {
	b := store.AppendFixed(make([]byte, 0, sLen+len(sts)), int64(stationID), 1)
	for j, n := range sWidths {
		b = store.AppendFixed(b, w[j], n)
	}
	wk := weekOf(ts)
	for i := 0; i+sLen <= len(sts); i += sLen {
		e := sts[i : i+sLen]
		if int(dec[e[0]]) == stationID {
			continue
		}
		if store.Num(e, 1, 4) == wk || ts-store.Num(e, sLen-6, 6) < queueCooldown {
			b = append(b, e...)
		}
	}
	return string(b)
}

// markPick keeps the time of a pick that earns no point (a sponsored one) for
// the queue cooldown.
func markPick(t *tx, by address, stationID int) {
	k := by.String()
	ts := now()
	c, sts := curRec(t, k)
	w := stationOf(sts, stationID)
	if wk := weekOf(ts); w[0] != wk {
		w = []int64{wk, 0, 0, 0, 0}
	}
	w[4] = ts
	putCur(t, k, c, withStation(sts, stationID, w, ts))
}

// lastPickAt is when addr last picked on a station (0: never).
func lastPickAt(t *tx, addr address, stationID int) int64 {
	rec := t.val(cCurators, addr.String())
	if rec == "" {
		return 0
	}
	return stationOf(rec[cLen:], stationID)[4]
}

// weekOf numbers weeks from Monday 00:00 UTC.
func weekOf(ts int64) int64 { return (ts + 3*24*3600) / week }

// ---- weekly tops: radio/tops P(station+1), 0 all stations ----

// A top is the week (4 digits), the number of entries n (1) and their
// scores, best first (4 each), then their addresses, each after its length
// (1).

type rank struct {
	key   string // address
	score int64  // picks + tips this week
}

// topRec is ranking i: 0 across stations, else station i-1's (in its
// record, which a pick there writes anyway).
func topRec(t *tx, i int) string {
	if i == 0 {
		return t.val(cTops, "all")
	}
	return t.station(i - 1).top
}

// top reads ranking i of week wk (nil when another week's).
func top(t *tx, i int, wk int64) []rank {
	rec := topRec(t, i)
	if rec == "" || store.Num(rec, 0, 4) != wk {
		return nil
	}
	n := int(dec[rec[4]])
	out := make([]rank, 0, n)
	for j, at := 0, 5+4*n; j < n; j++ {
		l := int(dec[rec[at]])
		out = append(out, rank{rec[at+1 : at+1+l], store.Num(rec, 5+4*j, 4)})
		at += 1 + l
	}
	return out
}

// setTop raises k's score in a ranking, emptied when a new week starts.
// Scores only grow, so a score below the last of a full top leaves it
// untouched (and unsaved): k cannot be in it. That is read without
// decoding the list.
func setTop(t *tx, i int, wk int64, k string, v int64) {
	if i == 0 {
		if int64(t.flowAt(fTopWeek, 4)) == wk && int64(t.flowAt(fTopLast, 4)) > v {
			return
		}
	} else if rec := topRec(t, i); rec != "" && store.Num(rec, 0, 4) == wk && int(dec[rec[4]]) == topCurators && v < store.Num(rec, 1+4*topCurators, 4) {
		return
	}
	list := top(t, i, wk)
	out := make([]rank, 0, topCurators+1)
	for _, r := range list {
		if r.key != k {
			out = append(out, r)
		}
	}
	j := len(out)
	for j > 0 && out[j-1].score < v {
		j--
	}
	if j >= topCurators {
		return
	}
	out = append(out, rank{})
	copy(out[j+1:], out[j:])
	out[j] = rank{k, v}
	if len(out) > topCurators {
		out = out[:topCurators]
	}
	b := store.AppendFixed(store.AppendFixed(make([]byte, 0, topMax), wk, 4), int64(len(out)), 1)
	for _, r := range out {
		b = store.AppendFixed(b, r.score, 4)
	}
	for _, r := range out {
		b = append(store.AppendFixed(b, int64(len(r.key)), 1), r.key...)
	}
	if i == 0 {
		t.set(cTops, "all", string(b))
		last := int64(0)
		if len(out) == topCurators {
			last = out[topCurators-1].score
		}
		t.setFlowAt(fTopWeek, 4, int(wk))
		t.setFlowAt(fTopLast, 4, int(last))
		return
	}
	st := t.station(i - 1)
	st.top, st.dirty = string(b), true
}

// CuratorOf returns a listener's curator record, all time.
func CuratorOf(addr address) Curator {
	c, _ := curRec(rd(), addr.String())
	return Curator{Address: addr, Picks: int(c[0]), Tips: int(c[1]), Earned: c[2], Promo: c[3]}
}

// TopCurators returns this week's top curators of a station (allStations:
// every station), best first, with their counts for the week. Picks and tips
// received on air score one point each.
func TopCurators(stationID int) []Curator {
	return weekTop(rd(), stationID)
}

func weekTop(t *tx, stationID int) []Curator {
	if stationID != allStations {
		mustStation(stationID)
	}
	list := top(t, stationID+1, weekOf(now()))
	out := make([]Curator, 0, len(list))
	for _, r := range list {
		c, sts := curRec(t, r.key)
		n := c[cWeek:]
		if stationID != allStations {
			n = stationOf(sts, stationID)
		}
		out = append(out, Curator{Address: address(r.key), Picks: int(n[1]), Tips: int(n[2]), Earned: n[3]})
	}
	return out
}

// CuratorJSON returns a listener's curator record: all time, this week, and
// their place in this week's top across stations (0 when outside the top 10).
func CuratorJSON(addr address) string {
	t := rd()
	r, _ := curRec(t, addr.String())
	w := r[cWeek:]
	if w[0] != weekOf(now()) {
		w = []int64{0, 0, 0, 0}
	}
	place := 0
	for i, c := range weekTop(t, allStations) {
		if c.Address == addr {
			place = i + 1
		}
	}
	return `{"address":` + text.Str(addr.String()) + `,"picks":` + text.Itoa64(r[0]) + `,"tips":` + text.Itoa64(r[1]) + `,"earned":` + text.Itoa64(r[2]) + `,"promo":` + text.Itoa64(r[3]) +
		`,"week":{"picks":` + text.Itoa64(w[1]) + `,"tips":` + text.Itoa64(w[2]) + `,"earned":` + text.Itoa64(w[3]) + `,"rank":` + text.Itoa(place) + `}}`
}

// TopCuratorsJSON returns TopCurators as JSON with the week's start (unix).
func TopCuratorsJSON(stationID int) string {
	var b strings.Builder
	b.WriteString(`{"station":` + text.Itoa(stationID) + `,"since":` + text.Itoa64(weekOf(now())*week-3*24*3600) + `,"top":[`)
	for i, c := range TopCurators(stationID) {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(`{"address":` + text.Str(c.Address.String()) + `,"picks":` + text.Itoa(c.Picks) + `,"tips":` + text.Itoa(c.Tips) + `,"earned":` + text.Itoa64(c.Earned) + `}`)
	}
	b.WriteString(`]}`)
	return b.String()
}

package radio

import (
	"strings"

	"gno.land/p/nym-alexiscolin000/gnoradio/blocks/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
)

// The radio's collections in the data realm (docs/ARCHITECTURE-v1.md,
// section 3). P(n) is store.Pad, T(t) a 12-digit unix time. Numbers inside
// the hot records are fixed-width base-64 digits (store.Num, store.Fixed): a decimal
// conversion costs the VM several times more.
const (
	cStations = "radio/stations" // P(station) -> Rec(epoch, ring, live, rotation header, schedule, recent picks, weekly top[, ring rotation, ring index])
	cRot      = "radio/rot"      // P(station)/b/P(block) -> block; P(station)/g/P(group) -> block sums (p/blocks)
	cHomes    = "radio/homes"    // P((id-1)/homesChunk) -> Rec of homes entries (the genre stations of a track), one per synced track
	cMeta     = "radio/meta"     // "flow" -> flow record
	cCurators = "radio/curators" // address -> curator record (curators.gno)
	cTops     = "radio/tops"     // "all" -> this week's top curators across stations (a station's is in its record)
	cDropped  = "radio/dropped"  // P(station)/P(track) -> "1"
	cNotes    = "radio/notes"    // P(station)/T(start) -> reporters, or the strike a hide gave (notes.gno)
	cMuted    = "radio/muted"    // address -> unix time its dedications are refused until
	cStrikes  = "radio/strikes"  // address -> unix time one of its dedications was last hidden
	cSponsor  = "radio/sponsor"  // address/P(station) -> open sponsored pick (sponsor.gno)
	cActivity = "radio/activity" // P(0..63) -> activity record (a ring, its head in the flow record)
	cConfig   = "radio/config"   // "admin" (mirror of the admin role), "modbot" (hex key)
)

var collections = []string{cStations, cRot, cHomes, cMeta, cCurators, cTops, cDropped, cNotes,
	cMuted, cStrikes, cSponsor, cActivity, cConfig}

const (
	homesChunk = 16       // homes entries per key
	maxRecord  = 16 << 10 // the data realm's longest value
)

// setup makes the radio's collections and its first records, once: a later
// release finds them made (it is not the writer in its init).
func setup(cur realm, holder address) {
	for _, c := range collections {
		data.Make(cross(cur), c)
	}
	if data.Has(cMeta, "flow") {
		return
	}
	ops := store.Ops{}.Set(cMeta, "flow", strings.Repeat("0", flowLen)).Set(cConfig, "admin", holder.String())
	data.Batch(cross(cur), ops)
}

// Fixed-width base-64 numbers are store.Num, store.Fixed and
// store.AppendFixed. dec is store.Digits' decoding table, for the digits
// the hot loops read in place: a call per digit costs about 1% of a pick.
var dec = decTable()

func decTable() (d [128]int64) {
	for i := 0; i < len(store.Digits); i++ {
		d[store.Digits[i]] = int64(i)
	}
	return d
}

// ---- tx: every key read once and written once ----

// tx reads each key from the data realm once and writes every key it
// changed once, in one call (data.Set or data.Batch); the stations it
// loaded are decoded once and encoded back when changed. Every entrypoint
// loads what it needs, changes it in its tx, then saves; readers use one
// too. A tx is never stored.
type tx struct {
	es  []entry
	idx map[string]int // entry key -> position in es
	sts [numStations]*station
	flw string // the flow record, once read (flowRec)
}

type entry struct {
	c, k  string // collection and key
	val   string
	ok    bool // the key exists
	dirty bool
}

func rd() *tx { return &tx{idx: map[string]int{}} }

// at finds a key's entry, reading it from data the first time unless blind
// (a key about to be overwritten).
func (t *tx) at(c, k string, blind bool) *entry {
	key := c + " " + k
	if i, ok := t.idx[key]; ok {
		return &t.es[i]
	}
	e := entry{c: c, k: k}
	if !blind {
		e.val, e.ok = data.Get(c, k)
	}
	t.idx[key] = len(t.es)
	t.es = append(t.es, e)
	return &t.es[len(t.es)-1]
}

func (t *tx) get(c, k string) (string, bool) {
	e := t.at(c, k, false)
	return e.val, e.ok
}

func (t *tx) val(c, k string) string { return t.at(c, k, false).val }

func (t *tx) has(c, k string) bool { return t.at(c, k, false).ok }

func (t *tx) set(c, k, v string) {
	e := t.at(c, k, false)
	e.val, e.ok, e.dirty = v, true, true
}

// put writes a key without reading it first.
func (t *tx) put(c, k, v string) {
	e := t.at(c, k, true)
	e.val, e.ok, e.dirty = v, true, true
}

func (t *tx) del(c, k string) bool {
	e := t.at(c, k, false)
	if !e.ok {
		return false
	}
	e.val, e.ok, e.dirty = "", false, true
	return true
}

// save writes what t changed: one data.Set or data.Remove, or Batches of
// 64 ops (a Sync or a RefreshArtist may change more keys than one Batch
// takes; the transaction keeps them atomic).
func save(cur realm, t *tx) {
	for _, st := range t.sts {
		if st != nil && st.dirty {
			sched := st.raw
			if st.decoded {
				sched = encodeSchedule(st.sched)
			}
			f := []string{store.Fixed(st.epoch, 6), store.Fixed(int64(st.ring), 6), store.Fixed(int64(st.live), 4), st.h, sched, st.picks, st.top}
			if st.ringed() {
				f = append(f, st.rot, st.idx)
			}
			// A pick is refused once its station's record would leave less
			// than recordHeadroom, and the writes a pick or a Sync makes on
			// other stations wait while theirs does (full): this is a last
			// resort.
			rec := store.Rec(f...)
			if len(rec) > maxRecord {
				panic("radio: this station is full for now, try again later")
			}
			t.set(cStations, store.Pad(st.id), rec)
			st.dirty = false
		}
	}
	var ops store.Ops
	for _, e := range t.es {
		if !e.dirty {
			continue
		}
		if e.ok {
			ops = ops.Set(e.c, e.k, e.val)
		} else {
			ops = ops.Del(e.c, e.k)
		}
	}
	for len(ops) > 4*64 {
		data.Batch(cross(cur), ops[:4*64])
		ops = ops[4*64:]
	}
	switch {
	case len(ops) == 0:
	case len(ops) > 4:
		data.Batch(cross(cur), ops)
	case ops[0] == store.OpSet:
		data.Set(cross(cur), ops[1], ops[2], ops[3])
	default:
		data.Remove(cross(cur), ops[1], ops[2])
	}
}

// ---- the flow record: radio/meta "flow" ----

// The flow record is fixed-width: synced (4 digits), the number of dropped
// slots (4), the activity ring's next slot (1), the week of the top across
// stations and its last score when it holds topCurators (0 else) (4 and
// 4: a pick that scores less leaves it as it is, unread), then "1" for each
// genre station with a live track ("0" else, index = genre): Main relays
// one of those (hourGenre). Every call reads it.
const (
	fSynced  = 0
	fDrops   = 4
	fHead    = 8
	fTopWeek = 9
	fTopLast = 13
	fLive    = 17
	flowLen  = fLive + NumGenres + 1
)

// flowRec is the flow record, read once per tx: every call reads it. The data
// realm is permanent: a record an earlier release wrote shorter is padded
// with "0" (a later one's extra fields are kept as they are).
func (t *tx) flowRec() string {
	if t.flw == "" {
		t.flw = t.val(cMeta, "flow")
		if len(t.flw) < flowLen {
			t.flw += strings.Repeat("0", flowLen-len(t.flw))
		}
	}
	return t.flw
}

func (t *tx) flowAt(at, w int) int { return int(store.Num(t.flowRec(), at, w)) }

func (t *tx) setFlowAt(at, w, v int) {
	f := t.flowRec()
	if n := store.Fixed(int64(v), w); n != f[at:at+w] {
		t.flw = f[:at] + n + f[at+w:]
		t.set(cMeta, "flow", t.flw)
	}
}

func (t *tx) synced() int { return t.flowAt(fSynced, 4) }

// hasLive reports whether a genre station has a live track.
func (t *tx) hasLive(genre int) bool {
	return genre >= 1 && genre <= NumGenres && t.flowRec()[fLive+genre] == '1'
}

// dropped reports whether the admin dropped a track from a station.
func (t *tx) dropped(stationID, trackID int) bool {
	return t.flowAt(fDrops, 4) > 0 && t.has(cDropped, dropKey(stationID, trackID))
}

func dropKey(stationID, trackID int) string { return store.Pad(stationID) + "/" + store.Pad(trackID) }

// ---- stations ----

// station is a station loaded in a tx: its header and schedule are one
// record (cStations); its rotation is read and written a block at a time
// (cRot), but for New and Choice: their rings (at most 500 slots) and the
// index of the tracks in them are part of their record, which a pick
// changes anyway.
// The schedule is decoded on first use (slots): a call that only needs the
// time paused under it (paused) or a picker (picker) reads it as it is.
type station struct {
	t       *tx
	id      int
	genre   int // 0 = every genre
	epoch   int64
	ring    int    // New and Choice: joins so far; the slot reused next is ring % keep
	live    int    // rotation slots with a duration > 0
	h       string // the rotation's header (p/blocks)
	raw     string // the encoded schedule
	picks   string // the picks of the last replayGap (lastPicked)
	top     string // this week's top curators here (curators.gno)
	rot     string // New and Choice: the group then the blocks of their ring
	idx     string // and the ring's tracks: sorted entries, the track (4 digits) and its slot (2)
	sched   []Slot // sorted by Start, short (folded as it ages), once decoded
	decoded bool
	dirty   bool
	pz      int64 // paused(pzAt), while pzOK: the schedule did not move since
	pzAt    int64
	pzOK    bool
}

// station loads a station once per tx.
func (t *tx) station(id int) *station {
	if id < 0 || id >= numStations {
		panic("radio: unknown station")
	}
	if st := t.sts[id]; st != nil {
		return st
	}
	st := &station{t: t, id: id, genre: id}
	if id > NumGenres {
		st.genre = 0
	}
	if rec := t.val(cStations, store.Pad(id)); rec != "" {
		f := store.Fields(rec)
		st.epoch, st.ring, st.live, st.h, st.raw, st.picks, st.top = store.Num(f[0], 0, 6), int(store.Num(f[1], 0, 6)), int(store.Num(f[2], 0, 4)), f[3], f[4], f[5], f[6]
		if len(f) > 7 {
			st.rot, st.idx = f[7], f[8]
		}
	}
	t.sts[id] = st
	return st
}

// size is the length of the record save writes for the station, its
// schedule measured as encodeSchedule writes it, without writing it.
func (st *station) size() int {
	n := 1 + 3*7 + 6 + 6 + 4 + len(st.h) + len(st.picks) + len(st.top)
	if st.ringed() {
		n += 3*2 + len(st.rot) + len(st.idx)
	}
	if !st.decoded {
		return n + len(st.raw)
	}
	var prevEnd int64
	for i := range st.sched {
		s := &st.sched[i]
		switch gap := s.Start - prevEnd; {
		case gap == 0:
			n++
		case gap < 0:
			n += 7
		default:
			n += 2
			for gap>>6 != 0 {
				gap >>= 6
				n++
			}
		}
		n += 25 + len(s.By) + len(s.Note)
		prevEnd = s.Start + s.Dur
	}
	return n
}

// full reports whether the record keeps less than recordHeadroom: a new pick
// is refused, and a write a pick makes on the side (a Choice or New join)
// waits. A side write adds far less than recordHeadroom, so
// the record never reaches the data realm's limit (maxRecord).
func (st *station) full() bool { return st.size() > maxRecord-recordHeadroom }

// slots is the decoded schedule.
func (st *station) slots() []Slot {
	if !st.decoded {
		st.sched, st.decoded = decodeSchedule(st.raw), true
	}
	return st.sched
}

// setSlots replaces the schedule.
func (st *station) setSlots(s []Slot) {
	st.sched, st.decoded, st.dirty, st.pzOK = s, true, true, false
}

// addLive counts a slot going live (d = 1) or silent (-1); the flow record
// keeps which genre stations have one.
func (st *station) addLive(d int) {
	st.live += d
	st.dirty = true
	if st.id >= 1 && st.id <= NumGenres && (st.live > 0) != st.t.hasLive(st.id) {
		on := 0
		if st.live > 0 {
			on = 1
		}
		st.t.setFlowAt(fLive+st.id, 1, on)
	}
}

// ---- a station's rotation: p/blocks over its keys ----

func (st *station) ringed() bool { return st.id == NewStation || st.id == ChoiceStation }

// A ring's rotation (one group) is its group's sums, 4 digits per block,
// then its blocks, blocks.Size slots each but the last.
const blockLen = blocks.Size * 6

// ringBlocks is where a ring's blocks start.
func (st *station) ringBlocks() int { return 4 * ((st.count() + blocks.Size - 1) / blocks.Size) }

// group and block read group g and block b of the rotation.
func (st *station) group(g int) string {
	if st.ringed() {
		return st.rot[:st.ringBlocks()]
	}
	return st.t.val(cRot, store.Pad(st.id)+"/g/"+store.Pad(g))
}

func (st *station) block(b int) string {
	if !st.ringed() {
		return st.t.val(cRot, store.Pad(st.id)+"/b/"+store.Pad(b))
	}
	at := st.ringBlocks() + b*blockLen
	if at >= len(st.rot) {
		return ""
	}
	if at+blockLen < len(st.rot) {
		return st.rot[at : at+blockLen]
	}
	return st.rot[at:]
}

// setRotVal writes group g and block b; st.h is still the rotation's
// header before the change.
func (st *station) setRotVal(g int, grp string, b int, blk string) {
	if !st.ringed() {
		st.t.set(cRot, store.Pad(st.id)+"/g/"+store.Pad(g), grp)
		st.t.set(cRot, store.Pad(st.id)+"/b/"+store.Pad(b), blk)
		return
	}
	bs := st.rot[st.ringBlocks():]
	at, end := b*blockLen, b*blockLen+blockLen
	if at > len(bs) {
		at = len(bs)
	}
	if end > len(bs) {
		end = len(bs)
	}
	st.rot, st.dirty = grp+bs[:at]+blk+bs[end:], true
}

func (st *station) total() int64 { return blocks.Total(st.h) }
func (st *station) count() int   { return blocks.Len(st.h) }

func (st *station) rotSlot(i int) (int, int64) {
	if i < 0 || i >= st.count() {
		panic("radio: rotation index out of range")
	}
	_, b := blocks.Where(i)
	return blocks.Slot(st.block(b), i)
}

// find returns the rotation slot playing at position pos of the loop.
func (st *station) find(pos int64) (slot, id int, offset int64, ok bool) {
	g, rest, ok := blocks.FindGroup(st.h, pos)
	if !ok {
		return 0, 0, 0, false
	}
	b, rest := blocks.FindBlock(st.group(g), g, rest)
	slot, id, offset = blocks.FindSlot(st.block(b), b, rest)
	return slot, id, offset, true
}

func (st *station) prefixBefore(i int) int64 {
	g, b := blocks.Where(i)
	return blocks.PrefixBefore(st.h, st.group(g), st.block(b), i)
}

// appendRot adds a slot at the end of the rotation and returns its index.
func (st *station) appendRot(id int, dur int64) int {
	g, b := blocks.Where(st.count())
	h, grp, blk, i := blocks.Append(st.h, st.group(g), st.block(b), id, dur)
	st.setRotVal(g, grp, b, blk)
	st.h, st.dirty = h, true
	return i
}

// setRot replaces slot i's id and duration.
func (st *station) setRot(i, id int, dur int64) {
	g, b := blocks.Where(i)
	h, grp, blk := blocks.Set(st.h, st.group(g), st.block(b), i, id, dur)
	st.setRotVal(g, grp, b, blk)
	st.h, st.dirty = h, true
}

// ---- schedules ----

// A schedule is its slots in order, each a record that starts with the gap
// since the previous slot's end (one digit "0" when it follows it, else the
// number of digits and the gap, "z" and the start if it overlaps), then its
// body: "L" (listener), the duration (2 digits), the track (4), the artist
// (4), the time booked (6), the refund (4), "1" when its note is hidden, and
// its address and note, each after its length (1 and 2 digits). A body is reused as long as its slot keeps
// its duration and note, so moving slots together costs no encoding.

func decodeSchedule(s string) []Slot {
	out := make([]Slot, 0, len(s)/8+1)
	for c := (cursor{s: s}); c.next(); {
		b := s[c.b:c.i]
		x := Slot{Track: int(dec[b[3]]<<18 | dec[b[4]]<<12 | dec[b[5]]<<6 | dec[b[6]]), Start: c.start, Dur: c.end - c.start, body: b, bdur: c.end - c.start}
		bl := int(dec[b[22]])
		x.artist, x.At, x.Pay, x.NoteHidden = int(store.Num(b, 7, 4)), store.Num(b, 11, 6), store.Num(b, 17, 4), b[21] == '1'
		x.By, x.Note = address(b[23:23+bl]), b[25+bl:]
		out = append(out, x)
	}
	return out
}

func encodeSchedule(ss []Slot) string {
	b := make([]byte, 0, 8*len(ss)+64)
	var prevEnd int64
	for i := range ss {
		s := &ss[i]
		switch {
		case s.body == "":
			s.body = s.encodeBody()
		case s.bdur != s.Dur:
			s.body = s.body[:1] + string(store.AppendFixed(make([]byte, 0, 2), s.Dur, 2)) + s.body[3:]
		}
		s.bdur = s.Dur
		switch gap := s.Start - prevEnd; {
		case gap == 0:
			b = append(b, '0')
		case gap < 0:
			b = store.AppendFixed(append(b, 'z'), s.Start, 6)
		default:
			n := 1
			for gap>>(6*n) != 0 {
				n++
			}
			b = store.AppendFixed(append(b, store.Digits[n]), gap, n)
		}
		b = append(b, s.body...)
		prevEnd = s.Start + s.Dur
	}
	return string(b)
}

func (s *Slot) encodeBody() string {
	b := make([]byte, 0, 32+len(s.By)+len(s.Note))
	b = store.AppendFixed(store.AppendFixed(store.AppendFixed(append(b, 'L'), s.Dur, 2), int64(s.Track), 4), int64(s.artist), 4)
	b = store.AppendFixed(store.AppendFixed(b, s.At, 6), s.Pay, 4)
	if s.NoteHidden {
		b = append(b, '1')
	} else {
		b = append(b, '0')
	}
	b = append(store.AppendFixed(b, int64(len(s.By)), 1), s.By...)
	return string(append(store.AppendFixed(b, int64(len(s.Note)), 2), s.Note...))
}

// cursor walks an encoded schedule a slot at a time without decoding it:
// after next, the slot's body is s[b:i] and it plays from start to end.
type cursor struct {
	s          string
	i, b       int
	start, end int64
}

func (c *cursor) next() bool {
	s, i := c.s, c.i
	if i >= len(s) {
		return false
	}
	start := c.end
	switch ch := s[i]; ch {
	case '0':
		i++
	case 'z':
		start, i = store.Num(s, i+1, 6), i+7
	default:
		n := int(dec[s[i]])
		start, i = c.end+store.Num(s, i+1, n), i+1+n
	}
	c.b, c.start, c.end = i, start, start+(dec[s[i+1]]<<6|dec[s[i+2]])
	k := i + 23 + int(dec[s[i+22]])
	c.i = k + 2 + int(dec[s[k]]<<6|dec[s[k+1]])
	return true
}

// ---- where a track rotates: Main at id-1, New and Choice in their ring
// index, genre stations in homes ----

const idxW = 6 // a ring index entry

// ringFind returns the position of a track in the ring index, or where it goes.
func (st *station) ringFind(trackID int) (int, bool) {
	lo, hi := 0, len(st.idx)/idxW
	for lo < hi {
		mid := (lo + hi) / 2
		if int(store.Num(st.idx, idxW*mid, 4)) < trackID {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return lo, lo < len(st.idx)/idxW && int(store.Num(st.idx, idxW*lo, 4)) == trackID
}

// ringSlot is a track's slot in the ring.
func (st *station) ringSlot(trackID int) (int, bool) {
	p, ok := st.ringFind(trackID)
	if !ok {
		return 0, false
	}
	return int(store.Num(st.idx, idxW*p+4, 2)), true
}

// ringIndex files a track at a slot of the ring, at position p of the
// index (ringFind), replacing the entry there when found.
func (st *station) ringIndex(p int, found bool, trackID, slot int) {
	end := idxW * p
	if found {
		end += idxW
	}
	st.idx, st.dirty = st.idx[:idxW*p]+store.Fixed(int64(trackID), 4)+store.Fixed(int64(slot), 2)+st.idx[end:], true
}

// ringUnindex forgets a track that left the ring's slot and returns where
// it was in the index (-1: it was not there).
func (st *station) ringUnindex(trackID, slot int) int {
	if p, ok := st.ringFind(trackID); ok && int(store.Num(st.idx, idxW*p+4, 2)) == slot {
		st.idx, st.dirty = st.idx[:idxW*p]+st.idx[idxW*p+idxW:], true
		return p
	}
	return -1
}

// A homes entry is 5 digits per genre station: the station (1) and the slot (4).

func homesKey(trackID int) (string, int) {
	return store.Pad((trackID - 1) / homesChunk), (trackID - 1) % homesChunk
}

// homes returns a synced track's entry.
func (t *tx) homes(trackID int) string {
	k, i := homesKey(trackID)
	if ch := t.val(cHomes, k); ch != "" {
		return store.Field(ch, i)
	}
	return ""
}

func (t *tx) setHomes(trackID int, e string) {
	k, i := homesKey(trackID)
	t.set(cHomes, k, store.With(t.val(cHomes, k), i, e))
}

// appendHomes files the entry of the next synced track.
func (t *tx) appendHomes(trackID int, e string) {
	k, i := homesKey(trackID)
	if i == 0 {
		t.put(cHomes, k, store.Rec(e))
		return
	}
	t.set(cHomes, k, store.Append(t.val(cHomes, k), e))
}

func homeEntry(stationID, slot int) string {
	return store.Fixed(int64(stationID), 1) + store.Fixed(int64(slot), 4)
}

// homeSlot finds a station's slot in an entry.
func homeSlot(e string, stationID int) (int, bool) {
	for i := 0; i+5 <= len(e); i += 5 {
		if int(dec[e[i]]) == stationID {
			return int(store.Num(e, i+1, 4)), true
		}
	}
	return 0, false
}

package radio

// Main's flow is a pure function of the clock and the stations: between
// listeners' picks, each UTC hour Main simulcasts one genre station, playing
// what it plays (its own picks included) until the next hour. The hour's genre follows an energy line around the
// target of the time of day (UTC dayparts: calm at night, peak in the
// evening): one step below the target in a 3-hour block's first hour, the
// target in its second, one step above in its third, or the nearest genre
// with a live track. Reads compute it and nothing is written, so it never
// runs dry and costs GnoRadio nothing: no Sync, robot or keeper.

// energy orders every genre from calm to intense; Main falls back on it.
var energy = [NumGenres]int{
	3,  // Ambient
	16, // Cinematic & Classical
	15, // Folk & Acoustic
	14, // Jazz & Blues
	8,  // Lo-fi Beats
	10, // R&B & Soul
	19, // Reggae & Dub
	17, // World
	18, // Latin
	20, // Funk & Disco
	13, // Pop
	9,  // Hip-hop & Rap
	11, // Rock & Indie
	2,  // Synthwave
	1,  // Electronica
	5,  // House
	4,  // Techno
	7,  // Dubstep & Trap
	6,  // Drum & Bass
	12, // Metal & Punk
}

// mainFlow is what Main relays by default, from calm to intense: the
// mainstream genres. The niche ones (Ambient, Cinematic, Synthwave, Techno,
// Dubstep, Drum & Bass, Metal, World) keep their own stations; Main reaches
// for them only when none of these has a live track.
var mainFlow = []int{
	8,  // Lo-fi Beats
	14, // Jazz & Blues
	15, // Folk & Acoustic
	10, // R&B & Soul
	19, // Reggae & Dub
	13, // Pop
	18, // Latin
	11, // Rock & Indie
	9,  // Hip-hop & Rap
	20, // Funk & Disco
	1,  // Electronica
	5,  // House
}

// dayparts is the target index in mainFlow for each 3-hour block of the UTC
// day: Jazz, Lo-fi, Folk, R&B, Pop, Rock, Funk & Disco, then House late at night.
var dayparts = [8]int{1, 0, 2, 3, 5, 7, 9, 11}

// hourGenre is the genre Main relays at ts: the daypart's target, one step
// below it in the block's first hour, above it in the last, or the nearest
// mainstream genre with a live track, else any genre with one (0: none).
func hourGenre(t *tx, ts int64) int {
	h := ts / 3600
	if g := nearestLive(t, mainFlow, dayparts[h%24/3]+int(h%3)-1); g > 0 {
		return g
	}
	return nearestLive(t, energy[:], 0)
}

// nearestLive is the genre of order nearest to index i with a live track, the
// calmer one first on a tie (0: none).
func nearestLive(t *tx, order []int, i int) int {
	if i < 0 {
		i = 0
	} else if i >= len(order) {
		i = len(order) - 1
	}
	for k := 0; k < 2*len(order); k++ {
		if j := i + (k+1)/2*(1-2*(k%2)); j >= 0 && j < len(order) && t.hasLive(order[j]) {
			return order[j]
		}
	}
	return 0
}

// HourGenre is the genre Main relays at unix time at (0: none), for pages
// that explain it.
func HourGenre(at int64) int { return hourGenre(rd(), at) }

package radio

import (
	"strconv"
	"strings"

	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	"gno.land/r/nym-alexiscolin000/gnoradio/catalog/v2"
)

// Read API for the GnoRadio app (vm/qeval).

// ScheduleJSON returns what a station plays from now until now+horizon seconds
// (60..7200, at most 60 entries): programmed slots and the rotation between
// them (on Main, the hour's genre station, simulcast and cut at each hour). A client plays entry i from offset+max(0, clock-start) and resyncs on
// "now". "relay" marks, on Main, an entry that is not Main's own slot but
// the hour's genre station simulcast (its picks included). "sponsored" is the refund its artist pays the picker (0: a normal
// pick), "at" the time a booked pick asked for (0: none). "booked" lists every
// booked pick still to air, whatever the horizon, and those that aired in the
// last hour (they count toward their clock hour's cap until they fold):
// {"track","start","end","at","by","note"}. Fetch it again every few minutes, not
// every second.
func ScheduleJSON(stationID, horizon int) string {
	st := rd().station(stationID)
	if horizon < 60 || horizon > 7200 {
		horizon = 3600
	}
	ts := now()
	end := ts + int64(horizon)
	var b strings.Builder
	b.WriteString(`{"station":` + text.Itoa(st.id) + `,"now":` + text.Itoa64(ts) + `,"entries":[`)
	n := 0
	emit := func(track int, title string, start, stop, offset int64, queued bool, by, note string, pay, at int64, relay bool) {
		if n > 0 {
			b.WriteString(",")
		}
		b.WriteString(`{"track":` + text.Itoa(track) + `,"title":` + text.Str(title) +
			`,"start":` + text.Itoa64(start) + `,"end":` + text.Itoa64(stop) + `,"offset":` + text.Itoa64(offset) +
			`,"queued":` + strconv.FormatBool(queued) + `,"by":` + text.Str(by) + `,"note":` + text.Str(note) + `,"sponsored":` + text.Itoa64(pay) + `,"at":` + text.Itoa64(at) + `,"relay":` + strconv.FormatBool(relay) + `}`)
		n++
	}
	cur := ts
	for cur < end && n < 60 {
		var slot *Slot
		next := int64(-1)
		sl := st.slots()
		for i := range sl {
			s := &sl[i]
			if cur >= s.Start && cur < s.Start+s.Dur {
				slot = s
				break
			}
			if s.Start > cur && (next < 0 || s.Start < next) {
				next = s.Start
			}
		}
		if slot != nil {
			stop := slot.Start + slot.Dur
			if title := catalog.PlayableTitle(slot.Track); title != "" {
				emit(slot.Track, title, slot.Start, stop, 0, true, slot.By.String(), slot.shownNote(), slot.Pay, slot.At, false)
			}
			cur = stop
			continue
		}
		track, off, dur, ok := st.between(cur)
		relay := st.id == MainStation // not Main's own slot: the hour's genre station, simulcast
		if !ok {
			if next < 0 {
				break
			}
			cur = next
			continue
		}
		stop := cur + dur - off
		if next >= 0 && next < stop {
			stop = next // the rotation (or Main's relay) pauses for the programmed slot
		}
		if title := catalog.PlayableTitle(track); title != "" {
			if s, ok := st.pickAt(cur); ok && s.Track == track { // Main simulcasting a genre station's pick
				emit(track, title, cur-off, stop, off, true, s.By.String(), s.shownNote(), s.Pay, s.At, relay)
			} else {
				emit(track, title, cur-off, stop, off, false, "", "", 0, 0, relay)
			}
		}
		cur = stop
	}
	b.WriteString(`],"booked":[`)
	n = 0
	for _, s := range st.slots() {
		if s.At > 0 && s.Start+s.Dur > ts-foldAfter {
			if n > 0 {
				b.WriteString(",")
			}
			b.WriteString(`{"track":` + text.Itoa(s.Track) + `,"start":` + text.Itoa64(s.Start) + `,"end":` + text.Itoa64(s.Start+s.Dur) + `,"at":` + text.Itoa64(s.At) + `,"by":` + text.Str(s.By.String()) + `,"note":` + text.Str(s.shownNote()) + `}`)
			n++
		}
	}
	b.WriteString(`]}`)
	return b.String()
}

// StationsJSON lists every station with what it plays now.
func StationsJSON() string {
	t := rd()
	var b strings.Builder
	// newFloor: only tracks above this id may be picked on New this week.
	synced := t.synced()
	floor := synced - newCap
	if floor < 0 {
		floor = 0
	}
	ts := now()
	b.WriteString(`{"pending":` + text.Itoa(catalog.TrackCount()-synced) + `,"newFloor":` + text.Itoa(floor) + `,"stations":[`)
	for id := 0; id < numStations; id++ {
		st := t.station(id)
		if id > 0 {
			b.WriteString(",")
		}
		track, offset, isQueued := st.onAir(ts)
		live, loop := st.rotating()
		b.WriteString(`{"id":` + text.Itoa(id) + `,"name":` + text.Str(StationName(id)) + `,"genre":` + text.Itoa(st.genre) +
			`,"tracks":` + text.Itoa(live) + `,"loop":` + text.Itoa64(loop) + `,"queued":` + text.Itoa(st.queued(ts)) +
			`,"now":{"track":` + text.Itoa(track) + `,"offset":` + text.Itoa64(offset) + `,"queued":` + strconv.FormatBool(isQueued) + `}}`)
	}
	b.WriteString(`]}`)
	return b.String()
}

package radio

import (
	"chain"
	"encoding/hex"
	"strconv"
	"strings"

	"gno.land/p/nym-alexiscolin000/gnoradio/role/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
)

// Dedications: reports, strikes and mutes. A dedication's reports are
// radio/notes P(station)/T(start) -> the reporters' addresses, each followed
// by ","; once hidden, struckMark, the strike time it gave its author and
// the one before ("" none), so that RestoreNote takes back this strike only.

const struckMark = "struck:"

func noteKey(stationID int, start int64) string {
	return store.Pad(stationID) + "/" + store.TimeKey(start)
}

// ReportNote flags the dedication of the slot starting at start. Only a
// listener with the reputation sponsored picks need (a first pick a week
// old, 3 normal picks this 15-day period and the one before: sponsorBlock) may report, so
// throwaway wallets cannot; the third such listener hides it at once, with
// no moderator involved. A first hidden dedication is a strike; a second
// within muteFor pauses its author's dedications for muteFor (the admin can
// lift it: Unmute).
func ReportNote(cur realm, stationID int, start int64) {
	caller := userCaller(cur)
	noPayment()
	t := rd()
	st, s := noteSlot(t, stationID, start)
	if s.NoteHidden {
		panic("radio: no dedication at this time on this station")
	}
	if s.By == caller {
		panic("radio: you cannot report your own dedication")
	}
	if sponsorBlock(t, caller) != "" {
		panic("radio: reporting needs a first pick 7 days old and 3 normal picks in the last two 15-day periods")
	}
	key := noteKey(st.id, start)
	by := t.val(cNotes, key)
	if strings.Contains(by, caller.String()) {
		panic("radio: you already reported this dedication")
	}
	by += caller.String() + ","
	if strings.Count(by, ",") < hideAfter {
		t.set(cNotes, key, by)
		save(cur, t)
		chain.Emit("NoteReported", "station", text.Itoa(st.id), "start", text.Itoa64(start), "by", caller.String())
		return
	}
	s.NoteHidden, s.body, st.dirty = true, "", true
	ts, author := now(), s.By.String()
	last, struck := t.get(cStrikes, author)
	mute := struck && ts-text.MustAtoi64(last) < muteFor
	if mute {
		t.set(cMuted, author, text.Itoa64(ts+muteFor))
	}
	t.set(cStrikes, author, text.Itoa64(ts))
	t.set(cNotes, key, struckMark+text.Itoa64(ts)+":"+last)
	save(cur, t)
	chain.Emit("NoteHidden", "station", text.Itoa(st.id), "start", text.Itoa64(start), "author", author, "muted", strconv.FormatBool(mute))
}

// RestoreNote shows again a dedication hidden by reports by mistake and
// clears its author's strike (Unmute lifts a pause). Radio admin only.
func RestoreNote(cur realm, stationID int, start int64) {
	onlyAdmin(cur)
	t := rd()
	st, s := noteSlot(t, stationID, start)
	if !s.NoteHidden {
		panic("radio: this dedication is not hidden") // its pending reports stay
	}
	s.NoteHidden, s.body, st.dirty = false, "", true
	key := noteKey(st.id, start)
	// A wrong hide is no strike: take back the one it gave, if it is still
	// the author's last, and keep any earlier one.
	if rec := t.val(cNotes, key); strings.HasPrefix(rec, struckMark) {
		gave, before, _ := strings.Cut(rec[len(struckMark):], ":")
		author := s.By.String()
		if t.val(cStrikes, author) == gave {
			if before == "" {
				t.del(cStrikes, author)
			} else {
				t.set(cStrikes, author, before)
			}
		}
	}
	t.del(cNotes, key)
	save(cur, t)
	chain.Emit("NoteRestored", "station", text.Itoa(st.id), "start", text.Itoa64(start))
}

// SetModBot names the moderation robot by its Ed25519 public key in hex
// ("" turns dedications off). Radio admin only.
func SetModBot(cur realm, pubKeyHex string) {
	onlyAdmin(cur)
	key, err := hex.DecodeString(pubKeyHex)
	if err != nil || (len(key) != 0 && len(key) != 32) {
		panic("radio: the robot key is a 32-byte Ed25519 public key in hex")
	}
	t := rd()
	t.set(cConfig, "modbot", hex.EncodeToString(key))
	save(cur, t)
	chain.Emit("ModBotSet", "key", pubKeyHex)
}

// MutedUntil returns the unix time until which who's dedications are paused
// after reports, 0 when they are not: the moderation robot refuses to sign
// for a muted author.
func MutedUntil(who address) int64 {
	if v := rd().val(cMuted, who.String()); v != "" {
		if until := text.MustAtoi64(v); now() < until {
			return until
		}
	}
	return 0
}

// Unmute lets a muted listener dedicate again before the week ends, e.g.
// after reports by throwaway wallets. Radio admin only.
func Unmute(cur realm, who address) {
	onlyAdmin(cur)
	if !role.Canonical(who) {
		panic("radio: not an address (lower-case g1...)")
	}
	t := rd()
	if !t.del(cMuted, who.String()) {
		panic("radio: this address is not muted")
	}
	save(cur, t)
	chain.Emit("Unmuted", "address", who.String())
}

// noteSlot finds the dedicated slot starting at start. On Main between its
// own picks it is the genre station's slot Main simulcast: the genre of the
// hour the slot began in, or of now when the hour changed under it.
func noteSlot(t *tx, stationID int, start int64) (*station, *Slot) {
	st := t.station(stationID)
	cands := []*station{st}
	if _, own := st.playing(start); !own {
		cands = []*station{st.relay(start), st.relay(now())}
	}
	for _, c := range cands {
		sl := c.slots()
		for i := range sl {
			if s := &sl[i]; s.Start == start && s.Note != "" {
				return c, s
			}
		}
	}
	panic("radio: no dedication at this time on this station")
}

package radio

import (
	"strings"

	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	"gno.land/r/nym-alexiscolin000/gnoradio/catalog/v2"
)

// Tracks enter and change through this realm: the catalog accepts
// PublishFor, ImportFor and EditFor from the radio writer only, so a track
// is in the station rotations from the transaction that publishes it, paid
// by its publisher. Nothing waits for Sync, and no robot pays for it.

// PublishTrack publishes a track by the caller's own artist profile (the
// arguments are catalog.PublishFor's) and puts it on the air in the same
// transaction: the main station, its genre station and New this week.
func PublishTrack(cur realm, title string, genre int, duration, license, cmo, credits, audio, audioSHA, cover, coverSHA, splits, rights string) int {
	caller := userCaller(cur)
	noPayment()
	id := catalog.PublishFor(cross(cur), caller, title, genre, duration, license, cmo, credits, audio, audioSHA, cover, coverSHA, splits, rights)
	onAir(cur, id, true)
	return id
}

// ImportTrack adds a curated or Audius track to an unclaimed artist (the
// arguments are catalog.ImportFor's) and puts it on the air, New this week
// left out: an import is not a new release. The catalog admin only, from its
// wallet or a realm that holds the role (a launch import).
func ImportTrack(cur realm, artistID int, title string, genre int, duration, license, credits, audio, audioSHA, cover, coverSHA, sourceURL, attribution string) int {
	noPayment()
	id := catalog.ImportFor(cross(cur), cur.Previous().Address(), artistID, title, genre, duration, license, credits, audio, audioSHA, cover, coverSHA, sourceURL, attribution)
	onAir(cur, id, false)
	return id
}

// maxImportBatch bounds ImportTracks: each track costs a few M gas once the
// realms are loaded, so a full batch stays far under the block's gas.
const maxImportBatch = 25

// ImportTracks imports up to maxImportBatch tracks in one transaction, so the
// realms load once for the batch instead of once per track. batch holds one
// track per line ("\n"), ImportTrack's 12 arguments separated by tabs ("\t";
// neither can appear in a valid field). All or nothing: a bad track panics the
// whole transaction (a malformed line is named before anything is written). It returns the id of the last track. Admin only, as
// ImportTrack.
func ImportTracks(cur realm, batch string) int {
	noPayment()
	lines := strings.Split(batch, "\n")
	if batch == "" || len(lines) > maxImportBatch {
		panic("radio: a batch holds 1 to " + text.Itoa(maxImportBatch) + " tracks")
	}
	rows := make([][]string, len(lines))
	for i, line := range lines { // the whole batch is read before anything is written
		f := strings.Split(line, "\t")
		if len(f) != 12 || !text.Digits(f[0]) || !text.Digits(f[2]) {
			panic("radio: batch line " + text.Itoa(i+1) + ": 12 tab-separated fields expected, artist and genre in digits")
		}
		rows[i] = f
	}
	by, id, t := cur.Previous().Address(), 0, rd()
	for _, f := range rows {
		id = catalog.ImportFor(cross(cur), by, text.MustAtoi(f[0]), f[1], text.MustAtoi(f[2]), f[3], f[4], f[5], f[6], f[7], f[8], f[9], f[10], f[11])
		airNext(t, id, false)
	}
	save(cur, t)
	return id
}

// EditTrack fixes a track's details (the arguments are catalog.EditFor's).
// A new genre or duration is applied to the stations in the same
// transaction, as Refresh does; other details need nothing on air.
func EditTrack(cur realm, trackID int, title string, genre int, duration, credits, audio, audioSHA, cover, coverSHA string) {
	caller := userCaller(cur)
	noPayment()
	_, oldGenre, oldDur, _ := catalog.TrackBrief(trackID)
	catalog.EditFor(cross(cur), caller, trackID, title, genre, duration, credits, audio, audioSHA, cover, coverSHA)
	if _, g, d, _ := catalog.TrackBrief(trackID); g != oldGenre || d != oldDur {
		t := rd()
		refresh(cur, t, trackID)
		save(cur, t)
	}
}

// onAir ingests the track the catalog just added, with Sync's own code: it
// is the next one (Sync and every add keep the stations level with the
// catalog), so this is one track's work whatever the catalog size.
func onAir(cur realm, id int, isNew bool) {
	t := rd()
	airNext(t, id, isNew)
	save(cur, t)
}

func airNext(t *tx, id int, isNew bool) {
	if n := id - t.synced(); n != 1 {
		panic("radio: the stations are behind the catalog, call Sync first")
	}
	ingest(t, now(), 1, isNew)
}

package radio

import (
	"chain"
	"chain/runtime"
	"crypto/ed25519"
	"encoding/hex"
	"strconv"

	"gno.land/p/nym-alexiscolin000/gnoradio/safe/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	"gno.land/r/nym-alexiscolin000/gnoradio/catalog/v2"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
)

// ---- Programming ----

// Queue programs a track on a station and adds it to Listeners' choice. It
// starts after the last track a listener programmed, or when the song on air
// ends: nothing is cut. On Main it starts at once over the hour's relay (the
// app crossfades), which resumes after it.
// Limits per station: one waiting slot per listener, two per artist, a track
// at most once, 30 upcoming.
func Queue(cur realm, stationID, trackID int) {
	queue(cur, userCaller(cur), stationID, trackID, false, false, "", 0)
}

// QueueAt is Queue for a chosen time: at (unix, UTC) between 15 minutes and
// 24 hours from now; 0 is Queue. The pick starts at the first track boundary
// at or after at (on Main, at at: the relay's track fades out as for any
// pick), unless listener picks fill that moment, then right after them. It
// keeps its time: later picks go before it only if they end by then, else
// after it. Every Queue rule applies, the 3-hour replay gap around at; the
// 2-hour airtime cap does not, but at most 4 picks are booked per station and
// clock hour and at most 15 booked picks wait per station.
func QueueAt(cur realm, stationID, trackID int, at int64) {
	queue(cur, userCaller(cur), stationID, trackID, false, false, "", at)
}

// QueueWithNote is Queue with a dedication shown on air ("for Marie!"). The
// moderation robot judges it before the transaction (word filter and a
// moderation model, app/netlify/functions/dedication.mts) and signs
// NoteMessage(note, expires): the listener sends that certificate and pays
// their own gas, so a dedication shows at once and costs GnoRadio nothing. It
// must also pass p/gnoradio/safe (plain text, no link, no blocked word).
// Listeners can report it: three reports hide it and give its author a strike;
// a second hidden dedication within a week pauses their dedications for a
// week (ReportNote). The pause is per wallet: an author can dedicate again
// from a fresh one, which reports hide and pause the same way (accepted
// residual; the robot and the word filter still judge every note).
func QueueWithNote(cur realm, stationID, trackID int, note string, expires int64, sigHex string) {
	queueWithNote(cur, stationID, trackID, 0, note, expires, sigHex)
}

// QueueWithNoteAt is QueueWithNote for a chosen time (see QueueAt; 0: now).
func QueueWithNoteAt(cur realm, stationID, trackID int, at int64, note string, expires int64, sigHex string) {
	queueWithNote(cur, stationID, trackID, at, note, expires, sigHex)
}

func queueWithNote(cur realm, stationID, trackID int, at int64, note string, expires int64, sigHex string) {
	caller := userCaller(cur)
	if until, ok := data.Get(cMuted, caller.String()); ok && now() < text.MustAtoi64(until) {
		panic("radio: your dedications are paused after reports, pick without one")
	}
	if why := safe.Note(note, maxNote); why != "" {
		panic("radio: dedication: " + why)
	}
	checkNote(caller, stationID, note, expires, sigHex)
	queue(cur, caller, stationID, trackID, false, false, note, at)
}

// NoteMessage is what the moderation robot signs to approve a dedication by
// author on stationID until expires (unix seconds), on this chain and this
// GnoRadio deployment (its data realm) only:
// "gnoradio-note|<chain id>|<data realm>|<author>|<station>|<note>|<expires>".
// A certificate seen in a public transaction serves no other wallet,
// station or deployment.
func NoteMessage(author address, stationID int, note string, expires int64) string {
	return "gnoradio-note|" + runtime.ChainID() + "|" + dataPath + "|" + author.String() + "|" + text.Itoa(stationID) + "|" + note + "|" + text.Itoa64(expires)
}

func checkNote(author address, stationID int, note string, expires int64, sigHex string) {
	v, _ := data.Get(cConfig, "modbot")
	key, _ := hex.DecodeString(v)
	if len(key) == 0 {
		panic("radio: dedications are paused, pick without one")
	}
	if ts := now(); expires <= ts || expires > ts+noteCertLife {
		panic("radio: the dedication check expired, send it again")
	}
	sig, err := hex.DecodeString(sigHex)
	if err != nil || len(sig) != 64 || !ed25519.Verify(key, []byte(NoteMessage(author, stationID, note, expires)), sig) {
		panic("radio: this dedication was not approved, send it again")
	}
}

// CuratorQueue programs a track like Queue but without the per-listener and
// per-artist quotas (the duplicate, genre and queue-size rules still apply).
// Radio admin only.
func CuratorQueue(cur realm, stationID, trackID int) {
	onlyAdmin(cur)
	queue(cur, cur.Previous().Address(), stationID, trackID, true, false, "", 0)
}

func queue(cur realm, caller address, stationID, trackID int, curator, sponsored bool, note string, at int64) {
	noPayment()
	t := rd()
	st := t.station(stationID)
	who := caller // own picks earn nothing: only a listener's needs the check
	if curator || sponsored {
		who = ""
	}
	artistID, genre, dur, playable, own := catalog.TrackBriefFor(trackID, who)
	if !playable {
		panic("radio: unknown track")
	}
	if st.genre != 0 && genre != st.genre {
		panic("radio: this track does not belong to this station")
	}
	if t.dropped(st.id, trackID) { // a pick must not undo the admin's DropSlot
		panic("radio: this track was removed from this station")
	}
	if st.id == NewStation && trackID <= t.synced()-newCap {
		panic("radio: only new tracks can be picked on New this week")
	}
	ts := now()
	airs := ts // when the pick is meant to air
	if at != 0 {
		if at < ts+bookMin || at > ts+bookMax {
			panic("radio: book a time between 15 minutes and 24 hours from now")
		}
		airs = at
	}
	st.fold(ts)
	start := st.place(ts, dur, at)
	// Main's simulcast is not a slot: picking the track it plays would
	// restart it over itself.
	if st.id == MainStation && at == 0 {
		if _, prog := st.playing(ts); !prog {
			if tr, _, _, _ := st.between(ts); tr == trackID {
				panic("radio: this track is already programmed")
			}
		}
	}
	// The replay gap counts from when the pick really airs: a pick for now
	// may wait up to 2 hours behind others, a booked one keeps its time.
	gapAt := airs
	if at == 0 {
		gapAt = start
	}
	// realign may still move a booked pick by up to a track: around one,
	// the replay gap takes that much more.
	gap := int64(replayGap)
	if at != 0 {
		gap += maxTrack
	}
	upcoming, kept, perArtist, booked, bookedUp := 0, 0, 0, 0, 0
	var ahead int64 // listener airtime for now still to play
	for _, s := range st.slots() {
		// A slot of the track blocks it within the replay gap.
		if s.Track == trackID && s.Start+s.Dur > ts {
			g := gap
			if s.At > 0 {
				g = replayGap + maxTrack
			}
			if abs64(s.Start-gapAt) < g {
				panic("radio: this track is already programmed")
			}
		}
		// A booked pick enters lastpick when folded, an hour after it ends:
		// until then its slot keeps the replay gap.
		if s.Track == trackID && s.At > 0 && s.Start+s.Dur <= ts && !curator && gapAt-s.Start < replayGap {
			panic("radio: this track was picked here less than 3 hours ago, pick another one")
		}
		kept++ // aired or not: a listener slot stays in the record until it folds
		if at != 0 && s.At/3600 == at/3600 {
			booked++ // aired ones too: at most maxBookedHour per clock hour
		}
		if s.Start+s.Dur <= ts {
			continue
		}
		upcoming++
		if s.At > 0 {
			bookedUp++
		}
		if !curator && s.Start > ts && s.By == caller {
			panic("radio: you already have a track waiting on this station")
		}
		if s.artist == artistID {
			perArtist++
		}
		if s.At == 0 {
			ahead += s.Start + s.Dur - max64(s.Start, ts)
		}
	}
	if upcoming >= maxQueue || kept >= maxKept {
		panic("radio: the queue is full, try again later")
	}
	// Bookings may cover the next 24 hours: they take at most half the
	// queue, so they never leave picks for now without room.
	if at != 0 && bookedUp >= maxBooked {
		panic("radio: booked picks are full on this station, pick for now or later")
	}
	if booked >= maxBookedHour {
		panic("radio: 4 picks are already booked for that hour here, choose another time")
	}
	// No track on a loop: many wallets cannot replay one song for hours.
	if last, ok := st.lastPicked(trackID); ok && !curator && gapAt-last < gap {
		panic("radio: this track was picked here less than 3 hours ago, pick another one")
	}
	if !curator {
		if last := lastPickAt(t, caller, st.id); last > 0 && ts-last < queueCooldown {
			panic("radio: you can queue one track per station every 30 minutes")
		}
		if at == 0 && ahead+dur > maxAheadAir {
			panic("radio: this station is programmed two hours ahead, try again later")
		}
	}
	if !curator && perArtist >= maxPerArtistQ {
		panic("radio: this artist already has 2 tracks in the queue")
	}
	if sponsored {
		sponsorQuota(st, artistID, dur, airs, gapAt)
	}
	if at == 0 {
		st.setPicked(trackID, start) // a booked pick is in the schedule; fold records it once aired
	}
	var pay int64
	if sponsored {
		pay = reserve(cur, t, caller, st.id, trackID, start, dur, Slot{Start: start, Dur: dur, At: at}.held())
	}
	st.put(Slot{Track: trackID, Start: start, Dur: dur, By: caller, Note: note, Pay: pay, At: at, artist: artistID})
	if st.full() {
		panic("radio: this station is full for now, try again later")
	}
	// Dedications use only the room the station's other listener slots, their
	// replay entries and a full curator top cannot need: plain picks always
	// fit (TestChoiceRecordWorstCase).
	if note != "" && st.size()+noteReserve(st, kept) > maxRecord-recordHeadroom {
		panic("radio: dedications are full on this station for now, pick without one")
	}
	kind := "queue"
	if curator {
		kind = "curator"
	} else if sponsored {
		kind = "sponsored"
	}
	recordActivity(t, kind, caller, trackID, st.id, start)
	// A sponsored pick is paid for by its artist: it feeds neither Listeners'
	// choice nor the curator ranking, and only keeps the cooldown. Nor does
	// an artist's (or a collaborator's) pick of their own track (an alt
	// wallet remains a residual, as for any sybil pick).
	switch {
	case sponsored || own:
		markPick(t, caller, st.id)
	case !curator:
		choose(t, trackID, dur, ts)
		credit(t, caller, st.id, 1, 0, 0)
	}
	save(cur, t)
	chain.Emit("Queued", "curator", strconv.FormatBool(curator), "station", text.Itoa(st.id), "track", text.Itoa(trackID), "by", caller.String(), "start", text.Itoa64(start), "sponsored", text.Itoa64(pay), "at", text.Itoa64(at))
}

// place says when a new pick of d seconds starts. A pick for now starts when
// the song on air ends (at once on Main, over the relay), after the picks
// for now already waiting; one booked for at starts at the first track
// boundary at or after at. Both go around booked picks: before one only if
// they end by its time, else after it.
func (st *station) place(ts, d, at int64) int64 {
	t := at
	if at == 0 {
		t = ts
		if st.id != MainStation {
			if _, _, off, slotDur, ok := st.rotationAt(ts); ok {
				t = ts + slotDur - off
			}
		}
		for _, s := range st.slots() {
			// after the picks for now, and after a booked pick on air (the
			// rotation is paused under it: its track would only play a
			// fragment before the pick)
			if end := s.Start + s.Dur; end > ts && (s.At == 0 || s.Start <= ts) {
				t = end
			}
		}
	} else {
		t = st.boundary(at)
	}
	for _, s := range st.slots() {
		if s.Start+s.Dur <= t {
			continue
		}
		if s.Start <= t {
			t = s.Start + s.Dur // playing then: wait for its end
			continue
		}
		limit := s.Start
		if s.At > 0 {
			limit = s.At // a booked pick may come back to its own time
		}
		if t+d <= limit {
			break
		}
		t = s.Start + s.Dur
	}
	return t
}

// boundary is the first track boundary at or after t outside listener
// picks: t itself on Main (the relay fades out) or inside a programmed
// slot (place waits for its end), else the end of the rotation track on air.
func (st *station) boundary(t int64) int64 {
	if st.id == MainStation {
		return t
	}
	for _, s := range st.slots() {
		if s.Start <= t && t < s.Start+s.Dur {
			return t
		}
	}
	if _, _, off, d, ok := st.rotationAt(t); ok && off > 0 {
		return t + d - off
	}
	return t
}

// put puts a new listener slot in the schedule. Elsewhere than on Main the
// slots after it are realigned: they moved with the rotation.
func (st *station) put(n Slot) {
	sl, i := insert(st.slots(), n)
	st.setSlots(sl)
	if st.id != MainStation {
		st.realign(i)
	}
}

// insert puts s in a schedule, sorted by start, and returns its index.
func insert(sl []Slot, s Slot) ([]Slot, int) {
	i := len(sl)
	for i > 0 && sl[i-1].Start > s.Start {
		i--
	}
	sl = append(sl, Slot{})
	copy(sl[i+1:], sl[i:])
	sl[i] = s
	return sl, i
}

// realign re-times the listener slots after index i once the rotation moved
// under them: a booked one to the first boundary at or after its time (or
// right after the slot before it), a pick that followed the slot before it
// still follows it, a pick for now that waited for a rotation track after a
// gap waits for the new end of that track. Sponsored records, note reports and
// the replay record move along.
// ponytail: only queue realigns; Unqueue, DropSlot and rotation edits leave
// booked slots in place (the rotation track then pauses around them, as
// around any pick after a removed one); realign there too if it matters.
func (st *station) realign(i int) {
	sl := st.slots()
	var paused int64 // airtime of the slots before k: they all ended by its time (paused, inline)
	for _, s := range sl[:i+1] {
		paused += s.Dur
	}
	total := st.total()
	oldEnd := sl[i].Start + sl[i].Dur
	var notes []int64 // the dedicated slots moved: old start, new start
	for k := i + 1; k < len(sl); k++ {
		prev, s := sl[k-1], sl[k]
		end := prev.Start + prev.Dur
		start := max64(s.Start, end)
		t := s.At
		if t == 0 && s.Start != oldEnd {
			t = s.Start // a pick for now that started on a rotation boundary after a gap
		}
		if t > end && total > 0 { // the rotation plays until then: wait for the end of that track
			start = t
			p := (t - st.epoch - paused) % total
			if p < 0 {
				p += total
			}
			if slot, _, off, ok := st.find(p); ok && off > 0 {
				_, d := st.rotSlot(slot)
				start += d - off
			}
		} else if s.At > 0 || s.Start == oldEnd {
			start = max64(s.At, end)
		}
		oldEnd = s.Start + s.Dur
		paused += s.Dur
		if start != s.Start {
			if s.Note != "" {
				notes = append(notes, s.Start, start)
			}
			st.move(k, start)
		}
	}
	st.moveNotes(notes)
}

// moveNotes re-keys the reports of moved dedications: all read, then all
// removed, then all written, so that a slot moved to where another one
// started never takes or loses its reports.
func (st *station) moveNotes(moves []int64) {
	t := st.t
	recs := make([]string, len(moves)/2)
	for j := 0; j < len(moves); j += 2 {
		recs[j/2] = t.val(cNotes, noteKey(st.id, moves[j]))
	}
	for j := 0; j < len(moves); j += 2 {
		t.del(cNotes, noteKey(st.id, moves[j]))
	}
	for j := 0; j < len(moves); j += 2 {
		if recs[j/2] != "" {
			t.set(cNotes, noteKey(st.id, moves[j+1]), recs[j/2])
		}
	}
}

// move re-times slot k, with its sponsored record and its replay record
// (its dedication's reports move with moveNotes).
func (st *station) move(k int, start int64) {
	t := st.t
	s := &st.sched[k]
	if s.Pay > 0 {
		k := sponsorKey(st.id, s.By)
		if rec, ok := t.get(cSponsor, k); ok && text.Atoi64(store.Field(rec, 0)) == s.Start {
			f := store.Fields(rec)
			t.set(cSponsor, k, store.Rec(text.Itoa64(start), f[1], text.Itoa64(start+s.Dur), f[3], f[4], f[5], f[6]))
		}
	}
	if s.At == 0 {
		st.setPicked(s.Track, start) // a pick for now: the replay gap counts from its airing
	}
	s.Start = start
	st.dirty, st.pzOK = true, false
}

// noteReserve is the record room the other plain picks a station may still
// take need: a slot and a replay entry each, plus its curator top at full.
func noteReserve(st *station, kept int) int {
	return (maxKept-kept-1)*(plainSlot+pickW) + topMax - len(st.top)
}

// Package radio is GnoRadio's radio rules, release 1: a main station that
// plays the whole catalog through the genre stations, one station per genre,
// "New this week" (the newest tracks) and "Listeners' choice" (the tracks
// listeners picked).
// Everyone tuned to a station hears the same track at the same second,
// computed from block time; no streaming server is involved. Between picks
// the main station simulcasts one genre station an hour, by the time of day
// (flow.gno); it has no rotation of its own.
//
// Each station has a rotation (every playable track of its genre, looping)
// stored in fixed-size blocks so that every operation costs the same
// whatever the catalog size, and a short schedule of tracks programmed by
// listeners. While a programmed track plays the rotation pauses, then
// resumes where it was. Adding, removing or editing a track never makes
// listeners jump.
//
// It keeps no state but its admin role. Every record lives in the data realm
// (gno.land/r/nym-alexiscolin000/gnoradio/data), in the "radio/…" collections only the current
// radio writer may change (db.gno). It reads the catalog through its value
// getters; sponsored picks are paid from data's vault through the catalog.
package radio

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"time"

	"gno.land/p/nym-alexiscolin000/gnoradio/role/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	"gno.land/r/nym-alexiscolin000/gnoradio/catalog/v2"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
)

// NumGenres is the catalog's: genre stations are 1..NumGenres.
const NumGenres = catalog.NumGenres

// Station ids are stored keys in the permanent data realm (schedules, drops,
// notes, curator ranks): Main 0, genres 1..NumGenres, New, Choice. A later
// release must keep them, and add any new station after Choice.
const (
	MainStation     = 0
	NewStation      = NumGenres + 1 // the newest newCap ingested tracks
	ChoiceStation   = NumGenres + 2 // the last choiceCap distinct listener picks
	numStations     = ChoiceStation + 1
	newCap          = 300
	choiceCap       = 500
	maxQueue        = 30 // upcoming slots per station
	maxPerArtistQ   = 2  // upcoming slots per artist and station
	maxSyncBatch    = 200
	maxRefreshBatch = 50
	foldAfter       = 3600          // programmed slots ended this long ago fold into the epoch
	queueCooldown   = 1800          // a listener may queue once per station every 30 minutes
	replayGap       = 3 * 3600      // a track picked on a station cannot be picked there again for 3 hours, by anyone
	maxAheadAir     = 7200          // listener-programmed airtime ahead on a station, seconds
	maxNote         = 40            // characters of a dedication
	noteCertLife    = 900           // seconds a moderation certificate may still have to live
	hideAfter       = 3             // distinct reputable listeners (sponsorBlock) reporting a dedication hide it
	muteFor         = 7 * 24 * 3600 // a second hidden dedication within this time mutes its author this long
	bookMin         = 15 * 60       // a pick booked for a time: at least this far ahead
	bookMax         = 24 * 3600     // and at most this far
	maxBookedHour   = 4             // booked picks per station and clock hour (UTC)
	maxKept         = 3 * maxQueue  // listener slots a station keeps, aired ones included until they fold
	maxBooked       = maxQueue / 2  // booked picks waiting per station
	maxTrack        = 1200          // the catalog's longest track, seconds
	recordHeadroom  = 1024          // bytes a station record keeps free for the writes that follow a pick
	plainSlot       = 72            // record bytes of a listener slot without a dedication: 25, an address, at most 7 of gap
)

// dataPath is the data realm: certificates are bound to it.
const dataPath = "gno.land/r/nym-alexiscolin000/gnoradio/data"

// Slot is a track a listener (or a curator) programmed on a station. Dur is
// captured when queued so later catalog edits cannot move the timeline.
type Slot struct {
	Track      int
	Start      int64
	Dur        int64
	By         address
	Note       string // the picker's dedication, checked by p/gnoradio/safe and the moderation robot
	NoteHidden bool   // hidden by reports or the admin
	Pay        int64  // a sponsored pick: the ugnot its artist reserved to refund the picker (sponsor.gno)
	At         int64  // a booked pick: the time asked (unix); it starts at the first track boundary at or after it
	artist     int    // a listener slot's artist (a track never changes artist): the per-artist rules read it
	body       string // the encoded slot without its start, reused while it does not change (db.gno)
	bdur       int64  // the duration body holds
}

var (
	self  string     // this realm's path
	admin *role.Role // the radio admin; nil when a release before renounced it
)

// init takes the admin over from the previous release (radio/config
// "admin"), or names the deployer. While this realm is the radio writer
// (release 1 at deploy) it also makes the radio's collections.
func init(cur realm) {
	self = cur.PkgPath()
	holder, mirrored := data.Get(cConfig, "admin")
	if !mirrored {
		deployer := unsafe.OriginCaller()
		if deployer == "" && runtime.ChainID() == "dev" {
			deployer = chain.PackageAddress(self + "/dev") // gno test: a key nobody holds
		}
		holder = deployer.String()
	}
	if holder != "" {
		admin = role.New("admin", address(holder))
	}
	if data.Writer("radio") == self {
		setup(cur, address(holder))
	}
}

// ---- Catalog ingestion (permissionless) ----

// Sync ingests up to max catalog tracks not yet on the stations into the
// main station, the station of their genre and New; the catalog's most
// liked tracks join Listeners' choice. Main's flow needs no Sync (flow.gno).
// Anyone may call it. PublishTrack and ImportTrack put each new track on the
// air themselves (publish.gno), so this is a safety net: a track is never
// ingested twice (the flow record counts the synced ones). A track that is
// not playable yet is added silent (duration 0) and Refresh turns it on.
func Sync(cur realm, max int) int {
	noPayment()
	max = store.Limit(max, maxSyncBatch)
	t := rd()
	ts := now()
	n := ingest(t, ts, max, true)
	synced, choice := t.synced(), t.station(ChoiceStation)
	for _, r := range catalog.TopLiked() {
		if id := text.Atoi(r.Key); id <= synced {
			if _, in := choice.ringFind(id); in {
				continue // there already: no need to read the catalog
			}
			if _, _, dur, ok := catalog.TrackBrief(id); ok {
				choose(t, id, dur, ts)
			}
		}
	}
	save(cur, t)
	return n
}

// ingest adds up to max newly published tracks to the stations, and to New
// when joinNew (a launch-catalog import is not a new release).
func ingest(t *tx, ts int64, max int, joinNew bool) int {
	synced := t.synced()
	from := synced + 1
	last := catalog.TrackCount()
	if last > synced+max {
		last = synced + max
	}
	for id := from; id <= last; id++ {
		_, genre, dur, playable := catalog.TrackBrief(id)
		if !playable {
			dur = 0
		}
		home := ""
		if genre >= 1 && genre <= NumGenres {
			home = homeEntry(genre, t.station(genre).add(id, dur, ts))
		}
		if joinNew {
			t.station(NewStation).join(id, dur, ts, newCap)
		}
		t.appendHomes(id, home)
	}
	n := last - synced
	if n > 0 {
		t.setFlowAt(fSynced, 4, last)
		chain.Emit("Synced", "from", text.Itoa(from), "to", text.Itoa(last))
	}
	return n
}

// Refresh re-reads a track from the catalog and updates its rotation slots:
// a hidden track goes silent, a restored one comes back, an edited duration is
// applied. Programmed slots of a track that is no longer playable are dropped.
// Anyone may call it. A slot the admin dropped stays silent.
func Refresh(cur realm, trackID int) {
	noPayment()
	t := rd()
	refresh(cur, t, trackID)
	save(cur, t)
}

// RefreshArtist refreshes up to maxRefreshBatch synced tracks of an artist,
// from offset in the artist's track list, so hiding (or restoring) a whole
// artist takes a few calls instead of one per track. It returns the offset to
// pass next, or 0 when the list is done. Anyone may call it.
func RefreshArtist(cur realm, artistID, offset int) int {
	noPayment()
	n := catalog.ArtistTrackCount(artistID)
	if n == 0 && catalog.ArtistName(artistID) == "" {
		panic("radio: unknown artist")
	}
	if offset < 0 || offset > n {
		offset = 0
	}
	t := rd()
	synced := t.synced()
	for _, id := range catalog.ArtistTrackPage(artistID, offset, maxRefreshBatch) {
		if id >= 1 && id <= synced {
			refresh(cur, t, id)
		}
	}
	save(cur, t)
	if end := offset + maxRefreshBatch; end < n {
		return end
	}
	return 0
}

func refresh(cur realm, t *tx, trackID int) {
	if trackID < 1 || trackID > t.synced() {
		panic("radio: track not synced yet")
	}
	_, genre, dur, playable := catalog.TrackBrief(trackID)
	if !playable {
		dur = 0
	}
	ts := now()
	// Only the stations that hold the track in their rotation need a slot
	// lookup (Main, New and Choice as they say, the genre stations listed in
	// homes). Programmed slots are checked on every station: a genre edit
	// must not leave a slot nobody can silence.
	inGenre := false
	for id := 0; id < numStations; id++ {
		st := t.station(id)
		belongs := st.genre == 0 || st.id == genre
		if i, ok := st.slot(trackID); ok {
			d := dur
			if !belongs || t.dropped(st.id, trackID) {
				d = 0
			}
			st.setDuration(i, d, ts)
			if st.id == genre {
				inGenre = true
			}
		}
		if !playable || !belongs {
			release(cur, st.dropSlots(trackID, ts))
		}
	}
	if !inGenre && genre >= 1 && genre <= NumGenres && dur > 0 {
		t.setHomes(trackID, t.homes(trackID)+homeEntry(genre, t.station(genre).add(trackID, dur, ts)))
	}
	chain.Emit("Refreshed", "track", text.Itoa(trackID), "playable", strconv.FormatBool(playable))
}

// ---- Reads ----

// NowPlaying returns what a station plays at the last block: the track, the
// offset into it in seconds, and whether a listener programmed it. trackID is
// 0 when nothing plays. Clients should prefer ScheduleJSON and their clock.
func NowPlaying(stationID int) (trackID int, offset int64, queued bool) {
	return rd().station(stationID).onAir(now())
}

// OnAirNote returns the dedication of the programmed slot on air ("" when
// none, or once reports hid it).
func OnAirNote(stationID int) string {
	if s, ok := rd().station(stationID).pickAt(now()); ok {
		return s.shownNote()
	}
	return ""
}

// OnAirPay is the refund of the sponsored pick on air (0: none), for labels.
func OnAirPay(stationID int) int64 {
	if s, ok := rd().station(stationID).pickAt(now()); ok {
		return s.Pay
	}
	return 0
}

// UpNext returns the slots listeners programmed on a station that have not
// started yet.
func UpNext(stationID int) []Slot {
	st := rd().station(stationID)
	ts := now()
	var out []Slot
	for _, s := range st.slots() {
		if s.Start > ts {
			if _, _, _, ok := catalog.TrackBrief(s.Track); ok {
				s.Note = s.shownNote()
				out = append(out, s)
			}
		}
	}
	return out
}

// StationCount returns the number of stations (ids 0..StationCount()-1).
func StationCount() int { return numStations }

// StationName is "Main", the genre name, "New this week" or "Listeners' choice".
func StationName(stationID int) string {
	switch mustStation(stationID) {
	case MainStation:
		return "Main"
	case NewStation:
		return "New this week"
	case ChoiceStation:
		return "Listeners' choice"
	default:
		return catalog.GenreName(stationID)
	}
}

// StationInfo returns how many tracks rotate on a station and the loop length.
func StationInfo(stationID int) (tracks int, loop int64, queued int) {
	st := rd().station(stationID)
	tracks, loop = st.rotating()
	return tracks, loop, st.queued(now())
}

// Pending returns how many catalog tracks are not on the stations yet: 0, since
// publishing puts a track on the air (Sync is the safety net).
func Pending() int { return catalog.TrackCount() - rd().synced() }

// PickRules returns the limits on listeners' picks, for pages that explain
// them: one pick per cooldown per station, a track not again within replay,
// at most ahead seconds and queue slots waiting, perArtist waiting per artist,
// booked picks bookFrom to bookTo ahead, bookedPerHour per clock hour and
// booked of the queue slots at most.
func PickRules() (cooldown, replay, ahead int64, queue, perArtist int, bookFrom, bookTo int64, bookedPerHour, booked int) {
	return queueCooldown, replayGap, maxAheadAir, maxQueue, maxPerArtistQ, bookMin, bookMax, maxBookedHour, maxBooked
}

// ---- helpers ----

func now() int64 { return time.Now().Unix() }

func mustStation(id int) int {
	if id < 0 || id >= numStations {
		panic("radio: unknown station")
	}
	return id
}

func userCaller(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("radio: call this directly from your wallet")
	}
	return cur.Previous().Address()
}

func noPayment() {
	if len(unsafe.OriginSend()) != 0 {
		panic("radio: this action does not take coins")
	}
}

func abs64(n int64) int64 {
	if n < 0 {
		return -n
	}
	return n
}

func max64(a, b int64) int64 {
	if a > b {
		return a
	}
	return b
}

package radio

import (
	"chain"

	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
	"gno.land/r/nym-alexiscolin000/gnoradio/catalog/v2"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
)

// Sponsored picks: an artist's promo budget (catalog/sponsor.gno) refunds a
// listener's pick of their track: by default what the pick and collecting
// its refund cost (0.2 GNOT, catalog/sponsor.gno). The listener
// chooses it (QueueSponsored) instead of a normal pick; the artist's refund is
// reserved at once in the data realm's vault, and the listener collects it
// (ClaimPickPayout, one signature, their gas) once the slot has aired in
// full. A slot dropped or cut before its end gives the reservation back; one
// not collected within 7 days lapses back to the budget by itself.
//
// Farming with throwaway wallets earns at most the pick cost back, and these
// rules keep it rare: a wallet needs a first pick 7 days old and 3 normal
// picks in the last two 15-day periods (two counters in the curator record: the
// current period and the one before, so the window is 15 to 30 days, never
// more);
// one sponsored pick per artist per station and hour; sponsored airtime at
// most a quarter of the 2 hours listeners may program; and per wallet one per
// artist and three a day (the catalog). They earn no curator point, do not
// join Listeners' choice and carry no dedication.

const (
	repPeriod     = 15 * 24 * 3600 // reputation counters roll over every 15 days
	repAge        = 7 * 24 * 3600  // a wallet's first pick must be this old
	repPicks      = 3              // normal picks this period and the one before
	sponsorShare  = maxAheadAir / 4
	sponsorWindow = 3600
)

// A sponsored pick not collected yet is radio/sponsor address/P(station) ->
// Rec(start, track, end, ugnot, held, reserved, gen): one open per
// wallet and station; held is the end the catalog reserved for, reserved
// when (unix), gen the budget's funding generation then.
//
// The vault pools an artist's holds per day, and a new owner's funding
// refunds the previous funder everything, holds included, and starts a new
// funding generation (catalog/sponsor.gno): a reservation made before is
// cancelled, never paid from (nor released into) a later listener's hold,
// even when the budget went back to the same funder.

func sponsorKey(stationID int, addr address) string {
	return addr.String() + "/" + store.Pad(stationID)
}

// QueueSponsored is Queue paid by the artist: once the pick has aired in
// full, ClaimPickPayout sends the picker the artist's refund (catalog
// PromoOffer). No dedication. A wallet has one sponsored pick open per
// station: it must be collected (or have lapsed) before the next.
func QueueSponsored(cur realm, stationID, trackID int) {
	queueSponsored(cur, stationID, trackID, 0)
}

// QueueSponsoredAt is QueueSponsored for a chosen time (see QueueAt; 0: now).
// The refund lapses 7 days after the booked time plus the track's length.
func QueueSponsoredAt(cur realm, stationID, trackID int, at int64) {
	queueSponsored(cur, stationID, trackID, at)
}

func queueSponsored(cur realm, stationID, trackID int, at int64) {
	caller := userCaller(cur)
	t := rd()
	if why := sponsorBlock(t, caller); why != "" {
		panic("radio: " + why)
	}
	mustStation(stationID)
	// One open per station until it lapses: collected, or nothing left to
	// pay (the catalog lapses it at the end of a UTC day, so a record past
	// end+7d may still pay).
	if rec, ok := data.Get(cSponsor, sponsorKey(stationID, caller)); ok {
		if payoutStatus(store.Fields(rec)) != "lapsed" {
			panic("radio: collect your last sponsored pick on this station first")
		}
	}
	queue(cur, caller, stationID, trackID, false, true, "", at)
}

// ClaimPickPayout sends the caller the refund of their sponsored pick that
// started at start on stationID, once it has aired in full.
func ClaimPickPayout(cur realm, stationID int, start int64) {
	caller := userCaller(cur)
	noPayment()
	mustStation(stationID)
	t := rd()
	k := sponsorKey(stationID, caller)
	rec, ok := t.get(cSponsor, k)
	if !ok || text.MustAtoi64(store.Field(rec, 0)) != start {
		panic("radio: no sponsored pick of yours to collect at this time")
	}
	f := store.Fields(rec)
	track, amt, held := text.MustAtoi(f[1]), text.MustAtoi64(f[3]), text.MustAtoi64(f[4])
	status := payoutStatus(f)
	if status == "airing" {
		panic("radio: your pick has not finished airing yet")
	}
	t.del(cSponsor, k)
	// A removed track, a cancelled sponsorship or a lapsed refund leaves
	// nothing to pay: the record goes, so the next sponsored pick is open.
	if status == "lapsed" {
		save(cur, t)
		chain.Emit("PickPayoutVoid", "station", text.Itoa(stationID), "start", text.Itoa64(start), "track", text.Itoa(track), "to", caller.String())
		return
	}
	catalog.PromoClaim(cross(cur), track, caller, held, amt, text.MustAtoi(f[6]))
	c, sts := curRec(t, caller.String())
	c[3] += amt
	putCur(t, caller.String(), c, sts)
	save(cur, t)
	chain.Emit("PickPaid", "station", text.Itoa(stationID), "start", text.Itoa64(start), "track", text.Itoa(track), "to", caller.String(), "amount", text.Itoa64(amt))
}

// sponsorBlock says why a wallet may not take sponsored picks yet ("" when it may).
func sponsorBlock(t *tx, addr address) string {
	c, _ := curRec(t, addr.String())
	ts := now()
	if c[4] == 0 || ts-c[4] < repAge {
		return "sponsored picks open 7 days after your first pick"
	}
	recent := int64(0)
	switch ts / repPeriod {
	case c[5]:
		recent = c[6] + c[7]
	case c[5] + 1:
		recent = c[6]
	}
	if recent < repPicks {
		return "sponsored picks need 3 normal picks in the last two 15-day periods"
	}
	return ""
}

// sponsorQuota: one sponsored pick per artist per station and hour, and
// sponsored airtime at most a quarter of the listener window, both around
// airs (now, or the time booked).
// The share counts the listener window from airs; the per-artist hour is
// checked around plays, when the pick really airs (review R31).
func sponsorQuota(st *station, artistID int, dur, airs, plays int64) {
	air := dur
	for _, s := range st.slots() {
		if s.Pay == 0 {
			continue
		}
		if end := s.Start + s.Dur; end > airs && s.Start < airs+maxAheadAir {
			air += end - max64(s.Start, airs)
		}
		if s.Start+s.Dur > plays-sponsorWindow && s.Start < plays+sponsorWindow && s.artist == artistID {
			panic("radio: this artist already has a sponsored pick this hour here, pick it normally")
		}
	}
	if air > sponsorShare {
		panic("radio: sponsored picks are full on this station for now, pick normally")
	}
}

// reserve books the artist's refund for a sponsored slot, lapsing after held.
func reserve(cur realm, t *tx, picker address, stationID, trackID int, start, dur, held int64) int64 {
	amt, gen := catalog.PromoReserve(cross(cur), trackID, picker, held)
	t.set(cSponsor, sponsorKey(stationID, picker), store.Rec(text.Itoa64(start), text.Itoa(trackID), text.Itoa64(start+dur), text.Itoa64(amt), text.Itoa64(held), text.Itoa64(now()), text.Itoa(gen)))
	return amt
}

// held is the end the catalog reserves a sponsored slot's refund for: a
// booked slot keeps the one of its time even if it moves to a boundary.
func (s Slot) held() int64 {
	if s.At > 0 {
		return s.At + s.Dur
	}
	return s.Start + s.Dur
}

// hold is a sponsored slot's reservation in the catalog: filed under the end
// it was reserved for (the slot may have moved since). reserved is when it
// was taken, 0 once the slot started airing: only a pick that never aired
// gives its daily counts back.
type hold struct {
	track                int
	picker               address
	held, paid, reserved int64
	gen                  int
}

// unsponsor forgets the open record of a sponsored slot cut at ts before it
// started, and returns its reservation; ok is false when there was none. A
// slot already on air keeps its record: whoever cut it (a hide, a genre edit,
// a drop), the picker earned the refund and collects it once its end passes.
func unsponsor(t *tx, stationID int, s Slot, ts int64) (hold, bool) {
	k := sponsorKey(stationID, s.By)
	rec, ok := t.get(cSponsor, k)
	if !ok || s.Start < ts || text.MustAtoi64(store.Field(rec, 0)) != s.Start {
		return hold{}, false
	}
	t.del(cSponsor, k)
	f := store.Fields(rec)
	return hold{s.Track, s.By, text.MustAtoi64(f[4]), s.Pay, text.MustAtoi64(f[5]), text.MustAtoi(f[6])}, true
}

// release gives the reservations of cut sponsored slots back to their
// artists. While the catalog is paused it gives nothing back, so the radio
// can still drop slots: each hold lapses back to its budget by itself.
func release(cur realm, cut []hold) {
	if data.Paused("catalog") {
		return
	}
	for _, h := range cut {
		catalog.PromoRelease(cross(cur), h.track, h.picker, h.held, h.paid, h.reserved, h.gen)
	}
}

// PickPayoutStatus says what ClaimPickPayout would do for addr's sponsored
// pick that started at start on stationID: "ok" (it pays), "airing" (not
// finished yet), "lapsed" (nothing to pay: lapsed or cancelled; collecting only clears it) or
// "none" (no such open pick).
func PickPayoutStatus(addr address, stationID int, start int64) string {
	rec, ok := data.Get(cSponsor, sponsorKey(stationID, addr))
	if !ok || text.Atoi64(store.Field(rec, 0)) != start {
		return "none"
	}
	return payoutStatus(store.Fields(rec))
}

func payoutStatus(f []string) string {
	track, end, amt, held := text.MustAtoi(f[1]), text.MustAtoi64(f[2]), text.MustAtoi64(f[3]), text.MustAtoi64(f[4])
	if now() < end {
		return "airing"
	}
	// An aired pick pays whatever happened to its track since: hiding it
	// must not let its artist take back a refund the picker earned.
	if !catalog.PromoClaimable(track, held, amt, text.MustAtoi(f[6])) {
		return "lapsed"
	}
	return "ok"
}

// SponsoredJSON lists a wallet's sponsored picks not collected yet, with
// whether it may take new ones and each one's PickPayoutStatus:
// {"block":"why not, or empty","open":[{"station","start","track","end","amount","status"}]}.
func SponsoredJSON(addr address) string {
	out := `{"block":` + text.Str(sponsorBlock(rd(), addr)) + `,"open":[`
	p := addr.String() + "/"
	keys, recs := store.Rows(data.Page(cSponsor, p, addr.String()+"0", numStations, false))
	for i, rec := range recs {
		f := store.Fields(rec)
		if i > 0 {
			out += ","
		}
		out += `{"station":` + text.Itoa(text.Atoi(keys[i][len(p):])) + `,"start":` + f[0] + `,"track":` + f[1] + `,"end":` + f[2] + `,"amount":` + f[3] + `,"status":"` + payoutStatus(f) + `"}`
	}
	return out + `]}`
}

package radio

import (
	"gno.land/p/nym-alexiscolin000/gnoradio/store/v0"
	"gno.land/r/nym-alexiscolin000/gnoradio/catalog/v2"
)

// ---- Station internals: the rotation loop and the schedule over it ----

// paused is the airtime taken by programmed slots before ts. It reads an
// undecoded schedule as it is, and keeps its result until the schedule
// moves (setSlots, move).
func (st *station) paused(ts int64) int64 {
	if st.pzOK && st.pzAt == ts {
		return st.pz
	}
	var p int64
	if st.decoded {
		for _, s := range st.sched {
			if ts <= s.Start {
				break
			}
			if ts >= s.Start+s.Dur {
				p += s.Dur
			} else {
				p += ts - s.Start
			}
		}
	} else {
		for c := (cursor{s: st.raw}); c.next() && ts > c.start; {
			if ts >= c.end {
				p += c.end - c.start
			} else {
				p += ts - c.start
			}
		}
	}
	st.pz, st.pzAt, st.pzOK = p, ts, true
	return p
}

// pos is the position in the rotation loop at ts.
func (st *station) pos(ts int64) int64 {
	total := st.total()
	if total == 0 {
		return 0
	}
	p := (ts - st.epoch - st.paused(ts)) % total
	if p < 0 {
		p += total
	}
	return p
}

// anchor sets the epoch so that the rotation is at position p at ts.
func (st *station) anchor(ts, p int64) {
	st.epoch, st.dirty = ts-st.paused(ts)-p, true
}

func (st *station) rotationAt(ts int64) (slot, track int, offset, dur int64, ok bool) {
	if st.total() == 0 {
		return 0, 0, 0, 0, false
	}
	slot, track, offset, ok = st.find(st.pos(ts))
	if !ok {
		return 0, 0, 0, 0, false
	}
	_, dur = st.rotSlot(slot)
	return slot, track, offset, dur, true
}

// rotating is how many tracks play on the station and its loop length: on
// Main, which simulcasts the genre stations, theirs added up.
func (st *station) rotating() (live int, loop int64) {
	if st.id != MainStation {
		return st.live, st.total()
	}
	for g := 1; g <= NumGenres; g++ {
		gs := st.t.station(g)
		live, loop = live+gs.live, loop+gs.total()
	}
	return
}

// playing is the programmed slot on air at ts.
func (st *station) playing(ts int64) (Slot, bool) {
	for _, s := range st.slots() {
		if ts >= s.Start && ts < s.Start+s.Dur {
			return s, true
		}
	}
	return Slot{}, false
}

// between is what a station plays at ts outside programmed slots: its
// rotation, or on Main a simulcast of the hour's genre station (flow.gno):
// what that station plays at ts, its own picks included, cut where it pauses
// for a pick and at the hour (the app's top-of-hour jingle covers the cut).
// The genre station never jumps (its edits re-anchor it), so neither does Main.
func (st *station) between(ts int64) (track int, off, dur int64, ok bool) {
	if st.id != MainStation {
		_, track, off, dur, ok = st.rotationAt(ts)
		return
	}
	g := hourGenre(st.t, ts)
	if g == 0 {
		return
	}
	gs := st.t.station(g)
	if s, prog := gs.playing(ts); prog {
		track, off, dur, ok = s.Track, ts-s.Start, s.Dur, true
	} else if _, track, off, dur, ok = gs.rotationAt(ts); !ok {
		return
	} else {
		for _, s := range gs.slots() { // the genre rotation pauses for its next pick
			if s.Start > ts && s.Start < ts-off+dur {
				dur = s.Start - (ts - off)
			}
		}
	}
	if end := ts - ts%3600 + 3600; ts-off+dur > end {
		dur = end - (ts - off)
	}
	if st.t.dropped(MainStation, track) {
		track = 0 // dropped from Main: silence (onAir and ScheduleJSON skip it)
	}
	return
}

// relay is the station Main simulcasts at ts (the hour's genre station), or st.
func (st *station) relay(ts int64) *station {
	if st.id == MainStation {
		if g := hourGenre(st.t, ts); g != 0 {
			return st.t.station(g)
		}
	}
	return st
}

// pickAt is the listener pick on air at ts: the station's own or, on Main
// between its own picks, the genre station's pick it simulcasts, so Main
// shows, tips and reports it as that pick.
func (st *station) pickAt(ts int64) (Slot, bool) {
	if s, ok := st.playing(ts); ok || st.id != MainStation {
		return s, ok
	}
	if r := st.relay(ts); r != st {
		if s, ok := r.playing(ts); ok && !st.t.dropped(MainStation, s.Track) {
			return s, true
		}
	}
	return Slot{}, false
}

func (st *station) onAir(ts int64) (int, int64, bool) {
	if s, ok := st.pickAt(ts); ok {
		if _, _, _, ok := catalog.TrackBrief(s.Track); ok {
			return s.Track, ts - s.Start, true
		}
		return 0, 0, false // a removed programmed slot plays silence until its end
	}
	track, off, _, ok := st.between(ts)
	if !ok {
		return 0, 0, false
	}
	if _, _, _, playable := catalog.TrackBrief(track); !playable {
		return 0, 0, false // hidden but not refreshed yet: silence, never its title
	}
	return track, off, false
}

// queued counts the listener slots not ended yet.
func (st *station) queued(ts int64) int {
	n := 0
	for _, s := range st.slots() {
		if s.Start+s.Dur > ts {
			n++
		}
	}
	return n
}

// add appends a track at the end of the loop and returns its slot; listeners do not move.
func (st *station) add(trackID int, dur int64, ts int64) int {
	p := st.pos(ts)
	i := st.appendRot(trackID, dur)
	if dur > 0 {
		st.addLive(1)
	}
	st.anchor(ts, p)
	return i
}

// join puts a synced track in New or Choice, a ring of keep slots: once
// full, the oldest slot is reused in place, so the rotation never outgrows
// keep whatever the catalog size or the number of picks. The track it held
// leaves the ring's index, so Refresh leaves it out. Listeners do not jump:
// replace re-anchors around the change.
func (st *station) join(trackID int, dur int64, ts int64, keep int) {
	p, found := st.ringFind(trackID)
	st.joinAt(p, found, trackID, dur, ts, keep)
}

// joinAt is join for a track at position p of the ring's index (ringFind).
func (st *station) joinAt(p int, found bool, trackID int, dur int64, ts int64, keep int) {
	if st.full() {
		return // no room in the record now: the track misses this ring (Choice takes it again with a later pick or Sync)
	}
	i := st.ring % keep
	st.ring++
	st.dirty = true
	if st.count() < keep {
		st.ringIndex(p, found, trackID, st.add(trackID, dur, ts))
		return
	}
	old, _ := st.rotSlot(i)
	st.replace(i, trackID, dur, ts)
	if q := st.ringUnindex(old, i); q >= 0 && q < p {
		p--
	} else if q == p && old == trackID {
		found = false
	}
	st.ringIndex(p, found, trackID, i)
}

// choose adds a synced track to Listeners' choice unless it is already there.
func choose(t *tx, trackID int, dur int64, ts int64) {
	if trackID < 1 || trackID > t.synced() {
		return // not ingested yet
	}
	cs := t.station(ChoiceStation)
	p, in := cs.ringFind(trackID)
	if in {
		return
	}
	if t.dropped(ChoiceStation, trackID) {
		dur = 0
	}
	cs.joinAt(p, false, trackID, dur, ts, choiceCap)
}

// slot returns a track's index in this station's rotation. Main has no
// rotation (it simulcasts the genre stations); New and Choice keep an index;
// genre stations look the slot up in homes.
func (st *station) slot(trackID int) (int, bool) {
	switch {
	case st.id == MainStation:
		return 0, false
	case st.ringed():
		return st.ringSlot(trackID)
	}
	return homeSlot(st.t.homes(trackID), st.id)
}

// setDuration changes slot i and re-anchors so the song on air keeps playing
// (or, if it is the one removed, the next one starts now). O(n/Size + Size).
func (st *station) setDuration(i int, d int64, ts int64) {
	id, old := st.rotSlot(i)
	if old == d {
		return
	}
	p := st.pos(ts)
	prefix := st.prefixBefore(i)
	np := p
	switch {
	case st.total() == 0 || p < prefix:
		// the change is ahead of the listeners
	case p >= prefix+old:
		np = p - old + d // the change is behind them
	default:
		// the slot on air changes
		if p-prefix >= d {
			np = prefix + d // cut short: the next track starts now
		}
	}
	st.setRot(i, id, d)
	if old == 0 && d > 0 {
		st.addLive(1)
	} else if old > 0 && d == 0 {
		st.addLive(-1)
	}
	if total := st.total(); total > 0 {
		st.anchor(ts, np%total)
	}
}

// replace puts another track in slot i, as setDuration(i, 0), a new id,
// then setDuration(i, d) would, in one rotation write: the old track stops
// if on air (the next starts now), listeners do not jump.
func (st *station) replace(i, id int, d int64, ts int64) {
	_, old := st.rotSlot(i)
	if old == 0 && d == 0 {
		st.setRot(i, id, 0) // the old sequence left the epoch alone
		return
	}
	p, prefix := st.pos(ts), st.prefixBefore(i)
	np := p
	switch {
	case st.total() == 0 || p < prefix:
	case p >= prefix+old:
		np = p - old + d
	default:
		np = prefix + d // the slot on air ends now
	}
	st.setRot(i, id, d)
	if old == 0 && d > 0 {
		st.addLive(1)
	} else if old > 0 && d == 0 {
		st.addLive(-1)
	}
	if total := st.total(); total > 0 {
		st.anchor(ts, np%total)
	}
}

// fold moves programmed slots that ended long ago into the epoch.
func (st *station) fold(ts int64) {
	sl := st.slots()
	i := 0
	for i < len(sl) && sl[i].Start+sl[i].Dur <= ts-foldAfter {
		s := sl[i]
		st.epoch += s.Dur
		if s.Note != "" { // only a dedication has reports
			st.t.del(cNotes, noteKey(st.id, s.Start))
		}
		if s.At > 0 { // the replay gap counts from when a booked pick aired
			st.setPicked(s.Track, s.Start)
		}
		i++
	}
	if i > 0 {
		st.setSlots(sl[i:])
	}
}

// dropSlots removes a track's programmed slots; one on air ends now. It
// returns the sponsored ones, which no longer air in full: their payout goes
// back to the artist (release).
func (st *station) dropSlots(trackID int, ts int64) (cut []hold) {
	var out []Slot
	changed := false
	for _, s := range st.slots() {
		if s.Track == trackID && s.Pay > 0 && s.Start+s.Dur > ts {
			if h, ok := unsponsor(st.t, st.id, s, ts); ok {
				cut = append(cut, h)
			}
		}
		if s.Track == trackID {
			if s.Start >= ts {
				// a later pick may reuse this start: its reports go too
				if s.Note != "" {
					st.t.del(cNotes, noteKey(st.id, s.Start))
				}
				changed = true
				continue
			}
			if s.Start+s.Dur > ts {
				s.Dur = ts - s.Start
				changed = true
			}
		}
		out = append(out, s)
	}
	if changed {
		st.setSlots(out)
	}
	return cut
}

// The replay record of a station (in its record: a pick changes both) is
// fixed-width entries, the track (4 digits) then the pick time (6), read by
// slicing.
const pickW = 10

// lastPicked is when a track was last picked on the station, within replayGap.
func (st *station) lastPicked(trackID int) (int64, bool) {
	rec := st.picks
	key := store.Fixed(int64(trackID), 4)
	for i := 0; i+pickW <= len(rec); i += pickW {
		if rec[i:i+4] == key {
			return store.Num(rec, i+4, 6), true
		}
	}
	return 0, false
}

// setPicked records a pick time (the later one wins) and drops the picks
// older than replayGap, which no check reads: the record stays as short as
// the picks of the last three hours.
func (st *station) setPicked(trackID int, at int64) {
	rec := st.picks
	key := store.Fixed(int64(trackID), 4)
	cut := now() - replayGap
	out := ""
	for i := 0; i+pickW <= len(rec); i += pickW {
		when := store.Num(rec, i+4, 6)
		if rec[i:i+4] == key {
			if when > at {
				at = when
			}
		} else if when > cut {
			out += rec[i : i+pickW]
		}
	}
	if at > cut {
		out += key + store.Fixed(at, 6)
	}
	if out != rec {
		st.picks, st.dirty = out, true
	}
}

// shownNote is the dedication listeners see ("" once hidden).
func (s Slot) shownNote() string {
	if s.NoteHidden {
		return ""
	}
	return s.Note
}

// picker is the listener whose pick of trackID plays at ts on the station,
// or ended less than tipGrace ago, read from the stored schedule: "" when
// none, a sponsored pick (its artist already refunds it) or the admin's (a
// curator pick: GnoRadio takes no share), and the station the pick lives on
// (on Main, the genre station whose pick it simulcast).
func (st *station) picker(trackID int, ts int64, adm address) (address, int) {
	var by address
	for c := (cursor{s: st.raw}); c.next(); {
		b := st.raw[c.b:c.i]
		if c.start > ts || ts >= c.end+tipGrace || int(dec[b[3]]<<18|dec[b[4]]<<12|dec[b[5]]<<6|dec[b[6]]) != trackID || store.Num(b, 17, 4) != 0 {
			continue
		}
		if p := address(b[23 : 23+int(dec[b[22]])]); p != adm {
			by = p
		}
	}
	if by == "" && st.id == MainStation && !st.t.dropped(MainStation, trackID) {
		for _, at := range []int64{ts, ts - tipGrace} { // the pick may have ended in the hour before
			if r := st.relay(at); r != st {
				if by, _ = r.picker(trackID, ts, adm); by != "" {
					return by, r.id
				}
			}
		}
	}
	return by, st.id
}

package home

import (
	"chain"
	"chain/runtime/unsafe"
	"strings"

	"gno.land/r/nym-alexiscolin000/gnoradio/catalog/v2"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
)

// The site's two settings live in the data realm, "home/config", so a later
// home release keeps them: "app" is the GnoRadio app (dApp) that pages link
// to, "" hides the links; "contact" is an extra way to reach the moderator,
// shown with the notice path, "" hides the line (the on-chain Report needs
// none). Only the catalog admin sets them: home has no admin of its own.
const (
	cConfig    = "home/config"
	maxAppURL  = 100
	maxContact = 120
)

// init makes home/config while this realm is the home writer (release 1 at
// deploy); a later release finds it made.
func init(cur realm) {
	if data.Writer("home") == cur.PkgPath() {
		data.Make(cross(cur), cConfig)
	}
}

// Ready tells the data realm that this release is on chain (see
// data.Propose). Anyone may call it.
func Ready(cur realm) {
	noPayment()
	data.Ready(cross(cur))
}

func noPayment() {
	if len(unsafe.OriginSend()) != 0 {
		panic("home: this action does not take coins")
	}
}

func onlyCatalogAdmin(cur realm) {
	if !cur.Previous().IsUserCall() || cur.Previous().Address() != catalog.Admin() {
		panic("home: catalog admin only")
	}
	noPayment()
}

// SetAppURL sets the app link shown on every page: an https URL of at most
// 100 characters from [A-Za-z0-9-._~/:%], or "" to remove it. Catalog admin only.
func SetAppURL(cur realm, url string) {
	onlyCatalogAdmin(cur)
	if url != "" && !validAppURL(url) {
		panic("home: app URL must be https://, at most 100 characters of A-Z a-z 0-9 - . _ ~ / : %")
	}
	data.Set(cross(cur), cConfig, "app", url)
	chain.Emit("AppURLSet", "url", url)
}

// SetContact sets the contact line shown next to the notice path (a web form,
// a postal address…): one line of at most 120 characters, or "" to remove it.
// Catalog admin only.
func SetContact(cur realm, line string) {
	onlyCatalogAdmin(cur)
	line = strings.TrimSpace(line)
	if len(line) > maxContact || strings.ContainsAny(line, "\r\n") {
		panic("home: the contact is one line of at most 120 characters")
	}
	data.Set(cross(cur), cConfig, "contact", line)
	chain.Emit("ContactSet", "contact", line)
}

func validAppURL(u string) bool {
	if !strings.HasPrefix(u, "https://") || len(u) <= len("https://") || len(u) > maxAppURL {
		return false
	}
	for _, c := range u {
		switch {
		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
		case strings.ContainsRune("-._~/:%", c):
		default:
			return false
		}
	}
	return true
}

// appURL and contact read the settings.
// appURL is checked again when read: a later release may write it.
func appURL() string {
	if v, _ := data.Get(cConfig, "app"); validAppURL(v) {
		return v
	}
	return ""
}

func contact() string {
	v, _ := data.Get(cConfig, "contact")
	return v
}

// inApp links an app route (e.g. "track/12", "" for the player), or returns
// "" when no app URL is set.
func inApp(route, label string) string {
	u := appURL()
	if u == "" {
		return ""
	}
	return "[" + label + "](" + strings.TrimRight(u, "/") + "/" + route + ")"
}

package home

import (
	"strconv"

	"gno.land/p/nym-alexiscolin000/gnoradio/svg/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"
)

// Sober Swiss artwork, drawn on-chain as SVG and embedded by gnoweb as
// data-URI images: black and off-white, warm greys and the app's red, blue
// and yellow accents. Cards with text sit on ink so they read in light and
// dark mode alike.
// Written with a strings.Builder to keep vm/qrender gas low.

const (
	ink   = "#0d0d0d"
	paper = "#fafaf8"
	cream = "#f2efe9"
	grey  = "#c4c4c0"
	stone = "#8f8b84"
	line  = "#e3e3df"
	red   = "#e5432f"
	blue  = "#2445c9"
	amber = "#f2b51d" // the app's yellow
	dim   = "#3a3a37" // unplayed ticks on ink
	font  = "font-family:Geist,'Helvetica Neue',Helvetica,Arial,sans-serif"
)

func newCanvas(w, h int) *svg.Canvas { return svg.New(w, h, "text{"+font+"}") }

// text writes s (escaped); weight 400–800; anchor start|middle|end.
func drawText(c *svg.Canvas, x, y int, s, fill string, size, weight int, anchor, extra string) {
	c.Text(x, y, s, fill, size, ` font-weight="`+text.Itoa(weight)+`" text-anchor="`+anchor+`"`+extra)
}

// coverSVG draws one of six geometric compositions and one of three accents,
// picked from the track and its artist so neighbours differ.
func coverSVG(id, artist int, title string, size int) string {
	h := svg.FNV(strconv.Itoa(id) + "/" + strconv.Itoa(artist) + title)
	accent := [3]string{red, blue, amber}[h/6%3]
	c := newCanvas(size, size)
	s := size
	switch h % 6 {
	case 0:
		c.Rect(0, 0, s, s, s/12, ink, "")
		c.Circle(s/2, s/2, s*28/100, accent)
	case 1:
		c.Rect(0, 0, s, s, s/12, grey, "")
		c.Circle(s/5, s*9/10, s*45/100, stone)
		c.Circle(s*68/100, s*32/100, s*15/100, ink)
	case 2:
		c.Rect(0, 0, s, s, s/12, accent, "")
		c.Raw(`<path d="M0 ` + text.Itoa(s/2) + `H` + text.Itoa(s) + `V` + text.Itoa(s-s/12) + `Q` + text.Itoa(s) + ` ` + text.Itoa(s) + ` ` + text.Itoa(s-s/12) + ` ` + text.Itoa(s) +
			`H` + text.Itoa(s/12) + `Q0 ` + text.Itoa(s) + ` 0 ` + text.Itoa(s-s/12) + `Z" fill="` + cream + `"/>`)
		c.Circle(s/2, s/2, s*15/100, ink)
	case 3:
		c.Rect(0, 0, s, s, s/12, cream, "")
		c.Rect(s*14/100, s*14/100, s*44/100, s*72/100, s*22/100, stone, "")
		c.Circle(s*74/100, s*27/100, s*13/100, accent)
	case 4:
		c.Rect(0, 0, s, s, s/12, stone, "")
		c.Raw(`<path d="M` + text.Itoa(s/12) + ` 0H` + text.Itoa(s/2) + `V` + text.Itoa(s) + `H` + text.Itoa(s/12) + `Q0 ` + text.Itoa(s) + ` 0 ` + text.Itoa(s-s/12) +
			`V` + text.Itoa(s/12) + `Q0 0 ` + text.Itoa(s/12) + ` 0Z" fill="` + ink + `"/>`)
		c.Circle(s/2, s/2, s/5, cream)
	default:
		c.Rect(0, 0, s, s, s/12, ink, "")
		for i := 0; i < 21; i++ {
			th := s / 14
			if i%5 == 0 {
				th = s / 7
			}
			c.Rect(s/10+i*(s*8/10)/20, s*62/100-th, 2, th, 0, paper, "")
		}
		c.Rect(s/10+int(h%17)*(s*8/10)/20, s*36/100, 3, s*30/100, 0, accent, "")
	}
	return c.Image("cover of " + title)
}

// onAirSVG is the station banner: huge time numerals and a tick ruler with
// the red needle, as in the app, on ink so it reads in dark mode too.
func onAirSVG(station, title, artist string, offset, dur int64) string {
	const w, h = 720, 330
	c := newCanvas(w, h)
	c.Rect(0, 0, w, h, 26, ink, "")
	c.Rect(28, 26, 104, 30, 10, red, "")
	drawText(c, 80, 46, "ON AIR", "#fff", 13, 600, "middle", ` letter-spacing="1.5"`)
	c.Rect(142, 26, 18+len(station)*9, 30, 10, dim, "")
	drawText(c, 151, 46, station, paper, 13, 500, "start", "")
	if title == "" {
		drawText(c, w/2, 170, "Silence. Publish the first track.", grey, 26, 600, "middle", "")
		return c.Image("nothing on air")
	}
	t := clock(offset)
	if offset < 600 {
		t = "0" + t
	}
	lead := 0
	for lead < len(t) && (t[lead] == '0' || t[lead] == ':') {
		lead++
	}
	c.Raw(`<text x="` + text.Itoa(w/2) + `" y="150" font-size="96" font-weight="500" text-anchor="middle" letter-spacing="-4">` +
		`<tspan fill="` + dim + `">` + t[:lead] + `</tspan><tspan fill="` + paper + `">` + t[lead:] + `</tspan></text>`)
	drawText(c, w/2, 178, "of "+clock(dur)+" · synced to the last block", stone, 13, 400, "middle", "")
	frac := 0
	if dur > 0 {
		frac = int(offset * 1000 / dur)
	}
	for i := 0; i <= 80; i++ {
		th, col := 10, dim
		if i%10 == 0 {
			th = 26
		} else if i%5 == 0 {
			th = 17
		}
		if i*1000/80 <= frac {
			col = paper
		}
		c.Rect(40+i*8, 238-th, 2, th, 0, col, "")
	}
	c.Rect(40+frac*640/1000, 196, 2, 50, 0, red, "")
	// Large enough to read once the card shrinks to a phone's width.
	drawText(c, 40, 284, svg.Clip(title, 36), paper, 28, 600, "start", "")
	drawText(c, 40, 312, svg.Clip(artist, 48), grey, 18, 400, "start", "")
	return c.Image("on air: " + title)
}

// avatarSVG is a symmetric identicon in the sober palette.
func avatarSVG(seed string, size int) string {
	h := svg.FNV(seed)
	c := newCanvas(size, size)
	c.Rect(0, 0, size, size, size/2, cream, "")
	cell := size / 9
	for y := 0; y < 5; y++ {
		for x := 0; x < 3; x++ {
			h ^= uint32(y*3 + x + 1)
			h *= 16777619
			if (h>>24)%2 == 0 {
				continue
			}
			col := ink
			if (h>>20)%7 == 0 {
				col = red
			}
			c.Rect(cell*2+x*cell, cell*2+y*cell, cell, cell, 2, col, "")
			if x < 2 {
				c.Rect(cell*2+(4-x)*cell, cell*2+y*cell, cell, cell, 2, col, "")
			}
		}
	}
	return c.Image("avatar")
}

// badgeSVG is the early-listener badge.
func badgeSVG(title string, rank int) string {
	c := newCanvas(120, 120)
	c.Circle(60, 60, 58, ink)
	c.Raw(`<circle cx="60" cy="60" r="50" fill="none" stroke="` + paper + `" stroke-width="1" stroke-dasharray="3 4"/>`)
	drawText(c, 60, 50, "EARLY", grey, 11, 600, "middle", ` letter-spacing="2"`)
	drawText(c, 60, 82, "#"+text.Itoa(rank), paper, 30, 500, "middle", "")
	c.Circle(60, 100, 4, red)
	return c.Image("early listener #" + text.Itoa(rank) + " of " + title)
}

type bar struct {
	label string
	value int64
}

// barsSVG draws a horizontal bar chart.
func barsSVG(rows []bar, unit func(int64) string) string {
	h := 30 + len(rows)*40
	c := newCanvas(640, h)
	c.Rect(0, 0, 640, h, 20, ink, "")
	var max int64 = 1
	for _, r := range rows {
		if r.value > max {
			max = r.value
		}
	}
	for i, r := range rows {
		y := 20 + i*40
		w := int(r.value * 300 / max)
		if w < 4 {
			w = 4
		}
		col := paper
		if i == 0 {
			col = red
		}
		drawText(c, 20, y+20, svg.Clip(r.label, 20), paper, 14, 500, "start", "")
		c.Rect(210, y+6, w, 18, 9, col, "")
		drawText(c, 220+w, y+20, unit(r.value), grey, 13, 400, "start", "")
	}
	return c.Image("chart")
}

package home

import (
	"strings"

	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"

	"gno.land/r/nym-alexiscolin000/gnoradio/radio/v2"
)

// topCurators lists a station's best pickers this week (radio/curators.gno).
func topCurators(st int) string {
	top := radio.TopCurators(st)
	if len(top) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("## Top curators this week\n\nA pick and a tip received while it is on air score one point each. Pickers earn the artist's promo share of those tips.\n\n")
	for i, c := range top {
		b.WriteString(text.Itoa(i+1) + ". " + who(c.Address) + " · " + plural(c.Picks, "pick") + " · " + plural(c.Tips, "tip") + " · earned " + text.GNOT(c.Earned) + "\n")
	}
	return b.String() + "\n"
}

// Package home is the GnoRadio website on gnoweb, release 1. It owns no
// data: every page is rendered from the catalog, radio and tickets realms,
// and its two settings (app.gno) live in the data realm, "home/config".
package home

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	roles "gno.land/p/nym-alexiscolin000/gnoradio/role/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/safe/v0"
	"gno.land/p/nym-alexiscolin000/gnoradio/text/v0"

	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/markdown/sanitize/v0"

	"gno.land/r/nym-alexiscolin000/gnoradio/catalog/v2"
	"gno.land/r/nym-alexiscolin000/gnoradio/data"
	"gno.land/r/nym-alexiscolin000/gnoradio/radio/v2"
	"gno.land/r/nym-alexiscolin000/gnoradio/tickets/v2"
)

const (
	catalogPath = "gno.land/r/nym-alexiscolin000/gnoradio/catalog/v2"
	radioPath   = "gno.land/r/nym-alexiscolin000/gnoradio/radio/v2"
	ticketsPath = "gno.land/r/nym-alexiscolin000/gnoradio/tickets/v2"
	dataPath    = "gno.land/r/nym-alexiscolin000/gnoradio/data"
	maxCovers   = 8
	pageSize    = 20
	ugnot       = 1_000_000
)

var (
	catalogTx = txlink.Realm(catalogPath)
	radioTx   = txlink.Realm(radioPath)
	ticketsTx = txlink.Realm(ticketsPath)
	dataTx    = txlink.Realm(dataPath)
	self      = unsafe.CurrentRealm().PkgPath()
	base      = strings.TrimPrefix(self, runtime.ChainDomain()) // gnoweb path of this realm
)

// Render serves:
//
//	""                       home: main station on air, stations, new releases, top, concerts
//	"stations" "station/<n>" radio stations and their schedule
//	"track/<id>"             a track
//	"artist/<id|name>"       an artist
//	"album/<id>" "playlist/<id>"
//	"catalog?p=N&g=G" "artists?p=N" "albums?p=N" "playlists?p=N"
//	"concerts?p=N" "event/<id>" "ticket/<id>"
//	"listener" "listener/<g1…>" listeners: top curators; one listener's likes, playlists, tickets, badges
//	"charts" "join" "about" "moderation?p=N"
//
// Bare entity segments ("track", "artist"…, linked by gnoweb's breadcrumb)
// open the matching list. Entity pages with long lists take ?p=N too.
//
// Raw path input is never echoed: ids are parsed, names and addresses looked up.
func Render(path string) string {
	p, query, _ := strings.Cut(path, "?")
	pg, genre := 1, 0
	for _, kv := range strings.Split(query, "&") {
		k, v, _ := strings.Cut(kv, "=")
		switch n := atoi(v); k {
		case "p":
			if n > 1 && n < 100000 {
				pg = n
			}
		case "g":
			if n >= 1 && n <= catalog.NumGenres {
				genre = n
			}
		}
	}
	out := route(p, pg, genre)
	if out == "" {
		out = header("Not found", "-") + "This page does not exist. [← Back to the radio](" + page("") + ")\n"
	}
	return banner() + out
}

// banner tells visitors what the data realm says of the release in force
// (data.Writers): a newer site, a paused role, or a release on its way.
func banner() string {
	if s := data.Writer("home"); s != self {
		return "> [!WARNING] GnoRadio has moved\n> The new version lives at [" + s + "](" +
			strings.TrimPrefix(s, runtime.ChainDomain()) + ").\n\n"
	}
	for _, r := range [3]string{"catalog", "radio", "tickets"} {
		if data.Paused(r) {
			return "> [!CAUTION] GnoRadio is paused\n> Its owner or guardian stopped the " + r +
				" for now. Pages stay readable, and promo budgets can still be withdrawn.\n\n"
		}
	}
	if at := releaseAt(data.Writers()); at > 0 {
		return "> [!NOTE] A new release takes over on " + date(at) + "\n> Its code is public until then: [see what changes](" +
			strings.TrimPrefix(dataPath, runtime.ChainDomain()) + "$source&file=data.gno), `Writers()`.\n\n"
	}
	return ""
}

// releaseAt reads "at" of data.Writers(): when a ready release takes over, 0
// when none is on its way.
func releaseAt(js string) int64 {
	_, v, ok := strings.Cut(js, `"at":`)
	if !ok {
		return 0
	}
	if i := strings.IndexByte(v, ','); i >= 0 {
		v = v[:i]
	}
	n, _ := strconv.ParseInt(v, 10, 64)
	return n
}

func route(p string, pg, genre int) string {
	switch p {
	case "":
		return renderHome()
	case "stations", "station":
		return renderStations()
	case "catalog", "track":
		return renderCatalog(pg, genre)
	case "artists", "artist":
		return renderArtists(pg)
	case "albums", "album":
		return renderAlbums(pg)
	case "playlists", "playlist":
		return renderPlaylists(pg)
	case "concerts", "event", "ticket":
		return renderConcerts(pg)
	case "listener":
		return renderListeners()
	case "charts":
		return renderCharts()
	case "join":
		return renderJoin()
	case "about":
		return renderAbout()
	case "moderation":
		return renderModeration(pg)
	}
	kind, arg, ok := strings.Cut(p, "/")
	if !ok {
		return ""
	}
	switch kind {
	case "station":
		if n, err := strconv.Atoi(arg); err == nil && n >= 0 && n < radio.StationCount() {
			return renderStation(n)
		}
	case "track":
		if t, ok := catalog.GetTrack(atoi(arg)); ok {
			return renderTrack(t)
		}
	case "artist":
		id := atoi(arg)
		if id == 0 {
			id = catalog.ArtistByName(arg)
		}
		if a, ok := catalog.GetArtist(id); ok {
			if a.Hidden {
				return renderRemoved(catalog.HiddenNote("artist", a.ID))
			}
			return renderArtist(a, pg)
		}
	case "album":
		if al, ok := catalog.GetAlbum(atoi(arg)); ok {
			switch {
			case al.Hidden:
				return renderRemoved(catalog.HiddenNote("album", al.ID))
			case !catalog.ArtistVisible(al.Artist):
				return renderRemoved(catalog.HiddenNote("artist", al.Artist))
			}
			return renderAlbum(al)
		}
	case "playlist":
		if pl, ok := catalog.GetPlaylist(atoi(arg)); ok {
			if pl.Hidden {
				return renderRemoved(catalog.HiddenNote("playlist", pl.ID))
			}
			return renderPlaylist(pl, pg)
		}
	case "event":
		id := atoi(arg)
		if e, ok := tickets.EventInfo(id); ok {
			if !catalog.ArtistVisible(e.ArtistID) {
				return renderRemoved(catalog.HiddenNote("artist", e.ArtistID))
			}
			return renderEvent(e)
		}
		if note := tickets.HiddenNote(id); note != "" {
			return renderRemoved(note)
		}
	case "ticket":
		if tk, ok := tickets.TicketInfo(atoi(arg)); ok {
			return renderTicket(tk)
		}
	case "listener":
		if addr := address(arg); roles.Canonical(addr) { // never the upper-case spelling of a wallet
			return renderListener(addr, pg)
		}
	}
	return ""
}

